        const effType = (eLbp > 0 && !(eUsd > 0)) ? 'Extra LBP' : 'Extra USD';
        const tallyVal = effType === 'Extra LBP' ? eLbp : amt;
        const payMo = val('f_paymonth') || repDate.slice(0, 7) || date.slice(0, 7);
