        const isCallout = FORM_UI.attPreset === 'callout';
        const inFmt = isNoClock ? '' : fmtAttClockTime(val('f_in'));
        const outFmt = isNoClock ? '' : fmtAttClockTime(val('f_out'));
        const schedEl = $('f_sched_hours');
