    FORM_UI.lastTransportBy = val('f_transportby');
    FORM_UI.lastTruck = val('f_truck');
    FORM_UI.lastAttStaff = val('f_staff');
    FORM_UI.lastAttDate = val('f_repdate') || val('f_date');
    FORM_UI.lastWhItem = val('f_item_name');
    recalcForm();
