  function inspectorValue(key, v) {
    if (v == null || v === '') return '—';
    if (typeof v === 'boolean') return v ? 'Yes' : 'No';
    if (Array.isArray(v)) return v.length ? v.join(', ') : '—';
    if (typeof v === 'object') return JSON.stringify(v);
    if (typeof v === 'number') {
      if (key === 'vat_percent') return fmtNum(v, Number.isInteger(v) ? 1 : 2) + '%';
      if (key === 'rate' || key === 'vat_fx_rate' || key === 'active_rate') return fmtNum(v, Number.isInteger(v) ? 0 : 2);
      if (key === 'est_km' || key === 'est_round_trip_km' || key === 'distance_km' || key === 'radius_km') return `${fmtNum(v, 1)} km`;
      if (key === 'lbp_delta') return fmtSignedLBP(v);
      if (/^lbp_|_lbp$/.test(key)) return fmtLBP(v);
      if (key === 'usd_delta') return fmtSignedUSD(v, 2);
      if (/price|cost|amount|total|vat|discount|tip|limit|salary|balance|^debit$|^credit$|adj|principal|value|change|rate_usd|daily_usd|paid|spent|sales_ttc|raw_cost|proceeds/.test(key) && !/rate$|pct|percent|factor|ton_factor|exchange|count|loads|days|hours|meter_reading|cost_class|cost_bucket/.test(key)) return fmtUSD(v, 2);
      return fmtNum(v, Number.isInteger(v) ? 0 : 2);
    }
    if (key === 'site_category') return formatSiteCategoryLabel(v);
    if (key === 'effective_to') return /^\d{4}-\d{2}-\d{2}/.test(String(v)) ? fmtDateDMY(v) : String(v);
    if (/date|last_sale|last_purchase/i.test(key)) return fmtDateDMY(v);
    return String(v);
  }

  function resolveInspectorRecord(key, idOrName) {
    const q = String(idOrName == null ? '' : idOrName).trim();
    if (!q) return null;
    if (key === 'gl_accounts') syncGlAccountsRegistry();
    const nq = norm(q);
    const list = (SEED.records[key] || []).concat(STATE.customRecords[key] || []);
    let hit = list.find(r => r && String(r.id) === q);
    if (!hit && key === 'sites') {
      const preferCust = Boolean(STATE && (STATE.view === 'sales' || STATE.view === 'customers' || STATE.view === 'pricing' || (STATE.tableViews && STATE.tableViews.sites === 'delivery')));
      const wantCat = preferCust ? 'customer' : 'supplier';
      hit = list.find(r => r && !r.voided && norm(r.name) === nq && resolveSiteCategory(r) === wantCat) ||
            list.find(r => r && !r.voided && norm(r.name) === nq);
    }
    if (!hit) {
      hit = list.find(r => r && (norm(r.name) === nq || norm(r.code) === nq || norm(r.ticket_no) === nq || norm(r.invoice_no) === nq || norm(r.staff) === nq || norm(r.driver) === nq || norm(r.equipment) === nq || norm(r.plate_no) === nq));
    }
    if (hit) return hit;

    // Synthesize a rich 360° master record if a lookup name exists in transactions or semantic summaries
    if (key === 'customers') {
      const ci = customerInfo(q);
      if (ci) return Object.assign({ id: q, name: ci.Customer || q, official_name: ci.Customer || q, method: ci.method || 'Credit', vat_registered: ci['VAT Registered'] === 'Yes' }, ci);
      return { id: q, name: q, official_name: q, method: 'Credit', vat_registered: false };
    }
    if (key === 'suppliers') {
      const si = supplierInfo(q);
      if (si) return Object.assign({ id: q, name: si.Supplier || q, official_name: si.Supplier || q, iva: !!si.iva, is_truck_owner: !!si.is_truck_owner }, si);
      return { id: q, name: q, official_name: q };
    }
    if (key === 'products') return { id: q, name: q, type: 'Material', uom: 'm³', list_price: listPrice(q) };
    if (key === 'sites') {
      const defCat = (STATE && (STATE.view === 'sales' || STATE.view === 'customers' || STATE.view === 'pricing' || (STATE.tableViews && STATE.tableViews.sites === 'delivery'))) ? 'customer' : 'supplier';
      return { id: q, name: q, site_category: defCat, region: 'Lebanon', is_jv: false };
    }
    if (key === 'equipment') return { id: q, name: q, plate_no: q, type: 'Truck', ownership: 'Third-Party' };
    if (key === 'drivers') return { id: q, name: q };
    if (key === 'employments') return { id: q, name: q, staff: q, type: 'Regular', status: 'Active' };
    if (key === 'expense_categories') return { id: q, name: q };
    if (key === 'expense_subcategories') return { id: q, name: q };
    if (key === 'regions') return { id: q, name: q };
    return null;
  }

  // Build Live Contextual Notification Banner (Screenshot 2 top blue notification strip)
  function buildInspectorLiveBanner(key, row) {
    if (key === 'sales_tickets') {
      const pr = findRule({ company: row.company, customer: row.customer, product: row.product, site: row.site, date: row.date, types: [row.sale_type === 'Pickup' ? 'Sales (Pickup)' : 'Sales (Delivery)', 'Sales (Delivery)', 'Sales (Pickup)'] });
      const eq = equipInfo(row.truck);
      const ct = creditTermsForCustomer(row.customer);
      const lp = listPrice(row.product);
      const ruleTxt = pr
        ? `${pr.rule_type || 'Sales Agreement'}: ${fmtUSD(pr.unit_price, 2)}/${row.uom || pr.unit || 'm³'}`
        : (lp != null ? `List Price Benchmark: ${fmtUSD(lp, 2)}/${row.uom || 'm³'} (no active customer rule)` : `Spot Ticket Price: ${fmtUSD(row.unit_price, 2)}/${row.uom || 'm³'}`);
      const trTxt = row.sale_type === 'Delivery'
        ? `Transport: ${fmtUSD(row.trans_unit_price || (pr && pr.trans_unit_price) || 0, 2)}/${row.uom || 'm³'} (${fmtUSD(row.trans_price, 2)})`
        : 'Pick-up (Material Only · $0.00 Transport)';
      const trkTxt = eq
        ? `${eq.ownership || 'Truck'}: ${eq.name}${eq.capacity ? ' (' + fmtNum(eq.capacity, 0) + ' m³)' : ''}${row.driver || eq.default_driver ? ' · ' + (row.driver || eq.default_driver) : ''}`
        : `Truck: ${row.truck || row.transport_by || '—'}${row.driver ? ' · ' + row.driver : ''}`;
      const totTxt = `Load Total: ${fmtNum(row.qty, 2)} ${row.uom || 'm³'} = ${fmtUSD(row.total_ttc != null ? row.total_ttc : row.total, 2)} USD`;
      const crTxt = ct ? `Credit Terms: ${ct.credit_days || 30} days (Limit ${fmtUSD(ct.credit_limit || 0, 0)})` : `Payment: ${row.method || 'Credit'}`;
      return { tone: pr ? 'info' : 'warn', text: `Pricing: ${ruleTxt}  |  ${trTxt}  |  ${trkTxt}  |  ${totTxt}  |  ${crTxt}` };
    }
    if (key === 'raw_purchases') {
      const matRule = findRule({ company: row.company, supplier: row.site_owner, site: row.site, product: row.product, date: row.date });
      const eq = equipInfo(row.truck);
      return {
        tone: 'info',
        text: `Two-Leg Material Split: Leg 1 Material ${fmtUSD(row.cost, 2)} → ${row.site_owner || row.site || 'Site Owner'}${matRule ? ' (Agreed Rate)' : ''}  |  Leg 2 Haulage ${fmtUSD(row.trans_cost, 2)} → ${row.truck_owner || row.transport_by || 'Company Fleet'}${eq ? ' · Truck ' + eq.name : ''}  |  Total Payable: ${fmtUSD(row.total, 2)} USD`
      };
    }
    if (key === 'price_rules') {
      const today = SEED_DATE;
      const active = (!row.end_date || String(row.end_date) >= today);
      if (isCommRule(row)) {
        const cVal = isMatIndiffRule(row) ? Number(ruleIndiffPrice(row) || 0) : Number(row.unit_price ?? row.price ?? 0);
        const cUnit = /^truck$/i.test(String(row.unit || '').trim()) ? 'Truck Load' : (row.unit || 'Ton');
        return {
          tone: active ? 'info' : 'warn',
          text: `Sales Commission Rule: ${row.supplier || 'Plant Owner'} · Grade: ${row.product || 'All Grades'} · Commission Rate: ${fmtUSD(cVal, 2)}/${cUnit} · Status: ${active ? 'ACTIVE (Accrues on sales tickets)' : 'ENDED (' + row.end_date + ')'}`
        };
      }
      const isTransOnly = /^(Transport Price \(Site\)|Haulage \(Customer Site\))$/i.test(String(row.rule_type || '').trim());
      const isFlatMat = isMatIndiffRule(row);
      const isFlatTrans = isTransIndiffRule(row);
      const matVal = isFlatMat ? Number(ruleIndiffPrice(row) || 0) : Number(row.unit_price ?? row.price ?? 0);
      const trVal = isFlatTrans ? Number(ruleTransIndiffPrice(row) || 0) : Number(row.trans_unit_price ?? row.trans_price ?? (isTransOnly ? (row.unit_price ?? row.price) : 0) ?? 0);
      const priceParts = [];
      if (!isTransOnly) {
        priceParts.push(isFlatMat ? `Material Price: ${fmtUSD(matVal, 2)} / Truck Load` : `Material Unit Price: ${fmtUSD(matVal, 2)} / ${row.unit || 'm³'}`);
      }
      if (isTransOnly || isFlatTrans || trVal > 0) {
        priceParts.push(isFlatTrans ? `Transportation Price: ${fmtUSD(trVal, 2)} / Truck Load` : `Transportation Unit Price: ${fmtUSD(trVal, 2)} / ${row.rate_per || row.unit || 'm³'}`);
      }
      const priceSummary = priceParts.join(' · ');
      return {
        tone: active ? 'info' : 'warn',
        text: `Price Agreement: ${row.rule_type || 'Rule'} for ${row.customer || row.supplier || row.site || 'Standard List'} · Grade: ${row.product || 'All Grades'} · ${priceSummary} · Status: ${active ? 'ACTIVE (Auto-fills weighbridge tickets)' : 'ENDED (' + row.end_date + ')'}`
      };
    }
    if (key === 'customers') {
      const ci = customerInfo(row.name || row.Customer) || {};
      const ct = creditTermsForCustomer(row.name || row.Customer);
      const rulesCnt = activeRulesCountFor('customer', row.name || row.Customer);
      return {
        tone: Number(ci.ar_60_plus || 0) > 0 ? 'warn' : 'info',
        text: `Customer 360° Ledger: Open FIFO AR Balance ${fmtUSD(ci.ar_balance || 0, 2)} (Overdue 60+d: ${fmtUSD(ci.ar_60_plus || 0, 0)})  |  Active Price Agreements: ${rulesCnt}  |  Credit Policy: ${ct ? ct.credit_days + ' days · Limit ' + fmtUSD(ct.credit_limit, 0) : 'Standard Account'}  |  VAT Status: ${(row.vat_registered || ci['VAT Registered'] === 'Yes') ? '11% VAT Registered' : 'Non-VAT'}`
      };
    }
    if (key === 'suppliers') {
      const si = supplierInfo(row.name || row.Supplier) || {};
      const rulesCnt = activeRulesCountFor('supplier', row.name || row.Supplier);
      return {
        tone: 'info',
        text: `Supplier & Hauler 3-Leg AP Ledger: Net AP Balance ${fmtUSD(si.ap_balance || 0, 2)} (Material Leg: ${fmtUSD(si.ap_material || 0, 0)} · Haulage Leg: ${fmtUSD(si.ap_haulage || 0, 0)} · Expense Leg: ${fmtUSD(si.ap_expense || 0, 0)})  |  Active Agreements: ${rulesCnt}  |  Registered Trucks: ${fmtNum(row.trucks_count || (row.trucks || []).length || 0)}`
      };
    }
    if (key === 'equipment' || key === 'company_equipment') {
      const eqName = row.equipment || row.name;
      const lm = lastMeter(null, eqName, null);
      const lmEff = lm ? effectiveFuelMeter(lm) : null;
      const mSpec = equipMeterSpec(row, row.company);
      const h = getEquipmentHealth(eqName);
      const healthSummary = `Health: ${h.status}${h.openCount ? ' (' + h.openCount + ' open defect' + (h.openCount > 1 ? 's' : '') + ')' : ''}${h.partCount ? ' · ' + h.partCount + ' part log' + (h.partCount > 1 ? 's' : '') : ''}`;
      return {
        tone: h.critCount > 0 ? 'crit' : (h.openCount > 0 ? 'warn' : 'info'),
        text: `Universal Fleet Registry: Unit ${eqName} (${row.type || 'Truck'} · ${mSpec.label} · ${row.ownership || 'Transporter'})  |  ${healthSummary}  |  Capacity: ${row.capacity ? fmtNum(row.capacity, 1) + ' m³' : 'Standard'}  |  Owner: ${row.supplier || 'Company Fleet'}  |  Default Driver: ${row.default_driver || '—'}  |  Last Meter: ${lm && lmEff && lmEff.reading != null ? fmtNum(lmEff.reading, lmEff.type === 'hours' && lmEff.reading % 1 !== 0 ? 1 : 0) + ' ' + lmEff.unit + ' (' + lm.date + ')' : 'No meter log'}`
      };
    }
    if (key === 'equipment_defects') {
      const open = isDefectOpen(row);
      const isCrit = /Grave|Critical/i.test(row.severity || '');
      return {
        tone: open ? (isCrit ? 'crit' : 'warn') : 'ok',
        text: `Equipment Warning ${row.name}: Unit ${row.equipment || '-'} · Subsystem: ${row.subsystem || '-'} · Affected Part: ${row.part_name || 'General'}  |  Severity: ${row.severity || '-'}  |  Status: ${row.status || 'Open'}${row.linked_part_log ? ' · Resolved by ' + row.linked_part_log : ''}`
      };
    }
    if (key === 'equipment_repairs') {
      const whC = Number(row.warehouse_parts_usd != null ? row.warehouse_parts_usd : (row.warehouse_cost || 0));
      const outC = Number(row.outside_parts_usd != null ? row.outside_parts_usd : (row.outside_parts_cost || 0));
      const labC = Number(row.external_labor_usd != null ? row.external_labor_usd : (row.outside_labor_cost || 0));
      const totC = Number(row.total_cost_usd != null ? row.total_cost_usd : (row.total_cost != null ? row.total_cost : (whC + outC + labC)));
      return {
        tone: 'info',
        text: `Equipment Repair ${row.name}: Unit ${row.equipment || '-'} · Source: ${row.repair_source || 'Warehouse Only'}  |  Warehouse Stock Cost: ${fmtUSD(whC, 2)} · Outside Parts: ${fmtUSD(outC, 2)} · Outside Labor: ${fmtUSD(labC, 2)}  |  Total Cost: ${fmtUSD(totC, 2)}`
      };
    }
    if (key === 'equipment_oil_logs') {
      const hrsVal = row.hours_reading != null ? row.hours_reading : row.meter_hours;
      const dueHrs = row.next_due_hours || (hrsVal != null && Number(row.interval_hours) > 0 ? Number(hrsVal) + Number(row.interval_hours) : null);
      const dueKm = row.next_due_km || (row.odometer_km != null && Number(row.interval_km) > 0 ? Number(row.odometer_km) + Number(row.interval_km) : null);
      const nextDueStr = [dueHrs ? fmtNum(dueHrs, 0) + ' hr' : '', dueKm ? fmtNum(dueKm, 0) + ' km' : '', row.next_due_date || (Number(row.interval_days) > 0 ? 'every ' + fmtNum(row.interval_days, 0) + 'd' : '')].filter(Boolean).join(' / ') || 'Open';
      return {
        tone: 'info',
        text: `Oil & Service Log ${row.name}: Unit ${row.equipment || '-'} · ${row.oil_type || 'Engine Oil'} (${fmtNum(row.qty || 1, 1)} ${row.uom || 'Litre'})  |  Hours: ${hrsVal != null ? fmtNum(hrsVal, 1) + ' hr' : '-'} · Odometer: ${row.odometer_km != null ? fmtNum(row.odometer_km, 0) + ' km' : '-'}  |  Next Due: ${nextDueStr}`
      };
    }
    if (key === 'warehouse_movements') {
      const isOut = isWarehouseOutMove(row.movement_type || row.move_type, row.direction);
      const mvLbl = formatWarehouseMovementLabel(row.movement_type || row.move_type, row.direction, 'warehouse_movements');
      return {
        tone: isOut ? 'warn' : 'ok',
        text: `Warehouse Shelf Adjustment ${row.name} (${mvLbl}): ${isOut ? '-' : '+'}${fmtNum(row.qty || 1, 2)} ${row.uom || 'Unit'} of ${row.item_name || '-'}  |  Unit Cost: ${fmtUSD(row.unit_cost || 0, 2)} · Total: ${fmtUSD(row.total_cost || 0, 2)}  |  Shelf: ${row.warehouse_location || row.location || 'Main Warehouse'}`
      };
    }
    if (key === 'part_movements') {
      const preOk = Boolean(row.prior_defect_notified || row.defect_ref);
      const netCost = round2(Number(row.new_part_cost || 0) + Number(row.repair_cost || 0) - Number(row.sale_proceeds || 0));
      return {
        tone: preOk ? 'ok' : 'warn',
        text: `Part Custody & Lifecycle ${row.name}: ${row.part_name || 'Part'} (×${fmtNum(row.qty || 1, 0)}) on Unit ${row.equipment || '—'}  |  Disposition: ${row.removed_disposition || '—'}${row.storage_location ? ' @ ' + row.storage_location : ''}  |  Pre-Defect Notification: ${preOk ? 'Verified (' + (row.defect_ref || 'Prior Report') + ')' : 'Unnotified Emergency Change'}  |  Net Cost: ${fmtUSD(netCost, 2)}`
      };
    }
    if (key === 'sites') {
      const isCustSite = resolveSiteCategory(row) === 'customer';
      const rulesCnt = activeRulesCountFor('site', row.name, isCustSite ? 'sales' : 'raw');
      const gpsTxt = row.latitude != null ? `${row.latitude}, ${row.longitude}` : 'Pending coordinates';
      return {
        tone: 'info',
        text: isCustSite
          ? `Customer Delivery Site: ${row.name} (${row.region || 'Lebanon'})  |  Linked Customer: ${row.customer || 'Open Delivery'}  |  Active Sales Site Rules: ${rulesCnt}  |  GPS Pin: ${gpsTxt}`
          : `Supplier / Quarry Site: ${row.name} (${row.region || 'Lebanon'})  |  Default Site Owner: ${row.supplier || 'Open Source'}  |  JV 50/50 Status: ${row.is_jv ? 'Active JV Site' : 'Standard Quarry Site'}  |  Active Quarry Site Rules: ${rulesCnt}  |  GPS Pin: ${gpsTxt}`
      };
    }
    if (key === 'products') {
      const lp = listPrice(row.name);
      const rulesCnt = activeRulesCountFor('product', row.name);
      return {
        tone: 'info',
        text: `Product & Grade Master: ${row.name} (${row.type || 'Material'} · Default UoM ${row.uom || 'm³'} · Tonnage Factor ${row.ton_factor || 1.5} t/m³)  |  List Price Benchmark: ${lp != null ? fmtUSD(lp, 2) : '-'}  |  Active Price Agreements: ${rulesCnt}`
      };
    }
    if (key === 'gl_accounts') {
      return {
        tone: 'info',
        text: `GL ${row.code} · ${row.name} (${row.pcg_class || 'Lebanese PCG'})  |  Automation: ${row.automation_mode || 'Direct Formula'} (${row.source_module || 'Double-Entry Engine'})  |  Debit Rule: ${row.debit_rule || '-'}  |  Credit Rule: ${row.credit_rule || '-'}`
      };
    }
    if (key === 'conversions') {
      const d = convSignedDeltas(row);
      return {
        tone: 'info',
        text: `FX Conversion (${d.dirLabel}): USD Drawer ${fmtSignedUSD(d.usd, 2)} (${d.u2l ? 'Decreased' : 'Increased'})  |  LBP Drawer ${fmtSignedLBP(d.lbp)} (${d.u2l ? 'Increased' : 'Decreased'})  |  Effective Rate: ${fmtNum(d.rate, 2)} LL/$  |  Entity: ${row.company || 'WTC'}`
      };
    }
    if (key === 'employments') {
      const stName = row.staff || row.name || '';
      const eqInfo = stName ? resolveStaffEquipmentSitesInfo(stName, row.company || '', row.start_date || todayISO()) : null;
      const eqTxt = eqInfo && eqInfo.hasConnection
        ? `Connected Equipment: ${eqInfo.registeredUnits.map(u => u.equipment + (u.site ? ' @ ' + u.site : '')).slice(0, 3).join(', ')}${eqInfo.siteLogs.length ? ` (${eqInfo.siteLogs.length} Equipment Sites Log ${eqInfo.siteLogs.length === 1 ? 'entry' : 'entries'})` : ''}`
        : 'No Equipment Assignment';
      const mContractUsd = empContractMonthlyUsd(row);
      const baseAmt = Number(row.daily_rate || row.amount || 0);
      return {
        tone: 'info',
        text: `Staff Contract · ${stName || 'Staff'} (${row.role || 'Staff'} · ${row.status || 'Current'}): ${(Number(row.salary_usd || 0) > 0 || Number(row.salary_lbp || 0) > 0) ? fmtUSD(mContractUsd, 2) + '/mo' : (baseAmt > 0 ? fmtUSD(baseAmt, 2) + '/d' : '-')}  |  ${eqTxt}`
      };
    }
    if (key === 'attendance') {
      const effSd = String(row.set_date || row.rep_date || row.date || '').slice(0, 10);
      const txDt = String(row.date || effSd || '').slice(0, 10);
      const wkInfo = attDateWeekdayInfo(effSd);
      const tp = row.type || row.status || 'Present';
      const shTxt = (row.in_time || row.out_time)
        ? `${fmtAttClockTime(row.in_time)} to ${fmtAttClockTime(row.out_time)} (${fmtNum(row.worked_hours || 0, 1)}h)`
        : (row.leave_days ? `${fmtNum(row.leave_days, 1)}d Leave` : `${fmtNum(row.tally || 0, 1)} Tally`);
      return {
        tone: /Absence|Absent|Lateness|Half\s*Day/i.test(tp) ? 'warn' : 'info',
        text: `Attendance Log · ${row.staff || 'Staff'} (${row.company || 'WTC'}): Reporting Date (Set Date) ${fmtDateDMY(effSd)}${wkInfo.short ? ' ' + wkInfo.short : ''}  |  Transaction Date ${fmtDateDMY(txDt)}  |  Category: ${tp} (${shTxt})`
      };
    }
    if (key === 'salaries') {
      const payMo = row.payroll_month || String(row.date || '').slice(0, 7);
      const pos = computeStaffMonthPayrollPosition(row.staff, row.company, payMo, row.date, row.id, true);
      const thisAmt = round2(salaryVoucherUsd895(row));
      if (pos && pos.hasContract) {
        const afterRem = round2(pos.monthNetEarned - (pos.paidSoFar + thisAmt));
        if (pos.isFutureMonth) {
          const futSt = afterRem >= -0.01
            ? `Future-Month Salary Advance (${fmtUSD(Math.max(0, afterRem), 2)} of ${pos.monthLabel} Base Unadvanced)`
            : `Future-Month Salary Advance (+${fmtUSD(Math.abs(afterRem), 2)} Over ${pos.monthLabel} Base)`;
          return {
            tone: 'warn',
            text: `Salary Payment · ${row.staff || 'Staff'} (${pos.monthLabel} Advance): Contract Base ${fmtUSD(pos.baseNet, 2)} ($0.00 Earned as of ${String(row.date || '').slice(0, 10)})  |  Other Advances: ${fmtUSD(pos.paidSoFar, 2)}  |  This Advance: ${fmtUSD(thisAmt, 2)}  |  Status: ${futSt}`
          };
        }
        const stTxt = afterRem < -0.01 ? `Advance / Overpayment (+${fmtUSD(Math.abs(afterRem), 2)})` : (afterRem <= 0.01 ? 'Month Settled ($0.00 Left)' : `${fmtUSD(afterRem, 2)} Remaining`);
        return {
          tone: afterRem < -0.01 ? 'warn' : 'info',
          text: `Salary Payment · ${row.staff || 'Staff'} (${pos.monthLabel}): Contract Base ${fmtUSD(pos.baseNet, 2)} + OT/Adj ${pos.attNetImpact >= 0 ? '+' : '-'}${fmtUSD(Math.abs(pos.attNetImpact), 2)} = Month Earned ${fmtUSD(pos.monthNetEarned, 2)}  |  Other Payments: ${fmtUSD(pos.paidSoFar, 2)}  |  This Payment: ${fmtUSD(thisAmt, 2)}  |  Status: ${stTxt}`
        };
      }
    }
    if (key === 'expenses') {
      const isPend = isPendingPriceExpense(row);
      const isDiesel = isBulkDieselExpense(row);
      const q = Number(row.qty || 1);
      if (isPend) {
        return {
          tone: 'warn',
          text: `PENDING INVOICE PRICE: ${fmtNum(q, q % 1 ? 2 : 0)}${isDiesel ? ' L Diesel added to ' + (row.company || 'WTC') + ' Plant Tank' : ' units received'} from ${row.supplier || 'Vendor'} at $0.00 AP · Click "Enter Final Price" once the supplier invoice arrives to book the final USD amount on the locked delivery voucher.`
        };
      }
      return {
        tone: 'info',
        text: `Expense Voucher ${row.name || ('#' + row.id)}: ${row.category || 'Operating'}${row.subcategory ? ' · ' + row.subcategory : ''}  |  Amount: ${fmtUSD(row.amount || 0, 2)} (${row.method || 'Cash'})  |  Vendor: ${row.supplier || '—'}  |  Quantity: ${fmtNum(q, q % 1 ? 2 : 0)}${isDiesel && q > 0 ? ' L (' + fmtUSD(Number(row.amount || 0) / q, 3) + '/L)' : ''}`
      };
    }
    if (key === 'fuel_malfunctions') {
      const lit = round2(Number(row.litres || 0));
      const tankDelta = round2(-lit);
      const coKey = COMPANY_KEY_BY_NAME[row.company] || 'wtc';
      const dtAll = getDieselTankLedger(coKey, null);
      const ym = String((STATE.basis === 'tx' ? row.date : (row.rep_date || row.date)) || '').slice(0, 7);
      const dtMo = /^\d{4}-\d{2}$/.test(ym) ? getDieselTankLedger(coKey, { from: ym + '-01', to: ym + '-31' }) : dtAll;
      return {
        tone: dtMo && dtMo.malfunctionAlert ? (dtMo.malfunctionSeverity === 'crit' ? 'crit' : 'warn') : 'info',
        text: `Tank Discrepancy (${row.discrepancy_type || 'Malfunction'}): ${lit >= 0 ? 'Shortage / Outflow' : 'Surplus / Over-Read'} ${lit > 0 ? '+' : ''}${fmtNum(lit, 1)} L (Tank Impact ${tankDelta > 0 ? '+' : ''}${fmtNum(tankDelta, 1)} L)  |  Live ${row.company || 'WTC'} Tank: ${fmtNum(dtAll ? dtAll.closingTankL : 0, 1)} L  |  ${_formatMonthYmLabel(ym)} Malfunction Share: ${dtMo ? dtMo.malfunctionPct.toFixed(1) : '0.0'}% (${dtMo && dtMo.malfunctionAlert ? '>=' + dtMo.malfunctionThresholdPct.toFixed(1) + '% WATCHDOG ALERT' : '<5.0% OK'})`
      };
    }
    return {
      tone: 'info',
      text: `Relational Record (${INSPECT_LABELS[key] || key}) · Connected to live relational SQL tables & SOA double-entry ledger (${SEED_DATE}). Click any blue lookup pill or related subgrid row below to drill across entities.`
    };
  }

  // Build 4-Card Navy Executive Telemetry & Control Cockpit (Screenshot 2 bhf_mfgCockpit.htm m283 parity)
  function buildInspectorCockpit(key, row) {
    const bu = row.company || COMPANY_BU_MATCH[STATE.company] || 'MFG';
    const isCommRow = key === 'price_rules' && isCommRule(row);
    const isQuarryPr = key === 'price_rules' && !isCommRow && /^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(String(row.rule_type || '').trim());
    const title = key === 'price_rules'
      ? `${isCommRow ? 'Sales Commission Rule' : (isQuarryPr ? 'Raw & Haulage Agreement' : 'Sales Price Agreement')} · ${row.customer || row.supplier || row.site || 'Standard List'}${row.product ? ' · ' + row.product : ''}`
      : (key === 'salaries'
          ? `Salary Payment · ${row.staff || 'Staff'}${row.payroll_month ? ' · ' + row.payroll_month : ''}`
          : (row.ticket_no ? `${INSPECT_LABELS[key] || key} #${row.ticket_no} · ${row.customer || row.site || row.equipment || row.name || ''}` : `${INSPECT_LABELS[key] || key} · ${row.name || row.invoice_no || row.staff || row.driver || row.equipment || row.id}`));

    if (key === 'sales_tickets') {
      const pr = findRule({ company: row.company, customer: row.customer, product: row.product, site: row.site, date: row.date, types: [row.sale_type === 'Pickup' ? 'Sales (Pickup)' : 'Sales (Delivery)', 'Sales (Delivery)', 'Sales (Pickup)'] });
      const lp = listPrice(row.product);
      const bench = pr ? Number(pr.unit_price || 0) : (lp != null ? Number(lp) : Number(row.unit_price || 0));
      const actual = Number(row.unit_price || 0);
      const diff = round2(actual - bench);
      const ci = customerInfo(row.customer) || {};
      const ct = creditTermsForCustomer(row.customer);
      const arBal = Number(ci.ar_balance || 0);
      const ar60 = Number(ci.ar_60_plus || 0);
      const credLim = Number((ct && ct.credit_limit) || 50000);
      const eq = equipInfo(row.truck);
      const ttc = Number(row.total_ttc != null ? row.total_ttc : row.total || 0);
      const tons = ticketTons(row);

      return {
        bu,
        title,
        pill: fmtUSD(ttc, 2),
        cards: [
          {
            lbl: 'UNIT PRICE VS AGREEMENT',
            tag: diff < -0.01 ? 'BELOW RULE' : (pr ? 'ON RULE' : 'LIST / SPOT'),
            tone: diff < -0.01 ? 'warn' : 'good',
            val: `${fmtUSD(actual, 2)} / ${row.uom || 'm³'}`,
            sub1: pr ? `Agreed: ${fmtUSD(pr.unit_price, 2)} · Diff ${diff >= 0 ? '+' : ''}${fmtUSD(diff, 2)}` : `List Benchmark: ${lp != null ? fmtUSD(lp, 2) : '—'} · Transport: ${fmtUSD(row.trans_price, 2)}`,
            sub2: `Material: ${fmtUSD(row.price, 2)} · VAT 11%: ${fmtUSD(row.vat, 2)}`,
            pct: Math.min(100, Math.max(20, bench > 0 ? Math.round((actual / bench) * 85) : 80))
          },
          {
            lbl: 'CUSTOMER AR & AGING',
            tag: ar60 > 0 ? 'OVER 60D' : 'CURRENT',
            tone: ar60 > 0 ? 'crit' : 'good',
            val: fmtUSD(arBal, 0),
            sub1: `0–30d: ${fmtUSD((ci.ar_current || 0) + (ci.ar_1_10 || 0) + (ci.ar_11_30 || 0), 0)} · 31–60d: ${fmtUSD(ci.ar_31_60 || 0, 0)}`,
            sub2: `60+d Overdue: ${fmtUSD(ar60, 0)} · Loads: ${fmtNum(ci.loads || 0)}`,
            pct: Math.min(100, arBal > 0 ? Math.max(15, Math.round((ar60 / arBal) * 100)) : 20)
          },
          {
            lbl: 'CREDIT LIMIT EXPOSURE',
            tag: credLim > 0 && arBal > credLim ? 'OVER LIMIT' : 'WITHIN LIMIT',
            tone: credLim > 0 && arBal > credLim ? 'warn' : 'good',
            val: `${ fmtNum(row.qty, 2)} ${row.uom || 'm³'}`,
            sub1: `Ticket TTC: ${fmtUSD(ttc, 2)} (${fmtNum(tons, 1)} tons)`,
            sub2: `Credit Terms: ${ct ? ct.credit_days + 'd · Limit ' + fmtUSD(credLim, 0) : row.method || 'Credit'}`,
            pct: credLim > 0 ? Math.min(100, Math.max(15, Math.round((arBal / credLim) * 100))) : 35
          },
          {
            lbl: 'TRUCK & TELEMETRY',
            tag: eq && /^own|company/i.test(eq.ownership || '') ? 'COMPANY FLEET' : '3RD-PARTY',
            tone: 'info',
            val: row.truck || row.transport_by || 'Pick-up',
            sub1: `Cap: ${eq && eq.capacity ? fmtNum(eq.capacity, 0) + ' m³' : fmtNum(row.qty, 0) + ' m³'} · Owner: ${(eq && eq.supplier) || row.truck_owner || 'Customer'}`,
            sub2: `Driver: ${row.driver || (eq && eq.default_driver) || '—'} · Site: ${row.site || 'Pick-up (Material Only)'}`,
            pct: 78
          }
        ]
      };
    }

    if (key === 'raw_purchases') {
      const siSite = supplierInfo(row.site_owner) || {};
      const siHaul = supplierInfo(row.truck_owner) || {};
      const tot = Number(row.total != null ? row.total : (Number(row.cost || 0) + Number(row.trans_cost || 0)));
      return {
        bu, title, pill: fmtUSD(tot, 2),
        cards: [
          { lbl: 'LEG 1 · RAW MATERIAL', tag: 'SITE OWNER', tone: 'good', val: fmtUSD(row.cost, 2), sub1: `Payee: ${row.site_owner || '—'} · Rate: ${fmtUSD(row.unit_cost, 2)}/${row.uom || 'm³'}`, sub2: `Site: ${row.site || '—'} · Open AP: ${fmtUSD(siSite.ap_balance || 0, 0)}`, pct: tot > 0 ? Math.round((Number(row.cost || 0) / tot) * 100) : 60 },
          { lbl: 'LEG 2 · HAULAGE / FREIGHT', tag: /company/i.test(row.transport_by || '') ? 'OWN FLEET' : 'HAULER AP', tone: 'info', val: fmtUSD(row.trans_cost, 2), sub1: `Hauler: ${row.truck_owner || row.transport_by || '—'}`, sub2: `Truck: ${row.truck || '—'} · Hauler AP: ${fmtUSD(siHaul.ap_balance || 0, 0)}`, pct: tot > 0 ? Math.round((Number(row.trans_cost || 0) / tot) * 100) : 40 },
          { lbl: 'INTAKE VOLUME & TONNAGE', tag: row.uom || 'M³', tone: 'good', val: `${fmtNum(row.qty, 2)} ${row.uom || 'm³'}`, sub1: `Estimated Weight: ${fmtNum(ticketTons(row), 1)} tons`, sub2: `Grade: ${row.product || 'Raw Aggregate'}`, pct: 80 },
          { lbl: 'COMBINED LANDED COST', tag: '2-LEG SPLIT', tone: 'info', val: fmtUSD(tot, 2), sub1: `Landed Unit Cost: ${row.qty > 0 ? fmtUSD(tot / row.qty, 2) : '—'}/${row.uom || 'm³'}`, sub2: `Tx Date: ${row.date || '—'} · Rep Date: ${row.rep_date || row.date || '—'}`, pct: 90 }
        ]
      };
    }

    if (key === 'customers') {
      const name = row.name || row.Customer;
      const ci = customerInfo(name) || {};
      const ct = creditTermsForCustomer(name);
      const tickets = (SEED.records.sales_tickets || []).filter(t => norm(t.customer) === norm(name));
      const rcpts = (SEED.records.receipts || []).filter(r => norm(r.customer) === norm(name));
      const rules = (SEED.records.price_rules || []).filter(r => norm(r.customer) === norm(name));
      const arBal = Number(ci.ar_balance != null ? ci.ar_balance : 0);
      return {
        bu: 'ALL BUs', title, pill: `AR ${fmtUSD(arBal, 2)}`,
        cards: [
          { lbl: 'OPEN FIFO AR BALANCE', tag: Number(ci.ar_60_plus || 0) > 0 ? 'AGED 60+D' : 'ACTIVE AR', tone: Number(ci.ar_60_plus || 0) > 0 ? 'warn' : 'good', val: fmtUSD(arBal, 2), sub1: `Current: ${fmtUSD(ci.ar_current || 0, 0)} · 60+d: ${fmtUSD(ci.ar_60_plus || 0, 0)}`, sub2: `VAT Status: ${(row.vat_registered || ci['VAT Registered'] === 'Yes') ? '11% VAT' : 'Standard'}`, pct: 75 },
          { lbl: 'LIFETIME SALES & LOADS', tag: `${fmtNum(ci.loads || tickets.length)} LOADS`, tone: 'info', val: fmtUSD(ci.sales_ttc || tickets.reduce((a, t) => a + Number(t.total_ttc || 0), 0), 0), sub1: `${fmtNum(tickets.length)} tickets in register`, sub2: `Last Sale: ${ci.last_sale || (tickets[0] && tickets[0].date) || '—'}`, pct: 85 },
          { lbl: 'RECEIPTS COLLECTED', tag: `${fmtNum(rcpts.length)} VOUCHERS`, tone: 'good', val: fmtUSD(ci.receipts || rcpts.reduce((a, r) => a + Number(r.amount || 0), 0), 0), sub1: `Oldest-First FIFO Relief`, sub2: `Default Method: ${row.method || ci.method || 'Credit'}`, pct: 80 },
          { lbl: 'AGREEMENTS & CREDIT TERMS', tag: `${rules.filter(r => !r.end_date).length} ACTIVE`, tone: 'info', val: ct ? `${ct.credit_days || 30} Days` : 'Open Terms', sub1: `Credit Limit: ${ct ? fmtUSD(ct.credit_limit, 0) : 'Not capped'}`, sub2: `${rules.length} total price agreements on file`, pct: 70 }
        ]
      };
    }

    if (key === 'suppliers') {
      const name = row.name || row.Supplier;
      const si = supplierInfo(name) || {};
      const matLoads = (SEED.records.raw_purchases || []).filter(r => norm(r.site_owner) === norm(name));
      const haulLoads = (SEED.records.raw_purchases || []).filter(r => norm(r.truck_owner) === norm(name));
      const exps = (SEED.records.expenses || []).filter(x => norm(x.supplier) === norm(name));
      const spays = (SEED.records.settlements || []).filter(s => norm(s.supplier) === norm(name));
      const apBal = Number(si.ap_balance != null ? si.ap_balance : 0);
      return {
        bu: 'ALL BUs', title, pill: `AP ${fmtUSD(apBal, 2)}`,
        cards: [
          { lbl: 'NET 3-LEG AP BALANCE', tag: '3-LEG AP', tone: apBal > 0 ? 'warn' : 'good', val: fmtUSD(apBal, 2), sub1: `Mat: ${fmtUSD(si.ap_material || 0, 0)} · Haul: ${fmtUSD(si.ap_haulage || 0, 0)}`, sub2: `Expense Leg: ${fmtUSD(si.ap_expense || 0, 0)}`, pct: 75 },
          { lbl: 'MATERIAL & HAULAGE LOADS', tag: `${fmtNum(matLoads.length + haulLoads.length)} TICKETS`, tone: 'info', val: fmtNum(si.raw_loads || (matLoads.length + haulLoads.length)), sub1: `As Site Owner: ${fmtNum(matLoads.length)} · As Hauler: ${fmtNum(haulLoads.length)}`, sub2: `Expenses Billed: ${fmtNum(exps.length)} vouchers`, pct: 80 },
          { lbl: 'SETTLEMENTS DISBURSED', tag: `${fmtNum(spays.length)} PAYMENTS`, tone: 'good', val: fmtUSD(si.settlements_paid || spays.reduce((a, s) => a + Number(s.amount || 0), 0), 0), sub1: `${fmtNum(spays.length)} settlement vouchers in register`, sub2: `IVA Registered: ${row.iva || si.iva ? 'Yes' : 'No'}`, pct: 85 },
          { lbl: 'FLEET & AGREEMENTS', tag: row.is_truck_owner ? 'HAULER FLEET' : 'VENDOR', tone: 'info', val: `${fmtNum(row.trucks_count || (row.trucks || []).length || 0)} Trucks`, sub1: `Drivers Linked: ${fmtNum((row.drivers || []).length)}`, sub2: `Active Price Rules: ${activeRulesCountFor('supplier', name)}`, pct: 70 }
        ]
      };
    }

    if (key === 'conversions') {
      const d = convSignedDeltas(row);
      return {
        bu,
        title,
        pill: `${fmtSignedUSD(d.usd, 2)} · ${fmtSignedLBP(d.lbp)}`,
        cards: [
          { lbl: 'USD DRAWER CHANGE', tag: d.u2l ? 'USD OUTFLOW' : 'USD INFLOW', tone: d.u2l ? 'crit' : 'good', val: fmtSignedUSD(d.usd, 2), sub1: d.u2l ? 'USD sold from cash till' : 'USD received into cash till', sub2: `Direction: ${d.dirLabel}`, pct: 85 },
          { lbl: 'LBP DRAWER CHANGE', tag: d.u2l ? 'LBP INFLOW' : 'LBP OUTFLOW', tone: d.u2l ? 'good' : 'crit', val: fmtSignedLBP(d.lbp), sub1: d.u2l ? 'LBP received into cash till' : 'LBP sold from cash till', sub2: `Dual-currency cash till`, pct: 85 },
          { lbl: 'EFFECTIVE FX RATE', tag: 'LL / USD', tone: 'info', val: `${fmtNum(d.rate, 0)} LL/$`, sub1: `Exact Rate: ${fmtNum(d.rate, 2)} LL/$`, sub2: `Tx Date: ${row.date || '—'}`, pct: 80 },
          { lbl: 'AUDIT & LEDGER SOURCE', tag: isAppRecord(row) ? 'WEB APP' : 'SQL LEDGER', tone: 'info', val: isAppRecord(row) ? 'App Entry' : 'Synced Book', sub1: isAppRecord(row) ? `Posted by ${row.entered_by || 'User'}` : `Snapshot ${SEED_DATE}`, sub2: `Cash Till Reconciled`, pct: 100 }
        ]
      };
    }

    if (key === 'equipment_defects') {
      const open = isDefectOpen(row);
      const isCrit = /Grave|Critical/i.test(row.severity || '');
      const h = getEquipmentHealth(row.equipment);
      const sevShort = isCrit ? 'GRAVE' : (/Mild/i.test(row.severity || '') ? 'MILD' : String(row.severity || 'Mild').split(/[-—]/)[0].trim());
      return {
        bu, title, pill: row.status || 'Open',
        cards: [
          { lbl: 'WARNING SEVERITY', tag: open ? (isCrit ? 'GRAVE ISSUE' : 'MILD WARNING') : 'RESOLVED', tone: open ? (isCrit ? 'crit' : 'warn') : 'good', val: sevShort, sub1: `Subsystem: ${row.subsystem || '-'}`, sub2: `Affected Part: ${row.part_name || 'General'}`, pct: isCrit ? 95 : 65 },
          { lbl: 'UNIT LIVE HEALTH', tag: String(h.shortBadge || 'OK').toUpperCase(), tone: h.critCount > 0 ? 'crit' : (h.openCount > 0 ? 'warn' : 'good'), val: row.equipment || '-', sub1: `Health: ${h.status}`, sub2: `Open Warnings on Unit: ${fmtNum(h.openCount)}`, pct: 80 },
          { lbl: 'REPORTED TELEMETRY', tag: row.meter_reading != null ? 'METER LOGGED' : 'INSPECTION', tone: 'info', val: row.meter_reading != null ? fmtNum(row.meter_reading, 0) : (row.date || '-'), sub1: `Reported By: ${row.reported_by || row.entered_by || '-'}`, sub2: `Report Date: ${row.date || '-'}`, pct: 75 },
          { lbl: 'REPAIR / PART LINK', tag: row.linked_part_log ? 'LINKED' : 'AWAITING REPAIR', tone: row.linked_part_log ? 'good' : 'warn', val: row.linked_part_log || 'Pending', sub1: `Resolved Date: ${row.resolved_date || 'Open'}`, sub2: `Pre-Replacement Governance`, pct: row.linked_part_log ? 100 : 40 }
        ]
      };
    }

    if (key === 'equipment_repairs') {
      const whCost = round2(Number(row.warehouse_parts_usd != null ? row.warehouse_parts_usd : (row.warehouse_cost || 0)));
      const outParts = round2(Number(row.outside_parts_usd != null ? row.outside_parts_usd : (row.outside_parts_cost || 0)));
      const outLabor = round2(Number(row.external_labor_usd != null ? row.external_labor_usd : (row.outside_labor_cost || 0)));
      const outCost = round2(outParts + outLabor);
      const totCost = round2(Number(row.total_cost_usd != null ? row.total_cost_usd : (row.total_cost != null ? row.total_cost : (whCost + outCost))));
      return {
        bu, title, pill: fmtUSD(totCost, 2),
        cards: [
          { lbl: 'REPAIR SOURCE', tag: (row.repair_source || 'WAREHOUSE').toUpperCase().slice(0, 18), tone: /Warehouse/i.test(row.repair_source || '') ? 'good' : 'info', val: row.repair_source || 'Warehouse Only', sub1: `Unit: ${row.equipment || '-'} · ${row.subsystem || 'General'}`, sub2: `Workshop / Vendor: ${row.supplier || 'Internal Workshop'}`, pct: 85 },
          { lbl: 'WAREHOUSE STOCK USED', tag: whCost > 0 ? '-STOCK ISSUED' : 'NO STOCK', tone: whCost > 0 ? 'good' : 'info', val: fmtUSD(whCost, 2), sub1: `Items: ${row.items_summary || '-'}`, sub2: `Deducted from live Warehouse`, pct: totCost > 0 ? Math.max(15, Math.round((whCost / totCost) * 100)) : 50 },
          { lbl: 'OUTSIDE PARTS & LABOR', tag: outCost > 0 ? 'OUTSIDE SPEND' : '$0 OUTSIDE', tone: outCost > 0 ? 'warn' : 'good', val: fmtUSD(outCost, 2), sub1: `Outside Parts: ${fmtUSD(outParts, 2)}`, sub2: `Outside Labor: ${fmtUSD(outLabor, 2)}`, pct: totCost > 0 ? Math.max(15, Math.round((outCost / totCost) * 100)) : 30 },
          { lbl: 'TOTAL REPAIR COST', tag: row.defect_ref ? 'LINKED WARNING' : 'REPAIR LOG', tone: 'info', val: fmtUSD(totCost, 2), sub1: `Linked Warning: ${row.defect_ref || 'Direct Repair'}`, sub2: `Tx Date: ${row.date || '-'} · Status: ${row.status || 'Completed'}`, pct: 90 }
        ]
      };
    }

    if (key === 'equipment_oil_logs') {
      const hrsVal = row.hours_reading != null ? row.hours_reading : row.meter_hours;
      const costVal = Number(row.cost_usd != null ? row.cost_usd : (row.cost || 0));
      const dueHrs = row.next_due_hours || (hrsVal != null && Number(row.interval_hours) > 0 ? Number(hrsVal) + Number(row.interval_hours) : null);
      const dueKm = row.next_due_km || (row.odometer_km != null && Number(row.interval_km) > 0 ? Number(row.odometer_km) + Number(row.interval_km) : null);
      const nextDueStr = [dueHrs ? fmtNum(dueHrs, 0) + ' hr' : '', dueKm ? fmtNum(dueKm, 0) + ' km' : '', row.next_due_date || (Number(row.interval_days) > 0 ? 'Every ' + fmtNum(row.interval_days, 0) + ' d' : '')].filter(Boolean).join(' · ') || 'Scheduled';
      const intStr = [row.interval_hours ? fmtNum(row.interval_hours, 0) + ' hr' : '', row.interval_km ? fmtNum(row.interval_km, 0) + ' km' : '', row.interval_days ? fmtNum(row.interval_days, 0) + ' d' : ''].filter(Boolean).join(' · ') || 'Standard';
      return {
        bu, title, pill: `${fmtNum(row.qty || 1, 1)} ${row.uom || 'Litre'}`,
        cards: [
          { lbl: 'OIL / SERVICE TYPE', tag: `${fmtNum(row.qty || 1, 1)} ${row.uom || 'Litre'}`, tone: 'good', val: row.oil_type || 'Engine Oil 15W-40', sub1: `Unit: ${row.equipment || '-'} · ${row.service_action || 'Full Change'}`, sub2: `Source: ${row.source || 'Plant Lube Bay'}`, pct: 85 },
          { lbl: 'METER AT SERVICE', tag: hrsVal != null ? 'HOURS' : (row.odometer_km != null ? 'ODOMETER' : 'DATE'), tone: 'info', val: hrsVal != null ? `${fmtNum(hrsVal, 1)} hr` : (row.odometer_km != null ? `${fmtNum(row.odometer_km, 0)} km` : (row.date || '-')), sub1: `Hours: ${hrsVal != null ? fmtNum(hrsVal, 1) + ' hr' : '-'}`, sub2: `Odometer: ${row.odometer_km != null ? fmtNum(row.odometer_km, 0) + ' km' : '-'}`, pct: 80 },
          { lbl: 'CHANGE INTERVAL', tag: 'PREVENTIVE', tone: 'info', val: intStr, sub1: `Service Date: ${row.date || '-'}`, sub2: `Cost: ${fmtUSD(costVal, 2)}`, pct: 75 },
          { lbl: 'NEXT CHANGE DUE', tag: 'SCHEDULED', tone: 'good', val: nextDueStr, sub1: `Auto-tracked against live meters`, sub2: `Notes: ${row.notes || '-'}`, pct: 90 }
        ]
      };
    }

    if (key === 'warehouse_movements') {
      const isOut = isWarehouseOutMove(row.movement_type || row.move_type, row.direction);
      const mvLbl = formatWarehouseMovementLabel(row.movement_type || row.move_type, row.direction, 'warehouse_movements');
      const whItem = getWarehouseIndex(row.company).byKey[norm(row.item_name)] || null;
      const balQty = whItem ? Number(whItem.onHandQty || 0) : 0;
      return {
        bu, title, pill: `${isOut ? '-' : '+'}${fmtNum(row.qty || 1, 2)} ${row.uom || 'Piece'}`,
        cards: [
          { lbl: 'SHELF ACTION & REASON', tag: isOut ? '-REMOVE FROM SHELF' : '+ADD TO SHELF', tone: isOut ? 'warn' : 'good', val: row.item_name || '-', sub1: `Reason: ${mvLbl}`, sub2: `Shelf: ${row.warehouse_location || row.location || 'WTC Main Warehouse'}`, pct: 85 },
          { lbl: 'ADJUSTMENT QUANTITY', tag: (row.uom || 'PIECE').toUpperCase(), tone: isOut ? 'warn' : 'good', val: `${isOut ? '-' : '+'}${fmtNum(row.qty || 1, 2)} ${row.uom || 'Piece'}`, sub1: `Unit Cost: ${fmtUSD(row.unit_cost || 0, 2)}`, sub2: `Total Value: ${fmtUSD(row.total_cost || 0, 2)}`, pct: 80 },
          { lbl: 'LIVE WAREHOUSE BALANCE', tag: balQty > 0 ? 'IN STOCK' : 'DEPLETED', tone: balQty > 0 ? 'good' : 'warn', val: whItem ? `${fmtNum(balQty, 2)} ${whItem.uom || 'Piece'}` : '0', sub1: whItem ? `Stocked In: ${fmtNum(whItem.stockedInQty || 0, 2)} · Repairs Out: ${fmtNum(whItem.usedInRepairsQty || 0, 2)}` : 'Item summary', sub2: whItem ? `Avg Cost: ${fmtUSD(whItem.avgUnitCost || 0, 2)}` : '-', pct: 75 },
          { lbl: 'RECORD ORIGIN', tag: isOut ? 'SHELF DEDUCTION' : 'SHELF ADDITION', tone: 'info', val: mvLbl, sub1: `Repair Link: ${row.repair_ref || '-'}`, sub2: `Expense Link: ${row.expense_ref || '-'}`, pct: 90 }
        ]
      };
    }

    if (key === 'part_movements') {
      const preOk = Boolean(row.prior_defect_notified || row.defect_ref);
      const outlay = round2(Number(row.new_part_cost || 0) + Number(row.repair_cost || 0));
      const proceeds = round2(Number(row.sale_proceeds || 0));
      return {
        bu, title, pill: row.removed_disposition || 'Tracked',
        cards: [
          { lbl: 'PART & DISPOSITION', tag: `QTY ${fmtNum(row.qty || 1, 0)}`, tone: 'info', val: row.part_name || '—', sub1: `Disposition: ${row.removed_disposition || '—'}`, sub2: `Condition: ${row.condition || '—'}${row.part_serial ? ' · SN ' + row.part_serial : ''}`, pct: 85 },
          { lbl: 'PRE-DEFECT GOVERNANCE', tag: preOk ? 'PRE-NOTIFIED' : 'UNNOTIFIED', tone: preOk ? 'good' : 'warn', val: preOk ? (row.defect_ref || 'Verified') : 'Emergency', sub1: preOk ? 'Prior defect report verified before change' : 'Flagged in AI Sentinel S10', sub2: `Unit: ${row.equipment || '—'} · ${row.subsystem || '—'}`, pct: preOk ? 100 : 45 },
          { lbl: 'CUSTODY & COUNTERPARTY', tag: (row.action_type || 'PART LOG').split('(')[0].trim().toUpperCase().slice(0, 16), tone: 'info', val: row.storage_location || row.vendor_or_buyer || row.equipment || '—', sub1: `Storage / Shelf: ${row.storage_location || '—'}`, sub2: `Workshop / Buyer: ${row.vendor_or_buyer || '—'}`, pct: 75 },
          { lbl: 'PART ECONOMICS ($)', tag: proceeds > 0 ? 'RECOVERY $' : 'COST TRACKED', tone: proceeds > 0 ? 'good' : 'info', val: fmtUSD(outlay - proceeds, 2), sub1: `New Cost: ${fmtUSD(row.new_part_cost || 0, 2)} · Repair: ${fmtUSD(row.repair_cost || 0, 2)}`, sub2: `Sale Proceeds: ${fmtUSD(proceeds, 2)} · Approved: ${row.approved_by || '—'}`, pct: 80 }
        ]
      };
    }

    if (key === 'fuel_malfunctions') {
      const lit = round2(Number(row.litres || 0));
      const tankDelta = round2(-lit);
      const coKey = COMPANY_KEY_BY_NAME[row.company] || 'wtc';
      const dtAll = getDieselTankLedger(coKey, null);
      const ym = String((STATE.basis === 'tx' ? row.date : (row.rep_date || row.date)) || '').slice(0, 7);
      const dtMo = /^\d{4}-\d{2}$/.test(ym) ? getDieselTankLedger(coKey, { from: ym + '-01', to: ym + '-31' }) : dtAll;
      return {
        bu,
        title,
        pill: `${tankDelta > 0 ? '+' : ''}${fmtNum(tankDelta, 1)} L Tank`,
        cards: [
          { lbl: 'DISCREPANCY VOLUME', tag: (row.discrepancy_type || 'MALFUNCTION').toUpperCase(), tone: lit > 0 ? 'warn' : 'good', val: `${lit > 0 ? '+' : ''}${fmtNum(lit, 1)} L`, sub1: lit >= 0 ? 'Tank Shortage / Outflow (-Tank)' : 'Tank Surplus / Over-Read (+Tank)', sub2: `Invoice / Slip: ${row.ticket_no ? '#' + row.ticket_no : '—'}`, pct: 80 },
          { lbl: 'LIVE TANK RECONCILIATION', tag: (dtAll && dtAll.closingTankL < 0) ? 'DEFICIT' : 'RECONCILED', tone: (dtAll && dtAll.closingTankL < 0) ? 'crit' : 'good', val: `${fmtNum(dtAll ? dtAll.closingTankL : 0, 1)} L`, sub1: `Entry Impact: ${tankDelta > 0 ? '+' : ''}${fmtNum(tankDelta, 1)} L`, sub2: `All-Time Disc: ${fmtNum(dtAll ? dtAll.discrepancyL : 0, 1)} L`, pct: 75 },
          { lbl: '5% MALFUNCTION WATCHDOG', tag: dtMo && dtMo.malfunctionAlert ? 'ALERT >= 5%' : 'WITHIN 5%', tone: dtMo && dtMo.malfunctionAlert ? (dtMo.malfunctionSeverity === 'crit' ? 'crit' : 'warn') : 'good', val: `${dtMo ? dtMo.malfunctionPct.toFixed(1) : '0.0'}%`, sub1: `${_formatMonthYmLabel(ym)} Gross Malf: ${fmtNum(dtMo ? dtMo.malfAbsL : 0, 1)} L`, sub2: `Company Used: ${fmtNum(dtMo ? dtMo.companyDieselUsedL : 0, 1)} L`, pct: Math.min(100, Math.max(15, Math.round((dtMo ? dtMo.malfunctionPct : 0) * 10))) },
          { lbl: 'UNIT & AUDIT SOURCE', tag: isAppRecord(row) ? 'WEB APP' : 'SQL LEDGER', tone: 'info', val: row.equipment || 'Plant Tank', sub1: `Driver: ${row.driver || '—'}`, sub2: `Tx: ${row.date || '—'} · Rep: ${row.rep_date || row.date || '—'}`, pct: 90 }
        ]
      };
    }

    if (key === 'gl_accounts') {
      const dr = round2(Number(row.debit || 0));
      const cr = round2(Number(row.credit || 0));
      const bal = round2(Number(row.balance || 0));
      const legs = Number(row.soa_legs || 0);
      return {
        bu: 'ALL BUs',
        title: `GL ${row.code} · ${row.name}`,
        pill: fmtUSD(bal, 2),
        cards: [
          { lbl: 'AUTOMATION ENGINE', tag: (row.automation_mode || 'AUTOMATED').toUpperCase(), tone: row.is_automated !== false ? 'good' : 'info', val: `GL ${row.code}`, sub1: `${row.pcg_class || 'Lebanese PCG'}`, sub2: `Driven By: ${row.source_module || 'Double-Entry Engine'}`, pct: 95 },
          { lbl: 'SCOPED GROSS DEBITS', tag: 'DEBIT LEG', tone: 'info', val: fmtUSD(dr, 2), sub1: `${row.debit_rule || 'Automated debit leg'}`, sub2: `Posted SOA Legs: ${fmtNum(legs)}`, pct: Math.min(100, Math.max(20, (dr + cr) > 0 ? Math.round((dr / (dr + cr)) * 100) : 50)) },
          { lbl: 'SCOPED GROSS CREDITS', tag: 'CREDIT LEG', tone: 'info', val: fmtUSD(cr, 2), sub1: `${row.credit_rule || 'Automated credit leg'}`, sub2: `Zero manual GL input on forms`, pct: Math.min(100, Math.max(20, (dr + cr) > 0 ? Math.round((cr / (dr + cr)) * 100) : 50)) },
          { lbl: 'NET ACCOUNT BALANCE', tag: Math.abs(bal) < 0.005 ? 'CLEARED ($0)' : (bal > 0 ? 'NET DEBIT' : 'NET CREDIT'), tone: Math.abs(bal) < 0.005 ? 'good' : 'info', val: fmtUSD(bal, 2), sub1: `Debit minus Credit in active scope`, sub2: `Tied 1-to-1 to Trial Balance`, pct: 100 }
        ]
      };
    }

    // Generic rich 4-card cockpit for all other 30 tables
    const subgrids = buildInspectorSubgrids(key, row);
    const totalRel = subgrids.reduce((a, sg) => a + sg.rows.length, 0);
    const prMoney = key === 'price_rules'
      ? (Number(row.unit_price || 0) > 0 ? row.unit_price : (Number(row.trans_unit_price || 0) > 0 ? row.trans_unit_price : ruleAnyIndiffPrice(row)))
      : row.unit_price;
    const primaryMoney = row.total_ttc ?? row.total ?? row.amount ?? row.usd_amount ?? prMoney ?? row.salary_usd ?? row.principal ?? row.credit_limit ?? row.list_price;
    const isPendExp = key === 'expenses' && isPendingPriceExpense(row);
    const isDieselExp = key === 'expenses' && isBulkDieselExpense(row);
    return {
      bu,
      title,
      pill: isPendExp ? 'PENDING PRICE ($0.00)' : (primaryMoney != null ? fmtUSD(primaryMoney, 2) : `${fmtNum(totalRel)} Linked Rows`),
      cards: [
        { lbl: 'PRIMARY RECORD VALUE', tag: isPendExp ? 'PENDING PRICE' : (INSPECT_LABELS[key] || key).toUpperCase().slice(0, 18), tone: isPendExp ? 'warn' : 'good', val: isPendExp ? `${fmtNum(row.qty || 1, 0)}${isDieselExp ? ' L ($0.00)' : ' Qty ($0.00)'}` : (primaryMoney != null ? fmtUSD(primaryMoney, 2) : (row.name || row.ticket_no || String(row.id).slice(0, 10))), sub1: isPendExp ? `Vendor: ${row.supplier || '—'} · Awaiting Invoice` : `Entity: ${INSPECT_LABELS[key] || key}`, sub2: `Company Scope: ${row.company || 'Shared / Root BU'}`, pct: 82 },
        { lbl: 'CONNECTED SUBGRIDS', tag: `${subgrids.length} TABLES`, tone: 'info', val: `${fmtNum(totalRel)} Rows`, sub1: subgrids.slice(0, 2).map(s => `${s.shortLabel}: ${fmtNum(s.rows.length)}`).join(' · ') || 'Direct master record', sub2: subgrids.slice(2, 4).map(s => `${s.shortLabel}: ${fmtNum(s.rows.length)}`).join(' · ') || 'Click any row below to inspect', pct: Math.min(100, Math.max(25, totalRel * 5)) },
        { lbl: 'EFFECTIVE DATES & TIMELINE', tag: row.end_date ? 'DATED' : 'ACTIVE', tone: row.end_date && String(row.end_date) < SEED_DATE ? 'warn' : 'good', val: String(row.date || row.start_date || SEED_DATE).slice(0, 10), sub1: `Rep / Start: ${row.rep_date || row.start_date || row.date || '—'}`, sub2: `End Date: ${row.end_date || 'Open / Current'}`, pct: 75 },
        { lbl: 'AUDIT & LEDGER SOURCE', tag: isAppRecord(row) ? 'WEB APP' : 'SQL LEDGER', tone: 'info', val: isAppRecord(row) ? 'App Entry' : 'Synced Book', sub1: isAppRecord(row) ? `Posted by ${row.entered_by || 'User'}` : `Snapshot ${SEED_DATE}`, sub2: `Double-Entry SOA Verified`, pct: 100 }
      ]
    };
  }

  // Build Locked Quick-View Cards (qv_customer, qv_truck, qv_site, qv_rule, qv_supplier) matching m12_forms.py
  function buildInspectorQuickViews(key, row) {
    const cards = [];
    const addCustomerQv = (custName) => {
      if (!custName) return;
      const ci = customerInfo(custName) || {};
      const ct = creditTermsForCustomer(custName);
      cards.push({
        tag: 'QUICK VIEW · CUSTOMER',
        targetKey: 'customers',
        targetVal: custName,
        title: custName,
        kvs: [
          ['Open AR (FIFO)', fmtUSD(ci.ar_balance || 0, 2)],
          ['Overdue 60+d', fmtUSD(ci.ar_60_plus || 0, 0)],
          ['Credit Terms', ct ? `${ct.credit_days || 30}d / ${fmtUSD(ct.credit_limit || 0, 0)}` : (ci.method || 'Credit')],
          ['VAT 11% Reg.', (ci['VAT Registered'] === 'Yes' || ci.vat_registered) ? 'Yes (11%)' : 'No']
        ]
      });
    };
    const addSupplierQv = (supName, roleLbl) => {
      if (!supName || supName === 'Company fleet') return;
      const si = supplierInfo(supName) || {};
      cards.push({
        tag: `QUICK VIEW · ${roleLbl || 'SUPPLIER'}`,
        targetKey: 'suppliers',
        targetVal: supName,
        title: supName,
        kvs: [
          ['Net 3-Leg AP', fmtUSD(si.ap_balance || 0, 2)],
          ['Material / Haul AP', `${fmtUSD(si.ap_material || 0, 0)} / ${fmtUSD(si.ap_haulage || 0, 0)}`],
          ['Registered Trucks', fmtNum(si.trucks_count || (si.trucks || []).length || 0)],
          ['IVA Status', si.iva ? 'IVA Registered' : 'Standard']
        ]
      });
    };
    const addTruckQv = (trkName, drvName) => {
      if (!trkName || trkName === 'Pickup') return;
      const eq = equipInfo(trkName) || {};
      const lm = lastMeter(row.company, trkName, row.date);
      const lmEff = lm ? effectiveFuelMeter(lm) : null;
      cards.push({
        tag: 'QUICK VIEW · TRUCK & FLEET',
        targetKey: 'equipment',
        targetVal: trkName,
        title: `${trkName}${eq.plate_no && eq.plate_no !== trkName ? ' · ' + eq.plate_no : ''}`,
        kvs: [
          ['Ownership / Type', `${eq.ownership || 'Third-Party'} · ${eq.type || 'Truck'}`],
          ['Box Capacity', eq.capacity ? `${fmtNum(eq.capacity, 1)} m³` : 'Standard'],
          ['Owner / Hauler', eq.supplier || row.truck_owner || 'Company Fleet'],
          ['Driver / Meter', `${drvName || eq.default_driver || '—'}${lmEff && lmEff.reading != null ? ' · ' + fmtNum(lmEff.reading, lmEff.type === 'hours' && lmEff.reading % 1 !== 0 ? 1 : 0) + ' ' + lmEff.unit : ''}`]
        ]
      });
    };
    const addSiteQv = (siteName, side) => {
      if (!siteName) return;
      const isCustSide = side === 'sales' || side === 'customer';
      const si = siteInfo(siteName, isCustSide ? 'sales' : (side ? 'raw' : undefined)) || {};
      const effCat = si && si.id ? resolveSiteCategory(si) : (isCustSide ? 'customer' : 'supplier');
      cards.push({
        tag: effCat === 'customer' ? 'QUICK VIEW · CUSTOMER DELIVERY SITE' : 'QUICK VIEW · SUPPLIER / QUARRY SITE',
        targetKey: 'sites',
        targetVal: (si && si.id) || siteName,
        title: siteName,
        kvs: effCat === 'customer'
          ? [
              ['Site Category', 'Customer Delivery Site'],
              ['Region / Zone', si.region || 'Lebanon'],
              ['Linked Customer', si.customer || row.customer || 'Open Delivery'],
              ['Active Sales Rules', fmtNum(activeRulesCountFor('site', siteName, 'sales'))]
            ]
          : [
              ['Site Category', 'Supplier / Quarry Site'],
              ['Region / Zone', si.region || 'Lebanon'],
              ['Site Owner', si.supplier || row.site_owner || 'Open Source'],
              ['JV / Quarry Rules', `${si.is_jv ? 'JV 50/50' : 'Standard'} · ${fmtNum(activeRulesCountFor('site', siteName, 'raw'))} rules`]
            ]
      });
    };
    const addProductQv = (prodName) => {
      if (!prodName) return;
      const pi = productInfo(prodName) || {};
      const lp = listPrice(prodName);
      cards.push({
        tag: 'QUICK VIEW · PRODUCT GRADE',
        targetKey: 'products',
        targetVal: prodName,
        title: prodName,
        kvs: [
          ['Family / UoM', `${pi.type || 'Aggregate'} · ${pi.uom || 'm³'}`],
          ['Tonnage Factor', `${pi.ton_factor || 1.5} t/m³`],
          ['List Price', lp != null ? fmtUSD(lp, 2) : '—'],
          ['Active Rules', fmtNum(activeRulesCountFor('product', prodName))]
        ]
      });
    };

    const addDriverQv = (drvName, roleLbl) => {
      if (!drvName) return;
      const di = driverInfo(drvName) || {};
      const dEqs = (SEED.records.equipment || []).filter(e => norm(e.default_driver) === norm(drvName));
      const dCos = (SEED.records.company_drivers || []).filter(cd => norm(cd.driver) === norm(drvName)).map(cd => cd.company);
      const trkStr = dEqs.map(e => `${e.name}${e.plate_no && norm(e.plate_no) !== norm(e.name) ? ' (' + e.plate_no + ')' : ''}`).join(', ') || di.truck || '—';
      cards.push({
        tag: `QUICK VIEW · ${roleLbl || 'DRIVER'}`,
        targetKey: 'drivers',
        targetVal: drvName,
        title: drvName,
        kvs: [
          ['Truck Owner', di.truck_owner || (dEqs[0] && dEqs[0].supplier) || 'Company Fleet'],
          ['Assigned Truck(s)', trkStr],
          ['Assigned BUs', dCos.length ? dCos.join(', ') : 'Shared'],
          ['Phone / Contact', di.phone || '—']
        ]
      });
    };

    if (key === 'sales_tickets') {
      addCustomerQv(row.customer);
      addProductQv(row.product);
      addSiteQv(row.site, 'sales');
      addTruckQv(row.truck, row.driver);
    } else if (key === 'raw_purchases') {
      addSiteQv(row.site, 'raw');
      addSupplierQv(row.site_owner, 'SITE OWNER');
      if (row.truck_owner && row.truck_owner !== row.site_owner) addSupplierQv(row.truck_owner, 'HAULER');
      addTruckQv(row.truck, row.driver);
    } else if (key === 'fuel_intakes') {
      addTruckQv(row.equipment, row.driver);
      addProductQv(row.item || 'Diesel');
    } else if (key === 'price_rules') {
      const isRawRule = /^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(String(row.rule_type || '').trim());
      if (row.customer) addCustomerQv(row.customer);
      if (row.supplier) addSupplierQv(row.supplier, 'SUPPLIER');
      if (row.product) addProductQv(row.product);
      if (row.site) addSiteQv(row.site, isRawRule ? 'raw' : 'sales');
    } else if (key === 'sites') {
      if (resolveSiteCategory(row) === 'customer') {
        if (row.customer) addCustomerQv(row.customer);
      } else if (row.supplier) {
        addSupplierQv(row.supplier, 'SITE OWNER');
      }
    } else if (key === 'receipts' || key === 'credit_terms' || key === 'vat_invoices') {
      addCustomerQv(row.customer);
    } else if (key === 'settlements') {
      addSupplierQv(row.supplier, 'SUPPLIER');
    } else if (key === 'expenses') {
      if (row.supplier) addSupplierQv(row.supplier, 'VENDOR');
      if (row.equipment) addTruckQv(row.equipment, null);
    } else if (key === 'equipment') {
      if (row.supplier) addSupplierQv(row.supplier, 'TRUCK OWNER');
      if (row.default_driver) addDriverQv(row.default_driver, 'DEFAULT DRIVER');
    } else if (key === 'company_equipment') {
      addTruckQv(row.equipment, row.default_driver);
      if (row.supplier) addSupplierQv(row.supplier, 'OWNER');
      if (row.default_driver) addDriverQv(row.default_driver, 'DEFAULT DRIVER');
      if (row.site) addSiteQv(row.site, 'raw');
    } else if (key === 'drivers' || key === 'company_drivers') {
      const drvName = row.driver || row.name;
      const dObj = driverInfo(drvName) || row;
      if (dObj.truck_owner) addSupplierQv(dObj.truck_owner, 'TRUCK OWNER');
      const dEqs = (SEED.records.equipment || []).filter(e => norm(e.default_driver) === norm(drvName));
      dEqs.slice(0, 2).forEach(eq => addTruckQv(eq.name, drvName));
    } else if (key === 'suppliers') {
      const sName = row.name || row.Supplier;
      const sEqs = (SEED.records.equipment || []).filter(e => normOwnerName(e.supplier) === normOwnerName(sName));
      sEqs.slice(0, 2).forEach(eq => addTruckQv(eq.name, eq.default_driver));
    } else if (key === 'equipment_defects') {
      addTruckQv(row.equipment, row.reported_by);
      if (row.reported_by) addDriverQv(row.reported_by, 'REPORTED BY');
    } else if (key === 'part_movements') {
      addTruckQv(row.equipment, null);
      if (row.vendor_or_buyer) addSupplierQv(row.vendor_or_buyer, 'WORKSHOP / BUYER');
    } else if (key === 'fuel_malfunctions') {
      if (row.equipment) addTruckQv(row.equipment, row.driver);
      if (row.driver) addDriverQv(row.driver, 'DRIVER / OPERATOR');
    }
    return cards;
  }

  // Build Interactive Related Subgrids for any record across all 34 tables (bhf_related_subgrids.py parity)
  function buildInspectorSubgrids(key, row) {
    const subgrids = [];
    const rec = SEED.records || {};
    const allowedCos = allowedCompanyNames();
    const addGrid = (id, title, shortLabel, relBadge, targetKey, rows, cols, sumCol) => {
      if (!rows) return;
      if (targetKey && !canAccessTable(targetKey)) return;
      const scoped = rows.filter(r => !r || (!r.voided && (!r.company || allowedCos.includes(r.company)))).slice();
      if (scoped.length > 1) {
        const viewId = targetKey ? ('tbl_' + targetKey) : '';
        const hasDate = Array.isArray(cols) && cols.includes('date');
        const hasStartDate = !hasDate && (targetKey === 'employments' || targetKey === 'logistics_allowances') && Array.isArray(cols) && cols.includes('start_date');
        scoped.sort((a, b) => {
          if (hasDate) {
            const da = recordDate(a), db = recordDate(b);
            if (da !== db) return db < da ? -1 : 1;
          } else if (hasStartDate) {
            const sa = String(a.start_date || ''), sb = String(b.start_date || '');
            if (sa !== sb) {
              if (!sa) return 1;
              if (!sb) return -1;
              return sb < sa ? -1 : 1;
            }
          }
          if (sumCol) {
            const va = Number(a[sumCol] != null ? a[sumCol] : (resolveColVal(a, sumCol, viewId) || 0));
            const vb = Number(b[sumCol] != null ? b[sumCol] : (resolveColVal(b, sumCol, viewId) || 0));
            if (Number.isFinite(va) && Number.isFinite(vb) && va !== vb) return vb - va;
          }
          return compareRowTie(a, b, hasStartDate ? 'start_date' : (sumCol || (hasDate ? 'date' : '')), viewId);
        });
      }
      const cleanBadge = String(relBadge || '')
        .replace(/^\s*(?:1:N|N:1|N:N)\s*/i, '')
        .replace(/\bbhf_[a-z0-9_]+\b/gi, '')
        .replace(/\bM\d+\b\s*/gi, '')
        .trim();
      subgrids.push({ id, title, shortLabel, relBadge: cleanBadge || shortLabel, targetKey, rows: scoped, cols, sumCol });
    };

    if (key === 'sales_tickets') {
      const custRules = (rec.price_rules || []).filter(r => !isCommRule(r) && !/^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(r.rule_type || '') && ((row.customer && norm(r.customer) === norm(row.customer)) || (row.product && norm(r.product) === norm(row.product) && !r.customer)));
      const sibTickets = (rec.sales_tickets || []).filter(t => norm(t.customer) === norm(row.customer) && String(t.id) !== String(row.id));
      const custRcpts = (rec.receipts || []).filter(r => norm(r.customer) === norm(row.customer));
      const custVat = (rec.vat_invoices || []).filter(v => norm(v.customer) === norm(row.customer));
      const trkFuel = row.truck ? (rec.fuel_intakes || []).filter(f => norm(f.equipment) === norm(row.truck)) : [];

      addGrid('sg_rules', `Matching Price Agreements (${row.customer || row.product})`, 'Price Rules', 'Rule Lookup', 'price_rules', custRules, ['company', 'rule_type', 'customer', 'product', 'site', 'unit', 'unit_price', 'trans_unit_price', 'start_date', 'end_date'], 'unit_price');
      addGrid('sg_sib_sales', `Other Sales Tickets for ${row.customer || 'Customer'}`, 'Customer Tickets', 'Sibling Loads', 'sales_tickets', sibTickets, ['date', 'ticket_no', 'company', 'sale_type', 'product', 'site', 'truck', 'qty', 'unit_price', 'total_ttc', 'method'], 'total_ttc');
      addGrid('sg_rcpts', `Customer Receipts & FIFO Settlements (${row.customer})`, 'AR Receipts', 'FIFO Relief', 'receipts', custRcpts, ['date', 'name', 'company', 'method', 'amount', 'discount', 'vat_invoice', 'reference'], 'amount');
      addGrid('sg_vat', `Customer VAT 11% Tax Invoices (${row.customer})`, 'VAT Invoices', 'Tax Billing', 'vat_invoices', custVat, ['invoice_no', 'date', 'company', 'start_date', 'end_date', 'net_amount', 'vat_amount', 'total_ttc'], 'total_ttc');
      if (row.truck) addGrid('sg_trk_fuel', `Fuel & Meter Log for Truck ${row.truck}`, 'Truck Fuel Log', 'Fleet Telemetry', 'fuel_intakes', trkFuel, ['date', 'ticket_no', 'company', 'equipment', 'driver', 'item', 'litres', 'odometer'], 'litres');
    }
    else if (key === 'raw_purchases') {
      const rawRules = (rec.price_rules || []).filter(r => /^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(r.rule_type || '') && ((row.site_owner && norm(r.supplier) === norm(row.site_owner)) || (row.truck_owner && norm(r.supplier) === norm(row.truck_owner)) || (row.site && norm(r.site) === norm(row.site))));
      const siteLoads = (rec.raw_purchases || []).filter(t => norm(t.site) === norm(row.site) && String(t.id) !== String(row.id));
      const suppSettle = (rec.settlements || []).filter(s => (row.site_owner && norm(s.supplier) === norm(row.site_owner)) || (row.truck_owner && norm(s.supplier) === norm(row.truck_owner)));

      addGrid('sg_raw_rules', `Site & Hauler Price Agreements (${row.site || row.site_owner})`, 'Site Rules', 'Rule Lookup', 'price_rules', rawRules, ['company', 'rule_type', 'supplier', 'product', 'site', 'unit', 'unit_price', 'trans_unit_price', 'start_date', 'end_date'], 'unit_price');
      addGrid('sg_site_loads', `Other Raw Material Purchases from ${row.site || 'Site'}`, 'Raw Loads', 'Sibling Loads', 'raw_purchases', siteLoads, ['date', 'ticket_no', 'company', 'site_owner', 'truck_owner', 'truck', 'product', 'qty', 'cost', 'trans_cost', 'total'], 'total');
      addGrid('sg_supp_settle', `Supplier Settlements for ${row.site_owner || row.truck_owner}`, 'AP Settlements', '3-Leg AP Relief', 'settlements', suppSettle, ['date', 'name', 'company', 'supplier', 'method', 'amount', 'discount', 'reference'], 'amount');
    }
    else if (key === 'customers') {
      const name = row.name || row.Customer;
      addGrid('sg_c_sales', `Sales Tickets & Deliveries (${name})`, 'Sales Tickets', 'Sales Tickets', 'sales_tickets', (rec.sales_tickets || []).filter(t => norm(t.customer) === norm(name)), ['date', 'ticket_no', 'company', 'sale_type', 'product', 'site', 'truck', 'qty', 'unit_price', 'vat', 'total_ttc', 'method'], 'total_ttc');
      addGrid('sg_c_rcpts', `Customer Receipts — FIFO Applied (${name})`, 'AR Receipts', 'AR Receipts', 'receipts', (rec.receipts || []).filter(r => norm(r.customer) === norm(name)), ['date', 'name', 'company', 'method', 'amount', 'discount', 'vat_invoice', 'reference'], 'amount');
      addGrid('sg_c_rules', `Price Agreements (${name})`, 'Price Rules', 'Price Rules', 'price_rules', (rec.price_rules || []).filter(r => norm(r.customer) === norm(name) && !isCommRule(r)), ['company', 'rule_type', 'product', 'site', 'unit', 'unit_price', 'trans_unit_price', 'start_date', 'end_date'], 'unit_price');
      addGrid('sg_c_cred', `Credit Terms & Limits (${name})`, 'Credit Terms', 'Credit Terms', 'credit_terms', (rec.credit_terms || []).filter(c => norm(c.customer) === norm(name)), ['name', 'company', 'credit_days', 'credit_limit', 'start_date', 'end_date', 'notes'], 'credit_limit');
      addGrid('sg_c_vat', `VAT 11% Tax Invoices (${name})`, 'VAT Invoices', 'VAT Invoices', 'vat_invoices', (rec.vat_invoices || []).filter(v => norm(v.customer) === norm(name)), ['invoice_no', 'date', 'company', 'start_date', 'end_date', 'net_amount', 'vat_amount', 'total_ttc'], 'total_ttc');
    }
    else if (key === 'suppliers') {
      const name = row.name || row.Supplier;
      addGrid('sg_s_mat', `Leg 1 · Raw Material Purchases (${name})`, 'Raw Loads', 'Site Owner Leg', 'raw_purchases', (rec.raw_purchases || []).filter(r => norm(r.site_owner || r.truck_owner) === norm(name) && (r.site_owner || Number(r.cost || 0) !== 0)), ['date', 'ticket_no', 'company', 'site', 'product', 'truck', 'qty', 'unit_cost', 'cost', 'total'], 'cost');
      addGrid('sg_s_haul', `Leg 2 · Haulage Loads (${name})`, 'Haulage Loads', 'Truck Owner Leg', 'raw_purchases', (rec.raw_purchases || []).filter(r => norm(r.truck_owner) === norm(name) && (Number(r.trans_cost || 0) !== 0 || r.transport_by !== 'Company fleet')), ['date', 'ticket_no', 'company', 'site', 'site_owner', 'truck', 'driver', 'qty', 'trans_cost', 'total'], 'trans_cost');
      addGrid('sg_s_exp', `Leg 3 · General & Fleet Expenses (${name})`, 'Expenses', 'Expense Leg', 'expenses', (rec.expenses || []).filter(x => norm(x.supplier) === norm(name)), ['date', 'name', 'company', 'category', 'subcategory', 'equipment', 'method', 'amount', 'reference'], 'amount');
      addGrid('sg_s_pay', `Supplier AP Settlements (${name})`, 'Settlements', 'Settlements', 'settlements', (rec.settlements || []).filter(s => norm(s.supplier) === norm(name)), ['date', 'name', 'company', 'method', 'amount', 'discount', 'raw_ticket', 'expense_record', 'reference'], 'amount');
      const commVouchersForSup = (rec.receipts || []).filter(r => norm(r.customer) === norm(name) && ['Rent', 'VATRent', 'RentConfig'].includes(String(r.method || '').trim()));
      if (commVouchersForSup.length) {
        addGrid('sg_s_comm_rcpt', `Plant Commission & 11% VAT Settlements (${name})`, 'Commission Payouts', 'GL 6222 & 449', 'receipts', commVouchersForSup, ['date', 'name', 'company', 'method', 'amount', 'discount', 'reference'], 'amount');
      }
      const supRules = (rec.price_rules || []).filter(r => norm(r.supplier) === norm(name));
      const allCommSup = supRules.length > 0 && supRules.every(isCommRule);
      addGrid(
        'sg_s_rules',
        allCommSup ? `Sales Commission Rules (${name})` : `Price & Commission Agreements (${name})`,
        allCommSup ? 'Commission Rules' : 'Price Rules',
        allCommSup ? 'Commission Schedule' : 'Price Rules',
        'price_rules',
        supRules,
        allCommSup ? ['company', 'product', 'unit', 'unit_price', 'start_date', 'end_date'] : ['company', 'rule_type', 'product', 'site', 'unit', 'unit_price', 'trans_unit_price', 'start_date', 'end_date'],
        'unit_price'
      );
      addGrid('sg_s_eq', `Registered Trucks & Equipment (${name})`, 'Trucks', 'Trucks & Equipment', 'equipment', (rec.equipment || []).filter(e => norm(e.supplier) === norm(name)), ['name', 'plate_no', 'type', 'ownership', 'capacity', 'default_driver'], 'capacity');
      addGrid('sg_s_drv', `Registered Drivers (${name})`, 'Drivers', 'Drivers', 'drivers', (rec.drivers || []).filter(d => norm(d.truck_owner) === norm(name)), ['name', 'truck', 'phone', 'truck_owner', 'notes'], null);
    }
    else if (key === 'products' || key === 'product_types' || key === 'uoms') {
      const name = row.name || row.Product;
      const matchField = key === 'product_types' ? 'type' : (key === 'uoms' ? 'uom' : 'product');
      if (key !== 'products') {
        addGrid('sg_p_prods', `Products in ${name}`, 'Products', 'Products', 'products', (rec.products || []).filter(p => norm(p[matchField]) === norm(name)), ['name', 'type', 'uom', 'ton_factor', 'ticket_product', 'fuel_item'], 'ton_factor');
      }
      addGrid('sg_p_rules', `Price Agreements for ${name}`, 'Price Rules', 'Price Rules', 'price_rules', (rec.price_rules || []).filter(r => norm(r.product) === norm(name) && !isCommRule(r)), ['company', 'rule_type', 'customer', 'supplier', 'site', 'unit', 'unit_price', 'trans_unit_price', 'start_date', 'end_date'], 'unit_price');
      addGrid('sg_p_sales', `Sales Tickets (${name})`, 'Sales Tickets', 'Sales Tickets', 'sales_tickets', (rec.sales_tickets || []).filter(t => norm(t.product) === norm(name) || norm(t.uom) === norm(name)), ['date', 'ticket_no', 'company', 'customer', 'site', 'truck', 'qty', 'unit_price', 'total_ttc'], 'total_ttc');
      addGrid('sg_p_raw', `Raw Material Purchases (${name})`, 'Raw Purchases', 'Raw Purchases', 'raw_purchases', (rec.raw_purchases || []).filter(t => norm(t.product) === norm(name) || norm(t.uom) === norm(name)), ['date', 'ticket_no', 'company', 'site', 'site_owner', 'truck', 'qty', 'unit_cost', 'total'], 'total');
    }
    else if (key === 'sites' || key === 'regions') {
      const name = row.name || row.Site;
      if (key === 'regions') {
        addGrid('sg_r_sites', `Sites in Region ${name}`, 'Sites', 'Sites', 'sites', (rec.sites || []).filter(s => norm(s.region) === norm(name)), ['name', 'site_category', 'region', 'supplier', 'customer', 'is_jv', 'latitude', 'longitude'], null);
        addGrid('sg_r_ot', `Driver Trip & Overtime Rates (${name})`, 'Overtime Rates', 'Overtime Rates', 'overtime_rates', (rec.overtime_rates || []).filter(o => norm(o.region) === norm(name)), ['name', 'company', 'region', 'amount', 'start_date', 'end_date'], 'amount');
      } else if (resolveSiteCategory(row) === 'customer') {
        addGrid('sg_st_rules', `Sales & Delivery Agreements at ${name}`, 'Sales Rules', 'Sales Rules', 'price_rules', (rec.price_rules || []).filter(r => norm(r.site) === norm(name) && !isCommRule(r) && !/^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(String(r.rule_type || '').trim())), ['company', 'rule_type', 'customer', 'product', 'unit', 'unit_price', 'trans_unit_price', 'start_date', 'end_date'], 'unit_price');
        addGrid('sg_st_sales', `Sales Deliveries to ${name}`, 'Sales Deliveries', 'Sales Deliveries', 'sales_tickets', (rec.sales_tickets || []).filter(t => norm(t.site) === norm(name)), ['date', 'ticket_no', 'company', 'customer', 'product', 'truck', 'qty', 'trans_price', 'total_ttc'], 'total_ttc');
      } else {
        addGrid('sg_st_rules', `Quarry & Haulage Agreements at ${name}`, 'Quarry Rules', 'Quarry Rules', 'price_rules', (rec.price_rules || []).filter(r => norm(r.site) === norm(name) && /^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(String(r.rule_type || '').trim())), ['company', 'rule_type', 'supplier', 'product', 'unit', 'unit_price', 'trans_unit_price', 'start_date', 'end_date'], 'unit_price');
        addGrid('sg_st_raw', `Raw Material Loads from ${name}`, 'Raw Loads', 'Raw Loads', 'raw_purchases', (rec.raw_purchases || []).filter(t => norm(t.site) === norm(name)), ['date', 'ticket_no', 'company', 'site_owner', 'truck_owner', 'truck', 'product', 'qty', 'cost', 'trans_cost', 'total'], 'total');
        addGrid('sg_st_jv', `JV Partnerships & Profit Split (${name})`, 'JV Partners', 'JV Partners', 'jv_partnerships', (rec.jv_partnerships || []).filter(j => norm(j.site) === norm(name)), ['name', 'company', 'partner', 'percentage', 'notes'], 'percentage');
        addGrid('sg_st_log', `Site Transport (${name})`, 'Site Transport', 'Site Transport', 'logistics_allowances', (rec.logistics_allowances || []).filter(l => norm(l.site) === norm(name)), ['name', 'company', 'staff', 'equipment', 'daily_usd', 'working_days', 'start_date', 'end_date'], 'daily_usd');
      }
    }
    else if (key === 'equipment' || key === 'company_equipment') {
      const name = row.equipment || row.name || row.Equipment;
      addGrid('sg_eq_defects', `Equipment Warnings & Defects (${name})`, 'Warnings', 'Health & Issues', 'equipment_defects', (rec.equipment_defects || []).filter(d => norm(d.equipment) === norm(name)), ['name', 'date', 'company', 'subsystem', 'part_name', 'severity', 'status', 'description'], null);
      addGrid('sg_eq_repairs', `Equipment Repairs (${name})`, 'Repairs', 'Repairs & Stock', 'equipment_repairs', (rec.equipment_repairs || []).filter(r => norm(r.equipment) === norm(name)), ['name', 'date', 'company', 'repair_source', 'subsystem', 'items_summary', 'warehouse_parts_usd', 'outside_parts_usd', 'external_labor_usd', 'total_cost_usd'], 'total_cost_usd');
      addGrid('sg_eq_oil', `Oil & Preventive Service Logs (${name})`, 'Oil Logs', 'Preventive Service', 'equipment_oil_logs', (rec.equipment_oil_logs || []).filter(o => norm(o.equipment) === norm(name)), ['name', 'date', 'company', 'oil_type', 'service_action', 'qty', 'hours_reading', 'odometer_km', 'interval_hours', 'interval_km', 'interval_days', 'cost_usd'], 'cost_usd');
      addGrid('sg_eq_parts', `Part Changes, Removals & Custody (${name})`, 'Part Custody', 'Parts Lifecycle', 'part_movements', (rec.part_movements || []).filter(p => norm(p.equipment) === norm(name)), ['name', 'date', 'company', 'action_type', 'part_name', 'qty', 'condition', 'removed_disposition', 'new_part_cost', 'sale_proceeds'], 'new_part_cost');
      addGrid('sg_eq_co', `Company-Equipment Assignments (${name})`, 'BU Assignments', 'BU Assignments', 'company_equipment', (rec.company_equipment || []).filter(ce => norm(ce.equipment) === norm(name)), ['company', 'equipment', 'ownership', 'status', 'supplier', 'default_driver', 'site', 'start_date', 'end_date'], null);
      addGrid('sg_eq_sales', `Sales Loads Hauled by ${name}`, 'Sales Loads', 'Sales Loads', 'sales_tickets', (rec.sales_tickets || []).filter(t => norm(t.truck) === norm(name)), ['date', 'ticket_no', 'company', 'customer', 'product', 'site', 'driver', 'qty', 'trans_price', 'total_ttc'], 'total_ttc');
      addGrid('sg_eq_raw', `Raw Material Loads Hauled by ${name}`, 'Raw Loads', 'Raw Loads', 'raw_purchases', (rec.raw_purchases || []).filter(t => norm(t.truck) === norm(name)), ['date', 'ticket_no', 'company', 'site', 'site_owner', 'truck_owner', 'driver', 'product', 'qty', 'trans_cost', 'total'], 'total');
      addGrid('sg_eq_fuel', `Fuel & Lubricant Intakes + Meter Log (${name})`, 'Fuel & Meters', 'Fuel & Meters', 'fuel_intakes', (rec.fuel_intakes || []).filter(f => norm(f.equipment) === norm(name)), ['date', 'ticket_no', 'company', 'driver', 'item', 'litres', 'odometer', 'hours'], 'litres');
      addGrid('sg_eq_exp', `Maintenance, Spare Parts & Fleet Expenses (${name})`, 'Fleet Expenses', 'Fleet Expenses', 'expenses', (rec.expenses || []).filter(x => norm(x.equipment) === norm(name)), ['date', 'name', 'company', 'category', 'subcategory', 'supplier', 'method', 'amount', 'reference'], 'amount');
    }
    else if (key === 'equipment_defects' || key === 'part_movements' || key === 'equipment_repairs' || key === 'equipment_oil_logs') {
      const eq = row.equipment;
      if (key === 'equipment_repairs') {
        const rItems = (rec.repair_items || []).filter(i => String(i.repair_id) === String(row.id) || norm(i.repair_ref) === norm(row.name));
        addGrid('sg_rep_items', `Items Used in Repair (${row.name})`, 'Items Used', 'Repair Breakdown', 'repair_items', rItems, ['name', 'item_name', 'source', 'qty', 'uom', 'unit_cost', 'line_total'], 'line_total');
      }
      addGrid('sg_m_defects', `All Warnings & Defects on ${eq}`, 'Unit Warnings', 'Health Log', 'equipment_defects', (rec.equipment_defects || []).filter(d => norm(d.equipment) === norm(eq)), ['name', 'date', 'company', 'subsystem', 'part_name', 'severity', 'status', 'linked_part_log'], null);
      addGrid('sg_m_repairs', `All Repairs on ${eq}`, 'Unit Repairs', 'Repairs & Stock', 'equipment_repairs', (rec.equipment_repairs || []).filter(r => norm(r.equipment) === norm(eq)), ['name', 'date', 'company', 'repair_source', 'subsystem', 'items_summary', 'warehouse_parts_usd', 'outside_parts_usd', 'external_labor_usd', 'total_cost_usd'], 'total_cost_usd');
      addGrid('sg_m_oil', `Oil & Preventive Service Logs on ${eq}`, 'Oil Logs', 'Preventive Service', 'equipment_oil_logs', (rec.equipment_oil_logs || []).filter(o => norm(o.equipment) === norm(eq)), ['name', 'date', 'company', 'oil_type', 'service_action', 'qty', 'hours_reading', 'odometer_km', 'interval_hours', 'interval_km', 'interval_days', 'cost_usd'], 'cost_usd');
      addGrid('sg_m_parts', `All Part Movements & Dispositions on ${eq}`, 'Unit Parts', 'Parts Custody', 'part_movements', (rec.part_movements || []).filter(p => norm(p.equipment) === norm(eq)), ['name', 'date', 'company', 'action_type', 'part_name', 'qty', 'condition', 'removed_disposition', 'defect_ref', 'new_part_cost', 'sale_proceeds'], 'new_part_cost');
      addGrid('sg_m_exp', `Maintenance & Spare Parts Expenses (${eq})`, 'Fleet Expenses', 'Expense Ledger', 'expenses', (rec.expenses || []).filter(x => norm(x.equipment) === norm(eq)), ['date', 'name', 'company', 'category', 'subcategory', 'supplier', 'method', 'amount', 'reference'], 'amount');
    }
    else if (key === 'warehouse_movements' || key === 'expense_items' || key === 'repair_items') {
      const itName = row.item_name;
      if (itName) {
        addGrid('sg_wh_moves', `Warehouse Stock Movements (${itName})`, 'Stock Ledger', 'Warehouse +IN / -OUT', 'warehouse_movements', (rec.warehouse_movements || []).filter(m => norm(m.item_name) === norm(itName)), ['date', 'name', 'company', 'movement_type', 'qty', 'uom', 'unit_cost', 'total_cost', 'equipment', 'repair_ref', 'expense_ref'], 'total_cost');
        addGrid('sg_wh_repitems', `Repairs Using ${itName}`, 'Used in Repairs', 'Repair Consumption', 'repair_items', (rec.repair_items || []).filter(ri => norm(ri.item_name) === norm(itName)), ['date', 'repair_ref', 'company', 'equipment', 'source', 'qty', 'uom', 'unit_cost', 'line_total'], 'line_total');
        addGrid('sg_wh_expitems', `Expense Invoices Purchasing ${itName}`, 'Purchase Lines', 'Expense Items', 'expense_items', (rec.expense_items || []).filter(ei => norm(ei.item_name) === norm(itName)), ['date', 'expense_ref', 'company', 'supplier', 'allocation_mode', 'target_equipment', 'qty', 'uom', 'unit_cost', 'line_total'], 'line_total');
      }
    }
    else if (key === 'drivers' || key === 'company_drivers') {
      const name = row.driver || row.name;
      const coEqNames = new Set((rec.company_equipment || []).filter(ce => norm(ce.default_driver) === norm(name)).map(ce => norm(ce.equipment)));
      addGrid('sg_d_co', `Company-Driver Assignments (${name})`, 'BU Assignments', 'BU Assignments', 'company_drivers', (rec.company_drivers || []).filter(cd => norm(cd.driver) === norm(name)), ['company', 'driver', 'staff', 'start_date', 'end_date', 'notes'], null);
      addGrid('sg_d_eq', `Assigned Trucks & Equipment (${name})`, 'Trucks', 'Trucks & Equipment', 'equipment', (rec.equipment || []).filter(e => norm(e.default_driver) === norm(name) || coEqNames.has(norm(e.name))), ['name', 'plate_no', 'type', 'ownership', 'capacity', 'supplier'], 'capacity');
      addGrid('sg_d_sales', `Sales Deliveries Driven by ${name}`, 'Sales Trips', 'Sales Trips', 'sales_tickets', (rec.sales_tickets || []).filter(t => norm(t.driver) === norm(name)), ['date', 'ticket_no', 'company', 'customer', 'product', 'site', 'truck', 'qty', 'total_ttc'], 'total_ttc');
      addGrid('sg_d_raw', `Raw Loads Driven by ${name}`, 'Raw Trips', 'Raw Trips', 'raw_purchases', (rec.raw_purchases || []).filter(t => norm(t.driver) === norm(name)), ['date', 'ticket_no', 'company', 'site', 'truck', 'product', 'qty', 'total'], 'total');
      addGrid('sg_d_fuel', `Fuel Intakes Signed by ${name}`, 'Fuel Log', 'Fuel Log', 'fuel_intakes', (rec.fuel_intakes || []).filter(f => norm(f.driver) === norm(name)), ['date', 'ticket_no', 'company', 'equipment', 'item', 'litres', 'odometer'], 'litres');
    }
    else if (key === 'price_rules') {
      const isCommPr = /^commission$/i.test(String(row.rule_type || '').trim());
      const isQuarryPr = !isCommPr && /^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(String(row.rule_type || '').trim());
      const prLabel = `${row.customer || row.supplier || row.site || 'Standard List'}${row.product ? ' · ' + row.product : ''}`;
      if (isQuarryPr) {
        const mRaw = (rec.raw_purchases || []).filter(t =>
          (!row.company || norm(t.company) === norm(row.company)) &&
          ((row.supplier && (norm(t.site_owner) === norm(row.supplier) || norm(t.truck_owner) === norm(row.supplier))) || (row.site && norm(t.site) === norm(row.site))) &&
          (!row.product || norm(t.product) === norm(row.product))
        );
        addGrid('sg_pr_raw', `Raw Material Tickets Governed by Rule (${prLabel})`, 'Matched Raw', 'Rule Execution', 'raw_purchases', mRaw, ['date', 'ticket_no', 'company', 'site', 'site_owner', 'truck_owner', 'product', 'qty', 'unit_cost', 'total'], 'total');
      } else {
        const mSales = (rec.sales_tickets || []).filter(t =>
          (!row.company || norm(t.company) === norm(row.company)) &&
          (!row.customer || norm(t.customer) === norm(row.customer)) &&
          (!row.product || norm(t.product) === norm(row.product)) &&
          (!row.site || norm(t.site) === norm(row.site)) &&
          (!isCommPr || ((!row.start_date || String(t.date || '').slice(0, 10) >= String(row.start_date).slice(0, 10)) && (!row.end_date || String(t.date || '').slice(0, 10) <= String(row.end_date).slice(0, 10))))
        );
        addGrid('sg_pr_sales', `Sales Tickets Governed by Rule (${prLabel})`, 'Matched Sales', 'Rule Execution', 'sales_tickets', mSales, ['date', 'ticket_no', 'company', 'customer', 'product', 'site', 'qty', 'unit_price', 'trans_price', 'total_ttc'], 'total_ttc');
        if (isCommPr && row.supplier) {
          const commRcpts = (rec.receipts || []).filter(r => norm(r.customer) === norm(row.supplier) && ['Rent', 'VATRent', 'RentConfig'].includes(String(r.method || '').trim()));
          addGrid('sg_pr_comm_rcpt', `Commission Payout Vouchers (${row.supplier})`, 'Commission Payouts', 'GL 6222 & 449', 'receipts', commRcpts, ['date', 'name', 'company', 'method', 'amount', 'discount', 'reference'], 'amount');
        }
      }
    }
    else if (['employments', 'salaries', 'attendance', 'logistics_allowances', 'freelance_entries'].includes(key)) {
      const staff = row.staff || row.name;
      const staffNorm = norm(staff);
      const staffKeys = new Set([staffNorm]);
      const addAliasKey = v => { const k = String(v || '').toLowerCase().replace(/[^a-z0-9]/g, ''); if (k) staffKeys.add(k); };
      addAliasKey(staff);
      Object.entries(WF_DRV_ALIASES).forEach(([a, b]) => {
        const ka = a.toLowerCase().replace(/[^a-z0-9]/g, '');
        const kb = b.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (staffKeys.has(ka) || staffKeys.has(kb)) { staffKeys.add(ka); staffKeys.add(kb); }
      });
      const matchStaffName = v => {
        if (!v) return false;
        if (norm(v) === staffNorm) return true;
        const kv = String(v).toLowerCase().replace(/[^a-z0-9]/g, '');
        return Boolean(kv && staffKeys.has(kv));
      };
      addGrid('sg_w_emp', `Employment & Freelance Contracts (${staff})`, 'Contracts', 'Contracts', 'employments', (rec.employments || []).filter(e => matchStaffName(e.staff || e.name)), ['name', 'company', 'staff', 'role', 'type', 'status', 'salary_usd', 'daily_rate', 'start_date', 'end_date'], 'salary_usd');
      addGrid('sg_w_sal', `Salary Payments (${staff})`, 'Salary Payments', 'Salary Payments', 'salaries', (rec.salaries || []).filter(s => matchStaffName(s.staff)), ['date', 'payroll_month', 'company', 'staff', 'method', 'amount', 'notes'], 'amount');
      addGrid('sg_w_att', `Attendance & Overtime Log (${staff})`, 'Attendance', 'Attendance', 'attendance', (rec.attendance || []).filter(a => matchStaffName(a.staff)), ['date', 'company', 'status', 'in_time', 'out_time', 'worked_hours', 'regular_hours', 'overtime_hours', 'late_hours', 'leave_days', 'extra_usd', 'notes'], 'overtime_hours');
      addGrid('sg_w_log', `Equipment Sites Log (${staff})`, 'Sites Log', 'Equipment Sites Log', 'logistics_allowances', (rec.logistics_allowances || []).filter(l => matchStaffName(l.staff)), ['name', 'company', 'site', 'equipment', 'daily_usd', 'working_days', 'start_date', 'end_date'], 'daily_usd');
      addGrid('sg_w_fl', `Freelance Work (${staff})`, 'Freelance', 'Freelance', 'freelance_entries', (rec.freelance_entries || []).filter(f => matchStaffName(f.staff)), ['date', 'company', 'hours', 'extra_hours', 'rate_usd', 'total', 'notes'], 'total');
    }
    else if (key === 'expense_categories' || key === 'expense_subcategories' || key === 'expenses') {
      const cat = row.category || row.name;
      if (key === 'expenses') {
        const expLines = (rec.expense_items || []).filter(i => String(i.expense_id) === String(row.id) || norm(i.expense_ref) === norm(row.name));
        addGrid('sg_exp_items', `Invoice Item Lines (${row.name})`, 'Invoice Items', 'Item Breakdown', 'expense_items', expLines, ['name', 'item_name', 'allocation_mode', 'target_equipment', 'qty', 'uom', 'unit_cost', 'line_total'], 'line_total');
      }
      if (key === 'expense_categories') {
        const relIdx = window.MFG_PBI && window.MFG_PBI.getHubRelIndex ? window.MFG_PBI.getHubRelIndex(SEED) : null;
        const subRows = (rec.expense_subcategories || []).filter(s => norm(s.category) === norm(cat)).map(s => {
          const se = relIdx
            ? (s.category && relIdx.subcatByKey ? relIdx.subcatByKey[`${norm(s.category)}|${norm(s.name)}`] : (relIdx.subcatByName && relIdx.subcatByName[norm(s.name)]))
            : null;
          return Object.assign({}, s, {
            expenses_count: se ? se.expenses_count : 0,
            total_spent: se ? se.total_spent : 0
          });
        });
        addGrid('sg_ec_sub', `Subcategories under ${cat}`, 'Subcategories', 'Subcategories', 'expense_subcategories', subRows, ['name', 'category', 'expenses_count', 'total_spent'], 'total_spent');
      }
      const matchExps = (rec.expenses || []).filter(x => key === 'expense_subcategories'
        ? (norm(x.subcategory) === norm(row.name) && (!row.category || norm(x.category) === norm(row.category)))
        : norm(x.category) === norm(cat));
      addGrid('sg_ec_exp', `Expense Vouchers (${row.subcategory || cat})`, 'Expense Vouchers', 'Expense Vouchers', 'expenses', matchExps, ['date', 'name', 'company', 'category', 'subcategory', 'supplier', 'equipment', 'method', 'amount', 'reference'], 'amount');
    }
    else if (key === 'receipts' || key === 'credit_terms' || key === 'vat_invoices') {
      const cust = row.customer;
      addGrid('sg_ar_sales', `Customer Sales Tickets (${cust})`, 'Sales Tickets', 'FIFO Pool', 'sales_tickets', (rec.sales_tickets || []).filter(t => norm(t.customer) === norm(cust)), ['date', 'ticket_no', 'company', 'product', 'site', 'qty', 'unit_price', 'vat', 'total_ttc', 'method'], 'total_ttc');
      addGrid('sg_ar_rcpt', `Customer Receipts (${cust})`, 'Receipts', 'AR Ledger', 'receipts', (rec.receipts || []).filter(r => norm(r.customer) === norm(cust)), ['date', 'name', 'company', 'method', 'amount', 'discount', 'vat_invoice', 'reference'], 'amount');
    }
    else if (key === 'settlements') {
      const sup = row.supplier;
      addGrid('sg_ap_raw', `Supplier Raw Material & Haulage Tickets (${sup})`, 'Raw & Haulage', 'AP Pool', 'raw_purchases', (rec.raw_purchases || []).filter(r => norm(r.site_owner) === norm(sup) || norm(r.truck_owner) === norm(sup)), ['date', 'ticket_no', 'company', 'site', 'site_owner', 'truck_owner', 'product', 'qty', 'cost', 'trans_cost', 'total'], 'total');
      addGrid('sg_ap_set', `All Settlements for ${sup}`, 'Settlements', 'AP Ledger', 'settlements', (rec.settlements || []).filter(s => norm(s.supplier) === norm(sup)), ['date', 'name', 'company', 'method', 'amount', 'discount', 'reference'], 'amount');
    }
    else if (key === 'fuel_intakes') {
      const eq = row.equipment;
      addGrid('sg_fi_log', `All Fuel & Meter Readings for ${eq}`, 'Unit Fuel History', 'Meter Series', 'fuel_intakes', (rec.fuel_intakes || []).filter(f => norm(f.equipment) === norm(eq)), ['date', 'ticket_no', 'company', 'equipment', 'driver', 'item', 'litres', 'odometer', 'hours'], 'litres');
      addGrid('sg_fi_sales', `Sales Loads Hauled by ${eq}`, 'Unit Sales Loads', 'Fleet Activity', 'sales_tickets', (rec.sales_tickets || []).filter(t => norm(t.truck) === norm(eq)), ['date', 'ticket_no', 'company', 'customer', 'product', 'site', 'qty', 'total_ttc'], 'total_ttc');
    }
    else if (key === 'fuel_malfunctions') {
      const ym = String(row.rep_date || row.date || '').slice(0, 7);
      const sibMalfs = (rec.fuel_malfunctions || []).filter(m => String(m.id) !== String(row.id) && (!row.company || norm(m.company) === norm(row.company)) && (!ym || String(m.rep_date || m.date || '').slice(0, 7) === ym));
      addGrid('sg_malf_sib', `Tank Malfunctions & Discrepancies (${_formatMonthYmLabel(ym)})`, 'Month Malfunctions', 'Tank Recon', 'fuel_malfunctions', sibMalfs, ['date', 'rep_date', 'ticket_no', 'company', 'discrepancy_type', 'litres', 'equipment', 'driver', 'notes'], 'litres');
      if (row.equipment) {
        addGrid('sg_malf_fuel', `Fuel & Meter Readings for ${row.equipment}`, 'Unit Fuel History', 'Meter Series', 'fuel_intakes', (rec.fuel_intakes || []).filter(f => norm(f.equipment) === norm(row.equipment)), ['date', 'ticket_no', 'company', 'equipment', 'driver', 'item', 'litres', 'odometer', 'hours'], 'litres');
      }
    }
    else if (key === 'currencies' || key === 'fx_rates' || key === 'vat_rates') {
      const currCode = String(row.code || row.currency || '').trim().toUpperCase();
      if (key === 'currencies' || key === 'fx_rates') {
        const fxRows = (rec.fx_rates || []).filter(r => r && !r.voided && (!currCode || String(r.currency || '').toUpperCase() === currCode));
        addGrid('sg_fx_hist', `FX Exchange Rate Schedule${currCode ? ' (' + currCode + ')' : ''}`, 'FX Rates', 'Currency Exchange Rates', 'fx_rates', fxRows, ['name', 'currency', 'start_date', 'effective_to', 'rate', 'status', 'notes'], null);
      }
      if (key === 'vat_rates') {
        const vatRows = (rec.vat_rates || []).filter(r => r && !r.voided);
        addGrid('sg_vat_hist', 'VAT Rate Schedule (All Effective Windows)', 'VAT Schedule', 'VAT Rates', 'vat_rates', vatRows, ['name', 'start_date', 'effective_to', 'vat_percent', 'vat_fx_rate', 'status', 'notes'], null);
        addGrid('sg_vat_invs', 'Recent VAT Tax Invoices', 'VAT Invoices', 'VAT Invoices', 'vat_invoices', (rec.vat_invoices || []).slice(0, 25), ['date', 'company', 'invoice_no', 'customer', 'net_amount', 'vat_amount', 'total_ttc'], 'total_ttc');
      }
    }
    else if (key === 'gl_accounts') {
      const m = getModel();
      const glCode = String(row.code || '').trim();
      const soaRows = ((m && m.soa_stream) || []).filter(s => s && String(s.code || '').trim() === glCode);
      subgrids.push({
        id: 'sg_gl_soa',
        title: `Automated SOA Journal Stream (GL ${glCode} · ${row.name || ''})`,
        shortLabel: 'SOA Journal Legs',
        relBadge: 'Double-Entry Ledger',
        targetKey: 'ledger',
        noRowInspect: true,
        rows: soaRows,
        cols: ['date', 'company', 'doc', 'detail', 'desc', 'debit', 'credit'],
        sumCol: 'debit'
      });
      if (Array.isArray(row.mapped_categories) && row.mapped_categories.length) {
        const catSet = new Set(row.mapped_categories.map(c => norm(c)));
        const matchExps = (rec.expenses || []).filter(x => x && !x.voided && catSet.has(norm(x.category)));
        addGrid('sg_gl_exp', `Auto-Mapped Expense Vouchers (GL ${glCode})`, 'Expense Vouchers', 'Category Auto-Map', 'expenses', matchExps, ['date', 'name', 'company', 'category', 'subcategory', 'supplier', 'method', 'amount'], 'amount');
      }
    }
    else {
      // Treasury, Loans, JV Partnerships & Distributions
      if (row.site) {
        addGrid('sg_jv_dist', `JV Profit Distributions (${row.site})`, 'JV Distributions', 'JV Distributions', 'jv_distributions', (rec.jv_distributions || []).filter(d => norm(d.site) === norm(row.site)), ['date', 'company', 'site', 'partner', 'basis', 'amount', 'total'], 'total');
      }
      const cpMatch = norm(row.counterparty || row.lender || row.borrower || '');
      const lnMatch = norm(key === 'loans' ? row.name : row.loan || '');
      const scopedLoans = (cpMatch || lnMatch)
        ? (rec.loans || []).filter(l => (lnMatch && norm(l.name) === lnMatch) || (cpMatch && norm(l.counterparty || l.lender) === cpMatch))
        : (rec.loans || []).slice(0, 25);
      const scopedLoanSet = (cpMatch || lnMatch)
        ? (rec.loan_settlements || []).filter(s => (lnMatch && norm(s.loan) === lnMatch) || (cpMatch && (norm(s.counterparty) === cpMatch || norm(s.borrower) === cpMatch)))
        : (rec.loan_settlements || []).slice(0, 25);
      addGrid('sg_tr_loans', `Partner Loans & Advances`, 'Loans', 'Loans', 'loans', scopedLoans, ['name', 'company', 'counterparty', 'direction', 'principal', 'settled_amount', 'start_date', 'notes'], 'principal');
      addGrid('sg_tr_set', `Loan Repayments & Drawdowns`, 'Loan Settlements', 'Loan Settlements', 'loan_settlements', scopedLoanSet, ['date', 'company', 'loan', 'type', 'method', 'amount', 'notes'], 'amount');
    }

    return subgrids;
  }

  function resolveInspectorRawTicketCalc(origRow, overrides = {}, editedSet = null) {
    const base = origRow || {};
    const hasOv = k => overrides && Object.prototype.hasOwnProperty.call(overrides, k) && overrides[k] !== undefined;
    const getStr = k => String((hasOv(k) ? overrides[k] : base[k]) ?? '').trim();
    const getNum = k => {
      const raw = hasOv(k) ? overrides[k] : base[k];
      if (raw === '' || raw == null) return 0;
      const n = Number(raw);
      return Number.isFinite(n) ? n : 0;
    };
    const wasEdited = k => {
      if (editedSet instanceof Set) return editedSet.has(k);
      if (!hasOv(k)) return false;
      const a = base[k], b = overrides[k];
      if (typeof a === 'number' || typeof b === 'number' || ['qty', 'unit_cost', 'trans_unit_cost', 'discount'].includes(k)) {
        return Math.abs(Number(a || 0) - Number(b || 0)) > 1e-6;
      }
      return String(a ?? '').trim() !== String(b ?? '').trim();
    };

    const origQty = Number(base.qty || 0);
    const origUc = Number(base.unit_cost || 0);
    const origTuc = Number(base.trans_unit_cost || 0);
    const origDisc = Number(base.discount || 0);
    const origCost = Number(base.cost || 0);
    const origTransCost = Number(base.trans_cost || 0);
    const origTotal = Number(base.total != null ? base.total : round2(origCost + origTransCost));

    const company = getStr('company') || 'WTC';
    const date = getStr('date');
    const repDate = getStr('rep_date') || date;
    const effDate = repDate || date;
    const site = getStr('site');
    const owner = getStr('site_owner');
    const product = getStr('product');
    const transportBy = getStr('transport_by') || (origTransCost > 0 || origTuc > 0 ? 'Third-party truck' : 'Company fleet');
    const isCoFleet = /^company/i.test(transportBy);
    const truckOwner = isCoFleet ? company : getStr('truck_owner');
    const uom = getStr('uom') || 'm³';
    const isTruckUom = /^truck$/i.test(uom);
    const qty = getNum('qty');
    const uc = getNum('unit_cost');
    const tuc = isCoFleet ? 0 : getNum('trans_unit_cost');
    const disc = getNum('discount');

    const matRule = (owner || site) && product ? findRule({ company, supplier: owner, site, product, date: effDate, types: ['Purchase Price (Site)'] }) : null;
    const haulRule = !isCoFleet && (site || truckOwner) ? findRule({ company, supplier: truckOwner, site, product, date: effDate, types: ['Transport Price (Site)'] }) : null;

    const storedMatFlat = origQty > 1.001 && origUc > 0 &&
      Math.abs(origCost - round2(Math.max(0, origUc - origDisc))) <= 0.05 &&
      Math.abs(origCost - round2(Math.max(0, origQty * origUc - origDisc))) > 0.50;
    const storedTransFlat = !(/^company/i.test(String(base.transport_by || ''))) && origQty > 1.001 && origTuc > 0 &&
      Math.abs(origTransCost - round2(Math.max(0, origTuc))) <= 0.05 &&
      Math.abs(origTransCost - round2(Math.max(0, origQty * origTuc))) > 0.50;

    const matIsFlat = Boolean(isTruckUom || base.mat_indiff === true || isMatIndiffRule(matRule) || storedMatFlat);
    const transIsFlat = Boolean(!isCoFleet && (isTruckUom || base.trans_indiff === true || isTransIndiffRule(haulRule) || storedTransFlat));

    const matEdited = wasEdited('qty') || wasEdited('uom') || wasEdited('unit_cost') || wasEdited('discount');
    const transEdited = wasEdited('qty') || wasEdited('uom') || wasEdited('trans_unit_cost') || wasEdited('transport_by');

    let cost;
    if (!matEdited) {
      cost = origCost;
    } else if (uc === 0 && origUc === 0 && origCost > 0 && !wasEdited('unit_cost')) {
      cost = round2(Math.max(0, origCost + origDisc - disc));
    } else if (matIsFlat) {
      cost = round2(Math.max(0, uc - disc));
    } else {
      const impliedMatTier = base.tier_adj != null
        ? Number(base.tier_adj || 0)
        : ((origQty > 0 && origUc > 0 && !storedMatFlat) ? round2((origCost + origDisc) - origQty * origUc) : 0);
      const keepMatTier = (!wasEdited('unit_cost') && Math.abs(impliedMatTier) <= 50) ? impliedMatTier : 0;
      cost = round2(Math.max(0, qty * uc + keepMatTier - disc));
    }

    let transCost;
    if (!transEdited) {
      transCost = origTransCost;
    } else if (isCoFleet) {
      transCost = 0;
    } else if (tuc === 0 && origTuc === 0 && origTransCost > 0 && !wasEdited('trans_unit_cost')) {
      transCost = origTransCost;
    } else if (transIsFlat) {
      transCost = round2(Math.max(0, tuc));
    } else {
      const impliedTransTier = base.trans_tier_adj != null
        ? Number(base.trans_tier_adj || 0)
        : ((origQty > 0 && origTuc > 0 && !storedTransFlat) ? round2(origTransCost - origQty * origTuc) : 0);
      const keepTransTier = (!wasEdited('trans_unit_cost') && Math.abs(impliedTransTier) <= 50) ? impliedTransTier : 0;
      transCost = round2(Math.max(0, qty * tuc + keepTransTier));
    }

    const total = (!matEdited && !transEdited) ? origTotal : round2(cost + transCost);
    return { cost, transCost, total, matIsFlat, transIsFlat, matEdited, transEdited, effDate };
  }

  function resolveInspectorSalesTicketCalc(origRow, overrides = {}, editedSet = null) {
    const base = origRow || {};
    const hasOv = k => overrides && Object.prototype.hasOwnProperty.call(overrides, k) && overrides[k] !== undefined;
    const getStr = k => String((hasOv(k) ? overrides[k] : base[k]) ?? '').trim();
    const getNum = k => {
      const raw = hasOv(k) ? overrides[k] : base[k];
      if (raw === '' || raw == null) return 0;
      const n = Number(raw);
      return Number.isFinite(n) ? n : 0;
    };
    const wasEdited = k => {
      if (editedSet instanceof Set) return editedSet.has(k);
      if (!hasOv(k)) return false;
      const a = base[k], b = overrides[k];
      if (typeof a === 'number' || typeof b === 'number' || ['qty', 'external_qty', 'unit_price', 'trans_unit_price', 'discount', 'tip'].includes(k)) {
        return Math.abs(Number(a || 0) - Number(b || 0)) > 1e-6;
      }
      return String(a ?? '').trim() !== String(b ?? '').trim();
    };

    const origQty = Number(base.qty || 0);
    const origExtQty = Number(base.external_qty || 0);
    const origUp = Number(base.unit_price || 0);
    const origTp = Number(base.trans_unit_price || 0);
    const origDisc = Number(base.discount || 0);
    const origPrice = Number(base.price || 0);
    const origTransPrice = Number(base.trans_price || 0);
    const origTotal = Number(base.total != null ? base.total : round2(Math.max(0, origPrice + origTransPrice)));
    const origVat = Number(base.vat || 0);
    const origTtc = Number(base.total_ttc != null ? base.total_ttc : (origTotal + origVat));
    const origResidual = round2(origTotal - (origPrice + origTransPrice));

    const company = getStr('company') || 'WTC';
    const date = getStr('date') || todayISO();
    const repDate = getStr('rep_date') || date;
    const effDate = repDate || date;
    const origEffDate = String(base.rep_date || base.date || date);
    const saleType = getStr('sale_type') || 'Delivery';
    const isDelivery = saleType === 'Delivery';
    const isPickup = saleType === 'Pickup';
    const isUnreg = saleType === 'Unregistered';
    const transportBy = getStr('transport_by') || 'Company fleet';
    const isCoFleet = /^company/i.test(transportBy);
    const customer = getStr('customer');
    const product = getStr('product');
    const site = getStr('site');
    const truckOwner = isCoFleet ? company : getStr('truck_owner');
    const uom = getStr('uom') || 'm³';
    const isTruckUom = /^truck$/i.test(uom);
    const qty = getNum('qty');
    const extQty = getNum('external_qty');
    const up = getNum('unit_price');
    const tp = isDelivery ? getNum('trans_unit_price') : 0;
    const disc = getNum('discount');

    const origUsedExtQty = Boolean(
      origExtQty > 0 && origUp > 0 && Math.abs(origExtQty - origQty) > 0.01 &&
      Math.abs(origPrice - round2(Math.max(0, origExtQty * origUp + Number(base.tier_adj || 0) - origDisc))) <= 0.20 &&
      Math.abs(origPrice - round2(Math.max(0, origQty * origUp + Number(base.tier_adj || 0) - origDisc))) > 0.50
    );
    const origBillQty = origUsedExtQty ? origExtQty : origQty;
    const useExtQty = extQty > 0 && (origUsedExtQty || (wasEdited('external_qty') && Boolean((customerInfo(customer) || {}).customer_declared_qty)));
    const billQty = useExtQty ? extQty : qty;

    const wantType = isPickup ? 'Sales (Pickup)' : 'Sales (Delivery)';
    let rule = (!isUnreg && customer && product) ? findRule({ company, customer, product, site: isDelivery ? site : '', date: effDate, types: [wantType], requireProduct: true }) : null;
    if (!rule && !isUnreg && customer && product) {
      const anyRule = findRule({ company, customer, product, site: isDelivery ? site : '', date: effDate, types: [wantType] });
      if (anyRule && (Number(anyRule.unit_price || anyRule.price || 0) > 0 || ruleIndiffPrice(anyRule) != null)) rule = anyRule;
    }
    const ruleHasTrans = Boolean(rule && (Number(rule.trans_unit_price || rule.trans_price || 0) > 0 || ruleTransIndiffPrice(rule) != null));
    const transRule = (isDelivery && !isUnreg && customer && !ruleHasTrans)
      ? findRule({ company, customer, product: '', site, date: effDate, types: ['Sales (Delivery)'] })
      : null;
    const haulCustRule = (isDelivery && !isUnreg && (customer || site || truckOwner))
      ? findRule({ company, customer, supplier: truckOwner, product, site, date: effDate, types: ['Haulage (Customer Site)'] })
      : null;
    const activeTransRule = !isDelivery ? null : (
      ruleHasTrans ? rule : (
        (transRule && (Number(transRule.trans_unit_price || transRule.trans_price || 0) > 0 || ruleTransIndiffPrice(transRule) != null)) ? transRule : (
          (haulCustRule && (Number(haulCustRule.trans_unit_price || haulCustRule.unit_price || 0) > 0 || ruleTransIndiffPrice(haulCustRule) != null)) ? haulCustRule : null
        )
      )
    );

    const storedMatFlat = origBillQty > 1.001 && origUp > 0 &&
      (Math.abs(origPrice - round2(Math.max(0, origUp - origDisc))) <= 0.05 || Math.abs(origPrice - round2(origUp)) <= 0.05) &&
      Math.abs(origPrice - round2(Math.max(0, origBillQty * origUp + Number(base.tier_adj || 0) - origDisc))) > 0.50;
    const storedTransFlat = base.sale_type !== 'Pickup' && origBillQty > 1.001 && origTp > 0 &&
      Math.abs(origTransPrice - round2(Math.max(0, origTp))) <= 0.05 &&
      Math.abs(origTransPrice - round2(Math.max(0, origBillQty * origTp + Number(base.trans_tier_adj || 0)))) > 0.50;

    const matIsFlat = Boolean(isTruckUom || base.mat_indiff === true || (!isUnreg && isMatIndiffRule(rule)) || storedMatFlat);
    const transIsFlat = Boolean(isDelivery && (isTruckUom || base.trans_indiff === true || (!isUnreg && isTransIndiffRule(activeTransRule)) || storedTransFlat));

    const matEdited = wasEdited('qty') || (useExtQty && wasEdited('external_qty')) || wasEdited('uom') || wasEdited('unit_price') || wasEdited('discount');
    const transEdited = wasEdited('qty') || (useExtQty && wasEdited('external_qty')) || wasEdited('uom') || wasEdited('trans_unit_price') || wasEdited('sale_type');

    let price;
    if (!matEdited) {
      price = origPrice;
    } else if (up === 0 && origUp === 0 && origPrice > 0 && !wasEdited('unit_price')) {
      price = round2(Math.max(0, origPrice + origDisc - disc));
    } else if (matIsFlat) {
      price = round2(Math.max(0, up - disc));
    } else {
      const keepMatTier = !wasEdited('unit_price') ? Number(base.tier_adj || 0) : 0;
      price = round2(Math.max(0, billQty * up + keepMatTier - disc));
    }

    let transPrice;
    if (!transEdited) {
      transPrice = origTransPrice;
    } else if (!isDelivery) {
      transPrice = 0;
    } else if (tp === 0 && origTp === 0 && origTransPrice > 0 && !wasEdited('trans_unit_price')) {
      transPrice = origTransPrice;
    } else if (transIsFlat) {
      transPrice = round2(Math.max(0, tp));
    } else {
      const keepTransTier = !wasEdited('trans_unit_price') ? Number(base.trans_tier_adj || 0) : 0;
      transPrice = round2(Math.max(0, billQty * tp + keepTransTier));
    }

    let total;
    if (!matEdited && !transEdited) {
      total = origTotal;
    } else if (!matEdited && transEdited) {
      total = round2(Math.max(0, price + transPrice + origResidual));
    } else {
      total = round2(Math.max(0, price + transPrice));
    }

    const modMethod = getStr('method') || base.method || 'Credit';
    const modVatInv = getStr('vat_invoice');
    const mSgn = ticketSign({ method: modMethod });
    const vatRateChanged = wasEdited('date') && Math.abs(getVatFraction(date) - getVatFraction(String(base.date || origEffDate))) > 1e-6;
    const vatCtxEdited = wasEdited('customer') || wasEdited('method') || wasEdited('vat_invoice') || vatRateChanged;

    let vat, totalTtc;
    if (!matEdited && !transEdited && !vatCtxEdited) {
      vat = origVat;
      totalTtc = origTtc;
    } else if (mSgn === 0) {
      vat = 0;
      totalTtc = round2(total);
    } else {
      const ci = customerInfo(customer) || {};
      const hasVat = vatCtxEdited
        ? Boolean(modVatInv || ci.vat_registered || ci['VAT Registered'] === 'Yes')
        : Boolean(origVat > 0 || modVatInv || ci.vat_registered || ci['VAT Registered'] === 'Yes');
      vat = hasVat ? round2(total * getVatFraction(date)) : 0;
      totalTtc = round2(total + vat);
    }

    return { price, transPrice, total, vat, totalTtc, matIsFlat, transIsFlat, matEdited, transEdited, effDate: date };
  }

