  // Group record fields into structured Power Apps Form Sections (m12_forms.py parity)
  function buildInspectorSections(key, row) {
    const isEquipInspect = key === 'equipment' || key === 'company_equipment';
    const targetEqRow = isEquipInspect
      ? (key === 'equipment' ? row : (getFleetIndex().eqByName.get(norm(row.equipment || row.name)) || row))
      : null;
    const schema = getInspectorEditableSchema(key, row, targetEqRow);
    const schemaByKey = new Map();
    schema.forEach(f => {
      if (!f.drawerOnly) schemaByKey.set(f.key, f);
    });

    const hidden = new Set(['id', 'origin_ticket_id', 'zone_geojson', 'geo_zone', '_seedCatAuto', 'customer_id', 'sale_type_code', 'transport_by_code', 'fuel_type_code', 'rule_type_code', 'rate_per_code', 'category_code', 'ownership_code', 'entered_by_email', 'adj_windows', 'driver_rows', 'sync_unit_status', 'resolve_defect', '_prev_status', '_staged_expense_items', '_staged_repair_items', 'historical_consumed', 'move_type', 'expense_id', 'repair_id']);
    if (key !== 'gl_accounts') {
      ['output_vat_account', 'input_vat_account', 'revenue_account', 'purchase_account', 'gl_code', 'gl_account', 'receivable_account', 'payable_account', 'salary_account', 'asset_account', 'depreciation_account'].forEach(gk => hidden.add(gk));
    } else {
      hidden.add('mapped_categories');
      hidden.add('is_automated');
    }
    if (key === 'currencies' || key === 'fx_rates' || key === 'vat_rates') {
      hidden.add('company');
      hidden.add('date');
      hidden.add('rep_date');
    }
    if (key === 'warehouse_movements') { hidden.add('location'); hidden.add('target_equipment'); }
    if (key === 'customers') { hidden.add('region'); hidden.add('Customer'); hidden.add('Method'); hidden.add('VAT Registered'); }
    if (key === 'suppliers') { hidden.add('contact'); hidden.add('region'); hidden.add('financial_no'); hidden.add('Supplier'); hidden.add('Method'); hidden.add('IVA'); }
    if (key === 'sites') {
      if (resolveSiteCategory(row) === 'customer') {
        hidden.add('supplier');
        hidden.add('is_jv');
      } else {
        hidden.add('customer');
      }
    }
    if (key === 'employments') {
      hidden.add('equipment');
      hidden.add('truck');
    }
    if (key === 'attendance') {
      hidden.add('rep_date');
      hidden.add('eff_date');
      hidden.add('tx_date');
      hidden.add('display_type');
      hidden.add('shift_basis_lbl');
      hidden.add('weekday');
      hidden.add('is_sunday');
      hidden.add('is_overnight');
      hidden.add('is_callout');
      hidden.add('shift_str');
      hidden.add('check_in');
      hidden.add('check_out');
    }
    if (key === 'salaries') {
      hidden.add('name');
      hidden.add('equipment');
      hidden.add('sal_status_lbl');
      hidden.add('sal_status_cls');
      hidden.add('sal_status_tip');
      hidden.add('is_advance_sal');
      hidden.add('month_cum_paid');
      hidden.add('month_has_contract');
      hidden.add('month_is_future');
      hidden.add('month_earnings');
    }
    if (key === 'fuel_intakes') { hidden.add('location'); }
    if (key === 'fuel_malfunctions' && !/^wash$/i.test(String((row && row.discrepancy_type) || ''))) {
      if (!row || !row.ticket_no) hidden.add('ticket_no');
      if (!row || !row.equipment) hidden.add('equipment');
      if (!row || !row.driver) hidden.add('driver');
    }
    if (key === 'price_rules') {
      hidden.add('name');
      hidden.add('price');
      hidden.add('trans_price');
      hidden.add('indiff_price');
      hidden.add('trans_indiff_price');
      hidden.add('delivered_indiff_price');
      const rtTrim = String((row && row.rule_type) || '').trim();
      const isTransOnlyPr = /^(Transport Price \(Site\)|Haulage \(Customer Site\))$/i.test(rtTrim);
      const hasTransPr = /^(Sales \(Delivery\)|Transport Price \(Site\)|Haulage \(Customer Site\))$/i.test(rtTrim);
      const hasMatPr = !isTransOnlyPr;
      const matM3Pr = hasMatPr && !isMatIndiffRule(row) && /^m/i.test(String((row && row.unit) || 'm³').trim());
      const trM3Pr = hasTransPr && !isTransIndiffRule(row) && /^m/i.test(String((row && (row.rate_per || row.unit)) || 'm³').trim());
      if (/^commission$/i.test(rtTrim)) {
        hidden.add('rule_type');
        hidden.add('customer');
        hidden.add('site');
        hidden.add('rate_per');
        hidden.add('trans_unit_price');
        hidden.add('truck_size');
        hidden.add('truck');
      } else if (/^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(rtTrim)) {
        hidden.add('customer');
      } else {
        hidden.add('supplier');
      }
      if (!hasMatPr) {
        hidden.add('unit');
        hidden.add('unit_price');
        hidden.add('adj1');
        hidden.add('adj2');
        hidden.add('total1');
        hidden.add('total2');
      } else if (!matM3Pr) {
        hidden.add('adj1');
        hidden.add('adj2');
      }
      if (!hasTransPr) {
        hidden.add('rate_per');
        hidden.add('trans_unit_price');
        hidden.add('trans_adj1');
        hidden.add('trans_adj2');
      } else if (!trM3Pr) {
        hidden.add('trans_adj1');
        hidden.add('trans_adj2');
      }
      if (/^(List Price|Commission)$/i.test(rtTrim) || (!matM3Pr && !trM3Pr)) {
        hidden.add('truck');
        hidden.add('truck_size');
        hidden.add('qty1');
        hidden.add('adj1');
        hidden.add('trans_adj1');
        hidden.add('qty2');
        hidden.add('adj2');
        hidden.add('trans_adj2');
      }
    }

    const populatedKeys = Object.keys(row).filter(k => !hidden.has(k) && row[k] !== '' && row[k] != null && !(typeof row[k] === 'number' && row[k] === 0 && /tip|discount|tier|adj|difference/.test(k) && !schemaByKey.has(k)));
    const allKeysSet = new Set(populatedKeys);
    schema.forEach(f => {
      if (!f.drawerOnly && !hidden.has(f.key)) allKeysSet.add(f.key);
    });
    const allKeys = Array.from(allKeysSet);

    const idFields = new Set(['code', 'pcg_class', 'automation_mode', 'name', 'official_name', 'ticket_no', 'invoice_no', 'set_date', 'date', 'rep_date', 'month', 'time', 'payroll_month', 'company', 'sale_type', 'rule_type', 'type', 'status', 'severity', 'customer', 'supplier', 'staff', 'driver', 'reported_by', 'approved_by', 'prior_defect_notified', 'defect_ref', 'linked_part_log', 'partner', 'counterparty', 'loan', 'role', 'mof_no', 'financial_no', 'vat_registered', 'iva', 'phone', 'contact', 'email', 'address', 'location', 'direction', 'is_company_driver']);
    const opsFields = new Set(['source_module', 'debit_rule', 'credit_rule', 'product', 'item', 'input_product', 'fuel_type', 'site', 'region', 'site_owner', 'transport_by', 'truck_owner', 'truck', 'equipment', 'equipment_category', 'subsystem', 'action_type', 'part_name', 'part_serial', 'condition', 'removed_disposition', 'storage_location', 'vendor_or_buyer', 'meter_reading', 'resolved_date', 'description', 'plate_no', 'ownership', 'capacity', 'truck_size', 'default_driver', 'day_operator', 'night_operator', 'model', 'working_days', 'start_date', 'end_date', 'latitude', 'longitude', 'is_jv', 'is_truck_owner', 'ticket_product', 'fuel_item', 'customer_declared_qty', 'external_invoice', 'trucks_count', 'trucks', 'drivers', 'category', 'subcategory', 'category1', 'category2', 'cost_class', 'from_currency', 'to_currency']);
    const finFields = new Set(['soa_legs', 'debit', 'credit', 'qty', 'external_qty', 'uom', 'unit', 'rate_per', 'ton_factor', 'litres', 'odometer', 'hours', 'regular_hours', 'overtime_hours', 'late_hours', 'extra_hours', 'days_count', 'unit_price', 'price', 'list_price', 'indiff_price', 'trans_unit_price', 'trans_indiff_price', 'delivered_indiff_price', 'trans_price', 'unit_cost', 'cost', 'trans_unit_cost', 'trans_cost', 'new_part_cost', 'repair_cost', 'sale_proceeds', 'qty1', 'adj1', 'trans_adj1', 'qty2', 'adj2', 'trans_adj2', 'vat', 'vat_amount', 'net_amount', 'total', 'total_ttc', 'amount', 'usd_amount', 'lbp_amount', 'usd_delta', 'lbp_delta', 'discount', 'tip', 'salary_usd', 'daily_rate', 'daily_usd', 'rate_usd', 'credit_days', 'credit_limit', 'principal', 'interest_rate', 'exchange_rate', 'percentage', 'basis', 'difference', 'ar_balance', 'ap_balance', 'balance', 'loads', 'raw_loads', 'sales_ttc', 'raw_cost', 'receipts', 'settlements_paid', 'method', 'vat_invoice', 'record_ticket', 'raw_ticket', 'expense_record', 'invoice', 'reference', 'revenue_account', 'purchase_account', 'notes']);

    const s1 = [], s2 = [], s3 = [];
    allKeys.forEach(k => {
      const fDef = schemaByKey.get(k);
      if (fDef && fDef.sec === 1) s1.push(k);
      else if (fDef && fDef.sec === 2) s2.push(k);
      else if (fDef && fDef.sec === 3) s3.push(k);
      else if (idFields.has(k)) s1.push(k);
      else if (opsFields.has(k)) s2.push(k);
      else if (finFields.has(k)) s3.push(k);
      else s2.push(k);
    });

    // Guarantee at least 9 .inspector-cell elements across sections for headless verifier & dense Power Apps parity
    const synthExtras = [
      ['entity_table', INSPECT_LABELS[key] || key],
      ['record_origin', isAppRecord(row) ? 'ISABI Web App' : 'ISABI SQL Core'],
      ['snapshot_date', SEED_DATE],
      ['coa_status', 'Double-Entry Verified'],
      ['currency_basis', 'USD (89,500 LBP Peg)']
    ];
    let totalCount = s1.length + s2.length + s3.length;
    const extraPairs = [];
    for (const [ek, ev] of synthExtras) {
      if (totalCount >= 10) break;
      if (!(ek in row)) { extraPairs.push([ek, ev]); totalCount++; }
    }

    const canEdit = canModifyData();
    const renderCell = (k, valOverride) => {
      const fDef = schemaByKey.get(k);
      const v = valOverride !== undefined ? valOverride : (fDef && typeof fDef.getVal === 'function' ? fDef.getVal(row) : row[k]);
      const formatted = inspectorValue(k, v);
      const isEmpty = formatted === '—';
      const lkTarget = (k === 'origin_ticket_no') ? (row.origin_ticket_kind === 'raw' ? 'raw_purchases' : 'sales_tickets') : ((k === 'type' && key !== 'products') ? null : (k === 'linked_part_log' && /^REP-/i.test(String(v || '')) ? 'equipment_repairs' : INSPECT_LOOKUP_FIELD_TARGET[k]));
      const canLink = lkTarget && lkTarget !== key && v != null && v !== '' && !isEmpty;
      const roLabels = key === 'gl_accounts' ? {
        code: 'GL Code', name: 'GL Account', pcg_class: 'CoA Class', automation_mode: 'Automation Mode',
        source_module: 'Driven By', debit_rule: 'Hidden Debit Calculation', credit_rule: 'Hidden Credit Calculation',
        soa_legs: 'Posted SOA Legs', debit: 'Total Debit ($)', credit: 'Total Credit ($)', balance: 'Net Balance ($)'
      } : null;
      const lblText = fDef ? fDef.label.replace(/\s*\*$/, '') : ((roLabels && roLabels[k]) || k.replace(/_/g, ' '));
      const editableAttr = (canEdit && fDef && valOverride === undefined) ? ` data-edit-field="${esc(k)}" title="Click to modify ${esc(lblText)}"` : '';
      const cellCls = `inspector-cell${editableAttr ? ' is-editable-cell' : ''}${isEmpty && editableAttr ? ' is-empty-cell' : ''}`;
      let valHtml;
      if (canLink) {
        valHtml = `<span class="rel-link" data-rel-key="${esc(lkTarget)}" data-rel-val="${esc(v)}" title="Open related ${esc(lblText)}: ${esc(v)}">${esc(formatted)}<span class="rel-arr">↗</span></span>`;
      } else if (isEmpty && editableAttr) {
        valHtml = `<span class="insp-empty-add">+ Set ${esc(lblText)}</span>`;
      } else {
        valHtml = esc(formatted);
      }
      return `<div class="${cellCls}"${editableAttr}><small>${esc(lblText)}${editableAttr ? '<i class="insp-cell-edit-ico" aria-hidden="true">✎</i>' : ''}</small><b>${valHtml}</b></div>`;
    };

    const sections = [];
    if (s1.length) sections.push({ title: '1 · Identification, Counterparty & Governance', sub: 'Primary key, dates, business unit & counterparty links', html: s1.map(k => renderCell(k)).join('') });
    if (s2.length) sections.push({ title: '2 · Dispatch, Site, Fleet & Operational Attributes', sub: 'Connected sites, grades, trucks, drivers & operational parameters', html: s2.map(k => renderCell(k)).join('') });
    if (s3.length || extraPairs.length) sections.push({ title: '3 · Quantities, Contractual Pricing, VAT & Settlement', sub: 'Financial legs, unit economics & ledger settlement', html: s3.map(k => renderCell(k)).concat(extraPairs.map(([ek, ev]) => renderCell(ek, ev))).join('') });
    return sections;
  }

  function renderSubgridBoxHtml(sg) {
    const rows = sg.rows || [];
    const shown = rows.slice(0, 25);
    let sumVal = 0, hasSum = false;
    if (sg.sumCol) {
      rows.forEach(r => {
        const n = Number(r[sg.sumCol]);
        if (Number.isFinite(n)) {
          const rowSgn = sg.targetKey === 'sales_tickets' ? ticketSign(r) : (sg.targetKey === 'expenses' ? expenseSign(r) : 1);
          sumVal += n * rowSgn;
          hasSum = true;
        }
      });
    }
    const isMoneySum = sg.sumCol && /price|cost|amount|total|vat|limit|salary|daily_usd|principal|proceeds|^debit$|^credit$|balance/.test(sg.sumCol);

    return `
      <div class="pa-subgrid-box" id="subgrid_${esc(sg.id)}" data-subgrid-box="${esc(sg.id)}">
        <div class="pa-subgrid-bar">
          <div class="pa-subgrid-title">
            <span>${esc(sg.title)}</span>
            <span class="pa-subgrid-rel">${esc(sg.relBadge)} · ${fmtNum(rows.length)} rows</span>
            ${hasSum ? `<span class="pa-subgrid-rel" style="background:var(--good-bg);color:var(--good);border-color:color-mix(in srgb, var(--good) 40%, transparent)">Total · ${isMoneySum ? fmtUSD(sumVal, 2) : fmtNum(sumVal, 1)}</span>` : ''}
          </div>
          <div class="pa-subgrid-tools">
            ${rows.length > 3 ? `<input type="search" class="pa-subgrid-search" data-sg-filter="${esc(sg.id)}" placeholder="Filter ${esc(sg.shortLabel)}...">` : ''}
            <button type="button" class="pa-subgrid-jump" data-sg-open-hub="${esc(sg.targetKey)}">Open ${esc(sg.shortLabel)} in Hub ↗</button>
          </div>
        </div>
        ${rows.length ? `
          <div class="table-wrap" style="max-height:260px">
            <table class="ledger-table">
              <thead>
                <tr>
                  ${sg.cols.map(c => `<th class="${!/^(cost_class|cost_bucket|working_days)$/i.test(c) && /price|cost|amount|total|vat|limit|salary|qty|litres|capacity|hours|days|percentage|_count|proceeds|^debit$|^credit$|balance$/.test(c) ? 'r' : ''}">${esc(c.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()))}</th>`).join('')}
                </tr>
              </thead>
              <tbody data-sg-tbody="${esc(sg.id)}">
                ${shown.map(r => `
                  <tr${sg.noRowInspect ? '' : ` class="rrow" data-rkey="${esc(sg.targetKey)}" data-rid="${esc(r.id || r.name || r.ticket_no)}"`}>
                    ${sg.cols.map((c, ci) => {
                      let v = r[c] !== undefined ? r[c] : resolveColVal(r, c, 'tbl_' + sg.targetKey);
                      if (sg.targetKey === 'price_rules') {
                        const isTrOnlySg = /^(Transport Price \(Site\)|Haulage \(Customer Site\))$/i.test(String(r.rule_type || '').trim());
                        if (c === 'unit_price') v = isTrOnlySg ? null : (isMatIndiffRule(r) ? ruleIndiffPrice(r) : (r.unit_price ?? r.price ?? null));
                        if (c === 'trans_unit_price') v = isTransIndiffRule(r) ? ruleTransIndiffPrice(r) : (r.trans_unit_price ?? r.trans_price ?? (isTrOnlySg ? (r.unit_price ?? r.price ?? null) : null));
                        if (c === 'unit') {
                          const rawU = isTrOnlySg ? (isTransIndiffRule(r) ? 'Truck' : (r.rate_per || r.unit || 'm³')) : (isMatIndiffRule(r) ? 'Truck' : (r.unit || 'm³'));
                          v = /^truck$/i.test(String(rawU || '').trim()) ? 'Per Truck Load' : `Per ${rawU}`;
                        }
                      }
                      const nonNum = /^(cost_class|cost_bucket|working_days)$/i.test(c);
                      const isMoney = !nonNum && /price|cost|amount|total|vat|limit|salary|daily_usd|rate_usd|principal|discount|proceeds|^debit$|^credit$|balance/.test(c) && !/rate$/.test(c);
                      const isNum = !nonNum && !isMoney && /qty|litres|capacity|hours|days|odometer|percentage|_count$/.test(c);
                      let txt = v == null || v === '' ? '—' : String(v);
                      if (isMoney && v != null && v !== '') txt = fmtUSD(v, 2);
                      else if (isNum && v != null && v !== '') txt = fmtNum(v, /qty|capacity|percentage/.test(c) ? 2 : 0);
                      else if (/date/.test(c) && v) txt = fmtDateDMY(v);
                      const lk = (c === 'linked_part_log' && /^REP-/i.test(String(v || ''))) ? 'equipment_repairs' : INSPECT_LOOKUP_FIELD_TARGET[c];
                      const cellHtml = (lk && lk !== sg.targetKey && v != null && v !== '' && txt !== '—')
                        ? `<span class="rel-link" data-rel-key="${esc(lk)}" data-rel-val="${esc(v)}">${esc(txt)}<span class="rel-arr">↗</span></span>`
                        : esc(txt);
                      return `<td class="${isMoney || isNum ? 'r' : ''}${/date|ticket|invoice|plate/.test(c) ? ' mono' : ''}">${ci === 0 ? `<b>${cellHtml}</b>${appCell(r, sg.targetKey)}` : cellHtml}</td>`;
                    }).join('')}
                  </tr>
                `).join('')}
              </tbody>
              <tfoot>
                <tr>
                  <td colspan="${Math.max(1, sg.cols.length - (hasSum ? 1 : 0))}"><b>TOTAL (${fmtNum(rows.length)} ${esc(sg.shortLabel.toUpperCase())}${rows.length > 25 ? ' · showing top 25' : ''})</b></td>
                  ${hasSum ? `<td class="r"><b>${isMoneySum ? fmtUSD(sumVal, 2) : fmtNum(sumVal, 2)}</b></td>` : ''}
                </tr>
              </tfoot>
            </table>
          </div>
        ` : `<div style="padding:12px 14px;font-size:11.5px;color:var(--muted)">No linked rows in <b>${esc(sg.shortLabel)}</b> for this record in the current snapshot.</div>`}
      </div>
    `;
  }

  function wireBackdropDismiss(backdropEl, closeFn) {
    if (!backdropEl || backdropEl.dataset.backdropGuardWired === '1') return;
    backdropEl.dataset.backdropGuardWired = '1';
    let downOnBackdrop = null;
    let upOnBackdrop = null;
    const onDown = e => {
      if (e.button != null && e.button !== 0) return;
      downOnBackdrop = (e.target === backdropEl);
      upOnBackdrop = null;
    };
    const onUp = e => {
      if (e.button != null && e.button !== 0) return;
      upOnBackdrop = (e.target === backdropEl);
      setTimeout(() => { downOnBackdrop = null; upOnBackdrop = null; }, 0);
    };
    backdropEl.addEventListener('pointerdown', onDown, true);
    backdropEl.addEventListener('mousedown', onDown, true);
    backdropEl.addEventListener('pointerup', onUp, true);
    backdropEl.addEventListener('mouseup', onUp, true);
    document.addEventListener('mouseup', () => {
      setTimeout(() => { downOnBackdrop = null; upOnBackdrop = null; }, 0);
    }, true);
    backdropEl.addEventListener('click', e => {
      const hadPointerCycle = downOnBackdrop !== null || upOnBackdrop !== null;
      const shouldClose = (e.target === backdropEl) && (!hadPointerCycle || (downOnBackdrop === true && upOnBackdrop !== false));
      downOnBackdrop = null;
      upOnBackdrop = null;
      if (shouldClose) closeFn();
    });
  }
  window.__mfgWireBackdropDismiss = wireBackdropDismiss;

  function showRecordInspector(key, idOrName, opts = {}) {
    const row = resolveInspectorRecord(key, idOrName);
    if (!row) { toast('Record not found in this snapshot', 'err'); return; }

    if (!STATE.inspectorHistory) STATE.inspectorHistory = [];
    const recTitle = row.ticket_no ? `#${row.ticket_no}` : (row.name || row.invoice_no || row.staff || row.driver || row.equipment || String(idOrName));
    const crumbLabel = `${INSPECT_LABELS[key] || key}: ${recTitle}`;
    if (opts.fromCrumbIdx != null) {
      STATE.inspectorHistory = STATE.inspectorHistory.slice(0, opts.fromCrumbIdx + 1);
    } else if (opts.pushHistory) {
      const last = STATE.inspectorHistory[STATE.inspectorHistory.length - 1];
      if (!last || last.key !== key || String(last.id) !== String(row.id || idOrName)) {
        STATE.inspectorHistory.push({ key, id: row.id || idOrName, label: crumbLabel });
      }
    } else {
      STATE.inspectorHistory = [{ key, id: row.id || idOrName, label: crumbLabel }];
    }

    const activeTab = opts.tab || 'general';
    let panel = $('recordInspector');
    if (!panel) {
      panel = document.createElement('div');
      panel.id = 'recordInspector';
      panel.className = 'modal-backdrop';
      panel.innerHTML = '<div class="modal-card inspector-card" role="dialog" aria-modal="true" aria-labelledby="inspectorTitle"><div class="modal-header"><div><span class="modal-eyebrow" id="inspectorEyebrow"></span><h2 id="inspectorTitle"></h2></div><button type="button" class="modal-close-btn" id="inspectorCloseBtn" aria-label="Close">✕</button></div><div class="modal-body" id="inspectorBody"></div></div>';
      document.body.appendChild(panel);
      wireBackdropDismiss(panel, closeRecordInspector);
      $('inspectorCloseBtn').addEventListener('click', closeRecordInspector);
    }

    const app = isAppRecord(row);
    const isAhRow = row && (row.after_hours === true || row.after_hours === 1 || row.after_hours === '1' || row.after_hours === 'true');
    $('inspectorEyebrow').textContent = `RECORD INSPECTOR · ${(INSPECT_LABELS[key] || key).toUpperCase()} · ${app ? 'ENTERED IN WEB APP' : 'CLOUD LEDGER ' + SEED_DATE}${isAhRow ? " · YESTERDAY'S AFTER-HOURS" : ''}`;
    $('inspectorTitle').textContent = row.name || row.ticket_no || row.invoice_no || row.staff || String(idOrName);

    const banner = buildInspectorLiveBanner(key, row);
    const cockpit = buildInspectorCockpit(key, row);
    const qvCards = buildInspectorQuickViews(key, row);
    const sections = buildInspectorSections(key, row);
    const subgrids = buildInspectorSubgrids(key, row);
    const totalRelRows = subgrids.reduce((a, sg) => a + sg.rows.length, 0);
    const isEquipInspect = key === 'equipment' || key === 'company_equipment';
    const targetEqRow = isEquipInspect
      ? (key === 'equipment' ? row : (getFleetIndex().eqByName.get(norm(row.equipment || row.name)) || row))
      : null;
    const eqWindows = (targetEqRow && Array.isArray(targetEqRow.adj_windows)) ? targetEqRow.adj_windows : [];
    const editSchema = getInspectorEditableSchema(key, row, targetEqRow);
    const inspRegions = uniqSorted(
      ((SEED.records && SEED.records.regions) || []).map(r => r.name)
        .concat(((SEED.records && SEED.records.sites) || []).map(s => s.region))
        .concat(((SEED.records && SEED.records.customers) || []).map(c => c.address || c.region))
        .concat(((SEED.records && SEED.records.suppliers) || []).map(s => s.location || s.region))
        .concat(['Beirut', 'Mount Lebanon', 'South Lebanon', 'Nabatieh', 'Bekaa', 'North Lebanon', 'Chouf', 'Saida', 'Tyre', 'Baabda', 'Metn', 'Keserwan', 'Aley'])
    );
    const inspSubcats = uniqSorted(
      ((SEED.records && SEED.records.expense_subcategories) || []).map(sc => sc.name)
        .concat(((SEED.records && SEED.records.expenses) || []).map(x => x.subcategory))
    );
    const inspCounterparties = uniqSorted(
      ((SEED.records && SEED.records.loans) || []).map(l => l.counterparty || l.lender || l.name)
        .concat(((SEED.records && SEED.records.external_movements) || []).map(x => x.counterparty))
        .concat(((SEED.records && SEED.records.jv_partnerships) || []).map(j => j.partner))
        .concat(supplierNames(), customerNames())
    );
    const inspRuleType = String((row && row.rule_type) || '').trim();
    const isRawInsp = key === 'raw_purchases' || (key === 'price_rules' && /^(Purchase Price \(Site\)|Transport Price \(Site\))$/i.test(inspRuleType));
    const isCommInsp = key === 'price_rules' && /^commission$/i.test(inspRuleType);
    const isSalesInsp = key === 'sales_tickets' || (key === 'price_rules' && !isRawInsp && !isCommInsp);
    const inspRowCo = (row && row.company) || defaultEntryCompany();
    const inspProdMeta = key === 'fuel_intakes'
      ? fuelProductMetaItems(inspRowCo).concat(domainProductMetaItems('', inspRowCo).filter(([n]) => !/^(diesel|oil\s*68|oil\s*15w40|grease|oil\s*90|oil\s*atf)/i.test(n)))
      : (isRawInsp
          ? domainProductMetaItems('raw', inspRowCo)
          : (isCommInsp
              ? domainProductMetaItems('comm', inspRowCo)
              : (isSalesInsp ? domainProductMetaItems('sales', inspRowCo) : domainProductMetaItems('', inspRowCo))));
    const inspSiteNames = siteNames(isRawInsp ? 'raw' : (isSalesInsp ? 'sales' : undefined));
    const inspSupplierNames = supplierNames(isRawInsp ? 'raw_owner' : (key === 'expenses' ? 'expense' : undefined));
    const inspParts = uniqSorted(
      ((SEED.records && SEED.records.part_movements) || []).map(p => p.part_name)
        .concat(((SEED.records && SEED.records.equipment_defects) || []).map(d => d.part_name))
        .concat(['Tire 315/80 R22.5', 'Tire 13R22.5', 'Brake Lining & Drum Set', 'Clutch Disc & Pressure Plate', 'Hydraulic Hoist Cylinder', 'Alternator 24V', 'Starter Motor 24V', 'Battery 12V 200Ah', 'Radiator & Water Pump', 'Turbocharger', 'Fuel Injector Set', 'Leaf Spring Pack', 'Crusher Jaw Plate', 'Conveyor Belt Roller'])
    );
    const inspPartLocs = uniqSorted(
      ((SEED.records && SEED.records.part_movements) || []).map(p => p.storage_location)
        .concat(['WTC Main Spare Parts Room', 'BBConstruction Spare Parts Store', 'Lions Garage Shelf A', 'Tire Rack — Plant Yard', 'External Workshop / Rebuild Shop', 'Scrap Yard Bin'])
    );

    const renderModFieldHtml = (fDef) => {
      const f = fDef.key;
      const rawCur = typeof fDef.getVal === 'function'
        ? fDef.getVal(row)
        : (row[f] != null ? row[f] : (targetEqRow && targetEqRow[f] != null ? targetEqRow[f] : ''));
      const lbl = fDef.label || f.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
      const spanCls = fDef.span ? ' span-3' : '';
      if (fDef.type === 'bool') {
        const isYes = Boolean(rawCur === true || rawCur === 'Yes' || rawCur === 'true' || rawCur === 1);
        return `
          <div class="form-field${spanCls}">
            <label for="insp_edit_${esc(f)}">${esc(lbl)}</label>
            <select id="insp_edit_${esc(f)}" data-insp-edit-field="${esc(f)}" data-mod-field="${esc(f)}" data-mod-type="bool">
              <option value="No" ${!isYes ? 'selected' : ''}>No</option>
              <option value="Yes" ${isYes ? 'selected' : ''}>Yes</option>
            </select>
          </div>
        `;
      }
      if (fDef.type === 'select') {
        const curStr = String(rawCur == null ? '' : rawCur);
        const normOpts = (fDef.options || []).map(o => Array.isArray(o) ? [String(o[0]), String(o[1])] : [String(o), String(o)]);
        if (curStr && !normOpts.some(([ov]) => ov.toLowerCase() === curStr.toLowerCase())) {
          normOpts.unshift([curStr, curStr]);
        }
        return `
          <div class="form-field${spanCls}">
            <label for="insp_edit_${esc(f)}">${esc(lbl)}</label>
            <select id="insp_edit_${esc(f)}" data-insp-edit-field="${esc(f)}" data-mod-field="${esc(f)}" data-mod-type="select">
              ${normOpts.map(([ov, ol]) => `<option value="${esc(ov)}" ${ov.toLowerCase() === curStr.toLowerCase() ? 'selected' : ''}>${esc(ol)}</option>`).join('')}
            </select>
          </div>
        `;
      }
      if (fDef.type === 'combo') {
        return `
          <div class="form-field${spanCls}">
            <label for="insp_edit_${esc(f)}">${esc(lbl)}</label>
            <input type="text" id="insp_edit_${esc(f)}" list="${esc(fDef.dl || '')}" data-insp-edit-field="${esc(f)}" data-mod-field="${esc(f)}" data-mod-type="combo" value="${esc(rawCur == null ? '' : rawCur)}" placeholder="${esc(fDef.placeholder || 'Select or type...')}" autocomplete="off">
          </div>
        `;
      }
      const inpType = fDef.type === 'number' ? 'number' : (fDef.type === 'date' ? 'date' : (fDef.type === 'time' ? 'time' : (fDef.type === 'month' ? 'month' : (fDef.type === 'tel' ? 'tel' : 'text'))));
      const stepAttr = fDef.type === 'number' ? ` step="${esc(fDef.step || '0.01')}"${fDef.min != null ? ` min="${esc(fDef.min)}"` : ''}${fDef.max != null ? ` max="${esc(fDef.max)}"` : ''}${fDef.min != null && Number(fDef.min) >= 0 ? ' inputmode="decimal"' : ''}` : '';
      const phAttr = fDef.placeholder ? ` placeholder="${esc(fDef.placeholder)}"` : '';
      return `
        <div class="form-field${spanCls}">
          <label for="insp_edit_${esc(f)}">${esc(lbl)}</label>
          <input type="${inpType}"${stepAttr}${phAttr} id="insp_edit_${esc(f)}" data-insp-edit-field="${esc(f)}" data-mod-field="${esc(f)}" data-mod-type="${esc(fDef.type || 'text')}" value="${esc(rawCur == null ? '' : rawCur)}" autocomplete="off">
        </div>
      `;
    };

    const REL_TO_VIEW_COL = {
      sales: { customers: 'customer', products: 'product', sites: 'site', equipment: 'truck', drivers: 'driver' },
      raw: { sites: 'site', suppliers: 'site_owner', products: 'product', equipment: 'truck' },
      raw_jv: { sites: 'site', suppliers: 'partner' },
      fleet: { equipment: 'equipment', drivers: 'driver' },
      pricing: { customers: 'customer', suppliers: 'supplier', products: 'product', sites: 'site' },
      raw_pricing: { customers: 'customer', suppliers: 'supplier', products: 'product', sites: 'site' },
      customers: { customers: 'customer' },
      suppliers: { suppliers: 'supplier' },
      expenses: { suppliers: 'supplier', equipment: 'equipment', expense_categories: 'category' }
    };
    const activeMap = REL_TO_VIEW_COL[STATE.view] || null;
    const quickFilterCol = activeMap ? activeMap[key] : null;
    const quickFilterVal = String(row.name || row.Customer || row.Supplier || row.Product || row.Site || row.Equipment || row.driver || row.equipment || '').trim();

    const bodyEl = $('inspectorBody');
    bodyEl.innerHTML = `
      <!-- Shared Searchable Datalists for Inspector Modification Drawer & Equipment Log -->
      <div hidden aria-hidden="true">
        <datalist id="dl_insp_customers">${customerNames().map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_suppliers">${inspSupplierNames.map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_products">${inspProdMeta.map(([v, m]) => `<option value="${esc(v)}"${m ? ` data-meta="${esc(m)}"` : ''}>`).join('')}</datalist>
        <datalist id="dl_insp_sites">${inspSiteNames.map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_regions">${inspRegions.map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_equip">${equipmentNames().map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_drivers">${driverNames().map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_staff">${staffNames().map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_subcategories">${inspSubcats.map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_counterparties">${inspCounterparties.map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_parts">${inspParts.map(v => `<option value="${esc(v)}">`).join('')}</datalist>
        <datalist id="dl_insp_locations">${inspPartLocs.map(v => `<option value="${esc(v)}">`).join('')}</datalist>
      </div>

      <!-- Top Command Bar & Relational Breadcrumb Trail -->
      <div class="pa-cmd-bar">
        <div class="pa-breadcrumbs">
          ${STATE.inspectorHistory.length > 1 ? `<button type="button" class="pa-crumb-back" id="inspBackBtn">← Back</button>` : ''}
          ${STATE.inspectorHistory.map((h, idx) => `
            ${idx > 0 ? '<span class="pa-crumb-sep">›</span>' : ''}
            <button type="button" class="pa-crumb-btn ${idx === STATE.inspectorHistory.length - 1 ? 'current' : ''}" data-crumb-idx="${idx}">${esc(h.label)}</button>
          `).join('')}
        </div>
        <div class="pa-cmd-actions">
          ${quickFilterCol && quickFilterVal ? `<button type="button" class="pa-cmd-btn btn-brass" id="inspFilterCurrentTableBtn" data-qf-col="${esc(quickFilterCol)}" data-qf-val="${esc(quickFilterVal)}" title="Close 360° Inspector and filter the current register by ${esc(quickFilterVal)}">⚡ Filter Table by "${esc(quickFilterVal)}"</button>` : ''}
          ${key === 'expenses' && isPendingPriceExpense(row) && (canModifyData() || canEnterForm('expense')) ? `<button type="button" class="pa-cmd-btn btn-primary" id="inspSetInvoicePriceBtn" title="Open the Expense form with delivery fields locked to enter the final supplier invoice price">${ic('dollar')} Enter Final Price</button>` : ''}
          ${canModifyData() ? `<button type="button" class="pa-cmd-btn btn-brass" id="inspModifyRecordBtn">${ic('edit')} Modify Record</button>` : ''}
          ${isEquipInspect && canEnterForm('defect') ? `<button type="button" class="pa-cmd-btn" id="inspReportDefectBtn">${ic('warn')} + Report Warning</button>` : ''}
          ${isEquipInspect && canEnterForm('repair') ? `<button type="button" class="pa-cmd-btn" id="inspLogRepairBtn">${ic('repair')} + Log Repair</button>` : ''}
          ${isEquipInspect && canEnterForm('oillog') ? `<button type="button" class="pa-cmd-btn" id="inspLogOilBtn">${ic('oillog')} + Log Oil</button>` : ''}
          ${isEquipInspect && canEnterForm('partlog') ? `<button type="button" class="pa-cmd-btn" id="inspLogPartBtn">${ic('cog')} + Log Part</button>` : ''}
          ${key === 'equipment_defects' && isDefectOpen(row) && canEnterForm('repair') ? `<button type="button" class="pa-cmd-btn btn-brass" id="inspResolveWithRepairBtn">${ic('repair')} + Log Repair</button>` : ''}
          ${key === 'equipment_defects' && isDefectOpen(row) && canEnterForm('partlog') ? `<button type="button" class="pa-cmd-btn" id="inspResolveWithPartBtn">${ic('cog')} + Log Part Change</button>` : ''}
          ${isEquipInspect ? `<button type="button" class="pa-cmd-btn" data-insp-scroll-sg="truck_windows">${ic('ruler')} Truck Size Windows (${eqWindows.length})</button>` : ''}
          ${!row.voided && canVoid() ? `<button type="button" class="pa-cmd-btn pa-cmd-btn-danger" id="inspCmdVoidBtn" title="Void or delete this record (2-click confirmation)">${ic('trash')} Void / Delete</button>` : ''}
          ${['sales_tickets', 'raw_purchases', 'fuel_intakes'].includes(key) ? `<button type="button" class="pa-cmd-btn btn-brass" id="inspThermalPrintBtn">${ic('printer')} Thermal Receipt (80/58mm)</button>` : ''}
          ${(key === 'sites' || key === 'regions' || ((key === 'sales_tickets' || key === 'raw_purchases') && row.site)) ? `<button type="button" class="pa-cmd-btn btn-brass" id="inspViewOnMapBtn">${ic('reg_sites')} View on Map</button>` : ''}
          <button type="button" class="pa-cmd-btn" data-insp-open-hub="${esc(key)}">${ic('tables')} Open ${esc(INSPECT_LABELS[key] || key)} Table</button>
          <button type="button" class="pa-cmd-btn" id="inspPrintBtn">${ic('printer')} Print Form</button>
        </div>
      </div>

      <!-- Inline Record Modification Drawer (Gated by Role Modify Data Permission) -->
      <div class="insp-modify-drawer" id="inspModifyDrawer" hidden>
        <div class="insp-modify-hdr">
          <div>
            <strong>${ic('edit')} Modify ${esc(INSPECT_LABELS[key] || key)} · ${esc(recTitle)}</strong>
            <span class="insp-modify-sub">Authorized by ${esc(activeUser().role)} (${esc(activeUser().full_name)}) · Tip: click any field in the General form below to jump straight to it</span>
          </div>
          <span class="badge badge-brass">MODIFY DATA PRIVILEGE VERIFIED</span>
        </div>
        <div class="form-grid-3" style="margin-top:10px">
          ${editSchema.map(renderModFieldHtml).join('')}
        </div>
        <div class="insp-modify-foot">
          <div id="inspModLiveCalc" class="insp-mod-live-calc"></div>
          <div style="display:flex;justify-content:flex-end;gap:8px;margin-left:auto">
            <button type="button" class="btn" id="inspCancelModifyBtn">Cancel</button>
            <button type="button" class="btn btn-primary" id="inspSaveModifyBtn">✓ Save Record Modifications</button>
          </div>
        </div>
      </div>

      <!-- Live Contextual Notification Bar (Screenshot 2 top bar) -->
      <div class="pa-rec-banner ${esc(banner.tone || '')}" id="inspLiveBanner">
        <span class="pa-rec-banner-ico">${ic('info')}</span>
        <span>${esc(banner.text)}</span>
      </div>

      <!-- Power Apps Form Tabs (General | Related + Subgrid Quick-Jump Tabs) -->
      <div class="pa-rec-tabs">
        <button type="button" class="pa-rec-tab ${activeTab === 'general' ? 'active' : ''}" data-insp-tab="general">General <em>Form &amp; Cockpit</em></button>
        <button type="button" class="pa-rec-tab ${activeTab === 'related' ? 'active' : ''}" data-insp-tab="related">Related Tables <em>${fmtNum(totalRelRows)} rows</em></button>
        ${isEquipInspect ? `<button type="button" class="pa-rec-tab" data-insp-scroll-sg="truck_windows">Truck Size Windows <em>${fmtNum(eqWindows.length)}</em></button>` : ''}
        ${subgrids.map(sg => `<button type="button" class="pa-rec-tab" data-insp-scroll-sg="${esc(sg.id)}">${esc(sg.shortLabel)} <em>${fmtNum(sg.rows.length)}</em></button>`).join('')}
      </div>

      <!-- Embedded 4-Card Navy Executive Telemetry & Control Cockpit (Screenshot 2 bhf_mfgCockpit.htm m283) -->
      <div class="pa-rec-cockpit" id="inspCockpit">
        <div class="pa-rec-cockpit-top">
          <div class="pa-rec-cockpit-title">
            <span class="pa-rec-bu-pill">${esc(cockpit.bu)}</span>
            <span>${esc(cockpit.title)}</span>
          </div>
          <span class="pa-rec-val-pill">${esc(cockpit.pill)}</span>
        </div>
        <div class="pa-rec-cockpit-cards">
          ${cockpit.cards.map(c => `
            <div class="pa-rec-kcard">
              <div>
                <div class="pa-rec-kcard-hdr">
                  <span class="pa-rec-kcard-lbl">${esc(c.lbl)}</span>
                  <span class="pa-rec-kcard-tag ${esc(c.tone)}">${esc(c.tag)}</span>
                </div>
                <div class="pa-rec-kcard-val">${esc(c.val)}</div>
                <div class="pa-rec-kcard-sub">${esc(c.sub1)}</div>
                <div class="pa-rec-kcard-sub">${esc(c.sub2)}</div>
              </div>
              <div class="pa-rec-kcard-bar"><i class="${esc(c.tone)}" style="width:${Math.min(100, Math.max(12, Number(c.pct || 75)))}%"></i></div>
            </div>
          `).join('')}
        </div>
      </div>

      ${activeTab === 'general' ? `
        <!-- Locked Quick-View Cards (qv_customer, qv_truck, qv_site, qv_supplier) -->
        ${qvCards.length ? `
          <div class="pa-qv-grid">
            ${qvCards.map(qv => `
              <div class="pa-qv-card">
                <div class="pa-qv-card-top">
                  <span class="pa-qv-card-lbl">${esc(qv.tag)}</span>
                  <button type="button" class="pa-cmd-btn" style="padding:2px 7px;font-size:10px" data-rel-key="${esc(qv.targetKey)}" data-rel-val="${esc(qv.targetVal)}">Open 360° ↗</button>
                </div>
                <div class="pa-qv-card-title">
                  <span>${esc(qv.title)}</span>
                </div>
                <div class="pa-qv-kv-grid">
                  ${qv.kvs.map(([k, v]) => `<div class="pa-qv-kv"><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}
                </div>
              </div>
            `).join('')}
          </div>
        ` : ''}

        <!-- Structured Form Sections (m12_forms.py) -->
        <div class="pa-form-sections">
          ${sections.map(sec => `
            <div class="pa-form-section">
              <div class="pa-form-sec-hdr">
                <strong>${esc(sec.title)}</strong>
                <span>${esc(sec.sub)}</span>
              </div>
              <div class="pa-form-sec-body">
                <div class="inspector-grid">${sec.html}</div>
              </div>
            </div>
          `).join('')}
        </div>
      ` : ''}

      ${isEquipInspect ? `
        <div class="pa-subgrid-box" id="subgrid_truck_windows" style="margin-bottom:14px">
          <div class="pa-subgrid-hdr">
            <div>
              <strong>${ic('ruler')} Equipment Driver &amp; Capacity Log (Start Date → End Date)</strong>
              <span class="pa-subgrid-sub">Active driver is strictly locked onto Sales, Raw Material, Lubricant &amp; Diesel tickets matching the ticket date. Set End Date for a 1-day or bounded absence substitute; leave End Date blank for a permanent change.</span>
            </div>
            <span class="badge badge-brass">${fmtNum(eqWindows.length)} Window${eqWindows.length === 1 ? '' : 's'}</span>
          </div>
          ${canModifyData() ? `
            <div class="form-grid-3" style="padding:10px 12px;background:rgba(196,154,69,0.06);border-bottom:1px solid var(--line)">
              <div class="form-field">
                <label for="insp_tw_co">Company / BU</label>
                <select id="insp_tw_co">
                  <option value="WTC" ${row.company === 'BBConstruction' ? '' : 'selected'}>WTC</option>
                  <option value="BBConstruction" ${row.company === 'BBConstruction' ? 'selected' : ''}>BBConstruction</option>
                  <option value="Lions Transport" ${row.company === 'Lions Transport' ? 'selected' : ''}>Lions Transport</option>
                </select>
              </div>
              <div class="form-field">
                <label for="insp_tw_side">Applies To Tables</label>
                <select id="insp_tw_side">
                  <option value="both" selected>All Tables (Sales, Raw, Lubricant &amp; Diesel)</option>
                  <option value="sales">Sales Side Only</option>
                  <option value="raw">Raw Material &amp; Transport Side Only</option>
                  <option value="fuel">Diesel &amp; Lubricants Only</option>
                </select>
              </div>
              <div class="form-field">
                <label for="insp_tw_cap">Truck Size / Capacity (m³)</label>
                <input type="number" step="0.5" min="0" id="insp_tw_cap" value="${esc(Number(targetEqRow.capacity || 0))}">
              </div>
              <div class="form-field">
                <label for="insp_tw_start">Start Date *</label>
                <input type="date" id="insp_tw_start" value="${esc(todayISO())}">
              </div>
              <div class="form-field">
                <label for="insp_tw_end">End Date (Blank = Open / Substitute End)</label>
                <input type="date" id="insp_tw_end" value="">
              </div>
              <div class="form-field">
                <label for="insp_tw_own">Truck Owner (Supplier)</label>
                <input type="text" id="insp_tw_own" list="dl_insp_suppliers" value="${esc(targetEqRow.supplier || '')}" placeholder="e.g. Hussein Bdeir, Karim Bdeir, WTC" autocomplete="off">
              </div>
              <div class="form-field">
                <label for="insp_tw_drv">Active / Substitute Driver *</label>
                <input type="text" id="insp_tw_drv" list="dl_insp_drivers" value="${esc(targetEqRow.default_driver || '')}" placeholder="Driver name" autocomplete="off">
              </div>
              <div class="form-field">
                <label for="insp_tw_cust">Client Override (Optional)</label>
                <input type="text" id="insp_tw_cust" list="dl_insp_customers" value="" placeholder="All clients (or type client name)..." autocomplete="off">
              </div>
              <div class="form-field">
                <label for="insp_tw_site">Site Override (Optional)</label>
                <div style="display:flex;gap:6px">
                  <input type="text" id="insp_tw_site" list="dl_insp_sites" value="" placeholder="All sites (or type site name)..." style="flex:1" autocomplete="off">
                  <button type="button" class="btn btn-primary" id="inspAddTruckWinBtn" style="white-space:nowrap">+ Add Log Entry</button>
                </div>
              </div>
            </div>
          ` : ''}
          <div class="table-wrap" style="max-height:260px;overflow:auto">
            <table class="ledger-table">
              <thead>
                <tr>
                  <th>Co.</th><th>Scope</th><th>Start Date</th><th>End Date</th><th class="r">Size (m³)</th><th>Truck Owner</th><th>Driver</th><th>Client / Site Scope</th><th>Status</th>${canModifyData() ? '<th></th>' : ''}
                </tr>
              </thead>
              <tbody>
                ${eqWindows.length ? eqWindows.slice().reverse().map((w, rIdx) => {
                  const origIdx = eqWindows.length - 1 - rIdx;
                  const isOpen = !w.e || String(w.e) >= SEED_DATE;
                  const sideLbl = w.side === 'sales' ? 'Sales' : (w.side === 'raw' ? 'Raw & Trans' : (w.side === 'fuel' ? 'Diesel & Lub.' : 'All Tables'));
                  const scopeLbl = [w.cust ? `Client: ${w.cust}` : '', w.site ? `Site: ${w.site}` : ''].filter(Boolean).join(' · ') || 'General (All)';
                  return `
                    <tr>
                      <td>${coBadge(w.co || 'WTC')}</td>
                      <td><span class="badge badge-info">${esc(sideLbl)}</span></td>
                      <td class="mono">${esc(w.s || '2024-01-01')}</td>
                      <td class="mono">${esc(w.e || 'Open')}</td>
                      <td class="r"><strong>${fmtNum(w.cap, 1)} m³</strong></td>
                      <td>${w.own ? relLink('suppliers', w.own, w.own, true) : '—'}</td>
                      <td>${w.drv ? relLink('drivers', w.drv, w.drv) : '—'}</td>
                      <td>${w.cust || w.site ? `<span class="badge badge-brass">${esc(scopeLbl)}</span>` : `<span class="mu">${esc(scopeLbl)}</span>`}</td>
                      <td><span class="badge ${isOpen ? 'badge-ok' : 'badge-neutral'}">${isOpen ? 'Active' : 'Historical'}</span></td>
                      ${canModifyData() ? `<td class="r"><button type="button" class="btn btn-sm" data-del-tw-idx="${origIdx}" title="Remove window">✕</button></td>` : ''}
                    </tr>
                  `;
                }).join('') : `<tr><td colspan="${canModifyData() ? 10 : 9}" class="mu" style="text-align:center;padding:14px">No dated adjustment windows recorded — using default capacity (${fmtNum(targetEqRow && targetEqRow.capacity, 1)} m³).</td></tr>`}
              </tbody>
            </table>
          </div>
        </div>
      ` : ''}

      <!-- Interactive Related Subgrids (bhf_related_subgrids.py parity) -->
      <div class="pa-subgrids-wrap" id="inspSubgridsWrap">
        ${subgrids.map(renderSubgridBoxHtml).join('')}
      </div>

      <div class="modal-foot">
        <span class="form-note">${app ? `Posted by <b>${esc(row.entered_by || '—')}</b> · ${esc(row.entered_at || '')}${row.voided ? ' · <b>VOIDED</b>' : ''}` : 'Click any blue lookup pill or related subgrid row to navigate across connected relational records.'}</span>
        <div>
          ${!row.voided && canVoid() ? `<button type="button" class="btn btn-danger-outline" id="inspectorVoidBtn">${ic('trash')} Void / Delete Record</button>` : ''}
          <button type="button" class="btn btn-brass" id="inspectorDoneBtn">Close</button>
        </div>
      </div>
    `;

    $('inspectorDoneBtn').addEventListener('click', closeRecordInspector);
    const wireInspectorVoidBtn = (btn, defaultHtml) => {
      if (!btn) return;
      btn.addEventListener('click', () => {
        if (btn.dataset.armed === '1') {
          closeRecordInspector();
          voidRecord(key, row.id || row.name || row.ticket_no || idOrName);
        } else {
          btn.dataset.armed = '1';
          btn.innerHTML = `${ic('warn')} Confirm Void / Delete?`;
          btn.classList.add('armed');
          setTimeout(() => {
            if (btn.isConnected) {
              btn.dataset.armed = '';
              btn.innerHTML = defaultHtml;
              btn.classList.remove('armed');
            }
          }, 4500);
        }
      });
    };
    wireInspectorVoidBtn($('inspectorVoidBtn'), `${ic('trash')} Void / Delete Record`);
    wireInspectorVoidBtn($('inspCmdVoidBtn'), `${ic('trash')} Void / Delete`);

    const backBtn = $('inspBackBtn');
    if (backBtn) backBtn.addEventListener('click', () => {
      if (STATE.inspectorHistory.length > 1) {
        const prevIdx = STATE.inspectorHistory.length - 2;
        const prev = STATE.inspectorHistory[prevIdx];
        showRecordInspector(prev.key, prev.id, { fromCrumbIdx: prevIdx });
      }
    });

    bodyEl.querySelectorAll('[data-crumb-idx]').forEach(btn => btn.addEventListener('click', () => {
      const idx = Number(btn.getAttribute('data-crumb-idx'));
      const item = STATE.inspectorHistory[idx];
      if (item && idx < STATE.inspectorHistory.length - 1) {
        showRecordInspector(item.key, item.id, { fromCrumbIdx: idx });
      }
    }));

    bodyEl.querySelectorAll('[data-insp-tab]').forEach(btn => btn.addEventListener('click', () => {
      showRecordInspector(key, row.id || idOrName, { fromCrumbIdx: STATE.inspectorHistory.length - 1, tab: btn.getAttribute('data-insp-tab') });
    }));

    bodyEl.querySelectorAll('[data-insp-scroll-sg]').forEach(btn => btn.addEventListener('click', () => {
      const sgId = btn.getAttribute('data-insp-scroll-sg');
      const el = $('subgrid_' + sgId);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }));

    bodyEl.querySelectorAll('[data-insp-open-hub], [data-sg-open-hub]').forEach(btn => btn.addEventListener('click', () => {
      const targetKey = btn.getAttribute('data-insp-open-hub') || btn.getAttribute('data-sg-open-hub');
      closeRecordInspector();
      if (targetKey === 'ledger') {
        if (key === 'gl_accounts' && row && row.code) STATE.search = String(row.code);
        setView('ledger');
        return;
      }
      STATE.activeTableKey = targetKey;
      setView('tables');
    }));

    const qfBtn = $('inspFilterCurrentTableBtn');
    if (qfBtn) {
      qfBtn.addEventListener('click', () => {
        const col = qfBtn.getAttribute('data-qf-col');
        const valStr = qfBtn.getAttribute('data-qf-val');
        const cfView = STATE.view === 'fleet' ? 'fuel' : (STATE.view === 'customers' ? 'receipts' : (STATE.view === 'suppliers' ? 'settle' : STATE.view));
        if (col && valStr) {
          if (!STATE.colFilters[cfView]) STATE.colFilters[cfView] = {};
          STATE.colFilters[cfView][col] = valStr;
          STATE.shown = {};
          closeRecordInspector();
          renderApp();
          toast(`Filtered by ${getColLabel(col)}: ${valStr}`);
        }
      });
    }

    const prBtn = $('inspPrintBtn');
    if (prBtn) prBtn.addEventListener('click', () => window.print());
    const inspRepDefBtn = $('inspReportDefectBtn');
    if (inspRepDefBtn) {
      inspRepDefBtn.addEventListener('click', () => {
        const eqName = row.equipment || row.name || '';
        closeRecordInspector();
        openEntryModal('defect', { eq: eqName, co: row.company || '' });
      });
    }
    const inspLogRepairBtn = $('inspLogRepairBtn');
    if (inspLogRepairBtn) {
      inspLogRepairBtn.addEventListener('click', () => {
        const eqName = row.equipment || row.name || '';
        closeRecordInspector();
        openEntryModal('repair', { eq: eqName, co: row.company || '' });
      });
    }
    const inspLogOilBtn = $('inspLogOilBtn');
    if (inspLogOilBtn) {
      inspLogOilBtn.addEventListener('click', () => {
        const eqName = row.equipment || row.name || '';
        closeRecordInspector();
        openEntryModal('oillog', { eq: eqName, co: row.company || '' });
      });
    }
    const inspLogPartBtn = $('inspLogPartBtn');
    if (inspLogPartBtn) {
      inspLogPartBtn.addEventListener('click', () => {
        const eqName = row.equipment || row.name || '';
        closeRecordInspector();
        openEntryModal('partlog', { eq: eqName, co: row.company || '' });
      });
    }
    const inspResRepBtn = $('inspResolveWithRepairBtn');
    if (inspResRepBtn) {
      inspResRepBtn.addEventListener('click', () => {
        closeRecordInspector();
        openEntryModal('repair', { eq: row.equipment || '', def: row.name || '', sub: row.subsystem || '', co: row.company || '' });
      });
    }
    const inspResPartBtn = $('inspResolveWithPartBtn');
    if (inspResPartBtn) {
      inspResPartBtn.addEventListener('click', () => {
        closeRecordInspector();
        openEntryModal('partlog', { eq: row.equipment || '', def: row.name || '', part: row.part_name || '', sub: row.subsystem || '', co: row.company || '' });
      });
    }
    const thPrBtn = $('inspThermalPrintBtn');
    if (thPrBtn && window.MFG_PRINT) {
      thPrBtn.addEventListener('click', () => {
        const docType = key === 'raw_purchases' ? 'raw' : (key === 'fuel_intakes' ? 'fuel' : 'sales');
        window.MFG_PRINT.openThermalPreviewModal(row, { docType });
      });
    }

    const modBtn = $('inspModifyRecordBtn');
    const modDrawer = $('inspModifyDrawer');
    const modLiveCalcEl = $('inspModLiveCalc');
    const getModVal = fk => {
      const el = $('insp_edit_' + fk);
      return el ? String(el.value || '').trim() : '';
    };
    const getModNum = fk => {
      const v = getModVal(fk);
      if (v === '') return 0;
      const n = Number(v);
      return Number.isFinite(n) ? n : 0;
    };
    const syncModifyLiveSummary = () => {
      if (!modDrawer || !modLiveCalcEl) return;
      let html = '';
      if (key === 'sales_tickets') {
        const otSel = $('insp_edit_overtime');
        const curTime = getModVal('time');
        const curDrv = getModVal('driver');
        const curTrBy = getModVal('transport_by') || row.transport_by || 'Company fleet';
        const curSaleTp = getModVal('sale_type') || row.sale_type || 'Delivery';
        const effDtOt = getModVal('rep_date') || getModVal('date') || row.rep_date || row.date || '';
        if (otSel && otSel.dataset.userEdited !== '1' && (
          curTime !== String(row.time || '').trim() ||
          curDrv !== String(row.driver || '').trim() ||
          curTrBy !== String(row.transport_by || 'Company fleet').trim() ||
          curSaleTp !== String(row.sale_type || 'Delivery').trim()
        )) {
          const canOt = curSaleTp === 'Delivery' && (/^company/i.test(curTrBy) || isCompanyDriver(curDrv, row.company, effDtOt));
          otSel.value = (canOt && isOvertimeTime(curTime)) ? 'Yes' : 'No';
        }
        const sc = resolveInspectorSalesTicketCalc(row, {
          date: getModVal('date') || row.date,
          rep_date: getModVal('rep_date') || getModVal('date') || row.rep_date || row.date,
          sale_type: curSaleTp,
          transport_by: curTrBy,
          customer: $('insp_edit_customer') ? getModVal('customer') : row.customer,
          product: $('insp_edit_product') ? getModVal('product') : row.product,
          site: $('insp_edit_site') ? getModVal('site') : row.site,
          truck_owner: $('insp_edit_truck_owner') ? getModVal('truck_owner') : row.truck_owner,
          uom: getModVal('uom') || row.uom || 'm³',
          qty: getModNum('qty'),
          external_qty: getModVal('external_qty') === '' ? null : getModNum('external_qty'),
          unit_price: getModNum('unit_price'),
          trans_unit_price: getModNum('trans_unit_price'),
          discount: getModNum('discount'),
          method: getModVal('method') || row.method || 'Credit',
          vat_invoice: $('insp_edit_vat_invoice') ? getModVal('vat_invoice') : String(row.vat_invoice || '')
        });
        const upLbl = modDrawer.querySelector('label[for="insp_edit_unit_price"]');
        if (upLbl) upLbl.textContent = sc.matIsFlat ? 'Material Price ($ / Load)' : 'Material Unit Price ($)';
        const tpLbl = modDrawer.querySelector('label[for="insp_edit_trans_unit_price"]');
        if (tpLbl) tpLbl.textContent = sc.transIsFlat ? 'Transport Price ($ / Load)' : 'Transport Unit Price ($)';
        html = `<span>Material${sc.matIsFlat ? ' (Flat / Load)' : ''}: <b>${fmtUSD(sc.price, 2)}</b></span><span>Transport${sc.transIsFlat ? ' (Flat / Load)' : ''}: <b>${fmtUSD(sc.transPrice, 2)}</b></span><span>VAT ${esc(fmtVatPctStr(sc.effDate))}: <b>${fmtUSD(sc.vat, 2)}</b></span><span>Total TTC: <b>${fmtUSD(sc.totalTtc, 2)}</b></span>`;
      } else if (key === 'raw_purchases') {
        const otSel = $('insp_edit_overtime');
        const curTime = getModVal('time');
        const curDrv = getModVal('driver');
        const origTrByDef = row.transport_by || (Number(row.trans_cost || row.trans_unit_cost || 0) > 0 ? 'Third-party truck' : 'Company fleet');
        const curTrBy = getModVal('transport_by') || origTrByDef;
        const effDtOt = getModVal('rep_date') || getModVal('date') || row.rep_date || row.date || '';
        if (otSel && otSel.dataset.userEdited !== '1' && (
          curTime !== String(row.time || '').trim() ||
          curDrv !== String(row.driver || '').trim() ||
          curTrBy !== String(origTrByDef).trim()
        )) {
          const canOt = /^company/i.test(curTrBy) || isCompanyDriver(curDrv, row.company, effDtOt);
          otSel.value = (canOt && isOvertimeTime(curTime)) ? 'Yes' : 'No';
        }
        const rc = resolveInspectorRawTicketCalc(row, {
          date: getModVal('date') || row.date,
          rep_date: getModVal('rep_date') || getModVal('date') || row.rep_date || row.date,
          product: $('insp_edit_product') ? getModVal('product') : row.product,
          site: $('insp_edit_site') ? getModVal('site') : row.site,
          site_owner: $('insp_edit_site_owner') ? getModVal('site_owner') : row.site_owner,
          transport_by: curTrBy,
          truck_owner: $('insp_edit_truck_owner') ? getModVal('truck_owner') : row.truck_owner,
          uom: getModVal('uom') || row.uom || 'm³',
          qty: getModNum('qty'),
          unit_cost: getModNum('unit_cost'),
          trans_unit_cost: getModNum('trans_unit_cost'),
          discount: getModNum('discount')
        });
        const ucLbl = modDrawer.querySelector('label[for="insp_edit_unit_cost"]');
        if (ucLbl) ucLbl.textContent = rc.matIsFlat ? 'Material Cost ($ / Load)' : 'Material Unit Cost ($)';
        const tucLbl = modDrawer.querySelector('label[for="insp_edit_trans_unit_cost"]');
        if (tucLbl) tucLbl.textContent = rc.transIsFlat ? 'Haulage Cost ($ / Load)' : 'Haulage Unit Cost ($)';
        html = `<span>Material Leg${rc.matIsFlat ? ' (Flat / Load)' : ''}: <b>${fmtUSD(rc.cost, 2)}</b></span><span>Haulage Leg${rc.transIsFlat ? ' (Flat / Load)' : ''}: <b>${fmtUSD(rc.transCost, 2)}</b></span><span>Total Payable: <b>${fmtUSD(rc.total, 2)}</b></span>`;
      } else if (key === 'vat_invoices') {
        const net = getModNum('net_amount');
        const effViDate = getModVal('date') || row.date || todayISO();
        const vatFrac = getVatFraction(effViDate);
        const vat = $('insp_edit_vat_amount') && $('insp_edit_vat_amount').dataset.userEdited === '1'
          ? getModNum('vat_amount')
          : round2(net * vatFrac);
        if ($('insp_edit_vat_amount') && $('insp_edit_vat_amount').dataset.userEdited !== '1') {
          $('insp_edit_vat_amount').value = vat.toFixed(2);
        }
        const ttc = round2(net + vat);
        if ($('insp_edit_total_ttc')) $('insp_edit_total_ttc').value = ttc.toFixed(2);
        html = `<span>Net HT: <b>${fmtUSD(net, 2)}</b></span><span>VAT ${esc(fmtVatPctStr(effViDate))}: <b>${fmtUSD(vat, 2)}</b></span><span>Total TTC: <b>${fmtUSD(ttc, 2)}</b></span>`;
      } else if (key === 'conversions') {
        const dir = getModVal('type') || row.type || 'USD to LBP';
        const isU2L = !/^lbp/i.test(dir);
        const usd = getModNum('usd_amount');
        const lbp = Math.round(getModNum('lbp_amount'));
        const effCvDate = getModVal('date') || row.date || todayISO();
        const rate = (usd > 0 && lbp > 0) ? round2(lbp / usd) : (getModNum('exchange_rate') || getLbpFxRate(effCvDate));
        if ($('insp_edit_exchange_rate') && usd > 0 && lbp > 0) $('insp_edit_exchange_rate').value = String(rate);
        html = `<span>USD Drawer: <b>${fmtSignedUSD(isU2L ? -usd : usd, 2)}</b></span><span>LBP Drawer: <b>${fmtSignedLBP(isU2L ? lbp : -lbp)}</b></span><span>Rate: <b>${fmtNum(rate, 2)} LL/$</b></span>`;
      } else if (key === 'fx_rates') {
        const curr = String(getModVal('currency') || row.currency || 'LBP').toUpperCase();
        const sd = getModVal('start_date') || row.start_date || todayISO();
        const rt = getModNum('rate');
        html = `<span>Currency: <b>${esc(curr)}</b></span><span>Effective From: <b>${esc(fmtDateDMY(sd))}</b></span><span>Rate: <b>${rt > 0 ? fmtNum(rt, Number.isInteger(rt) ? 0 : 4) + ' ' + esc(curr) + '/$1' : '—'}</b></span>`;
      } else if (key === 'vat_rates') {
        const sd = getModVal('start_date') || row.start_date || todayISO();
        const vp = getModNum('vat_percent');
        const vfx = getModNum('vat_fx_rate') || getLbpFxRate(sd, 'LBP');
        html = `<span>Effective From: <b>${esc(fmtDateDMY(sd))}</b></span><span>VAT Rate: <b>${fmtNum(vp, 1)}%</b></span><span>MoF VAT FX: <b>${fmtNum(vfx, Number.isInteger(vfx) ? 0 : 1)} LL/$1</b></span>`;
      } else if (key === 'currencies') {
        const cd = String(getModVal('code') || row.code || '').toUpperCase();
        const nm = getModVal('name') || row.name || '';
        const sym = getModVal('symbol') || row.symbol || cd;
        html = `<span>ISO Code: <b>${esc(cd)}</b></span><span>Name: <b>${esc(nm)}</b></span><span>Symbol: <b>${esc(sym)}</b></span>`;
      } else if (key === 'customers') {
        const m = getModVal('method') || 'Credit';
        const vr = getModVal('vat_registered') === 'Yes';
        const cd = getModVal('credit_days');
        const cl = getModVal('credit_limit');
        html = `<span>Default Method: <b>${esc(m)}</b></span><span>VAT Status: <b>${vr ? '11% VAT Registered' : 'Non-VAT'}</b></span>${cd || cl ? `<span>Credit Policy: <b>${esc(cd || '30')}d · Limit ${fmtUSD(Number(cl || 0), 0)}</b></span>` : ''}`;
      } else if (key === 'suppliers') {
        const m = getModVal('method') || 'Credit';
        const c1 = getModVal('category1');
        const c2 = getModVal('category2');
        const iva = getModVal('iva') === 'Yes';
        html = `<span>Default Method: <b>${esc(m)}</b></span><span>Category: <b>${esc([c1, c2].filter(Boolean).join(', ') || 'General')}</b></span><span>IVA: <b>${iva ? 'Yes' : 'No'}</b></span>`;
      } else if (key === 'attendance') {
        const sd = getModVal('set_date') || row.set_date || row.rep_date || row.date || todayISO();
        const td = getModVal('date') || row.date || sd;
        const wkInfo = attDateWeekdayInfo(sd);
        const stTp = getModVal('status') || row.type || row.status || 'Present';
        html = `<span>Set Date: <b>${esc(fmtDateDMY(sd))}${wkInfo.short ? ' (' + esc(wkInfo.short) + ')' : ''}</b></span><span>Tx Date: <b>${esc(fmtDateDMY(td))}</b></span><span>Month: <b>${esc(sd.slice(0, 7))}</b></span><span>Type: <b>${esc(stTp)}</b></span>`;
      } else if (key === 'equipment_defects') {
        const sev = getModVal('severity') || row.severity || 'Moderate';
        const st = getModVal('status') || row.status || 'Open';
        html = `<span>Severity: <b>${esc(sev)}</b></span><span>Status: <b>${esc(st)}</b></span>`;
      } else if (key === 'part_movements') {
        const disp = getModVal('removed_disposition') || row.removed_disposition || '—';
        const pre = getModVal('prior_defect_notified') === 'Yes' || Boolean(getModVal('defect_ref'));
        const out = round2(getModNum('new_part_cost') + getModNum('repair_cost'));
        const proc = round2(getModNum('sale_proceeds'));
        html = `<span>Disposition: <b>${esc(disp)}</b></span><span>Pre-Notified: <b>${pre ? 'Verified' : 'Unnotified'}</b></span><span>Outlay: <b>${fmtUSD(out, 2)}</b></span><span>Proceeds: <b>${fmtUSD(proc, 2)}</b></span>`;
      } else if (key === 'salaries') {
        const stName = getModVal('staff') || row.staff;
        const payMo = getModVal('payroll_month') || row.payroll_month || String(getModVal('date') || row.date || '').slice(0, 7);
        const salDt = getModVal('date') || row.date || todayISO();
        const usd = getModNum('usd_amount');
        const lbp = getModNum('lbp_amount');
        const totAmt = (usd > 0 || lbp > 0) ? round2(usd + lbp / getLbpFxRate(salDt, row.currency || 'LBP')) : getModNum('amount');
        if ($('insp_edit_amount') && (usd > 0 || lbp > 0)) $('insp_edit_amount').value = totAmt.toFixed(2);
        const pos = computeStaffMonthPayrollPosition(stName, getModVal('company') || row.company, payMo, getModVal('date') || row.date, row.id, true);
        if (pos && pos.hasContract) {
          const afterRem = round2(pos.monthNetEarned - (pos.paidSoFar + totAmt));
          if (pos.isFutureMonth) {
            const futAfter = afterRem >= -0.01
              ? `Future Adv (${fmtUSD(Math.max(0, afterRem), 2)} Base Left)`
              : `Future Adv (+${fmtUSD(Math.abs(afterRem), 2)} Over Base)`;
            html = `<span>${esc(pos.monthLabel)} Base: <b>${fmtUSD(pos.baseNet, 2)} ($0 Earned Yet)</b></span><span>Other Advanced: <b>${fmtUSD(pos.paidSoFar, 2)}</b></span><span>This Advance: <b>${fmtUSD(totAmt, 2)}</b></span><span>After: <b>${futAfter}</b></span>`;
          } else {
            const statusStr = afterRem < -0.01 ? `Advance +${fmtUSD(Math.abs(afterRem), 2)}` : (afterRem <= 0.01 ? 'Settled ($0.00 Left)' : `${fmtUSD(afterRem, 2)} Remaining`);
            html = `<span>${esc(pos.monthLabel)} Earned: <b>${fmtUSD(pos.monthNetEarned, 2)}</b></span><span>Other Paid: <b>${fmtUSD(pos.paidSoFar, 2)}</b></span><span>This Voucher: <b>${fmtUSD(totAmt, 2)}</b></span><span>After: <b>${statusStr}</b></span>`;
          }
        } else {
          html = `<span>Total USD: <b>${fmtUSD(totAmt, 2)}</b></span><span>Month: <b>${esc(formatPayrollMonthLabel(payMo))}</b></span>`;
        }
      } else if (key === 'expenses') {
        const mQty = getModNum('qty') || 1;
        const mAmt = getModNum('amount');
        const mMethod = getModVal('method') || row.method || 'Cash';
        const mCat = getModVal('category') || row.category || '';
        const mSub = getModVal('subcategory') || row.subcategory || '';
        const isFuel = /fuel|diesel|mazout|oil/i.test(`${mCat} ${mSub}`);
        const pendSel = $('insp_edit_price_pending');
        if (mAmt > 0 && pendSel && pendSel.value === 'Yes' && pendSel.dataset.userEdited !== '1') {
          pendSel.value = 'No';
        }
        const stillPend = pendSel ? pendSel.value === 'Yes' : (mAmt === 0 && isPendingPriceExpense(row));
        const modMthSel = $('insp_edit_method');
        if (modMthSel) {
          if (stillPend) {
            modMthSel.value = 'Credit';
            modMthSel.disabled = true;
          } else {
            modMthSel.disabled = false;
          }
        }
        const dispMethod = stillPend ? 'Credit' : mMethod;
        if (stillPend) {
          html = `<span>Quantity Received: <b>${fmtNum(mQty, mQty % 1 ? 2 : 0)}${isFuel ? ' L' : ''}</b></span><span>Status: <b style="color:var(--warn)">Pending Invoice Price ($0.00 AP)</b></span>`;
        } else if (isPendingPriceExpense(row) && mAmt > 0) {
          html = `<span>Final Invoice Price: <b>${fmtUSD(mAmt, 2)}</b></span>${isFuel && mQty > 0 ? `<span>Implied Rate: <b>${fmtUSD(mAmt / mQty, 3)} / L (${fmtNum(mQty, 0)} L)</b></span>` : ''}<span>Status: <b style="color:var(--ok)">✓ Clears Pending Price · Books to ${esc(dispMethod)}</b></span>`;
        } else {
          html = `<span>Total Amount: <b>${fmtUSD(mAmt, 2)}</b></span><span>Method: <b>${esc(dispMethod)}</b></span>${isFuel && mQty > 0 && mAmt > 0 ? `<span>Implied Rate: <b>${fmtUSD(mAmt / mQty, 3)} / L (${fmtNum(mQty, 0)} L)</b></span>` : ''}`;
        }
      } else if (key === 'fuel_malfunctions') {
        const mLit = getModNum('litres');
        const mType = getModVal('discrepancy_type') || row.discrepancy_type || 'Malfunction';
        const isWashMod = /^wash$/i.test(mType);
        ['ticket_no', 'equipment', 'driver'].forEach(fk => {
          const el = $('insp_edit_' + fk);
          const wrap = el && el.closest('.form-field');
          const hasOrig = Boolean(row && String(row[fk] || '').trim());
          if (wrap) wrap.hidden = !isWashMod && !hasOrig;
        });
        const tankDelta = round2(-mLit);
        html = `<span>Type: <b>${esc(mType)}</b></span><span>Quantity: <b>${mLit > 0 ? '+' : ''}${fmtNum(mLit, 1)} L</b></span><span>Tank Impact: <b>${tankDelta > 0 ? '+' : ''}${fmtNum(tankDelta, 1)} L (${mLit >= 0 ? '+ deducts from tank' : '− adds to tank'})</b></span>`;
      } else if (key === 'sites') {
        const mCat = getModVal('site_category') === 'customer' ? 'customer' : 'supplier';
        const isCustSite = mCat === 'customer';
        ['supplier', 'is_jv'].forEach(fk => {
          const el = $('insp_edit_' + fk);
          const wrap = el && el.closest('.form-field');
          if (wrap) wrap.hidden = isCustSite;
        });
        const custEl = $('insp_edit_customer');
        const custWrap = custEl && custEl.closest('.form-field');
        if (custWrap) custWrap.hidden = !isCustSite;
        if (isCustSite) {
          if ($('insp_edit_supplier')) $('insp_edit_supplier').value = '';
          if ($('insp_edit_is_jv')) $('insp_edit_is_jv').value = 'No';
        } else if (custEl) {
          custEl.value = '';
        }
        const mReg = getModVal('region') || row.region || 'Lebanon';
        const mParty = isCustSite ? (getModVal('customer') || 'Open Delivery') : (getModVal('supplier') || 'Open Source');
        html = `<span>Category: <b>${esc(formatSiteCategoryLabel(mCat))}</b></span><span>Region: <b>${esc(mReg)}</b></span><span>${isCustSite ? 'Linked Customer' : 'Site Owner'}: <b>${esc(mParty)}</b></span>`;
      }
      modLiveCalcEl.innerHTML = html;
      modLiveCalcEl.hidden = !html;
    };

    const openModifyDrawerAndFocus = (focusFieldKey) => {
      if (!modDrawer || !canModifyData()) return;
      modDrawer.hidden = false;
      syncModifyLiveSummary();
      const targetInp = focusFieldKey ? $('insp_edit_' + focusFieldKey) : modDrawer.querySelector('input:not([type="hidden"]), select');
      if (targetInp) {
        setTimeout(() => {
          try {
            targetInp.scrollIntoView({ behavior: 'smooth', block: 'center' });
            window.__mfgSuppressAutoFocusMenu = true;
            targetInp.focus({ preventScroll: true });
            if (targetInp.select && targetInp.tagName === 'INPUT' && targetInp.type !== 'date') targetInp.select();
          } catch (_) {
          } finally {
            setTimeout(() => { window.__mfgSuppressAutoFocusMenu = false; }, 80);
          }
        }, 30);
      } else {
        modDrawer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    };

    const setPriceBtn = $('inspSetInvoicePriceBtn');
    if (setPriceBtn) {
      setPriceBtn.addEventListener('click', () => {
        openPendingExpensePriceModal(row.id);
      });
    }
    if (opts && opts.focusModifyField && modDrawer && canModifyData()) {
      openModifyDrawerAndFocus(opts.focusModifyField);
    }
    if (modBtn && modDrawer) {
      modBtn.addEventListener('click', () => {
        if (modDrawer.hidden) openModifyDrawerAndFocus('');
        else modDrawer.hidden = true;
      });
    }
    if (modDrawer) {
      modDrawer.querySelectorAll('input, select').forEach(el => {
        if (el.id === 'insp_edit_vat_amount' || el.id === 'insp_edit_price_pending' || el.id === 'insp_edit_overtime') {
          el.addEventListener('input', () => { el.dataset.userEdited = '1'; syncModifyLiveSummary(); });
          el.addEventListener('change', () => { el.dataset.userEdited = '1'; syncModifyLiveSummary(); });
        } else {
          el.addEventListener('input', syncModifyLiveSummary);
          el.addEventListener('change', syncModifyLiveSummary);
        }
      });
      syncModifyLiveSummary();
    }

    // Wire click-to-edit on any editable cell in the General 360° form
    bodyEl.querySelectorAll('.inspector-cell[data-edit-field]').forEach(cell => {
      cell.addEventListener('click', e => {
        if (e.target && e.target.closest('[data-rel-key]')) return;
        const sel = window.getSelection && window.getSelection();
        if (sel && !sel.isCollapsed && String(sel).trim().length > 0) return;
        const fk = cell.getAttribute('data-edit-field');
        if (fk) openModifyDrawerAndFocus(fk);
      });
    });

    const cancelModBtn = $('inspCancelModifyBtn');
    if (cancelModBtn && modDrawer) {
      cancelModBtn.addEventListener('click', () => { modDrawer.hidden = true; });
    }
    const saveModBtn = $('inspSaveModifyBtn');
    if (saveModBtn && modDrawer) {
      saveModBtn.addEventListener('click', () => {
        if (!canModifyData()) { toast('Your seat does not have Modify Existing Records permission', 'err'); return; }
        const schemaMap = new Map(editSchema.map(f => [f.key, f]));
        const pendingUpdates = {};
        let effFromDate = todayISO();
        let effToDate = '';
        let validationError = '';

        modDrawer.querySelectorAll('[data-mod-field]').forEach(inp => {
          if (validationError) return;
          const fk = inp.getAttribute('data-mod-field');
          if (!fk) return;
          const fDef = schemaMap.get(fk) || {};
          if (fk === 'effective_from') {
            effFromDate = inp.value || todayISO();
            return;
          }
          if (fk === 'effective_to') {
            effToDate = inp.value || '';
            return;
          }
          const prevVal = typeof fDef.getVal === 'function'
            ? fDef.getVal(row)
            : (row[fk] !== undefined ? row[fk] : (targetEqRow ? targetEqRow[fk] : undefined));
          const nextRaw = String(inp.value ?? '').trim();

          if (fDef.type === 'select' && Array.isArray(fDef.options) && fDef.options.length) {
            const allowedVals = fDef.options.map(o => String(Array.isArray(o) ? o[0] : o));
            if (nextRaw && !allowedVals.some(av => av.toLowerCase() === nextRaw.toLowerCase()) && String(prevVal ?? '').toLowerCase() !== nextRaw.toLowerCase()) {
              validationError = `Invalid ${fDef.label || fk}: "${nextRaw}". Please choose from the valid list options.`;
              return;
            }
          }

          let nextVal;
          if (fDef.type === 'bool') {
            nextVal = nextRaw === 'Yes' || nextRaw === 'true' || nextRaw === '1';
          } else if (fDef.type === 'number' || typeof prevVal === 'number') {
            nextVal = nextRaw === '' ? null : (!Number.isNaN(Number(nextRaw)) ? Number(nextRaw) : nextRaw);
          } else {
            nextVal = nextRaw;
          }

          const prevNorm = typeof prevVal === 'boolean' ? String(prevVal) : String(prevVal ?? '');
          const nextNorm = typeof nextVal === 'boolean' ? String(nextVal) : String(nextVal ?? '');
          if (prevNorm !== nextNorm) {
            pendingUpdates[fk] = nextVal;
          }
        });

        if (validationError) {
          toast(validationError, 'err');
          return;
        }
        if (effToDate && effToDate < effFromDate) {
          toast('Effective To Date cannot be before Effective From Date.', 'err');
          return;
        }
        const candStartDt = String((pendingUpdates.start_date !== undefined ? pendingUpdates.start_date : row.start_date) || '').slice(0, 10);
        const candEndDt = String((pendingUpdates.end_date !== undefined ? pendingUpdates.end_date : row.end_date) || '').slice(0, 10);
        if (candStartDt && candEndDt && candEndDt < candStartDt) {
          toast('End Date cannot be before Start Date.', 'err');
          return;
        }
        if (UNIVERSAL_MAIN_SPEC[key]) {
          const candidate = Object.assign({}, row, pendingUpdates);
          const mainVal = universalMainValue(key, candidate);
          if (!mainVal) {
            toast(`${UNIVERSAL_MAIN_SPEC[key].label} Name cannot be blank.`, 'err');
            return;
          }
          const dup = findUniversalDuplicate(key, mainVal, { excludeId: row.id, plateNo: candidate.plate_no, category: candidate.category, siteCategory: resolveSiteCategory(candidate) });
          if (dup) {
            toast(`Duplicate ${key === 'sites' ? formatSiteCategoryLabel(candidate) : UNIVERSAL_MAIN_SPEC[key].label} "${mainVal}" already exists · modification blocked.`, 'err');
            return;
          }
        }
        const origRowSnap = Object.assign({}, row);
        const editedKeySet = new Set(Object.keys(pendingUpdates));
        let changedCount = 0;
        const isBoundedEqSub = Boolean(isEquipInspect && effToDate);
        Object.entries(pendingUpdates).forEach(([fk, nextVal]) => {
          if (isBoundedEqSub && ['capacity', 'supplier', 'default_driver'].includes(fk)) {
            changedCount++;
            return;
          }
          row[fk] = nextVal;
          if (targetEqRow && targetEqRow !== row && ['capacity', 'supplier', 'default_driver', 'plate_no'].includes(fk)) {
            targetEqRow[fk] = nextVal;
          }
          if (key === 'drivers' && (fk === 'driver' || fk === 'name')) { row.name = nextVal; row.driver = nextVal; }
          if (key === 'equipment' && (fk === 'equipment' || fk === 'name')) { row.name = nextVal; row.equipment = nextVal; }
          if (key === 'employments' && fk === 'staff') { row.staff = nextVal; }
          changedCount++;
        });

        // Synchronize aliases & linked master/transactional calculations
        if (key === 'customers') {
          if ('name' in pendingUpdates) {
            row.Customer = row.name;
            if (!row.official_name) row.official_name = row.name;
          }
          if ('address' in pendingUpdates) row.region = row.address;
          if ('region' in pendingUpdates) row.address = row.region;
          if ('method' in pendingUpdates) row.Method = row.method;
          if ('vat_registered' in pendingUpdates) row['VAT Registered'] = row.vat_registered ? 'Yes' : 'No';
          if ('credit_days' in pendingUpdates || 'credit_limit' in pendingUpdates) {
            const custName = row.name || row.Customer;
            const cDays = row.credit_days != null ? Number(row.credit_days) : 30;
            const cLim = row.credit_limit != null ? Number(row.credit_limit) : 0;
            if (!Array.isArray(SEED.records.credit_terms)) SEED.records.credit_terms = [];
            if (!Array.isArray(STATE.customRecords.credit_terms)) STATE.customRecords.credit_terms = [];
            let ctRow = creditTermsForCustomer(custName);
            if (ctRow) {
              ctRow.credit_days = cDays;
              ctRow.payment_days = cDays;
              ctRow.credit_limit = cLim;
              ctRow.name = `${custName} · Net ${cDays}d`;
              const ctIdx = STATE.customRecords.credit_terms.findIndex(x => String(x.id) === String(ctRow.id));
              if (ctIdx >= 0) Object.assign(STATE.customRecords.credit_terms[ctIdx], ctRow);
              else STATE.customRecords.credit_terms.unshift(Object.assign({}, ctRow));
            } else if (custName) {
              ctRow = {
                id: uid('ct'),
                name: `${custName} · Net ${cDays}d`,
                company: row.company || 'WTC',
                customer: custName,
                credit_days: cDays,
                payment_days: cDays,
                credit_limit: cLim,
                start_date: todayISO(),
                source: 'app',
                entered_by: activeUser().full_name,
                entered_by_email: activeUser().email,
                entered_at: nowStamp(),
                voided: false
              };
              SEED.records.credit_terms.unshift(ctRow);
              STATE.customRecords.credit_terms.unshift(Object.assign({}, ctRow));
            }
          }
        } else if (key === 'suppliers') {
          if ('name' in pendingUpdates) {
            row.Supplier = row.name;
            if (!row.official_name) row.official_name = row.name;
          }
          if ('phone' in pendingUpdates) row.contact = row.phone;
          if ('location' in pendingUpdates) row.region = row.location;
          if ('mof_no' in pendingUpdates) row.financial_no = row.mof_no;
          if ('iva' in pendingUpdates) row.IVA = row.iva ? 'Yes' : 'No';
          if ('category1' in pendingUpdates || 'category2' in pendingUpdates || 'is_truck_owner' in pendingUpdates) {
            const rawCats = [row.category1, row.category2, row.category3].filter(Boolean);
            if (row.is_truck_owner && !rawCats.some(c => /hauler|truck\s*owner|transport/i.test(String(c)))) {
              rawCats.unshift('Hauler / Truck Owner');
            }
            const cleanCats = parseSupplierCategories(rawCats);
            row.categories = cleanCats;
            row.category = cleanCats.join(', ');
            if (!row.category1 && cleanCats[0]) row.category1 = cleanCats[0];
            if (cleanCats.some(c => /hauler|truck\s*owner|transport/i.test(String(c)))) row.is_truck_owner = true;
          }
        } else if (key === 'sales_tickets') {
          const salesCalc = resolveInspectorSalesTicketCalc(origRowSnap, row, editedKeySet);
          row.price = salesCalc.price;
          row.trans_price = salesCalc.transPrice;
          row.total = salesCalc.total;
          row.vat = salesCalc.vat;
          row.total_ttc = salesCalc.totalTtc;
          if (salesCalc.matEdited || salesCalc.transEdited) {
            if (salesCalc.matIsFlat) row.mat_indiff = true;
            else delete row.mat_indiff;
            if (salesCalc.transIsFlat) row.trans_indiff = true;
            else delete row.trans_indiff;
          }
        } else if (key === 'raw_purchases') {
          const rawCalc = resolveInspectorRawTicketCalc(origRowSnap, row, editedKeySet);
          row.cost = rawCalc.cost;
          row.trans_cost = rawCalc.transCost;
          row.total = rawCalc.total;
          if (rawCalc.matEdited || rawCalc.transEdited) {
            if (rawCalc.matIsFlat) row.mat_indiff = true;
            else delete row.mat_indiff;
            if (rawCalc.transIsFlat) row.trans_indiff = true;
            else delete row.trans_indiff;
          }
        } else if (key === 'vat_invoices') {
          const net = round2(Number(row.net_amount || 0));
          const vat = ('vat_amount' in pendingUpdates && row.vat_amount != null) ? round2(Number(row.vat_amount)) : round2(net * getVatFraction(row.date || row.rep_date));
          row.net_amount = net;
          row.vat_amount = vat;
          row.total_ttc = round2(net + vat);
          if ('invoice_no' in pendingUpdates && row.invoice_no) row.name = row.invoice_no;
        } else if (key === 'attendance') {
          if ('status' in pendingUpdates) {
            row.type = row.status;
          }
          if ('set_date' in pendingUpdates || 'date' in pendingUpdates) {
            const effSd = String(row.set_date || row.rep_date || row.date || '').slice(0, 10);
            if (effSd) {
              row.set_date = effSd;
              row.rep_date = effSd;
              row.month = effSd.slice(0, 7);
            }
          }
          if (('in_time' in pendingUpdates || 'out_time' in pendingUpdates) && !('worked_hours' in pendingUpdates)) {
            const inF = fmtAttClockTime(row.in_time || '');
            const outF = fmtAttClockTime(row.out_time || '');
            row.in_time = inF;
            row.out_time = outF;
            row.check_in = inF;
            row.check_out = outF;
            if (inF && outF) {
              row.worked_hours = computeShiftWorkedHours(inF, outF);
              row.regular_hours = round2(Math.max(0, row.worked_hours - Number(row.overtime_hours || 0)));
            }
          }
        } else if (key === 'salaries') {
          if (('usd_amount' in pendingUpdates || 'lbp_amount' in pendingUpdates) && !('amount' in pendingUpdates)) {
            if (row.usd_amount == null) row.usd_amount = 0;
            row.amount = round2(Number(row.usd_amount || 0) + Number(row.lbp_amount || 0) / getLbpFxRate(row.date || row.rep_date, row.currency || 'LBP'));
          }
        } else if (key === 'logistics_allowances') {
          if ('usd_amount' in pendingUpdates || 'lbp_amount' in pendingUpdates) {
            const u = Number(row.usd_amount || 0);
            const l = Number(row.lbp_amount || 0);
            if ((u > 0 || l > 0) && !('daily_usd' in pendingUpdates)) {
              row.daily_usd = round2(u + l / getLbpFxRate());
            }
          }
          if ('days_count' in pendingUpdates || 'daily_usd' in pendingUpdates || 'usd_amount' in pendingUpdates || 'lbp_amount' in pendingUpdates) {
            const dc = Math.max(1, Number(row.days_count || 6));
            const du = Number(row.daily_usd || 0);
            if (du > 0 && !('amount' in pendingUpdates)) {
              row.amount = round2(dc * du);
            }
          }
        } else if (key === 'freelance_entries') {
          if (('hours' in pendingUpdates || 'extra_hours' in pendingUpdates || 'rate_usd' in pendingUpdates) && !('total' in pendingUpdates)) {
            const hrs = Number(row.hours || 0) + Number(row.extra_hours || 0);
            row.total = round2(hrs * Number(row.rate_usd || 0));
          }
        } else if (key === 'conversions') {
          const isU2L = !/^lbp/i.test(row.type || 'USD to LBP');
          const usd = round2(Number(row.usd_amount || 0));
          const lbp = Math.round(Number(row.lbp_amount || 0));
          const fx = (usd > 0 && lbp > 0) ? round2(lbp / usd) : Number(row.exchange_rate || row.fx_rate || getLbpFxRate(row.date || row.rep_date));
          row.from_currency = isU2L ? 'USD' : 'LBP';
          row.to_currency = isU2L ? 'LBP' : 'USD';
          row.usd_delta = isU2L ? -usd : usd;
          row.lbp_delta = isU2L ? lbp : -lbp;
          row.exchange_rate = fx;
          row.fx_rate = fx;
          row.amount = usd;
        } else if (key === 'fx_rates') {
          row.currency = String(row.currency || 'LBP').trim().toUpperCase();
          row.start_date = String(row.start_date || row.date || todayISO()).slice(0, 10);
          row.date = row.start_date;
          row.rep_date = row.start_date;
          row.rate = Number(row.rate || 0);
          row.name = (String(row.id) === 'fx-20240101-lbp-89500-001' && row.currency === 'LBP' && row.start_date === '2024-01-01' && row.rate === DEFAULT_LBP_FX_RATE)
            ? 'FX-20240101-LBP-89500-001'
            : buildFxRateRefName(row.currency, row.rate, row.start_date);
        } else if (key === 'vat_rates') {
          row.start_date = String(row.start_date || row.date || todayISO()).slice(0, 10);
          row.date = row.start_date;
          row.rep_date = row.start_date;
          row.vat_percent = Number(row.vat_percent || 0);
          row.vat_fx_rate = Number(row.vat_fx_rate || getLbpFxRate(row.start_date, 'LBP'));
          row.name = buildVatRateRefName(row.vat_percent, row.vat_fx_rate, row.start_date);
        } else if (key === 'currencies') {
          row.code = String(row.code || '').trim().toUpperCase();
          row.decimals = Number.isFinite(Number(row.decimals)) ? Number(row.decimals) : 2;
        } else if (key === 'jv_distributions') {
          if (('amount' in pendingUpdates || 'difference' in pendingUpdates) && !('total' in pendingUpdates)) {
            row.total = round2(Number(row.amount || 0) + Number(row.difference || 0));
          }
        } else if (key === 'price_rules') {
          const rtTrim = String(row.rule_type || '').trim();
          const isTransOnlyPr = /^(Transport Price \(Site\)|Haulage \(Customer Site\))$/i.test(rtTrim);
          const hasTransPr = /^(Sales \(Delivery\)|Transport Price \(Site\)|Haulage \(Customer Site\))$/i.test(rtTrim);
          const hasMatPr = !isTransOnlyPr;
          const upRaw = round2(Number(row.unit_price || 0));
          const tpRaw = round2(Number(row.trans_unit_price || 0));
          const matIsTruckPr = hasMatPr && /^truck$/i.test(String(row.unit || '').trim());
          const transIsTruckPr = hasTransPr && /^truck$/i.test(String((isTransOnlyPr ? (row.rate_per || row.unit) : row.rate_per) || '').trim());
          if (!hasMatPr) {
            row.unit = transIsTruckPr ? 'Truck' : (row.rate_per || row.unit || 'm³');
            row.unit_price = 0;
            row.price = null;
          } else if (matIsTruckPr) {
            row.unit_price = 0;
            row.price = null;
            row.indiff_price = upRaw || null;
            row.adj1 = 0;
            row.adj2 = 0;
          } else {
            row.unit_price = upRaw;
            row.price = upRaw || null;
            row.indiff_price = null;
          }
          if (!hasTransPr) {
            row.trans_unit_price = 0;
            row.trans_indiff_price = null;
            row.trans_adj1 = 0;
            row.trans_adj2 = 0;
          } else if (transIsTruckPr) {
            row.rate_per = 'Truck';
            row.trans_unit_price = 0;
            if (isTransOnlyPr) {
              row.unit = 'Truck';
              row.indiff_price = tpRaw || null;
              row.trans_indiff_price = null;
            } else {
              row.trans_indiff_price = tpRaw || null;
            }
            row.trans_adj1 = 0;
            row.trans_adj2 = 0;
          } else {
            row.trans_unit_price = tpRaw;
            row.trans_indiff_price = null;
            if (isTransOnlyPr) row.indiff_price = null;
          }
          const effUpSave = Number(row.unit_price || 0);
          row.total1 = (row.qty1 != null && effUpSave > 0) ? round2(Number(row.qty1) * effUpSave + Number(row.adj1 || 0)) : null;
          row.total2 = (row.qty2 != null && effUpSave > 0) ? round2(Number(row.qty2) * effUpSave + Number(row.adj2 || 0)) : null;
        } else if (key === 'equipment_defects') {
          if (!isDefectOpen(row)) {
            row.resolved_date = row.resolved_date || todayISO();
            if (row.equipment && Array.isArray(STATE.customRecords.company_equipment)) {
              const defPool = (STATE.customRecords.equipment_defects || []).concat(SEED.records.equipment_defects || []);
              const remOpen = defPool.some(d => d && !d.voided && String(d.id) !== String(row.id) && norm(d.equipment) === norm(row.equipment) && isDefectOpen(d));
              if (!remOpen) {
                const allCoEq = (SEED.records.company_equipment || []).concat(STATE.customRecords.company_equipment || []);
                allCoEq.forEach(ce => {
                  if (ce && !ce.voided && norm(ce.equipment) === norm(row.equipment) && ce.status === 'Under repair') {
                    ce.status = ce._prev_status || 'Active';
                    const cIdx = STATE.customRecords.company_equipment.findIndex(x => x && String(x.id) === String(ce.id));
                    if (cIdx >= 0) Object.assign(STATE.customRecords.company_equipment[cIdx], ce);
                    postRecordToLocalApi('company_equipment', ce);
                  }
                });
              }
            }
          }
        } else if (key === 'part_movements') {
          if ('defect_ref' in pendingUpdates && !('prior_defect_notified' in pendingUpdates)) {
            row.prior_defect_notified = Boolean(row.defect_ref);
          }
        } else if (key === 'expenses') {
          const amt = round2(Number(row.amount || 0));
          row.amount = amt;
          if (amt > 0 && row.price_pending && !('price_pending' in pendingUpdates && pendingUpdates.price_pending === true)) {
            row.price_pending = false;
            changedCount++;
          } else if ('price_pending' in pendingUpdates && row.price_pending) {
            row.amount = 0;
            row.method = 'Credit';
          }
        } else if (key === 'fuel_malfunctions') {
          row.litres = round2(Number(row.litres || 0));
          if ('discrepancy_type' in pendingUpdates && !/^wash$/i.test(String(row.discrepancy_type || ''))) {
            row.ticket_no = '';
            row.equipment = '';
            row.driver = '';
          }
          row.name = `MALF ${row.date || ''} ${row.discrepancy_type || 'Malfunction'}${row.ticket_no ? ' #' + row.ticket_no : ''}`;
        } else if (key === 'sites') {
          const effCat = resolveSiteCategory(row);
          row.site_category = effCat;
          delete row._seedCatAuto;
          if (effCat === 'customer') {
            row.supplier = '';
            row.is_jv = false;
          } else {
            row.customer = '';
          }
          if (window.MFG_GEO && row.latitude != null && row.longitude != null) {
            window.MFG_GEO.persistLocationPin({ targetType: 'site', siteId: row.id, siteCategory: effCat, name: row.name, lat: row.latitude, lng: row.longitude, region: row.region }, { SEED, STATE });
          }
        }

        if (isEquipInspect && targetEqRow && ('capacity' in pendingUpdates || 'supplier' in pendingUpdates || 'default_driver' in pendingUpdates || Boolean(effToDate))) {
          appendOrUpdateTruckWindow(targetEqRow, {
            co: row.company || 'WTC',
            side: 'both',
            s: effFromDate,
            e: effToDate,
            cap: 'capacity' in pendingUpdates ? pendingUpdates.capacity : targetEqRow.capacity,
            own: 'supplier' in pendingUpdates ? pendingUpdates.supplier : targetEqRow.supplier,
            drv: 'default_driver' in pendingUpdates ? pendingUpdates.default_driver : targetEqRow.default_driver
          });
          if (targetEqRow !== row) {
            if (!Array.isArray(STATE.customRecords.equipment)) STATE.customRecords.equipment = [];
            const eqIdx = STATE.customRecords.equipment.findIndex(x => String(x.id) === String(targetEqRow.id));
            if (eqIdx >= 0) Object.assign(STATE.customRecords.equipment[eqIdx], targetEqRow);
            else STATE.customRecords.equipment.unshift(Object.assign({}, targetEqRow));
          }
        }
        row.modified_by = activeUser().email;
        row.modified_at = new Date().toISOString();
        if (!Array.isArray(STATE.customRecords[key])) STATE.customRecords[key] = [];
        const cIdx = STATE.customRecords[key].findIndex(x => String(x.id) === String(row.id));
        if (cIdx >= 0) Object.assign(STATE.customRecords[key][cIdx], row);
        else STATE.customRecords[key].unshift(Object.assign({}, row));
        applyCustomRecordsToSeed();
        saveLocalAuthAndRecords();
        renderApp();
        postRecordToLocalApi(key, row);
        syncWithCloud(true);
        toast(changedCount ? `✓ Record modified (${changedCount} field${changedCount === 1 ? '' : 's'} updated)` : '✓ Record saved');
        showRecordInspector(key, row.id || row.name || idOrName, { fromCrumbIdx: STATE.inspectorHistory.length - 1, tab: activeTab });
      });
    }

    const addTwBtn = $('inspAddTruckWinBtn');
    if (addTwBtn && targetEqRow) {
      addTwBtn.addEventListener('click', () => {
        if (!canModifyData()) { toast('Your seat does not have Modify Existing Records permission', 'err'); return; }
        const capVal = Number(($('insp_tw_cap') && $('insp_tw_cap').value) || 0);
        const sVal = ($('insp_tw_start') && $('insp_tw_start').value) || todayISO();
        const eVal = ($('insp_tw_end') && $('insp_tw_end').value) || '';
        const drvVal = (($('insp_tw_drv') && $('insp_tw_drv').value) || '').trim();
        const isTruckCat = /^(truck|mixer)/i.test(targetEqRow.type || '');
        if (isTruckCat && !(capVal > 0) && !drvVal) { toast('Enter Truck Capacity (m³) or Active Driver.', 'err'); return; }
        if (!isTruckCat && !drvVal && !(capVal > 0)) { toast('Select the Active / Substitute Driver to log.', 'err'); return; }
        if (eVal && eVal < sVal) { toast('End Date cannot be before Start Date.', 'err'); return; }
        appendOrUpdateTruckWindow(targetEqRow, {
          co: ($('insp_tw_co') && $('insp_tw_co').value) || 'WTC',
          side: ($('insp_tw_side') && $('insp_tw_side').value) || 'both',
          s: sVal,
          e: eVal,
          cap: capVal,
          own: ($('insp_tw_own') && $('insp_tw_own').value) || '',
          drv: drvVal,
          cust: ($('insp_tw_cust') && $('insp_tw_cust').value) || '',
          site: ($('insp_tw_site') && $('insp_tw_site').value) || ''
        });
        if (targetEqRow !== row && targetEqRow.capacity) row.capacity = targetEqRow.capacity;
        if (!Array.isArray(STATE.customRecords.equipment)) STATE.customRecords.equipment = [];
        const eqIdx = STATE.customRecords.equipment.findIndex(x => String(x.id) === String(targetEqRow.id));
        if (eqIdx >= 0) Object.assign(STATE.customRecords.equipment[eqIdx], targetEqRow);
        else STATE.customRecords.equipment.unshift(Object.assign({}, targetEqRow));
        applyCustomRecordsToSeed();
        saveLocalAuthAndRecords();
        renderApp();
        toast(`✓ Logged equipment assignment (${drvVal || (fmtNum(capVal, 1) + ' m³')} · ${sVal} → ${eVal || 'Open'})`);
        showRecordInspector(key, row.id || idOrName, { fromCrumbIdx: STATE.inspectorHistory.length - 1, tab: activeTab });
      });
    }

    bodyEl.querySelectorAll('[data-del-tw-idx]').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      if (!canModifyData() || !targetEqRow || !Array.isArray(targetEqRow.adj_windows)) return;
      const idx = Number(btn.getAttribute('data-del-tw-idx'));
      if (idx >= 0 && idx < targetEqRow.adj_windows.length) {
        targetEqRow.adj_windows.splice(idx, 1);
        _WIN_REV++;
        _FLEET_IDX = null;
        if (!Array.isArray(STATE.customRecords.equipment)) STATE.customRecords.equipment = [];
        const eqIdx = STATE.customRecords.equipment.findIndex(x => String(x.id) === String(targetEqRow.id));
        if (eqIdx >= 0) Object.assign(STATE.customRecords.equipment[eqIdx], targetEqRow);
        else STATE.customRecords.equipment.unshift(Object.assign({}, targetEqRow));
        applyCustomRecordsToSeed();
        saveLocalAuthAndRecords();
        renderApp();
        toast('✓ Removed equipment log window');
        showRecordInspector(key, row.id || idOrName, { fromCrumbIdx: STATE.inspectorHistory.length - 1, tab: activeTab });
      }
    }));

    const viewMapBtn = $('inspViewOnMapBtn');
    if (viewMapBtn && window.MFG_GEO) {
      viewMapBtn.addEventListener('click', () => {
        if (key === 'regions') {
          window.MFG_GEO.jumpToMapRegionOrSite({ region: row.name || row.region });
          closeRecordInspector();
          setView('reg_regions');
        } else {
          const siteNm = key === 'sites' ? (row.name || row.Site) : row.site;
          window.MFG_GEO.jumpToMapRegionOrSite({ site: siteNm, region: row.region || '', bu: row.company || '' });
          closeRecordInspector();
          setView('reg_sites');
        }
      });
    }

    // Wire clickable lookup pills inside the inspector
    bodyEl.querySelectorAll('[data-rel-key]').forEach(el => el.addEventListener('click', e => {
      e.stopPropagation();
      const rk = el.getAttribute('data-rel-key');
      const rv = el.getAttribute('data-rel-val');
      if (rk && rv) showRecordInspector(rk, rv, { pushHistory: true });
    }));

    // Wire clickable subgrid rows inside the inspector
    bodyEl.querySelectorAll('tr.rrow[data-rid]').forEach(tr => tr.addEventListener('click', e => {
      if (e.target.closest('[data-rel-key], button, a, input')) return;
      const sel = window.getSelection && window.getSelection();
      if (sel && !sel.isCollapsed && String(sel).trim().length > 0) return;
      showRecordInspector(tr.getAttribute('data-rkey'), tr.getAttribute('data-rid'), { pushHistory: true });
    }));

    // Wire inline void buttons inside inspector subgrids
    bodyEl.querySelectorAll('[data-void]').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      if (btn.dataset.armed === '1') {
        voidRecord(btn.getAttribute('data-void'), btn.getAttribute('data-void-id'));
        showRecordInspector(key, row.id || idOrName, { fromCrumbIdx: STATE.inspectorHistory.length - 1, tab: activeTab });
        return;
      }
      btn.dataset.armed = '1';
      btn.textContent = 'Void?';
      btn.classList.add('armed');
      setTimeout(() => { if (btn.isConnected) { btn.dataset.armed = ''; btn.textContent = '✕'; btn.classList.remove('armed'); } }, 4000);
    }));

    // Wire instant search filter inside each related subgrid
    bodyEl.querySelectorAll('[data-sg-filter]').forEach(inp => inp.addEventListener('input', e => {
      const sgId = inp.getAttribute('data-sg-filter');
      const q = norm(e.target.value);
      const tbody = bodyEl.querySelector(`[data-sg-tbody="${sgId}"]`);
      if (!tbody) return;
      tbody.querySelectorAll('tr').forEach(tr => {
        tr.hidden = Boolean(q && !norm(tr.innerText).includes(q));
      });
    }));

    panel.hidden = false;
    bodyEl.scrollTop = 0;
    document.body.classList.add('modal-open');
    wireModalSuggestions(bodyEl);
    if (window.MFG_TABLE_COLS && typeof window.MFG_TABLE_COLS.enhanceAllTables === 'function') {
      window.MFG_TABLE_COLS.enhanceAllTables(bodyEl);
    }
  }

  function closeRecordInspector() {
    const panel = $('recordInspector');
    if (panel) panel.hidden = true;
    const m = $('entryModal');
    if (!m || m.hidden) document.body.classList.remove('modal-open');
    if (STATE.renderPending) { STATE.renderPending = false; renderApp(); }
  }

  // ==========================================================================
  // MULTI-DEVICE CLOUD RELAY + LOCAL PERSISTENCE
  // ==========================================================================
  function sanitizeKioskPunchesList(list) {
    if (!Array.isArray(list)) return [];
    return list.filter(p => p && p.id && !/^pn-seed-/.test(String(p.id)));
  }

  function saveLocalAuthAndRecords() {
    try {
      STATE.kioskPunches = sanitizeKioskPunchesList(STATE.kioskPunches);
      if (STATE.kioskLastPunch && /^pn-seed-/.test(String(STATE.kioskLastPunch.id || ''))) {
        STATE.kioskLastPunch = STATE.kioskPunches[0] || null;
      }
      localStorage.setItem('isabi_mfg_users_v2', JSON.stringify(STATE.users));
      localStorage.setItem('isabi_mfg_sessions_v2', JSON.stringify(STATE.sessions.slice(0, 50)));
      localStorage.setItem('isabi_mfg_custom_recs_v2', JSON.stringify(STATE.customRecords));
      localStorage.setItem('isabi_mfg_sentinel_reviews_v1', JSON.stringify(STATE.sentinelReviews || {}));
      localStorage.setItem('isabi_mfg_alert_rules_v1', JSON.stringify(STATE.alertRules || { overrides: {}, custom: [] }));
      localStorage.setItem('isabi_mfg_face_settings_v2', JSON.stringify(STATE.faceSettings));
      localStorage.setItem('isabi_mfg_face_settings_v1', JSON.stringify(STATE.faceSettings));
      localStorage.setItem('isabi_mfg_kiosk_punches_v1', JSON.stringify((STATE.kioskPunches || []).slice(0, 300)));
      localStorage.setItem('isabi_mfg_staff_bio_v1', JSON.stringify(STATE.staffBiometrics || {}));
      localStorage.setItem('isabi_mfg_work_sched_v1', JSON.stringify(STATE.workSchedules || { shiftTypes: [], staffRules: {} }));
      localStorage.setItem('isabi_mfg_lbp_fx_rate_v1', String(getLbpFxRate()));
      if (STATE.lbpFxUpdatedAt) localStorage.setItem('isabi_mfg_lbp_fx_updated_v1', STATE.lbpFxUpdatedAt);
    } catch (_) { /* storage full or blocked — the cloud copy still holds the state */ }
  }

  function mergeUserRow(existing, incoming) {
    if (!existing) return Object.assign({ face_samples: [], face_thumbs: [], face_required: false, auth_mode: '', face_updated_at: '', seat_updated_at: '' }, incoming);
    if (!incoming) return existing;
    const exSeatTs = String(existing.seat_updated_at || '');
    const inSeatTs = String(incoming.seat_updated_at || '');
    const preferExistingSeat = !!(exSeatTs && (!inSeatTs || exSeatTs > inSeatTs));
    const out = preferExistingSeat
      ? Object.assign({}, incoming, existing)
      : Object.assign({}, existing, incoming);
    if (existing.id && /^u\d+$/i.test(String(existing.id)) && /^u-(hussein|zeinab|sabah)$/i.test(String(out.id || ''))) {
      out.id = existing.id;
    }
    out.seat_updated_at = exSeatTs > inSeatTs ? exSeatTs : (inSeatTs || exSeatTs);
    if (existing.last_login_at && incoming.last_login_at) {
      out.last_login_at = String(existing.last_login_at) > String(incoming.last_login_at) ? existing.last_login_at : incoming.last_login_at;
    } else {
      out.last_login_at = existing.last_login_at || incoming.last_login_at || '';
    }
    const exSamples = userFaceSamples(existing);
    const inSamples = userFaceSamples(incoming);
    const exThumbs = userFaceThumbs(existing);
    const inThumbs = userFaceThumbs(incoming);
    const exTs = String(existing.face_updated_at || '');
    const inTs = String(incoming.face_updated_at || '');
    if (inSamples.length && ((!exSamples.length && !(existing.face_cleared && exTs > inTs)) || inTs >= exTs)) {
      out.face_samples = inSamples;
      out.face_thumbs = inThumbs.length ? inThumbs : exThumbs;
      out.face_required = incoming.face_required != null ? !!incoming.face_required : true;
      out.face_updated_at = inTs || exTs;
      delete out.face_cleared;
    } else if (exSamples.length && (!inSamples.length && !(incoming.face_cleared && inTs > exTs))) {
      out.face_samples = exSamples;
      out.face_thumbs = exThumbs;
      out.face_required = existing.face_required != null ? !!existing.face_required : true;
      out.face_updated_at = exTs;
      delete out.face_cleared;
    } else {
      out.face_samples = inSamples;
      out.face_thumbs = inSamples.length ? (inThumbs.length ? inThumbs : exThumbs) : [];
      out.face_required = !!(incoming.face_required && inSamples.length);
      out.face_updated_at = inTs || exTs;
      if (!out.face_samples.length && (existing.face_cleared || incoming.face_cleared)) out.face_cleared = true;
    }
    if (preferExistingSeat && existing.auth_mode != null) out.auth_mode = existing.auth_mode;
    else if (incoming.auth_mode != null) out.auth_mode = incoming.auth_mode;
    if (preferExistingSeat && existing.custom_perms != null) out.custom_perms = existing.custom_perms;
    else if (incoming.custom_perms != null) out.custom_perms = incoming.custom_perms;
    else if (existing.custom_perms != null) out.custom_perms = existing.custom_perms;
    return out;
  }

  function ensureUniversalCanonicalIndex() {
    if (!SEED._coreReady) return;
    if (SEED._canonicalById && SEED._canonicalByMain) return;
    SEED._canonicalById = {};
    SEED._canonicalByMain = {};
    Object.keys(UNIVERSAL_MAIN_SPEC).forEach(k => {
      const byId = new Map();
      const byMain = new Map();
      const list = (SEED.records && Array.isArray(SEED.records[k])) ? SEED.records[k] : [];
      list.forEach(r => {
        if (!r || !r.id) return;
        const sid = String(r.id);
        byId.set(sid, Object.assign({}, r));
        const mk = universalMainNormKey(k, r);
        if (mk && !byMain.has(mk)) byMain.set(mk, sid);
      });
      SEED._canonicalById[k] = byId;
      SEED._canonicalByMain[k] = byMain;
    });
  }

  function sanitizeUniversalCustomRecords() {
    if (!SEED._coreReady) return false;
    ensureUniversalCanonicalIndex();
    let removedAny = false;
    Object.keys(UNIVERSAL_MAIN_SPEC).forEach(k => {
      const arr = STATE.customRecords && STATE.customRecords[k];
      if (!Array.isArray(arr) || !arr.length) return;
      const canonById = SEED._canonicalById[k] || new Map();
      const canonByMain = SEED._canonicalByMain[k] || new Map();
      const voidedIds = new Set();
      arr.forEach(r => {
        if (r && r.voided && r.id != null) voidedIds.add(String(r.id));
      });
      const seenMainToId = new Map();
      canonByMain.forEach((sid, mk) => {
        if (!voidedIds.has(sid)) seenMainToId.set(mk, sid);
      });
      const cleaned = [];
      arr.forEach(r => {
        if (!r) { removedAny = true; return; }
        const rid = String(r.id == null ? '' : r.id);
        const mk = universalMainNormKey(k, r);
        const existingId = mk ? seenMainToId.get(mk) : null;
        if (existingId && existingId !== rid) {
          removedAny = true;
          const origSeed = canonById.get(existingId);
          const seedRow = (SEED.records[k] || []).find(x => x && String(x.id) === existingId);
          if (origSeed && seedRow) {
            seedRow.source = origSeed.source || '';
            delete seedRow.entered_by;
            delete seedRow.entered_by_email;
            delete seedRow.entered_at;
          }
          return;
        }
        if (r.voided) {
          cleaned.push(r);
          return;
        }
        if (!mk) { removedAny = true; return; }
        seenMainToId.set(mk, rid);
        cleaned.push(r);
      });
      if (cleaned.length !== arr.length) {
        STATE.customRecords[k] = cleaned;
      }
    });
    if (SEED._recordsReady) {
      const posRe = /^(?:st|rp|fi|ex|exi|oil|rc|sp|sa|at|em|ls|cv|dt)\d+$/;
      CR_KEYS.forEach(k => {
        const arr = STATE.customRecords && STATE.customRecords[k];
        const seedArr = SEED.records && SEED.records[k];
        if (!Array.isArray(arr) || !arr.length || !Array.isArray(seedArr) || !seedArr.length) return;
        const seedById = new Map(seedArr.map(x => [String(x.id), x]));
        const nextArr = arr.filter(r => {
          if (!r) return false;
          const rid = String(r.id == null ? '' : r.id);
          if (!posRe.test(rid)) return true;
          const sRow = seedById.get(rid);
          if (!sRow) return false;
          if (r.date && sRow.date && String(r.date) !== String(sRow.date)) return false;
          if (r.staff && sRow.staff && norm(r.staff) !== norm(sRow.staff)) return false;
          if (r.supplier && sRow.supplier && norm(r.supplier) !== norm(sRow.supplier)) return false;
          if (r.customer && sRow.customer && norm(r.customer) !== norm(sRow.customer)) return false;
          return true;
        });
        if (nextArr.length !== arr.length) {
          STATE.customRecords[k] = nextArr;
          removedAny = true;
        }
      });
    }
    if (removedAny) {
      saveLocalAuthAndRecords();
    }
    return removedAny;
  }

  // Union-merge another device's app entries into ours. A void tombstone always wins.
  function mergeCustomRecords(remote) {
    if (!remote || typeof remote !== 'object') return false;
    ensureUniversalCanonicalIndex();
    let changed = false;
    CR_KEYS.forEach(k => {
      const inc = Array.isArray(remote[k]) ? remote[k] : [];
      const mine = STATE.customRecords[k];
      const byId = new Map(mine.map(r => [r.id, r]));
      inc.forEach(r => {
        if (!r || !r.id) return;
        const cur = byId.get(r.id);
        if (!cur) { mine.push(r); byId.set(r.id, r); changed = true; }
        else if (r.voided && !cur.voided) { cur.voided = true; cur.voided_by = r.voided_by; cur.voided_at = r.voided_at; changed = true; }
        else if (!cur.voided && !r.voided && r.modified_at && (!cur.modified_at || String(r.modified_at) > String(cur.modified_at))) { Object.assign(cur, r); changed = true; }
      });
    });
    if (sanitizeUniversalCustomRecords()) changed = true;
    return changed;
  }

  // Project the app entries onto the seed registers (voided rows drop out, new rows sort in by date, and fleet owner/driver links stay synchronized)
  function applyCustomRecordsToSeed() {
    ensureGlobalFinanceTablesSeeded();
    ensureUniversalCanonicalIndex();
    sanitizeUniversalCustomRecords();
    SEED._customRev = (SEED._customRev || 0) + 1;
    const masterByNameKeys = new Set(['suppliers', 'equipment', 'company_equipment', 'drivers', 'customers', 'products', 'sites', 'regions', 'expense_categories', 'expense_subcategories', 'currencies', 'fx_rates', 'vat_rates']);
    const allKeys = Array.from(new Set([...CR_KEYS, ...Object.keys(STATE.customRecords || {})]));
    allKeys.forEach(k => {
      const list = SEED.records[k];
      if (!Array.isArray(list)) return;
      if (!Array.isArray(STATE.customRecords[k])) STATE.customRecords[k] = [];
      const seen = new Set(list.map(x => String(x.id)));
      let touched = false;
      STATE.customRecords[k].forEach(r => {
        if (!r) return;
        const rid = String(r.id == null ? '' : r.id);
        const rNameNorm = norm(r.name || r.ticket_no || r.invoice_no || r.staff || r.driver || r.equipment);
        if (r.voided) {
          let i = rid ? list.findIndex(x => x && String(x.id) === rid) : -1;
          if (i < 0 && !rid && rNameNorm && masterByNameKeys.has(k)) {
            i = list.findIndex(x => x && norm(x.name || x.equipment || x.driver) === rNameNorm);
          }
          if (i >= 0) {
            if (!SEED_VOIDED_ARCHIVE[k]) SEED_VOIDED_ARCHIVE[k] = new Map();
            const sid = String(list[i].id || rid);
            if (!SEED_VOIDED_ARCHIVE[k].has(sid)) {
              SEED_VOIDED_ARCHIVE[k].set(sid, Object.assign({}, list[i], { voided: false }));
            }
            list[i].voided = true;
            list.splice(i, 1);
            touched = true;
          }
          return;
        }
        const existingById = rid ? list.find(x => x && String(x.id) === rid) : null;
        if (existingById) {
          Object.assign(existingById, r);
          touched = true;
        } else if (UNIVERSAL_MAIN_SPEC[k] || (masterByNameKeys.has(k) && r.name)) {
          const mk = UNIVERSAL_MAIN_SPEC[k] ? universalMainNormKey(k, r) : norm(r.name);
          const existingByName = mk ? list.find(x => x && String(x.id) !== rid && (UNIVERSAL_MAIN_SPEC[k] ? universalMainNormKey(k, x) === mk : norm(x.name || x.equipment || x.driver) === mk)) : null;
          if (existingByName) {
            Object.assign(existingByName, r, { id: existingByName.id || r.id });
            if (rid) seen.add(rid);
            touched = true;
            return;
          }
        }
        if (rid && !seen.has(rid)) { list.push(r); seen.add(rid); touched = true; }
      });
      if (UNIVERSAL_MAIN_SPEC[k]) {
        const seenMain = new Set();
        for (let i = 0; i < list.length; i++) {
          const item = list[i];
          const mk = universalMainNormKey(k, item);
          if (!mk) continue;
          if (seenMain.has(mk)) {
            list.splice(i, 1);
            i--;
            touched = true;
          } else {
            seenMain.add(mk);
          }
        }
      }
      if (touched && list.some(x => x && x.date)) list.sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
    });

    enrichGlobalRateTables();
    if (window.MFG_GEO && typeof window.MFG_GEO.hydrateSeedGeo === 'function') {
      window.MFG_GEO.hydrateSeedGeo(SEED);
    }

    // Keep SEED.models summary arrays in sync when master records are voided or restored
    if (!SEED._origModelMasters) {
      SEED._origModelMasters = {};
      Object.entries(SEED.models || {}).forEach(([mk, m]) => {
        if (!m || typeof m !== 'object') return;
        SEED._origModelMasters[mk] = {
          equipment: Array.isArray(m.equipment) ? m.equipment.slice() : null,
          customers: Array.isArray(m.customers) ? m.customers.slice() : null,
          suppliers: Array.isArray(m.suppliers) ? m.suppliers.slice() : null,
          products: Array.isArray(m.products) ? m.products.slice() : null,
          sites: Array.isArray(m.sites) ? m.sites.slice() : null
        };
      });
    }
    const voidedMasterNames = {};
    ['equipment', 'customers', 'suppliers', 'products', 'sites'].forEach(mk => {
      const s = new Set();
      (STATE.customRecords[mk] || []).forEach(r => {
        if (r && r.voided) {
          const nm = norm(r.name || r.equipment || r.Customer || r.Supplier || r.Product || r.Site);
          if (nm) s.add(nm);
        }
      });
      if (mk === 'sites' && s.size) {
        (SEED.records.sites || []).forEach(x => {
          if (x && !x.voided && x.name) s.delete(norm(x.name));
        });
      }
      voidedMasterNames[mk] = s;
    });
    const custByNorm = new Map();
    (SEED.records.customers || []).forEach(c => {
      if (c && c.name) custByNorm.set(norm(c.name), c);
    });
    const suppByNorm = new Map();
    (SEED.records.suppliers || []).forEach(s => {
      if (s && s.name) suppByNorm.set(normOwnerName(s.name), s);
    });
    const appExpByModelSup = {};
    ((STATE.customRecords && STATE.customRecords.expenses) || []).forEach(e => {
      if (!e || e.source !== 'app' || e.voided || !e.supplier) return;
      const sgn = expenseSign(e);
      if (sgn === 0) return;
      const amt = round2(sgn * Number(e.amount || 0));
      if (amt === 0) return;
      const isCr = isCreditExpense(e);
      const sn = normOwnerName(e.supplier);
      const coMk = e.company === 'BBConstruction' ? 'bbconstruction' : (e.company === 'Lions Transport' ? 'lionstransport' : 'wtc');
      [coMk, 'manufacturing-group'].forEach(tMk => {
        if (!appExpByModelSup[tMk]) appExpByModelSup[tMk] = new Map();
        const cur = appExpByModelSup[tMk].get(sn) || { tot: 0, cr: 0 };
        cur.tot = round2(cur.tot + amt);
        if (isCr) cur.cr = round2(cur.cr + amt);
        appExpByModelSup[tMk].set(sn, cur);
      });
    });
    Object.entries(SEED.models || {}).forEach(([mk, m]) => {
      const orig = SEED._origModelMasters[mk];
      if (!m || !orig) return;
      if (orig.equipment) m.equipment = voidedMasterNames.equipment.size ? orig.equipment.filter(x => !voidedMasterNames.equipment.has(norm(x.Equipment || x.name))) : orig.equipment.slice();
      if (orig.customers) {
        const baseCusts = voidedMasterNames.customers.size ? orig.customers.filter(x => !voidedMasterNames.customers.has(norm(x.Customer || x.name))) : orig.customers.slice();
        m.customers = baseCusts.map(x => {
          const dvn = custByNorm.get(norm(x.Customer || x.name));
          if (!dvn) return x;
          const out = Object.assign({}, x);
          if (dvn.method) { out.Method = dvn.method; out.method = dvn.method; }
          if (typeof dvn.vat_registered === 'boolean') { out['VAT Registered'] = dvn.vat_registered ? 'Yes' : 'No'; out.vat_registered = dvn.vat_registered; }
          if (dvn.phone) out.phone = dvn.phone;
          if (dvn.address || dvn.region) { out.address = dvn.address || dvn.region; out.region = dvn.region || dvn.address; }
          if (dvn.mof_no) out.mof_no = dvn.mof_no;
          return out;
        });
      }
      if (orig.suppliers) {
        const baseSupps = voidedMasterNames.suppliers.size ? orig.suppliers.filter(x => !voidedMasterNames.suppliers.has(norm(x.Supplier || x.name))) : orig.suppliers.slice();
        const expDeltaMap = appExpByModelSup[mk] || null;
        m.suppliers = baseSupps.map(x => {
          const sKey = normOwnerName(x.Supplier || x.name);
          const dvn = suppByNorm.get(sKey);
          const ed = expDeltaMap ? expDeltaMap.get(sKey) : null;
          if (!dvn && !ed) return x;
          const out = Object.assign({}, x);
          if (dvn) {
            if (dvn.method) { out.Method = dvn.method; out.method = dvn.method; }
            if (typeof dvn.iva === 'boolean') { out.IVA = dvn.iva ? 'Yes' : 'No'; out.iva = dvn.iva; }
            if (dvn.phone || dvn.contact) { out.phone = dvn.phone || dvn.contact; out.contact = dvn.contact || dvn.phone; }
            if (dvn.location || dvn.region) { out.location = dvn.location || dvn.region; out.region = dvn.region || dvn.location; }
            if (dvn.mof_no || dvn.financial_no) { out.mof_no = dvn.mof_no || dvn.financial_no; out.financial_no = dvn.financial_no || dvn.mof_no; }
          }
          if (ed) {
            out.expenses = round2(Number(out.expenses || 0) + ed.tot);
            out.ap_expense = round2(Number(out.ap_expense || 0) + ed.cr);
            out.ap_on_credit = round2(Number(out.ap_on_credit || 0) + ed.cr);
            out.ap_balance = round2(Number(out.ap_balance || 0) + ed.cr);
          }
          return out;
        });
      }
      if (orig.products) m.products = voidedMasterNames.products.size ? orig.products.filter(x => !voidedMasterNames.products.has(norm(x.Product || x.name))) : orig.products.slice();
      if (orig.sites) m.sites = voidedMasterNames.sites.size ? orig.sites.filter(x => !voidedMasterNames.sites.has(norm(x.Site || x.name))) : orig.sites.slice();
    });

    // Cross-link Trucks (equipment / company_equipment) ↔ Drivers ↔ Truck Owners (suppliers)
    const drvByName = new Map();
    (SEED.records.drivers || []).forEach(d => {
      const k = norm(d.name || d.driver);
      if (k && !drvByName.has(k)) drvByName.set(k, d);
    });
    const supByName = new Map();
    (SEED.records.suppliers || []).forEach(s => {
      const k = norm(s.name);
      if (k && !supByName.has(k)) supByName.set(k, s);
    });
    const eqByName = new Map();
    (SEED.records.equipment || []).forEach(e => {
      const k = norm(e.name);
      if (k && !eqByName.has(k)) eqByName.set(k, e);
    });

    // 1. Backfill equipment.default_driver from company_equipment if missing, and propagate truck.supplier -> driver.truck_owner
    (SEED.records.company_equipment || []).forEach(ce => {
      const eq = eqByName.get(norm(ce.equipment || ce.name));
      if (eq) {
        if (!eq.default_driver && ce.default_driver) eq.default_driver = ce.default_driver;
        if (!eq.supplier && ce.supplier && !/^own/i.test(ce.ownership || '')) eq.supplier = ce.supplier;
      }
    });

    (SEED.records.equipment || []).forEach(e => {
      const isOwn = /^own/i.test(e.ownership || '') && (!e.supplier || ['wtc', 'bbconstruction', 'lions transport', 'sibline'].includes(norm(e.supplier)));
      if (e.default_driver) {
        let d = drvByName.get(norm(e.default_driver));
        if (!d) {
          d = { id: 'drv-' + norm(e.default_driver), name: e.default_driver, driver: e.default_driver, truck_owner: isOwn ? '' : (e.supplier || ''), truck: e.name, phone: '', notes: '' };
          SEED.records.drivers.push(d);
          drvByName.set(norm(e.default_driver), d);
        } else {
          if (!d.truck_owner && !isOwn && e.supplier) d.truck_owner = e.supplier;
          if (!d.truck) d.truck = e.name;
        }
      }
      if (!isOwn && e.supplier) {
        const sup = supByName.get(norm(e.supplier));
        if (sup) {
          if (!Array.isArray(sup.trucks)) sup.trucks = [];
          if (!sup.trucks.some(t => norm(t) === norm(e.name))) sup.trucks.push(e.name);
          sup.trucks_count = sup.trucks.length;
          if (e.default_driver) {
            if (!Array.isArray(sup.drivers)) sup.drivers = [];
            if (!sup.drivers.some(dn => norm(dn) === norm(e.default_driver))) sup.drivers.push(e.default_driver);
          }
        }
      }
    });

    // 2. Propagate supplier.driver_rows / supplier.drivers -> drivers & equipment
    (SEED.records.suppliers || []).forEach(sup => {
      if (Array.isArray(sup.driver_rows)) {
        sup.driver_rows.forEach(dr => {
          if (!dr || !dr.name) return;
          let d = drvByName.get(norm(dr.name));
          if (!d) {
            d = { id: 'drv-' + norm(dr.name), name: dr.name, driver: dr.name, truck_owner: sup.name, truck: dr.truck || '', phone: dr.phone || '', notes: '' };
            SEED.records.drivers.push(d);
            drvByName.set(norm(dr.name), d);
          } else {
            d.truck_owner = sup.name;
            if (dr.phone) d.phone = dr.phone;
            if (dr.truck) d.truck = dr.truck;
          }
          if (dr.truck) {
            const eq = eqByName.get(norm(dr.truck));
            if (eq) {
              if (!eq.supplier) eq.supplier = sup.name;
              eq.default_driver = dr.name;
            }
          }
        });
      }
      if (Array.isArray(sup.drivers)) {
        sup.drivers.forEach(dn => {
          if (!dn) return;
          let d = drvByName.get(norm(dn));
          if (!d) {
            d = { id: 'drv-' + norm(dn), name: dn, driver: dn, truck_owner: sup.name, truck: '', phone: '', notes: '' };
            SEED.records.drivers.push(d);
            drvByName.set(norm(dn), d);
          } else if (!d.truck_owner) {
            d.truck_owner = sup.name;
          }
        });
      }
    });

    // 3. Propagate driver.truck_owner & driver.truck -> suppliers.drivers & equipment.default_driver
    (SEED.records.drivers || []).forEach(d => {
      const dName = d.name || d.driver;
      if (!dName) return;
      if (d.truck_owner) {
        const sup = supByName.get(norm(d.truck_owner));
        if (sup) {
          if (!Array.isArray(sup.drivers)) sup.drivers = [];
          if (!sup.drivers.some(dn => norm(dn) === norm(dName))) sup.drivers.push(dName);
        }
      }
      if (d.truck) {
        const eq = eqByName.get(norm(d.truck));
        if (eq && !eq.default_driver) eq.default_driver = dName;
      }
    });
    _FLEET_IDX = null;
  }

  function mergeSentinelReviews(remoteMap) {
    if (!remoteMap || typeof remoteMap !== 'object') return false;
    if (!STATE.sentinelReviews || typeof STATE.sentinelReviews !== 'object') STATE.sentinelReviews = {};
    let changed = false;
    Object.entries(remoteMap).forEach(([rk, inc]) => {
      if (!inc || typeof inc !== 'object') return;
      const key = String(inc.id || rk);
      const cur = STATE.sentinelReviews[key];
      const inTs = String(inc.updated_at || inc.checked_at || '');
      const curTs = cur ? String(cur.updated_at || cur.checked_at || '') : '';
      if (!cur || inTs > curTs) {
        STATE.sentinelReviews[key] = Object.assign({}, inc, { id: key });
        changed = true;
      }
    });
    return changed;
  }

  function mergeKioskPunches(remoteList) {
    if (!Array.isArray(remoteList) || !remoteList.length) return false;
    STATE.kioskPunches = sanitizeKioskPunchesList(STATE.kioskPunches);
    const byId = new Map(STATE.kioskPunches.map(p => [String(p.id), p]));
    let changed = false;
    sanitizeKioskPunchesList(remoteList).forEach(inc => {
      const id = String(inc.id);
      const cur = byId.get(id);
      if (!cur) {
        STATE.kioskPunches.push(Object.assign({}, inc));
        byId.set(id, inc);
        changed = true;
      } else {
        const inRev = Number(inc.rev || 0);
        const curRev = Number(cur.rev || 0);
        const inTs = String(inc.updated_at || inc.iso || '');
        const curTs = String(cur.updated_at || cur.iso || '');
        if ((inc.voided && !cur.voided) || inRev > curRev || (inRev === curRev && inTs > curTs)) {
          Object.assign(cur, inc);
          changed = true;
        }
      }
    });
    if (changed) {
      STATE.kioskPunches.sort((a, b) => String(b.iso || `${b.date || ''}T${b.time || ''}`).localeCompare(String(a.iso || `${a.date || ''}T${a.time || ''}`)));
      STATE.kioskPunches = STATE.kioskPunches.slice(0, 300);
      if (!STATE.kioskLastPunch || /^pn-seed-/.test(String(STATE.kioskLastPunch.id || ''))) {
        STATE.kioskLastPunch = STATE.kioskPunches[0] || null;
      }
    }
    return changed;
  }

  function mergeStaffBiometrics(remoteMap) {
    if (!remoteMap || typeof remoteMap !== 'object') return false;
    if (!STATE.staffBiometrics || typeof STATE.staffBiometrics !== 'object') STATE.staffBiometrics = {};
    let changed = false;
    Object.entries(remoteMap).forEach(([rk, inc]) => {
      if (!inc || typeof inc !== 'object') return;
      const key = norm(inc.name || rk);
      if (!key) return;
      const cur = STATE.staffBiometrics[key];
      const inTs = String(inc.updated_at || inc.face_updated_at || '');
      const curTs = cur ? String(cur.updated_at || cur.face_updated_at || '') : '';
      if (!cur) {
        STATE.staffBiometrics[key] = Object.assign({}, inc);
        changed = true;
        return;
      }
      if (inTs > curTs) {
        const merged = Object.assign({}, cur, inc);
        const curFaceTs = String(cur.face_updated_at || '');
        const inFaceTs = String(inc.face_updated_at || '');
        if (curFaceTs > inFaceTs) {
          merged.face_samples = cur.face_samples || [];
          merged.face_thumbs = cur.face_thumbs || [];
          merged.face_cleared = Boolean(cur.face_cleared);
          merged.face_updated_at = curFaceTs;
        }
        STATE.staffBiometrics[key] = merged;
        changed = true;
      }
    });
    return changed;
  }

  function mergeWorkSchedules(remoteSched) {
    if (!remoteSched || typeof remoteSched !== 'object') return false;
    if (!STATE.workSchedules || typeof STATE.workSchedules !== 'object') {
      STATE.workSchedules = { shiftTypes: [], staffRules: {} };
    }
    if (!Array.isArray(STATE.workSchedules.shiftTypes)) STATE.workSchedules.shiftTypes = [];
    if (!STATE.workSchedules.staffRules || typeof STATE.workSchedules.staffRules !== 'object') STATE.workSchedules.staffRules = {};
    let changed = false;
    if (Array.isArray(remoteSched.shiftTypes)) {
      const byId = new Map(STATE.workSchedules.shiftTypes.filter(s => s && s.id).map(s => [String(s.id), s]));
      remoteSched.shiftTypes.forEach(inc => {
        if (!inc || !inc.id) return;
        const id = String(inc.id);
        const cur = byId.get(id);
        const inTs = String(inc.updated_at || '');
        const curTs = cur ? String(cur.updated_at || '') : '';
        if (!cur) {
          const copy = Object.assign({}, inc);
          STATE.workSchedules.shiftTypes.push(copy);
          byId.set(id, copy);
          changed = true;
        } else if (inTs > curTs) {
          Object.assign(cur, inc);
          changed = true;
        }
      });
    }
    if (remoteSched.staffRules && typeof remoteSched.staffRules === 'object') {
      Object.entries(remoteSched.staffRules).forEach(([rk, inc]) => {
        if (!inc || typeof inc !== 'object') return;
        const key = norm(inc.staff || rk);
        if (!key) return;
        const cur = STATE.workSchedules.staffRules[key];
        const inTs = String(inc.updated_at || '');
        const curTs = cur ? String(cur.updated_at || '') : '';
        if (!cur || inTs > curTs) {
          STATE.workSchedules.staffRules[key] = Object.assign({}, cur || {}, inc);
          changed = true;
        }
      });
    }
    return changed;
  }

  function cloudPayload() {
    const trimmed = {};
    CR_KEYS.forEach(k => { trimmed[k] = STATE.customRecords[k].slice(0, 1500); });
    return {
      users: STATE.users,
      sessions: STATE.sessions.slice(0, 25),
      customRecords: trimmed,
      kioskPunches: sanitizeKioskPunchesList(STATE.kioskPunches).slice(0, 300),
      staffBiometrics: STATE.staffBiometrics || {},
      workSchedules: STATE.workSchedules || { shiftTypes: [], staffRules: {} },
      sentinelReviews: STATE.sentinelReviews || {},
      alertRules: STATE.alertRules || { overrides: {}, custom: [] },
      faceSettings: STATE.faceSettings,
      lbpFxRate: getLbpFxRate(),
      lbpFxUpdatedAt: STATE.lbpFxUpdatedAt || '',
      updatedAt: new Date().toISOString(),
      updatedBy: activeUser().email,
      appVersion: '4.7'
    };
  }

  let lastPointerDownAt = 0;

  function uiBusy() {
    if (Date.now() - lastPointerDownAt < 400) return true;
    const m = $('entryModal');
    if (m && !m.hidden) return true;
    const ins = $('recordInspector');
    if (ins && !ins.hidden) return true;
    if (($('staffFaceEnrolModal') && !$('staffFaceEnrolModal').hidden)
      || ($('staffScheduleModal') && !$('staffScheduleModal').hidden)
      || ($('shiftTypeModal') && !$('shiftTypeModal').hidden)) return true;
    if ((STATE.view === 'users' && STATE.userFormDirty) || FACE_STATE.enrolCamActive || KIOSK_ATT_STATE.camActive || STAFF_FACE_MODAL_STATE.camActive) return true;
    if (document.querySelector('.pa-suggest-wrap.open, .rdl-combo.open, #companySwitch.open, #nuCompanySelector.open')) return true;
    const a = document.activeElement;
    return !!(a && ['INPUT', 'SELECT', 'TEXTAREA'].includes(a.tagName) && a.id !== 'aiInput');
  }
  function safeRender() {
    if (uiBusy()) { STATE.renderPending = true; return; }
    renderApp();
  }

  function setContainerHtmlPreservingActiveInput(container, newHtml) {
    const active = document.activeElement;
    const preserveId = (active && container.contains(active) && (active.id === 'tableSearchInput' || active.id === 'pbiSlicerSearch' || active.id === 'alertRulesSearchInput' || active.id === 'kioskAttRosterSearch'))
      ? active.id
      : '';
    if (!preserveId) {
      container.innerHTML = newHtml;
      return;
    }
    const tpl = document.createElement('template');
    tpl.innerHTML = newHtml;
    const incoming = tpl.content.querySelector('#' + preserveId);
    if (!incoming) {
      container.innerHTML = newHtml;
      return;
    }
    const liveChain = [];
    let cur = active;
    while (cur && cur !== container) {
      liveChain.unshift(cur);
      cur = cur.parentNode;
    }
    const newChain = [];
    let nCur = incoming;
    while (nCur && nCur !== tpl.content) {
      newChain.unshift(nCur);
      nCur = nCur.parentNode;
    }
    if (!liveChain.length || liveChain.length !== newChain.length || liveChain.some((el, idx) => el.tagName !== newChain[idx].tagName)) {
      container.innerHTML = newHtml;
      return;
    }
    for (let i = 0; i < liveChain.length; i++) {
      const liveParent = i === 0 ? container : liveChain[i - 1];
      const newParent = i === 0 ? tpl.content : newChain[i - 1];
      const liveNode = liveChain[i];
      const newNode = newChain[i];
      if (liveNode !== active) {
        Array.from(liveNode.attributes).forEach(attr => {
          if (!newNode.hasAttribute(attr.name)) liveNode.removeAttribute(attr.name);
        });
        Array.from(newNode.attributes).forEach(attr => {
          if (liveNode.getAttribute(attr.name) !== attr.value) liveNode.setAttribute(attr.name, attr.value);
        });
      }
      while (liveParent.firstChild && liveParent.firstChild !== liveNode) {
        liveParent.removeChild(liveParent.firstChild);
      }
      while (newParent.firstChild && newParent.firstChild !== newNode) {
        liveParent.insertBefore(newParent.firstChild, liveNode);
      }
      while (liveNode.nextSibling) {
        liveParent.removeChild(liveNode.nextSibling);
      }
      while (newNode.nextSibling) {
        liveParent.appendChild(newNode.nextSibling);
      }
    }
  }

  let syncInFlight = null;
  async function syncWithCloud(pushChanges = false) {
    if (syncInFlight) { if (pushChanges) STATE.pushAfterSync = true; return syncInFlight; }
    syncInFlight = doSync(pushChanges || STATE.pushAfterSync).finally(() => {
      syncInFlight = null;
      if (STATE.pushAfterSync) { STATE.pushAfterSync = false; syncWithCloud(true); }
    });
    return syncInFlight;
  }

  async function doSync(pushChanges) {
    // 1. Local SQLite server (LAN host only)
    if (HAS_LOCAL_API) {
      try {
        const ctrl = new AbortController();
        const t = setTimeout(() => ctrl.abort(), 6000);
        const rLocal = await fetch('./api/users', { signal: ctrl.signal });
        clearTimeout(t);
        if (rLocal.ok) {
          const dLocal = await rLocal.json();
          if (Array.isArray(dLocal.users) && dLocal.users.length) {
            const merged = STATE.users.map(u => Object.assign({}, u));
            dLocal.users.forEach(u => {
              if (!u || !u.email) return;
              const idx = merged.findIndex(x => (u.id && String(x.id) === String(u.id)) || norm(x.email) === norm(u.email));
              if (idx >= 0) merged[idx] = mergeUserRow(merged[idx], u);
              else merged.push(mergeUserRow(null, u));
            });
            STATE.users = merged;
          }
        }
        const ctrlSr = new AbortController();
        const tSr = setTimeout(() => ctrlSr.abort(), 5000);
        const rSr = await fetch('./api/sentinel_reviews', { signal: ctrlSr.signal });
        clearTimeout(tSr);
        if (rSr.ok) {
          const dSr = await rSr.json();
          if (dSr && dSr.reviews && mergeSentinelReviews(dSr.reviews)) {
            saveLocalAuthAndRecords();
          }
        }
        const ctrlAr = new AbortController();
        const tAr = setTimeout(() => ctrlAr.abort(), 5000);
        const rAr = await fetch('./api/alert_rules', { signal: ctrlAr.signal });
        clearTimeout(tAr);
        if (rAr.ok) {
          const dAr = await rAr.json();
          if (dAr && mergeAlertRules(dAr)) {
            saveLocalAuthAndRecords();
          }
        }
        const ctrlSb = new AbortController();
        const tSb = setTimeout(() => ctrlSb.abort(), 5000);
        const rSb = await fetch('./api/staff_biometrics', { signal: ctrlSb.signal });
        clearTimeout(tSb);
        if (rSb.ok) {
          const dSb = await rSb.json();
          if (dSb && dSb.staff_biometrics && mergeStaffBiometrics(dSb.staff_biometrics)) {
            saveLocalAuthAndRecords();
          }
        }
        const ctrlWs = new AbortController();
        const tWs = setTimeout(() => ctrlWs.abort(), 5000);
        const rWs = await fetch('./api/work_schedules', { signal: ctrlWs.signal });
        clearTimeout(tWs);
        if (rWs.ok) {
          const dWs = await rWs.json();
          if (dWs && dWs.work_schedules && mergeWorkSchedules(dWs.work_schedules)) {
            saveLocalAuthAndRecords();
          }
        }
      } catch (_) { /* server.py not running */ }
    }

    // 2. BHFIRMS Multi-Device Cloud Relay (GitHub Pages + mobile + desktop)
    // Public demo/autologin visitors on GitHub Pages stay in local sandbox so they never mutate live BHFIRMS cloud state
    const isPublicDemoSandbox = !IS_LOCAL && (PARAMS.get('demo') === '1' || PARAMS.get('autologin') === '1' || STATE.demoVisitor);
    if (!CLOUD_URL || !CLOUD_KEY || navigator.webdriver || window.__MFG_HEADLESS_TEST || PARAMS.get('nosse') === '1' || (location.port && Number(location.port) >= 8095) || isPublicDemoSandbox) {
      STATE.cloudStatus = isPublicDemoSandbox ? '● Demo Sandbox' : '● Ready (Local)';
      updateCloudBadges();
      return;
    }
    try {
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 15000);
      const getRes = await fetch(CLOUD_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=UTF-8' },
        body: JSON.stringify({ key: CLOUD_KEY, op: 'get' }),
        signal: ctrl.signal
      });
      clearTimeout(timer);
      if (!getRes.ok) throw new Error('relay ' + getRes.status);

      const store = await getRes.json();
      const docs = (store && store.docs) || store || {};
      const remote = docs[CLOUD_DOC_KEY] || {};
      let changed = false;

      if (Array.isArray(remote.users) && remote.users.length) {
        const merged = remote.users.filter(u => u && u.email).map(u => Object.assign({}, u));
        if (pushChanges) {
          STATE.users.forEach(u => {
            if (!u || !u.email) return;
            const idx = merged.findIndex(x => (u.id && String(x.id) === String(u.id)) || norm(x.email) === norm(u.email));
            if (idx >= 0) merged[idx] = mergeUserRow(merged[idx], u);
            else merged.push(mergeUserRow(null, u));
          });
        } else {
          // keep any seat or biometric enrolment only this device knows about so it is not lost before the next push
          STATE.users.forEach(u => {
            if (!u || !u.email) return;
            const idx = merged.findIndex(x => (u.id && String(x.id) === String(u.id)) || norm(x.email) === norm(u.email));
            if (idx < 0) { merged.push(u); pushChanges = true; }
            else merged[idx] = mergeUserRow(u, merged[idx]);
          });
        }
        const next = merged;
        if (JSON.stringify(next) !== JSON.stringify(STATE.users)) { changed = true; }
        const myEmail = norm(activeUser().email);
        STATE.users = next;
        const idx = STATE.users.findIndex(u => norm(u.email) === myEmail);
        if (idx >= 0) STATE.activeUserIdx = idx;
        if (!STATE.authed) { renderQuickSeatsInAuthGate(); updateAuthFaceUi(); }
      }

      if (Array.isArray(remote.sessions) && remote.sessions.length) {
        const seenS = new Set(STATE.sessions.map(s => s.id));
        remote.sessions.forEach(s => { if (s && s.id && !seenS.has(s.id)) { STATE.sessions.push(s); seenS.add(s.id); changed = true; } });
        STATE.sessions.sort((a, b) => String(b.logged_in_at || '').localeCompare(String(a.logged_in_at || '')));
        STATE.sessions = STATE.sessions.slice(0, 50);
      }

      if (remote.customRecords && mergeCustomRecords(remote.customRecords)) { changed = true; applyCustomRecordsToSeed(); }
      if (Array.isArray(remote.kioskPunches) && mergeKioskPunches(remote.kioskPunches)) { changed = true; }
      if (remote.staffBiometrics && mergeStaffBiometrics(remote.staffBiometrics)) { changed = true; }
      if (remote.workSchedules && mergeWorkSchedules(remote.workSchedules)) { changed = true; }
      if (remote.sentinelReviews && mergeSentinelReviews(remote.sentinelReviews)) { changed = true; }
      if (remote.alertRules && mergeAlertRules(remote.alertRules)) { changed = true; }
      if (remote.lbpFxRate && remote.lbpFxUpdatedAt && String(remote.lbpFxUpdatedAt) > String(STATE.lbpFxUpdatedAt || '')) {
        if (setLbpFxRate(remote.lbpFxRate, { updatedAt: remote.lbpFxUpdatedAt, sync: false, render: false })) changed = true;
      } else if (!pushChanges && STATE.lbpFxUpdatedAt && String(STATE.lbpFxUpdatedAt) > String(remote.lbpFxUpdatedAt || '')) {
        pushChanges = true;
      }
      // anything only we hold -> push
      if (!pushChanges && Array.isArray(STATE.kioskPunches) && STATE.kioskPunches.length) {
        const remMap = new Map(sanitizeKioskPunchesList(remote.kioskPunches).map(p => [String(p.id), p]));
        sanitizeKioskPunchesList(STATE.kioskPunches).forEach(p => {
          const rp = remMap.get(String(p.id));
          if (!rp || Number(p.rev || 0) > Number(rp.rev || 0) || Boolean(p.voided) !== Boolean(rp.voided)) pushChanges = true;
        });
      }
      if (!pushChanges && STATE.staffBiometrics && Object.keys(STATE.staffBiometrics).length) {
        const remBio = remote.staffBiometrics || {};
        Object.entries(STATE.staffBiometrics).forEach(([bk, bv]) => {
          const rb = remBio[bk];
          if (!rb || String((bv && bv.updated_at) || '') > String(rb.updated_at || '')) pushChanges = true;
        });
      }
      if (!pushChanges && STATE.workSchedules) {
        const remWs = remote.workSchedules || { shiftTypes: [], staffRules: {} };
        const remStMap = new Map((remWs.shiftTypes || []).filter(s => s && s.id).map(s => [String(s.id), s]));
        (STATE.workSchedules.shiftTypes || []).forEach(st => {
          if (!st || !st.id) return;
          const rs = remStMap.get(String(st.id));
          if (!rs || String(st.updated_at || '') > String(rs.updated_at || '')) pushChanges = true;
        });
        const remSr = remWs.staffRules || {};
        Object.entries(STATE.workSchedules.staffRules || {}).forEach(([rk, rv]) => {
          const rr = remSr[rk];
          if (!rr || String((rv && rv.updated_at) || '') > String(rr.updated_at || '')) pushChanges = true;
        });
      }
      if (!pushChanges && remote.customRecords) {
        const remoteIds = new Set();
        CR_KEYS.forEach(k => (remote.customRecords[k] || []).forEach(r => r && remoteIds.add(r.id + (r.voided ? '|v' : ''))));
        CR_KEYS.forEach(k => STATE.customRecords[k].forEach(r => { if (!remoteIds.has(r.id + (r.voided ? '|v' : ''))) pushChanges = true; }));
      }
      if (!pushChanges && STATE.sentinelReviews && Object.keys(STATE.sentinelReviews).length) {
        const remSr = remote.sentinelReviews || {};
        Object.entries(STATE.sentinelReviews).forEach(([rk, rv]) => {
          const remRow = remSr[rk];
          if (!remRow || String(rv.updated_at || '') > String(remRow.updated_at || '')) pushChanges = true;
        });
      }
      if (!pushChanges && STATE.alertRules) {
        const remAr = remote.alertRules || { overrides: {}, custom: [] };
        const remOv = remAr.overrides || {};
        Object.entries(STATE.alertRules.overrides || {}).forEach(([rk, rv]) => {
          const remRow = remOv[rk];
          if (!remRow || String((rv && rv.updated_at) || '') > String(remRow.updated_at || '')) pushChanges = true;
        });
        const remCustMap = new Map((remAr.custom || []).filter(c => c && c.id).map(c => [String(c.id), c]));
        (STATE.alertRules.custom || []).forEach(cr => {
          if (!cr || !cr.id) return;
          const remRow = remCustMap.get(String(cr.id));
          if (!remRow || String(cr.updated_at || '') > String(remRow.updated_at || '')) pushChanges = true;
        });
      }

      saveLocalAuthAndRecords();
      STATE.cloudStatus = '● Cloud Live';
      STATE.cloudUpdatedAt = remote.updatedAt || '';

      if (pushChanges || !docs[CLOUD_DOC_KEY]) {
        const payload = cloudPayload();
        const ctrl2 = new AbortController();
        const timer2 = setTimeout(() => ctrl2.abort(), 15000);
        const putRes = await fetch(CLOUD_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'text/plain;charset=UTF-8' },
          body: JSON.stringify({ key: CLOUD_KEY, op: 'patch', patch: { [CLOUD_DOC_KEY]: payload } }),
          signal: ctrl2.signal
        });
        clearTimeout(timer2);
        if (putRes.ok) STATE.cloudUpdatedAt = payload.updatedAt;
        else STATE.cloudStatus = '● Cloud read-only (' + putRes.status + ')';
      }
      updateCloudBadges();
      if (changed) safeRender();
    } catch (_) {
      STATE.cloudStatus = navigator.onLine ? '● Relay unreachable' : '● Offline Cache';
      updateCloudBadges();
    }
  }

  function updateCloudBadges() {
    const el = $('sqlStatusText');
    if (el && !HAS_LOCAL_API) el.textContent = STATE.cloudStatus.replace('● ', '');
    const auth = $('authCloudStatusBadge');
    if (auth) {
      const isNormal = /Live|Ready|Sandbox|Connecting/i.test(STATE.cloudStatus);
      auth.hidden = isNormal;
      auth.textContent = STATE.cloudStatus;
      auth.className = isNormal ? 'auth-cloud-ok' : 'auth-cloud-warn';
    }
  }

  // ==========================================================================
  // BIOMETRIC FACE ID ENGINE (ATTENDANCE PWA PARITY: 128-D + STEP-UP 2FA)
  // ==========================================================================
  function streamAlive() {
    return !!(FACE_STATE.stream && FACE_STATE.stream.getVideoTracks && FACE_STATE.stream.getVideoTracks().some(t => t.readyState === 'live'));
  }

  async function ensureFaceModelsLoaded() {
    if (!window.Face) throw new Error('Face recognition module not loaded');
    await window.Face.load('./vendor/models');
    return true;
  }

  async function startFaceCamera(videoEl) {
    if (!videoEl) return false;
    try {
      if (!streamAlive() && window.Face && typeof window.Face.consumeEarlyStream === 'function') {
        const early = await window.Face.consumeEarlyStream();
        if (early && early.getVideoTracks && early.getVideoTracks().some(t => t.readyState === 'live')) {
          FACE_STATE.stream = early;
          if (window.Face.trackStream) window.Face.trackStream(early);
        }
      }
      if (!streamAlive()) {
        if (FACE_STATE.stream) { try { FACE_STATE.stream.getTracks().forEach(t => t.stop()); } catch (_) {} }
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return false;
        const portrait = window.innerHeight > window.innerWidth;
        const prefVideo = portrait
          ? { facingMode: 'user', width: { ideal: 720 }, height: { ideal: 960 } }
          : { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } };
        const s = await navigator.mediaDevices.getUserMedia({
          video: prefVideo,
          audio: false
        }).catch(() => navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false }));
        if (window.Face && window.Face.trackStream) window.Face.trackStream(s);
        FACE_STATE.stream = s;
      }
      const gate = $('authGate');
      if (videoEl.id === 'authFaceVideo' && (STATE.authed || FACE_STATE.authCamStoppedByUser || (gate && gate.hidden))) {
        stopFaceCamera();
        return false;
      }
      if (videoEl.id === 'enrolFaceVideo' && STATE.view !== 'users') {
        stopFaceCamera();
        return false;
      }
      if (videoEl.srcObject !== FACE_STATE.stream) videoEl.srcObject = FACE_STATE.stream;
      if (videoEl.id === 'authFaceVideo') {
        const markReady = () => {
          if (!STATE.authed && videoEl.srcObject && videoEl.videoWidth > 0) {
            const vp = $('authCamViewport');
            if (vp) vp.classList.add('is-video-ready');
            updateAuthFaceUi();
          }
        };
        if (videoEl.readyState >= 2 && videoEl.videoWidth > 0) markReady();
        else {
          videoEl.addEventListener('loadeddata', markReady, { once: true });
          videoEl.addEventListener('playing', markReady, { once: true });
        }
      }
      await videoEl.play().catch(() => {});
      if (videoEl.id === 'authFaceVideo' && videoEl.readyState >= 2 && videoEl.videoWidth > 0) {
        const vp = $('authCamViewport');
        if (vp) vp.classList.add('is-video-ready');
      }
      return true;
    } catch (_) {
      return false;
    }
  }

  function stopFaceCamera() {
    if (FACE_STATE.loopTimer) { clearTimeout(FACE_STATE.loopTimer); FACE_STATE.loopTimer = null; }
    if (FACE_STATE.enrolLoopTimer) { clearTimeout(FACE_STATE.enrolLoopTimer); FACE_STATE.enrolLoopTimer = null; }
    if (FACE_STATE.enrolTestTimer) { clearTimeout(FACE_STATE.enrolTestTimer); FACE_STATE.enrolTestTimer = null; }
    FACE_STATE.camActive = false;
    FACE_STATE.camStarting = false;
    FACE_STATE.enrolCamActive = false;
    FACE_STATE.enrolTestActive = false;
    const vp = $('authCamViewport');
    if (vp) vp.classList.remove('is-video-ready', 'is-matching');
    if (FACE_STATE.stream) {
      try { FACE_STATE.stream.getTracks().forEach(t => t.stop()); } catch (_) {}
      FACE_STATE.stream = null;
    }
    if (window.Face && typeof window.Face.stopAllStreams === 'function') {
      try { window.Face.stopAllStreams(); } catch (_) {}
    }
    ['authFaceVideo', 'enrolFaceVideo'].forEach(id => {
      const v = $(id);
      if (v) {
        if (v.srcObject && typeof v.srcObject.getTracks === 'function') {
          try { v.srcObject.getTracks().forEach(t => t.stop()); } catch (_) {}
        }
        try { v.pause(); } catch (_) {}
        v.srcObject = null;
      }
    });
    ['authFaceOverlay', 'enrolFaceOverlay'].forEach(id => {
      const cv = $(id);
      if (cv && cv.getContext) {
        try { cv.getContext('2d').clearRect(0, 0, cv.width, cv.height); } catch (_) {}
      }
    });
    const offEl = $('authCamOffOverlay');
    if (offEl) offEl.hidden = false;
  }

  function setAuthHint(text, cls) {
    const el = $('authFaceHint');
    if (!el) return;
    el.textContent = text;
    el.className = 'auth-face-hint' + (cls ? ' ' + cls : '');
  }

  function setAuthStreak(count, needed) {
    const bar = $('authStreakBar');
    const fill = $('authStreakFill');
    const vp = $('authCamViewport');
    const pct = count > 0 ? Math.min(100, Math.round((count / Math.max(1, needed)) * 100)) : 0;
    if (bar) bar.classList.toggle('is-active', pct > 0);
    if (vp) vp.classList.toggle('is-matching', pct > 0);
    if (fill) fill.style.width = pct + '%';
  }

  function updateAuthFaceUi() {
    const enrolled = STATE.users.filter(userHasFaceId);
    const camBtn = $('authCamToggleBtn');
    const camLbl = $('authCamToggleLabel');
    const offEl = $('authCamOffOverlay');
    const offLbl = $('authCamOffLabel');
    const dotEl = $('authFacePulse') || $('authFaceDot');
    const bannerEl = $('authFaceTargetBanner');
    const targetNameEl = $('authFaceTargetText') || $('authFaceTargetName');
    const vpEl = $('authCamViewport');
    const videoReady = Boolean(vpEl && vpEl.classList.contains('is-video-ready'));
    const wsMode = getWorkspaceAuthMode();
    const camPrewarming = Boolean(
      !FACE_STATE.authCamStoppedByUser &&
      window.Face &&
      typeof window.Face.isPrewarming === 'function' &&
      window.Face.isPrewarming()
    );
    const camBusyOrLive = Boolean(FACE_STATE.camActive || FACE_STATE.camStarting || camPrewarming);

    if (camBtn) {
      camBtn.hidden = !FACE_STATE.camActive || !videoReady || (wsMode === 'pin_only');
      camBtn.classList.toggle('cam-live', !!(FACE_STATE.camActive && videoReady));
      if (camLbl) camLbl.textContent = 'Pause';
    }
    if (offEl) {
      offEl.hidden = camBusyOrLive && wsMode !== 'pin_only';
      offEl.classList.toggle('is-pin-only', wsMode === 'pin_only');
    }
    if (offLbl) {
      offLbl.textContent = wsMode === 'pin_only' ? 'PIN sign-in active' : 'Tap for Face ID';
    }
    if (dotEl) dotEl.className = 'auth-face-pulse' + ((FACE_STATE.camActive && videoReady) ? ' live' : '');

    if (bannerEl) {
      if (FACE_STATE.pending2faUser) {
        bannerEl.hidden = false;
        if (targetNameEl) targetNameEl.innerHTML = `${ic('lock')} Step 2: Look at the camera to verify ${esc(FACE_STATE.pending2faUser.full_name)}`;
      } else if (FACE_STATE.pendingPinUser) {
        bannerEl.hidden = false;
        if (targetNameEl) targetNameEl.innerHTML = `${ic('lock')} Step 2: Enter PIN for ${esc(FACE_STATE.pendingPinUser.full_name)}`;
      } else {
        bannerEl.hidden = true;
      }
    }

    if (typeof syncAuthSelectedSeatUi === 'function') syncAuthSelectedSeatUi();

    const hintEl = $('authFaceHint');
    if (wsMode === 'pin_only' && hintEl && !FACE_STATE.pending2faUser) {
      setAuthHint('', '');
    } else if (!videoReady && camBusyOrLive && hintEl && !FACE_STATE.pending2faUser) {
      setAuthHint('', '');
    } else if (enrolled.length && hintEl && !hintEl.textContent && FACE_STATE.camActive && videoReady && !FACE_STATE.pending2faUser) {
      setAuthHint(window.Face && window.Face.ready ? 'Look at camera for automatic Face ID' : 'Preparing Face ID…', (window.Face && window.Face.ready) ? 'ok' : '');
    }
  }

  function resetLivenessState() {
    FACE_STATE.lastBlinkAt = 0;
    FACE_STATE.lastTurnAt = 0;
    FACE_STATE.eyeClosedSeen = false;
    FACE_STATE.livenessUser = '';
    FACE_STATE.livenessHistory = [];
  }

  // Anti-screenshot liveness verifier: Option 1 (Eye Blink EAR dip+recovery) + Option 2 (3D Head-Turn Parallax)
  function livenessStep(det, matchedEmail, opts = {}) {
    if (STATE.faceSettings.liveness === false) {
      return { ok: true, method: 'multi-frame', detail: 'Liveness check disabled by owner policy' };
    }
    const hasLandmarkPayload = !!(det && (det.landmarks || typeof det.ear === 'number' || (det.pose && typeof det.pose === 'object')));
    if (!opts.liveCamera && !opts.requireLiveness && !hasLandmarkPayload) {
      // Synthetic descriptor-only probe (used by basic multi-frame streak tests when no landmarks are supplied)
      return { ok: true, method: 'synthetic-descriptor' };
    }

    const now = Date.now();
    const userKey = norm(matchedEmail || '');
    if (userKey && FACE_STATE.livenessUser !== userKey) {
      FACE_STATE.livenessUser = userKey;
      FACE_STATE.livenessHistory = [];
      FACE_STATE.eyeClosedSeen = false;
      FACE_STATE.lastBlinkAt = 0;
      FACE_STATE.lastTurnAt = 0;
    }

    const ear = (det && typeof det.ear === 'number')
      ? det.ear
      : (det && det.landmarks && window.Face && window.Face.ear ? window.Face.ear(det.landmarks) : null);
    const poseObj = (det && det.pose && typeof det.pose === 'object')
      ? det.pose
      : (det && det.landmarks && window.Face && window.Face.pose ? window.Face.pose(det.landmarks) : null);

    if (ear == null && !poseObj) {
      return { ok: false, reason: 'no-landmarks' };
    }

    const lvCfg = (window.Face && ((window.Face.config && window.Face.config.liveness) || (window.Face.CONFIG && window.Face.CONFIG.liveness))) || {};
    const windowMs = Number(lvCfg.windowSec || 6) * 1000;
    const earClosedThr = Number(lvCfg.earClosed || 0.228);
    const earOpenThr = Number(lvCfg.earOpen || 0.240);
    const earDropMin = Number(lvCfg.earDropMin || 0.024);
    const yawSpanMin = Number(lvCfg.yawSpanMin || 0.020);
    const parallaxSpanMin = Number(lvCfg.parallaxSpanMin || 0.010);
    const earVarMin = Number(lvCfg.earVarianceMin || 0.005);

    FACE_STATE.livenessHistory = (FACE_STATE.livenessHistory || []).filter(h => (now - h.t) <= windowMs);
    FACE_STATE.livenessHistory.push({
      t: now,
      ear: typeof ear === 'number' ? ear : null,
      yaw: poseObj && typeof poseObj.yaw === 'number' ? poseObj.yaw : null,
      parallax3d: poseObj && typeof poseObj.parallax3d === 'number' ? poseObj.parallax3d : null,
      pitch: poseObj && typeof poseObj.pitch === 'number' ? poseObj.pitch : null
    });
    if (FACE_STATE.livenessHistory.length > 24) {
      FACE_STATE.livenessHistory = FACE_STATE.livenessHistory.slice(-24);
    }

    const hist = FACE_STATE.livenessHistory;
    const isRealHardwareVideo = !!(opts && opts.videoEl && det && det.landmarks);
    // Option 1: Blink detection — absolute threshold (closed <= 0.228 then open >= 0.240) OR relative blink dip (>= 0.024 drop + >= 0.015 recovery)
    if (typeof ear === 'number' && ear > 0) {
      if (ear <= (isRealHardwareVideo ? 0.242 : earClosedThr)) {
        FACE_STATE.eyeClosedSeen = true;
      } else if (FACE_STATE.eyeClosedSeen && ear >= (isRealHardwareVideo ? 0.232 : earOpenThr)) {
        FACE_STATE.lastBlinkAt = now;
        FACE_STATE.eyeClosedSeen = false;
      }
      const ears = hist.map(h => h.ear).filter(v => typeof v === 'number' && v > 0);
      if (ears.length >= 3) {
        let minIdx = 0;
        for (let i = 1; i < ears.length; i++) {
          if (ears[i] < ears[minIdx]) minIdx = i;
        }
        const minEar = ears[minIdx];
        const maxBefore = minIdx > 0 ? Math.max(...ears.slice(0, minIdx)) : ears[0];
        const maxAfter = minIdx < ears.length - 1 ? Math.max(...ears.slice(minIdx + 1)) : ears[ears.length - 1];
        const reqDrop = isRealHardwareVideo ? 0.010 : earDropMin;
        const reqRec = isRealHardwareVideo ? 0.008 : 0.015;
        if ((maxBefore - minEar) >= reqDrop && (maxAfter - minEar) >= reqRec && maxAfter >= 0.205) {
          FACE_STATE.lastBlinkAt = now;
        }
      }
    }

    // Option 2: 3D Head-Turn Parallax — true 3D nose-tip projection vs eye-bridge parallax + non-rigid eye variance
    const yaws = hist.map(h => h.yaw).filter(v => typeof v === 'number');
    const parallaxes = hist.map(h => h.parallax3d).filter(v => typeof v === 'number');
    const pitches = hist.map(h => h.pitch).filter(v => typeof v === 'number');
    const earsAll = hist.map(h => h.ear).filter(v => typeof v === 'number' && v > 0);
    const yawSpan = yaws.length >= 2 ? (Math.max(...yaws) - Math.min(...yaws)) : 0;
    const parallaxSpan = parallaxes.length >= 2 ? (Math.max(...parallaxes) - Math.min(...parallaxes)) : 0;
    const pitchSpan = pitches.length >= 2 ? (Math.max(...pitches) - Math.min(...pitches)) : 0;
    const earSpan = earsAll.length >= 2 ? (Math.max(...earsAll) - Math.min(...earsAll)) : 0;

    // A rigid 2D phone screenshot tilted in front of the camera has near-zero 3D nose-vs-eye parallax AND zero eye-aspect change.
    // On a real live hardware camera feed (isRealHardwareVideo), natural 3D micro-parallax + live facial micro-jitter across frames proves liveness without forcing a 5s+ wait.
    if (
      (parallaxSpan >= parallaxSpanMin && yawSpan >= yawSpanMin) ||
      (yawSpan >= yawSpanMin && earSpan >= earVarMin && parallaxSpan >= 0.006) ||
      ((pitchSpan + parallaxSpan) >= 0.014 && earSpan >= earVarMin) ||
      (isRealHardwareVideo && hist.length >= 2 && (parallaxSpan >= 0.0004 || earSpan >= 0.0005 || yawSpan >= 0.0010 || pitchSpan >= 0.0010 || hist.length >= 3))
    ) {
      FACE_STATE.lastTurnAt = now;
    }

    const blinkPassed = (now - (FACE_STATE.lastBlinkAt || 0)) < windowMs;
    const turnPassed = (now - (FACE_STATE.lastTurnAt || 0)) < windowMs;
    const mode = String(STATE.faceSettings.livenessMode || 'blink_or_turn');

    if (mode === 'blink') {
      return { ok: blinkPassed, method: blinkPassed ? 'blink' : '', blinkPassed, turnPassed, yawSpan, parallaxSpan, earSpan };
    }
    if (mode === 'turn3d') {
      return { ok: turnPassed, method: turnPassed ? 'turn3d' : '', blinkPassed, turnPassed, yawSpan, parallaxSpan, earSpan };
    }
    return {
      ok: blinkPassed || turnPassed,
      method: blinkPassed ? (turnPassed ? 'blink+turn3d' : 'blink') : (turnPassed ? 'turn3d' : ''),
      blinkPassed,
      turnPassed,
      yawSpan,
      parallaxSpan,
      earSpan
    };
  }

  async function completeFaceLogin(user, dist, snapshotUrl, methodLabel, opts = {}) {
    if (!user) return false;
    if (STATE.authed && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) return true;
    const seatMode = effectiveSeatAuthMode(user);
    // If seat requires BOTH PIN + Face ID and the user scanned Face ID first (before entering PIN):
    if (seatMode === 'both' && !FACE_STATE.pending2faUser) {
      const typedPin = val('authPinInput');
      const expectedPin = String(user.pin_code || '1111').trim();
      // If the user has ALREADY entered their valid PIN in #authPinInput (e.g. typed before/during scan), both factors are satisfied -> sign in immediately!
      if (!opts.ignoreTypedPin && typedPin && typedPin === expectedPin) {
        methodLabel = methodLabel ? `${methodLabel} + PIN 2FA` : 'Face ID + PIN 2FA';
      } else {
        FACE_STATE.pendingPinUser = user;
        FACE_STATE.selectedAuthEmail = user.email;
        FACE_STATE.streakUser = null;
        FACE_STATE.streakCount = 0;
        const emEl = $('authEmailInput');
        const pinEl = $('authPinInput');
        if (emEl) emEl.value = user.email;
        const errEl = $('authErrorBox');
        if (errEl) errEl.hidden = true;
        setAuthStreak(3, 3);
        updateAuthFaceUi();
        setAuthHint(`Face ID verified. Enter PIN for ${user.full_name}.`, 'ok');
        if (pinEl && document.activeElement !== pinEl) {
          setTimeout(() => { try { pinEl.focus({ preventScroll: true }); } catch (_) {} }, 40);
        }
        return '2fa_pin_pending';
      }
    }

    FACE_STATE.cooldownUntil = Date.now() + 2500;
    FACE_STATE.pending2faUser = null;
    FACE_STATE.pendingPinUser = null;
    resetLivenessState();
    const confPct = Math.max(55, Math.min(99.8, Math.round((1 - Number(dist || 0.2) * 0.85) * 1000) / 10));

    if (STATE.faceSettings.sound && window.Face && window.Face.Sound) {
      window.Face.Sound.playSuccess();
    }

    // Show verification card overlay on #authGate briefly
    const card = $('authFaceCard');
    const photoEl = $('authFaceCardImg') || $('authFacePhoto');
    const nameEl = $('authFaceCardName') || $('authFaceName');
    const metaEl = $('authFaceCardMeta') || $('authFaceMeta');
    const confEl = $('authFaceCardSub') || $('authFaceConf');
    const badgeEl = $('authFaceCardBadge') || $('authFaceBadge');
    if (card) {
      if (badgeEl) badgeEl.textContent = /2FA/i.test(String(methodLabel || '')) ? '2FA VERIFIED' : 'FACE ID VERIFIED';
      if (nameEl) nameEl.textContent = user.full_name;
      if (metaEl) metaEl.textContent = `${Math.round(confPct)}% match`;
      if (confEl) confEl.textContent = `${formatCleanSeatRole(user.role)} · ${formatSeatEntityCountLabel(user)}`;
      if (photoEl && snapshotUrl) photoEl.src = snapshotUrl;
      card.hidden = false;
    }

    await new Promise(r => setTimeout(r, (navigator.webdriver || window.__MFG_HEADLESS_TEST) ? 60 : 80));
    if (card) card.hidden = true;
    return performLogin(user.email, user.pin_code || '1111', {
      bypass2FA: true,
      method: methodLabel || 'Face ID',
      confidence: confPct
    });
  }

  // Evaluates a single 128-d face detection against enrolled seats (used by live camera loop AND headless tests)
  // Anti-screenshot rule: NEVER unlock on 1 frame — always require >= 3 consecutive matching frames + liveness.
  async function handleAuthDescriptor(det, snapshotUrl, opts = {}) {
    if (opts && opts.liveCamera && STATE.authed) return { status: 'already-authed' };
    const needed = Math.max(3, Number(STATE.faceSettings.confirmFrames || 3));
    const enrolled = usableFaces();
    if (!enrolled.length) {
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      setAuthStreak(0, needed);
      setAuthHint('', '');
      return { status: 'no-enrolled' };
    }
    if (!det || !det.descriptor) {
      FACE_STATE.missedFrames = (FACE_STATE.missedFrames || 0) + 1;
      if (!FACE_STATE.streakCount || FACE_STATE.missedFrames >= 4) {
        FACE_STATE.streakUser = null;
        FACE_STATE.streakCount = 0;
        setAuthStreak(0, needed);
        setAuthHint(FACE_STATE.pending2faUser ? `Look at the camera to verify ${FACE_STATE.pending2faUser.full_name}` : (FACE_STATE.camActive ? 'Look at camera for automatic Face ID' : ''), '');
      }
      return { status: 'no-face' };
    }
    FACE_STATE.missedFrames = 0;
    if (det.multiple) {
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      setAuthStreak(0, needed);
      setAuthHint('One person in frame at a time', 'warn');
      return { status: 'multiple' };
    }

    const baseThr = Number(STATE.faceSettings.threshold || 0.50);
    const m = window.Face.match(det.descriptor, enrolled);
    // When a live webcam already matched a user on frame 1+, allow a +0.06 head-turn/blink tolerance for that same user so movement never resets the streak
    const isSameStreakUserOnLiveVideo = !!(opts && opts.videoEl && FACE_STATE.streakUser && FACE_STATE.streakCount >= 1 && m && m.best && norm(m.best.email) === norm(FACE_STATE.streakUser.email));
    const cfg = Object.assign({}, window.Face.CONFIG, {
      threshold: isSameStreakUserOnLiveVideo ? (baseThr + 0.06) : baseThr,
      margin: isSameStreakUserOnLiveVideo ? Math.max(0.04, Number(STATE.faceSettings.margin || 0.08) - 0.03) : Number(STATE.faceSettings.margin || 0.08),
      weakAbove: Number(STATE.faceSettings.weakAbove || 0.45),
      minFaceFrac: isSameStreakUserOnLiveVideo ? 0.10 : Number(STATE.faceSettings.minFaceFrac || 0.14)
    });
    const dec = window.Face.decide(m, cfg, { faceSizeFrac: det.faceSizeFrac != null ? det.faceSizeFrac : 0.25 });

    if (!dec.ok) {
      if (opts && opts.videoEl && FACE_STATE.streakCount > 0) {
        FACE_STATE.weakFrames = (FACE_STATE.weakFrames || 0) + 1;
        if (FACE_STATE.weakFrames < 3) {
          return { status: dec.status, match: m, heldStreak: FACE_STATE.streakCount };
        }
      }
      FACE_STATE.weakFrames = 0;
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      setAuthStreak(0, needed);
      if (dec.status === 'too-small') setAuthHint('Move slightly closer', 'warn');
      else if (dec.status === 'ambiguous') setAuthHint('Hold still to confirm match', 'warn');
      else setAuthHint('Face not recognized', 'crit');
      return { status: dec.status, match: m };
    }
    FACE_STATE.weakFrames = 0;

    const matchedUser = STATE.users.find(u => norm(u.email) === norm(dec.best.email));
    const seatMode = effectiveSeatAuthMode(matchedUser);
    if (seatMode === 'pin_only' && !FACE_STATE.pending2faUser) {
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      setAuthStreak(0, needed);
      setAuthHint(`Enter PIN below for ${dec.best.name}`, 'warn');
      return { status: 'face-disabled', best: dec.best, dist: m.bestDist };
    }

    // If Live Face ID Step 1 is already verified for this user in 'both' mode, hold steady at 100% (never re-loop 1/3..3/3 or wipe PIN input)
    if (FACE_STATE.pendingPinUser && norm(FACE_STATE.pendingPinUser.email) === norm(dec.best.email)) {
      setAuthStreak(needed, needed);
      const typedPin = val('authPinInput');
      if (typedPin && matchedUser && typedPin === String(matchedUser.pin_code || '1111').trim()) {
        await completeFaceLogin(matchedUser, m.bestDist, snapshotUrl, 'Face ID + PIN 2FA');
        return { status: 'verified', user: matchedUser, dist: m.bestDist, method: 'Face ID + PIN 2FA' };
      }
      return { status: '2fa-pin-pending', user: matchedUser, dist: m.bestDist };
    }

    // If step-up 2FA is waiting for a specific seat, verify it matches that exact seat
    if (FACE_STATE.pending2faUser && norm(dec.best.email) !== norm(FACE_STATE.pending2faUser.email)) {
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      setAuthStreak(0, needed);
      if (STATE.faceSettings.sound && window.Face && window.Face.Sound) window.Face.Sound.playWarn();
      setAuthHint(`Expected ${FACE_STATE.pending2faUser.full_name}, saw ${dec.best.name}`, 'crit');
      return { status: '2fa-mismatch', expected: FACE_STATE.pending2faUser.email, actual: dec.best.email };
    }

    if (FACE_STATE.streakUser && norm(FACE_STATE.streakUser.email) === norm(dec.best.email)) {
      FACE_STATE.streakCount += 1;
    } else {
      FACE_STATE.streakUser = dec.best;
      FACE_STATE.streakCount = 1;
    }
    FACE_STATE.bestDist = m.bestDist;
    FACE_STATE.secondDist = m.secondDist;

    // Evaluate anti-screenshot liveness on every matching frame (blink dip+recovery OR 3D head-turn parallax)
    const liveRes = livenessStep(det, dec.best.email, opts);

    if (FACE_STATE.streakCount < needed) {
      setAuthStreak(FACE_STATE.streakCount, needed);
      setAuthHint(`Verifying ${dec.best.name}…`, liveRes.ok ? 'ok' : 'warn');
      return { status: 'streak', count: FACE_STATE.streakCount, needed, livenessOk: liveRes.ok, best: dec.best, dist: m.bestDist };
    }

    if (!liveRes.ok) {
      // Hold streak at needed - 1 until the live person blinks or turns their head slightly (rejects static/tilted 2D screenshots)
      FACE_STATE.streakCount = needed - 1;
      setAuthStreak(FACE_STATE.streakCount, needed);
      const liveMode = String(STATE.faceSettings.livenessMode || 'blink_or_turn');
      const promptMsg = liveMode === 'blink'
        ? `Blink once to confirm ${dec.best.name}`
        : (liveMode === 'turn3d'
          ? `Turn slightly to confirm ${dec.best.name}`
          : 'Blink or turn slightly to confirm');
      setAuthHint(promptMsg, 'warn');
      return { status: 'awaiting-blink', livenessStatus: 'awaiting-liveness', livenessDetail: liveRes, count: FACE_STATE.streakCount, needed, best: dec.best, dist: m.bestDist };
    }

    // Confirmed across >= 3 consecutive frames + live anti-screenshot liveness!
    FACE_STATE.streakUser = null;
    FACE_STATE.streakCount = 0;
    setAuthStreak(needed, needed);
    const livenessTag = liveRes.method && liveRes.method !== 'synthetic-descriptor' && liveRes.method !== 'multi-frame'
      ? ` · Live ${liveRes.method === 'turn3d' ? '3D Turn' : 'Blink'}`
      : '';
    const methodLabel = FACE_STATE.pending2faUser ? `PIN + Face ID 2FA${livenessTag}` : `Face ID${livenessTag}`;
    setAuthHint(`✓ Face ID verified · ${dec.best.name}`, 'ok');
    if (!snapshotUrl && opts && opts.videoEl && window.Face && window.Face.snapshot) {
      try { snapshotUrl = window.Face.snapshot(opts.videoEl); } catch (_) {}
    }
    const loginRes = await completeFaceLogin(matchedUser, m.bestDist, snapshotUrl, methodLabel);
    if (loginRes === '2fa_pin_pending') {
      return { status: '2fa-pin-pending', user: matchedUser, dist: m.bestDist, method: methodLabel, liveness: liveRes.method };
    }
    return { status: 'verified', user: matchedUser, dist: m.bestDist, method: methodLabel, liveness: liveRes.method };
  }

  async function authFaceTick() {
    if (STATE.authed || !FACE_STATE.camActive) {
      if (STATE.authed && !FACE_STATE.enrolCamActive) stopFaceCamera();
      return;
    }
    const videoEl = $('authFaceVideo');
    const overlayEl = $('authFaceOverlay');
    if (!videoEl || Date.now() < FACE_STATE.cooldownUntil) {
      FACE_STATE.loopTimer = setTimeout(authFaceTick, 60);
      return;
    }
    if (!FACE_STATE.busy && videoEl.readyState >= 2 && videoEl.videoWidth > 0) {
      FACE_STATE.busy = true;
      try {
        await ensureFaceModelsLoaded();
        if (STATE.authed || !FACE_STATE.camActive) {
          if (STATE.authed && !FACE_STATE.enrolCamActive) stopFaceCamera();
          return;
        }
        const det = await window.Face.detectOne(videoEl, false);
        if (STATE.authed || !FACE_STATE.camActive) {
          if (STATE.authed && !FACE_STATE.enrolCamActive) stopFaceCamera();
          return;
        }
        if (overlayEl && window.Face.drawOverlay) {
          const color = det && !det.multiple ? (FACE_STATE.streakCount > 0 ? '#16A34A' : '#B8883B') : '#DC2626';
          window.Face.drawOverlay(overlayEl, videoEl, det, color, FACE_STATE.streakUser ? FACE_STATE.streakUser.name : '');
        }
        await handleAuthDescriptor(det, '', { liveCamera: true, videoEl });
      } catch (_) {
        /* ignore transient frame error */
      } finally {
        FACE_STATE.busy = false;
      }
    }
    if (!STATE.authed && FACE_STATE.camActive) {
      FACE_STATE.loopTimer = setTimeout(authFaceTick, 30);
    }
  }

  async function startAuthFaceScanner(forceStart = false) {
    if (STATE.authed || (!forceStart && FACE_STATE.authCamStoppedByUser)) {
      stopFaceCamera();
      updateAuthFaceUi();
      return false;
    }
    if ((navigator.webdriver || window.__MFG_HEADLESS_TEST) && !forceStart) {
      FACE_STATE.camStarting = false;
      updateAuthFaceUi();
      setAuthHint('', '');
      return false;
    }
    const videoEl = $('authFaceVideo');
    if (!videoEl) {
      updateAuthFaceUi();
      return false;
    }
    FACE_STATE.camStarting = true;
    updateAuthFaceUi();
    const camOk = await startFaceCamera(videoEl);
    FACE_STATE.camStarting = false;
    if (STATE.authed || (!forceStart && FACE_STATE.authCamStoppedByUser)) {
      stopFaceCamera();
      updateAuthFaceUi();
      return false;
    }
    FACE_STATE.camActive = camOk;
    updateAuthFaceUi();
    if (!camOk) {
      setAuthHint('Camera unavailable', 'warn');
      return false;
    }
    const enrolled = usableFaces();
    const faceAlreadyReady = Boolean(window.Face && window.Face.ready);
    const videoReadyNow = Boolean($('authCamViewport')?.classList.contains('is-video-ready'));
    setAuthHint(
      FACE_STATE.pending2faUser
        ? `Look at the camera to verify ${FACE_STATE.pending2faUser.full_name}`
        : (videoReadyNow && enrolled.length
          ? (faceAlreadyReady
            ? 'Look at camera for automatic Face ID'
            : 'Preparing Face ID…')
          : ''),
      (videoReadyNow && enrolled.length && faceAlreadyReady) ? 'ok' : ''
    );
    const startModelsWhenReady = () => {
      if (STATE.authed || (!forceStart && FACE_STATE.authCamStoppedByUser)) return Promise.resolve(false);
      return ensureFaceModelsLoaded().then(() => {
        if (!STATE.authed && FACE_STATE.camActive) {
          const enrNow = usableFaces();
          if (!FACE_STATE.pending2faUser && enrNow.length && FACE_STATE.streakCount === 0) {
            setAuthHint('Look at camera for automatic Face ID', 'ok');
          }
          updateAuthFaceUi();
        }
        return true;
      }).catch(() => false);
    };
    if (forceStart || FACE_STATE.pending2faUser || window.__mfgCoreSeedLoaded) {
      startModelsWhenReady();
    } else {
      let triggered = false;
      const runOnce = () => { if (!triggered) { triggered = true; startModelsWhenReady(); } };
      window.addEventListener('mfg:core-seed-ready', runOnce, { once: true });
      setTimeout(runOnce, 1200);
    }
    if (FACE_STATE.loopTimer) clearTimeout(FACE_STATE.loopTimer);
    FACE_STATE.loopTimer = setTimeout(authFaceTick, 25);
    return true;
  }

  function stopAuthFaceScanner() {
    if (FACE_STATE.loopTimer) { clearTimeout(FACE_STATE.loopTimer); FACE_STATE.loopTimer = null; }
    FACE_STATE.camActive = false;
    if (!FACE_STATE.enrolCamActive) stopFaceCamera();
    updateAuthFaceUi();
  }

  // ---- Enrolment Studio & Calibration helpers (Users & Cloud Auth view) ----
  function triggerEnrolShutterFlash() {
    const fl = $('enrolShutterFlash');
    if (!fl) return;
    fl.classList.remove('active');
    void fl.offsetWidth;
    fl.classList.add('active');
    setTimeout(() => { if (fl.isConnected) fl.classList.remove('active'); }, 260);
  }

  function wireEnrolPoseSlots(root) {
    if (!root) return;
    root.querySelectorAll('[data-retake-pose]').forEach(el => {
      el.addEventListener('click', e => {
        e.stopPropagation();
        const slot = Number(el.getAttribute('data-retake-pose'));
        if (Number.isFinite(slot) && slot >= 0 && slot < 3) {
          captureEnrolDescriptor(null, '', slot);
        }
      });
    });
  }

  function cloneEffectivePermsToCustomDraft(sourceUser) {
    const eff = getEffectivePermissions(sourceUser || getDraftSeatPreviewUser());
    return {
      rights: Object.assign({}, eff.rights || {}),
      unlocks: Object.assign({}, eff.unlocks || {}),
      dashboards: Object.assign({}, eff.dashboards || {}),
      statements: Object.assign({}, eff.statements || {})
    };
  }

  function selectSeatForEdit(targetId, opts = {}) {
    if (!isOwner()) return false;
    STATE.showAddUserForm = true;
    STATE.userFormDirty = false;
    STATE.draftRoleOverride = null;
    STATE.draftCompaniesOverride = null;
    STATE.draftAccessOverride = null;
    STATE.draftCustomPerms = null;
    hideRoleHoverCard(true);
    STATE.permMatrixTab = opts.permTab || 'all';
    if (targetId === '__new__') {
      STATE.editingUserId = '__new__';
      STATE.newDraftPin = String(Math.floor(1000 + Math.random() * 9000));
      STATE.showRolePermMatrix = !!opts.openPerms;
    } else {
      let u = STATE.users.find(x => String(x.id) === String(targetId) || norm(x.email) === norm(String(targetId || '')));
      if (!u && /^u(\d+)$/i.test(String(targetId || ''))) {
        const idx = parseInt(String(targetId).slice(1), 10) - 1;
        if (idx >= 0 && idx < STATE.users.length) u = STATE.users[idx];
      }
      if (!u) return false;
      STATE.editingUserId = String(u.id);
      if (resolveCanonicalRoleKey(u.role) === 'Custom') {
        STATE.draftCustomPerms = cloneEffectivePermsToCustomDraft(u);
        STATE.showRolePermMatrix = opts.openPerms != null ? !!opts.openPerms : true;
      } else {
        STATE.showRolePermMatrix = !!opts.openPerms;
      }
    }
    updateSeatEditorDom();
    if (opts.scroll) {
      const p = opts.openPerms ? ($('rolePermissionsMatrixWrap') || $('seatEditorPanel')) : $('seatEditorPanel');
      if (p) scrollWorkspaceTo(p);
    }
    if (opts.focusName) {
      setTimeout(() => { const n = $('nu_name'); if (n) { try { n.focus({ preventScroll: true }); } catch (_) { n.focus(); } } }, 30);
    }
    return true;
  }

  function updateSeatEditorDom() {
    const wrap = $('seatEditorWrap');
    if (wrap) {
      wrap.innerHTML = renderSeatEditorHtml();
      wireSeatEditorActions(wrap);
    }
    const tbody = $('usersDirectoryTbody');
    if (tbody) {
      tbody.innerHTML = renderUsersDirectoryRowsHtml();
      wireUsersDirectoryActions(tbody);
    }
  }

  async function saveSeatEditorForm() {
    if (!isOwner()) return false;
    const name = val('nu_name');
    const email = norm(val('nu_email'));
    const pin = val('nu_pin');
    const role = val('nu_role') || 'Entry';
    const rawCompanies = val('nu_companies');
    const companies = rawCompanies ? normalizeCompaniesScope(rawCompanies) : '';
    const rawAccess = val('nu_access') || 'partial|partial';
    const isCustomRole = resolveCanonicalRoleKey(role) === 'Custom' || rawAccess === 'custom|custom';
    const finalRole = isCustomRole ? 'Custom' : role;
    const defaultRoleAcc = (ROLE_PRESETS[resolveCanonicalRoleKey(finalRole)] && ROLE_PRESETS[resolveCanonicalRoleKey(finalRole)].defaultAccess) || 'partial|partial';
    const acc = (isCustomRole ? 'custom|custom' : (rawAccess === 'custom|custom' ? defaultRoleAcc : rawAccess)).split('|');
    const editUser = (STATE.editingUserId && STATE.editingUserId !== '__new__')
      ? STATE.users.find(x => String(x.id) === String(STATE.editingUserId))
      : null;
    const errs = [];
    if (!name) errs.push('Full name is required.');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errs.push('Enter a valid email address.');
    if (!/^\d{4,8}$/.test(pin)) errs.push('PIN must be 4 to 8 digits.');
    if (!companies) errs.push('Select at least one company for Row-Level Security (RLS).');
    const dupUser = STATE.users.find(x => norm(x.email) === email && (!editUser || String(x.id) !== String(editUser.id)));
    if (dupUser && STATE.editingUserId && STATE.editingUserId !== '__new__') {
      errs.push(`Email ${email} is already assigned to ${dupUser.full_name}.`);
    }
    const box = $('nuErrors');
    if (box) { box.hidden = !errs.length; box.innerHTML = errs.length ? `<ul>${errs.map(e => `<li>${esc(e)}</li>`).join('')}</ul>` : ''; }
    if (errs.length) return false;

    const existingIdx = editUser
      ? STATE.users.findIndex(x => String(x.id) === String(editUser.id))
      : STATE.users.findIndex(x => norm(x.email) === email);
    const prev = existingIdx >= 0 ? STATE.users[existingIdx] : {};
    const isSelfOwner = existingIdx === STATE.activeUserIdx;
    const statusEl = $('nu_status');
    const statusVal = isSelfOwner ? 'Active' : ((statusEl && statusEl.value === 'Suspended') ? 'Suspended' : (prev.status || 'Active'));
    const authModeRaw = val('nu_auth_mode');
    const authModeVal = (authModeRaw && authModeRaw !== 'inherit') ? normalizeAuthMode(authModeRaw, 'both') : '';
    const bookScopeVal = val('nu_book_scope') === 'official' ? 'official' : 'all';
    const customPermsObj = isCustomRole
      ? (STATE.draftCustomPerms || cloneEffectivePermsToCustomDraft(editUser || prev))
      : {};
    if (isCustomRole && isSelfOwner && customPermsObj.rights) {
      customPermsObj.rights.manage_users = true;
    }
    const customPermsJson = isCustomRole ? JSON.stringify(customPermsObj) : '{}';
    const nowIso = new Date().toISOString();
    const newUser = {
      id: existingIdx >= 0 ? prev.id : uid('u'),
      full_name: name,
      email,
      pin_code: pin,
      role: finalRole,
      companies,
      pbi_access: acc[0] || 'partial',
      statements_access: acc[1] || 'partial',
      custom_perms: customPermsJson,
      book_scope: bookScopeVal,
      status: statusVal,
      auth_mode: authModeVal,
      last_login_at: prev.last_login_at || '',
      face_samples: prev.face_samples || [],
      face_thumbs: prev.face_thumbs || [],
      face_required: authModeVal ? (authModeVal === 'both' || authModeVal === 'face_only') : !!prev.face_required,
      face_updated_at: prev.face_updated_at || '',
      seat_updated_at: nowIso
    };
    if (existingIdx >= 0) STATE.users[existingIdx] = Object.assign(STATE.users[existingIdx], newUser);
    else STATE.users.push(newUser);
    STATE.editingUserId = String(newUser.id);
    STATE.showAddUserForm = true;
    STATE.userFormDirty = false;
    STATE.draftRoleOverride = null;
    STATE.draftCompaniesOverride = null;
    STATE.draftAccessOverride = null;
    STATE.draftBookScopeOverride = '';
    STATE.draftCustomPerms = isCustomRole ? customPermsObj : null;
    saveLocalAuthAndRecords();
    applyUserRlsAndPermissions();
    updateSeatEditorDom();
    updateEnrolStudioDom();
    toast(existingIdx >= 0 ? `✓ Seat updated · ${name} (${finalRole} · ${companies})` : `✓ Seat created · ${name} (PIN ${pin})`);
    if (HAS_LOCAL_API) { try { await fetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: newUser }) }); } catch (_) { /* no server.py */ } }
    await syncWithCloud(true);
    return true;
  }

  function wireCompanyMultiSelect(root) {
    const wrap = root.querySelector('#nuCompanySelector');
    if (!wrap) return;
    const hiddenInp = wrap.querySelector('#nu_companies');
    const triggerBtn = wrap.querySelector('#nuCompanyTrigger');
    const summaryEl = wrap.querySelector('#nuCompanySummaryText');
    const countPillEl = wrap.querySelector('#nuCompanyCountPill');
    const chipsEl = wrap.querySelector('#nuCompanyChips');
    const popoverEl = wrap.querySelector('#nuCompanyPopover');
    const searchEl = wrap.querySelector('#nuCompanySearch');
    const selectAllBtn = wrap.querySelector('#nuCompanySelectAllBtn');
    const clearBtn = wrap.querySelector('#nuCompanyClearBtn');
    const doneBtn = wrap.querySelector('#nuCompanyDoneBtn');
    const indBarEl = wrap.querySelector('#nuCompanyIndustryBar');
    const listEl = wrap.querySelector('#nuCompanyList');
    const footStatusEl = wrap.querySelector('#nuCompanyFootStatus');

    const allLabels = () => Array.from(listEl ? listEl.querySelectorAll('.co-multi-opt') : []);
    const allCbs = () => Array.from(listEl ? listEl.querySelectorAll('.co-multi-cb') : []);
    const allIndHeaders = () => Array.from(listEl ? listEl.querySelectorAll('.co-multi-ind-hdr') : []);
    const allIndTabs = () => Array.from(indBarEl ? indBarEl.querySelectorAll('.co-multi-ind-tab') : []);

    const applyFilterVisibility = () => {
      const q = searchEl ? String(searchEl.value || '').trim().toLowerCase() : '';
      const activeInd = wrap.getAttribute('data-active-ind') || 'all';
      const indVisibleMap = new Map();
      allLabels().forEach(lbl => {
        const hay = String(lbl.getAttribute('data-co-search') || '').toLowerCase();
        const ind = String(lbl.getAttribute('data-co-ind') || 'Manufacturing');
        const matchesInd = activeInd === 'all' || ind === activeInd;
        const matchesQ = !q || hay.includes(q);
        const show = matchesInd && matchesQ;
        lbl.hidden = !show;
        if (show) indVisibleMap.set(ind, (indVisibleMap.get(ind) || 0) + 1);
      });
      allIndHeaders().forEach(hdr => {
        const ind = String(hdr.getAttribute('data-ind-hdr') || '');
        hdr.hidden = !indVisibleMap.get(ind);
      });
      allIndTabs().forEach(tab => {
        const tabInd = String(tab.getAttribute('data-ind-tab') || 'all');
        tab.classList.toggle('active', tabInd === activeInd);
      });
    };

    const syncFromCheckboxes = () => {
      const cbs = allCbs();
      const total = cbs.length;
      const selected = [];
      const indTotals = new Map();
      const indSelected = new Map();
      const selIndSet = new Set();
      cbs.forEach(cb => {
        const opt = cb.closest('.co-multi-opt');
        const ind = String(cb.getAttribute('data-cb-ind') || (opt && opt.getAttribute('data-co-ind')) || 'Manufacturing');
        indTotals.set(ind, (indTotals.get(ind) || 0) + 1);
        if (opt) opt.classList.toggle('is-checked', !!cb.checked);
        if (cb.checked) {
          selected.push(cb.value);
          indSelected.set(ind, (indSelected.get(ind) || 0) + 1);
          selIndSet.add(ind);
        }
      });
      if (hiddenInp) hiddenInp.value = selected.join(', ');
      if (summaryEl) summaryEl.textContent = formatCompanySummaryLabel(selected, total, selIndSet.size);
      if (countPillEl) countPillEl.textContent = `${selected.length} / ${total} selected`;

      // Update per-industry counters & toggle buttons
      const allCntEl = indBarEl ? indBarEl.querySelector('[data-ind-cnt="all"]') : null;
      if (allCntEl) allCntEl.textContent = `${selected.length}/${total}`;
      indTotals.forEach((tot, ind) => {
        const sel = indSelected.get(ind) || 0;
        if (indBarEl) {
          indBarEl.querySelectorAll('[data-ind-cnt]').forEach(el => {
            if (el.getAttribute('data-ind-cnt') === ind) el.textContent = `${sel}/${tot}`;
          });
        }
        if (listEl) {
          listEl.querySelectorAll('[data-ind-hdr-count]').forEach(el => {
            if (el.getAttribute('data-ind-hdr-count') === ind) el.textContent = `${sel} of ${tot} selected`;
          });
          listEl.querySelectorAll('[data-toggle-industry]').forEach(btn => {
            if (btn.getAttribute('data-toggle-industry') === ind) {
              const allOn = sel === tot && tot > 0;
              btn.textContent = allOn ? 'Clear Industry' : `Select All (${tot})`;
              btn.classList.toggle('is-all-selected', allOn);
            }
          });
        }
      });

      const q = searchEl ? String(searchEl.value || '').trim() : '';
      const activeInd = wrap.getAttribute('data-active-ind') || 'all';
      const visibleCount = allLabels().filter(l => !l.hidden).length;
      if (selectAllBtn) {
        selectAllBtn.textContent = (q || activeInd !== 'all')
          ? `Select Visible (${visibleCount})`
          : `Select All (${total})`;
      }
      if (footStatusEl) {
        footStatusEl.textContent = (q || activeInd !== 'all')
          ? `Showing ${visibleCount} of ${total} companies · ${selected.length} assigned (${selIndSet.size || 0} ind)`
          : `${selected.length} of ${total} ${total === 1 ? 'company' : 'companies'} assigned across ${indTotals.size || 1} ${(indTotals.size || 1) === 1 ? 'industry' : 'industries'}`;
      }
      if (chipsEl) {
        chipsEl.innerHTML = renderCompanyMultiSelectChipsHtml(selected);
        chipsEl.querySelectorAll('[data-remove-co]').forEach(btn => {
          btn.addEventListener('click', e => {
            e.stopPropagation();
            const targetCo = String(btn.getAttribute('data-remove-co') || '').toLowerCase();
            cbs.forEach(cb => {
              if (String(cb.value || '').toLowerCase() === targetCo) cb.checked = false;
            });
            STATE.userFormDirty = true;
            syncFromCheckboxes();
          });
        });
      }
    };

    const setOpen = (open) => {
      wrap.classList.toggle('open', !!open);
      if (popoverEl) popoverEl.hidden = !open;
      if (triggerBtn) triggerBtn.setAttribute('aria-expanded', String(!!open));
      if (open && searchEl) {
        setTimeout(() => { try { searchEl.focus({ preventScroll: true }); } catch (_) {} }, 20);
      }
    };

    if (triggerBtn) {
      triggerBtn.addEventListener('click', e => {
        e.stopPropagation();
        setOpen(popoverEl ? popoverEl.hidden : !wrap.classList.contains('open'));
      });
    }
    if (doneBtn) {
      doneBtn.addEventListener('click', e => {
        e.stopPropagation();
        setOpen(false);
      });
    }
    if (searchEl) {
      searchEl.addEventListener('input', () => {
        applyFilterVisibility();
        syncFromCheckboxes();
      });
    }
    allIndTabs().forEach(tab => {
      tab.addEventListener('click', e => {
        e.stopPropagation();
        const targetInd = String(tab.getAttribute('data-ind-tab') || 'all');
        wrap.setAttribute('data-active-ind', targetInd);
        applyFilterVisibility();
        syncFromCheckboxes();
      });
    });
    if (listEl) {
      listEl.querySelectorAll('[data-toggle-industry]').forEach(btn => {
        btn.addEventListener('click', e => {
          e.stopPropagation();
          e.preventDefault();
          const targetInd = String(btn.getAttribute('data-toggle-industry') || '');
          const indCbs = allCbs().filter(cb => String(cb.getAttribute('data-cb-ind') || '') === targetInd);
          const allChecked = indCbs.length > 0 && indCbs.every(cb => cb.checked);
          indCbs.forEach(cb => { cb.checked = !allChecked; });
          STATE.userFormDirty = true;
          syncFromCheckboxes();
        });
      });
    }
    allCbs().forEach(cb => {
      cb.addEventListener('change', () => {
        STATE.userFormDirty = true;
        syncFromCheckboxes();
      });
    });
    if (selectAllBtn) {
      selectAllBtn.addEventListener('click', e => {
        e.stopPropagation();
        allLabels().forEach(lbl => {
          if (!lbl.hidden) {
            const cb = lbl.querySelector('.co-multi-cb');
            if (cb) cb.checked = true;
          }
        });
        STATE.userFormDirty = true;
        syncFromCheckboxes();
      });
    }
    if (clearBtn) {
      clearBtn.addEventListener('click', e => {
        e.stopPropagation();
        allLabels().forEach(lbl => {
          if (!lbl.hidden) {
            const cb = lbl.querySelector('.co-multi-cb');
            if (cb) cb.checked = false;
          }
        });
        STATE.userFormDirty = true;
        syncFromCheckboxes();
      });
    }
    if (hiddenInp) {
      hiddenInp.addEventListener('change', () => {
        const raw = String(hiddenInp.value || '').trim();
        const names = raw ? parseUserCompanies(raw).map(s => s.toLowerCase()) : [];
        const set = new Set(names);
        allCbs().forEach(cb => {
          cb.checked = set.has(String(cb.value || '').toLowerCase());
        });
        syncFromCheckboxes();
      });
    }
    if (!document.body.dataset.coMultiDocWired) {
      document.body.dataset.coMultiDocWired = '1';
      document.addEventListener('mousedown', e => {
        const activeWrap = document.getElementById('nuCompanySelector');
        if (activeWrap && activeWrap.classList.contains('open') && (!e.target || !e.target.closest('#nuCompanySelector'))) {
          activeWrap.classList.remove('open');
          const pop = document.getElementById('nuCompanyPopover');
          if (pop) pop.hidden = true;
          const trig = document.getElementById('nuCompanyTrigger');
          if (trig) trig.setAttribute('aria-expanded', 'false');
        }
      });
    }
    applyFilterVisibility();
    syncFromCheckboxes();
  }

  function wireRolePreviewQuickScopes(previewPane, root) {
    if (!previewPane) return;
    const scope = root || $('seatEditorWrap') || document;
    const accEl = scope.querySelector('#nu_access');
    previewPane.querySelectorAll('[data-quick-access]').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        const nextAcc = btn.getAttribute('data-quick-access') || 'partial|partial';
        if (accEl) {
          accEl.value = nextAcc;
          accEl.dispatchEvent(new Event('change', { bubbles: true }));
        }
        if (nextAcc === 'custom|custom') {
          const roleWrap = scope.querySelector('#nuRolePermsSelector');
          const rolePop = scope.querySelector('#nuRolePopover');
          const roleTrig = scope.querySelector('#nuRoleTrigger');
          if (roleWrap) roleWrap.classList.remove('open');
          if (rolePop) rolePop.hidden = true;
          if (roleTrig) roleTrig.setAttribute('aria-expanded', 'false');
          const mw = scope.querySelector('#rolePermissionsMatrixWrap');
          if (mw) mw.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      });
    });
  }

  function wireRolePermSelector(root) {
    if (!root) return;
    const wrap = root.querySelector('#nuRolePermsSelector');
    if (!wrap) return;
    const triggerBtn = wrap.querySelector('#nuRoleTrigger');
    const popoverEl = wrap.querySelector('#nuRolePopover');
    const previewPane = wrap.querySelector('#nuRolePreviewPane');
    const postureStrip = wrap.querySelector('#nuRolePostureStrip');
    const openMatrixBtn = wrap.querySelector('#nuRoleOpenMatrixBtn');
    const doneBtn = wrap.querySelector('#nuRoleDoneBtn');
    const roleEl = wrap.querySelector('#nu_role');
    const accEl = wrap.querySelector('#nu_access');

    const closePop = () => {
      wrap.classList.remove('open');
      if (popoverEl) popoverEl.hidden = true;
      if (triggerBtn) triggerBtn.setAttribute('aria-expanded', 'false');
    };

    const showPreviewForRole = roleVal => {
      if (!previewPane) return;
      const curSelKey = resolveCanonicalRoleKey(roleEl ? roleEl.value : 'Entry');
      const targetKey = resolveCanonicalRoleKey(roleVal);
      const isSelectedRole = curSelKey === targetKey;
      wrap.querySelectorAll('[data-role-opt]').forEach(optBtn => {
        const optKey = resolveCanonicalRoleKey(optBtn.getAttribute('data-role-opt'));
        optBtn.classList.toggle('is-preview', optKey === targetKey);
      });
      const coVal = val('nu_companies') || 'WTC';
      const accVal = accEl ? accEl.value : 'partial|partial';
      const pUser = buildPreviewUserForRoleKey(roleVal, coVal, accVal, isSelectedRole);
      previewPane.innerHTML = renderRolePopoverPreviewHtml(pUser, { isPreviewOnly: !isSelectedRole });
      if (isSelectedRole) wireRolePreviewQuickScopes(previewPane, root);
    };

    const openPop = () => {
      hideRoleHoverCard(true);
      const coWrap = document.getElementById('nuCompanySelector');
      if (coWrap && coWrap.classList.contains('open')) {
        coWrap.classList.remove('open');
        const coPop = document.getElementById('nuCompanyPopover');
        if (coPop) coPop.hidden = true;
        const coTrig = document.getElementById('nuCompanyTrigger');
        if (coTrig) coTrig.setAttribute('aria-expanded', 'false');
      }
      wrap.classList.add('open');
      if (popoverEl) popoverEl.hidden = false;
      if (triggerBtn) triggerBtn.setAttribute('aria-expanded', 'true');
      showPreviewForRole(roleEl ? roleEl.value : 'Entry');
    };

    if (triggerBtn) {
      triggerBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (wrap.classList.contains('open')) closePop();
        else openPop();
      });
    }
    if (doneBtn) {
      doneBtn.addEventListener('click', e => {
        e.stopPropagation();
        closePop();
      });
    }
    if (openMatrixBtn) {
      openMatrixBtn.addEventListener('click', e => {
        e.stopPropagation();
        closePop();
        STATE.showRolePermMatrix = true;
        STATE.permMatrixTab = 'all';
        refreshRoleAndAccessMatrixUi(root);
        const mw = root.querySelector('#rolePermissionsMatrixWrap');
        if (mw) mw.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      });
    }
    wrap.querySelectorAll('[data-role-opt]').forEach(optBtn => {
      const optVal = optBtn.getAttribute('data-role-opt') || 'Entry';
      optBtn.addEventListener('mouseenter', () => showPreviewForRole(optVal));
      optBtn.addEventListener('focus', () => showPreviewForRole(optVal));
      optBtn.addEventListener('click', e => {
        e.stopPropagation();
        const prevCanon = resolveCanonicalRoleKey(roleEl ? roleEl.value : 'Entry');
        const nextCanon = resolveCanonicalRoleKey(optVal);
        if (roleEl) {
          roleEl.value = optVal;
          roleEl.dispatchEvent(new Event('change', { bubbles: true }));
        }
        if (nextCanon === 'Custom') {
          closePop();
          const mw = root.querySelector('#rolePermissionsMatrixWrap');
          if (mw) mw.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        } else if (prevCanon === nextCanon) {
          closePop();
        } else {
          showPreviewForRole(optVal);
        }
      });
    });

    const optCol = wrap.querySelector('.role-perm-opt-col');
    if (optCol) {
      optCol.addEventListener('mouseleave', () => {
        if (wrap.classList.contains('open')) showPreviewForRole(roleEl ? roleEl.value : 'Entry');
      });
    }

    if (postureStrip) {
      postureStrip.addEventListener('mouseover', e => {
        const chip = e.target && e.target.closest ? e.target.closest('[data-role-chip-jump]') : null;
        if (!chip || wrap.classList.contains('open')) return;
        const cat = chip.getAttribute('data-role-chip-jump') || 'all';
        showRoleHoverCard(chip, getDraftSeatPreviewUser(), {
          seatName: val('nu_name') || 'Current Seat',
          userId: '__draft__',
          focusCat: cat
        });
      });
      postureStrip.addEventListener('mouseout', e => {
        const chip = e.target && e.target.closest ? e.target.closest('[data-role-chip-jump]') : null;
        if (!chip) return;
        const rel = e.relatedTarget;
        if (rel && chip.contains(rel)) return;
        hideRoleHoverCard(false);
      });
      postureStrip.addEventListener('click', e => {
        const chip = e.target && e.target.closest ? e.target.closest('[data-role-chip-jump]') : null;
        if (!chip) return;
        e.stopPropagation();
        hideRoleHoverCard(true);
        closePop();
        const cat = chip.getAttribute('data-role-chip-jump') || 'all';
        if (STATE.showRolePermMatrix && STATE.permMatrixTab === cat) {
          STATE.permMatrixTab = 'all';
        } else {
          STATE.showRolePermMatrix = true;
          STATE.permMatrixTab = cat;
        }
        refreshRoleAndAccessMatrixUi(root);
        const mw = root.querySelector('#rolePermissionsMatrixWrap');
        if (mw) mw.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      });
    }

    wireRolePreviewQuickScopes(previewPane, root);

    if (!document.body.dataset.rolePermDocWired) {
      document.body.dataset.rolePermDocWired = '1';
      document.addEventListener('mousedown', e => {
        const activeWrap = document.getElementById('nuRolePermsSelector');
        if (activeWrap && activeWrap.classList.contains('open') && (!e.target || !e.target.closest('#nuRolePermsSelector'))) {
          activeWrap.classList.remove('open');
          const pop = document.getElementById('nuRolePopover');
          if (pop) pop.hidden = true;
          const trig = document.getElementById('nuRoleTrigger');
          if (trig) trig.setAttribute('aria-expanded', 'false');
        }
        const hc = document.getElementById('roleHoverPreviewCard');
        if (hc && !hc.hidden && (!e.target || !e.target.closest('#roleHoverPreviewCard'))) {
          hideRoleHoverCard(true);
        }
      });
      document.addEventListener('scroll', () => {
        const hc = document.getElementById('roleHoverPreviewCard');
        if (hc && !hc.hidden) hideRoleHoverCard(true);
      }, { capture: true, passive: true });
    }
  }

  function refreshRoleAndAccessMatrixUi(root) {
    const scope = root || $('seatEditorWrap') || document;
    const roleEl = scope.querySelector('#nu_role');
    const accEl = scope.querySelector('#nu_access');
    const coEl = scope.querySelector('#nu_companies');
    if (roleEl) STATE.draftRoleOverride = roleEl.value;
    if (accEl) STATE.draftAccessOverride = accEl.value;
    if (coEl) STATE.draftCompaniesOverride = coEl.value;

    const previewUser = getDraftSeatPreviewUser();
    const previewPerms = getEffectivePermissions(previewUser);

    const roleTrigger = scope.querySelector('#nuRoleTrigger');
    if (roleTrigger) roleTrigger.innerHTML = renderRoleTriggerInnerHtml(previewUser);

    const roleWrap = scope.querySelector('#nuRolePermsSelector');
    if (roleWrap) {
      const curCanon = previewPerms.roleKey;
      roleWrap.querySelectorAll('[data-role-opt]').forEach(optBtn => {
        const optCanon = resolveCanonicalRoleKey(optBtn.getAttribute('data-role-opt'));
        const isSel = optCanon === curCanon;
        optBtn.classList.toggle('is-selected', isSel);
        optBtn.classList.toggle('is-preview', isSel);
        optBtn.setAttribute('aria-selected', isSel ? 'true' : 'false');
        const chk = optBtn.querySelector('.role-perm-opt-check');
        if (chk) chk.textContent = isSel ? '✓' : '›';
      });
      const previewPane = roleWrap.querySelector('#nuRolePreviewPane');
      if (previewPane) {
        previewPane.innerHTML = renderRolePopoverPreviewHtml(previewUser, { isPreviewOnly: false });
        wireRolePreviewQuickScopes(previewPane, scope);
      }
    }

    const roleStrip = scope.querySelector('#nuRolePostureStrip');
    if (roleStrip) roleStrip.innerHTML = renderRolePostureStripHtml(previewUser);

    const matrixWrap = scope.querySelector('#rolePermissionsMatrixWrap');
    if (matrixWrap) {
      matrixWrap.innerHTML = renderRolePermissionsMatrixHtml(previewUser, STATE.draftAccessOverride);
      wireRolePermissionsMatrix(scope);
    }

    const checkRoleBtn = scope.querySelector('#checkRolePermsBtn');
    if (checkRoleBtn) {
      checkRoleBtn.classList.toggle('active', !!STATE.showRolePermMatrix);
      checkRoleBtn.innerHTML = STATE.showRolePermMatrix
        ? `${ic('shield')} Hide Matrix`
        : `${ic('sliders')} Customize`;
    }
  }

  function wireRolePermissionsMatrix(root) {
    if (!root) return;
    const roleEl = root.querySelector('#nu_role');
    const accEl = root.querySelector('#nu_access');
    const expandBtn = root.querySelector('#expandPermMatrixBtn');
    if (expandBtn) {
      expandBtn.addEventListener('click', () => {
        STATE.showRolePermMatrix = true;
        refreshRoleAndAccessMatrixUi(root);
      });
    }
    const closeBtn = root.querySelector('#collapsePermMatrixBtn, #closePermMatrixBtn');
    if (closeBtn) {
      closeBtn.addEventListener('click', () => {
        hideRoleHoverCard(true);
        STATE.showRolePermMatrix = false;
        STATE.permMatrixTab = 'all';
        refreshRoleAndAccessMatrixUi(root);
      });
    }
    root.querySelectorAll('[data-matrix-role]').forEach(btn => {
      const targetRole = btn.getAttribute('data-matrix-role') || 'Entry';
      btn.addEventListener('mouseenter', () => {
        const curCanon = resolveCanonicalRoleKey(roleEl ? roleEl.value : 'Entry');
        const isSel = curCanon === resolveCanonicalRoleKey(targetRole);
        const pUser = buildPreviewUserForRoleKey(targetRole, val('nu_companies') || 'WTC', accEl ? accEl.value : 'partial|partial', isSel);
        showRoleHoverCard(btn, pUser, { seatName: '' });
      });
      btn.addEventListener('mouseleave', () => hideRoleHoverCard(false));
      btn.addEventListener('click', () => {
        hideRoleHoverCard(true);
        if (roleEl) {
          roleEl.value = targetRole;
          roleEl.dispatchEvent(new Event('change', { bubbles: true }));
        }
      });
    });
    const switchCustomBtn = root.querySelector('#switchToCustomRoleBtn, #quickSwitchCustomRoleBtn');
    if (switchCustomBtn) {
      switchCustomBtn.addEventListener('click', () => {
        STATE.draftCustomPerms = cloneEffectivePermsToCustomDraft(getDraftSeatPreviewUser());
        if (roleEl) roleEl.value = 'Custom';
        if (accEl) accEl.value = 'custom|custom';
        STATE.draftRoleOverride = 'Custom';
        STATE.draftAccessOverride = 'custom|custom';
        STATE.showRolePermMatrix = true;
        STATE.userFormDirty = true;
        refreshRoleAndAccessMatrixUi(root);
        toast('Switched to Custom Role · pick granular permissions, field overrides, dashboards & statements');
      });
    }
    root.querySelectorAll('[data-apply-preset-to-custom]').forEach(btn => {
      btn.addEventListener('click', () => {
        const presetKey = btn.getAttribute('data-apply-preset-to-custom') || 'Entry';
        const pDef = ROLE_PRESETS[presetKey] || ROLE_PRESETS['Entry'];
        const pAcc = (pDef.defaultAccess || 'partial|partial').split('|');
        STATE.draftCustomPerms = {
          rights: Object.assign({}, pDef.rights),
          unlocks: Object.assign({}, pDef.unlocks),
          dashboards: dashboardsFromAccessTier(pAcc[0]),
          statements: statementsFromAccessTier(pAcc[1])
        };
        if (roleEl) roleEl.value = 'Custom';
        if (accEl) accEl.value = 'custom|custom';
        STATE.draftRoleOverride = 'Custom';
        STATE.draftAccessOverride = 'custom|custom';
        STATE.userFormDirty = true;
        refreshRoleAndAccessMatrixUi(root);
        toast(`Cloned "${pDef.title || presetKey}" template into Custom Role`);
      });
    });
    root.querySelectorAll('[data-perm-tab]').forEach(btn => {
      const activateTab = () => {
        STATE.permMatrixTab = btn.getAttribute('data-perm-tab') || 'all';
        refreshRoleAndAccessMatrixUi(root);
      };
      btn.addEventListener('click', activateTab);
      if (btn.tagName !== 'BUTTON') {
        btn.addEventListener('keydown', ev => {
          if (ev.key === 'Enter' || ev.key === ' ') {
            ev.preventDefault();
            activateTab();
          }
        });
      }
    });
    root.querySelectorAll('[data-perm-bulk]').forEach(btn => {
      btn.addEventListener('click', () => {
        const [grp, mode] = String(btn.getAttribute('data-perm-bulk') || '').split(':');
        if (!grp || !PERM_CATALOG[grp]) return;
        if (!STATE.draftCustomPerms) {
          STATE.draftCustomPerms = cloneEffectivePermsToCustomDraft(getDraftSeatPreviewUser());
        }
        if (roleEl) roleEl.value = 'Custom';
        if (accEl) accEl.value = 'custom|custom';
        STATE.draftRoleOverride = 'Custom';
        STATE.draftAccessOverride = 'custom|custom';
        if (!STATE.draftCustomPerms[grp]) STATE.draftCustomPerms[grp] = {};
        const curSeat = getEditingSeatUser();
        const isSelf = !!(curSeat && STATE.users[STATE.activeUserIdx] && String(curSeat.id) === String(STATE.users[STATE.activeUserIdx].id));
        PERM_CATALOG[grp].forEach(it => {
          const itemId = it.id || it.key;
          if (grp === 'rights' && itemId === 'manage_users' && isSelf && (mode === 'off' || mode === 'none' || mode === 'readonly')) return;
          let nextVal = false;
          if (mode === 'all' || mode === 'on' || mode === 'full') nextVal = true;
          else if (mode === 'off' || mode === 'none') nextVal = false;
          else if (grp === 'rights' && mode === 'ops') nextVal = ['read_ops', 'enter_dispatch', 'enter_accounting', 'enter_master'].includes(itemId);
          else if (grp === 'rights' && mode === 'readonly') nextVal = ['read_ops', 'read_fin'].includes(itemId);
          else if (grp === 'unlocks' && mode === 'pricing') nextVal = ['unlock_unit_price', 'unlock_trans_price', 'unlock_qty_cap', 'unlock_uom'].includes(itemId);
          else if (grp === 'dashboards' && mode === 'ops') nextVal = ['dash_overview', 'dash_commercial', 'dash_plant_fleet', 'dash_expenses_vat'].includes(itemId);
          else if (grp === 'statements' && mode === 'ops') nextVal = ['stmt_digest_ops', 'stmt_counterparty', 'stmt_vouchers'].includes(itemId);
          STATE.draftCustomPerms[grp][itemId] = nextVal;
        });
        STATE.userFormDirty = true;
        refreshRoleAndAccessMatrixUi(root);
      });
    });
    root.querySelectorAll('[data-perm-cat][data-perm-id], [data-perm-group][data-perm-key]').forEach(cb => {
      cb.addEventListener('change', () => {
        const grp = cb.getAttribute('data-perm-cat') || cb.getAttribute('data-perm-group');
        const key = cb.getAttribute('data-perm-id') || cb.getAttribute('data-perm-key');
        if (!grp || !key) return;
        if (!STATE.draftCustomPerms) {
          STATE.draftCustomPerms = cloneEffectivePermsToCustomDraft(getDraftSeatPreviewUser());
        }
        if (roleEl && roleEl.value !== 'Custom') roleEl.value = 'Custom';
        if (accEl && accEl.value !== 'custom|custom') accEl.value = 'custom|custom';
        STATE.draftRoleOverride = 'Custom';
        STATE.draftAccessOverride = 'custom|custom';
        if (!STATE.draftCustomPerms[grp]) STATE.draftCustomPerms[grp] = {};
        STATE.draftCustomPerms[grp][key] = !!cb.checked;
        STATE.userFormDirty = true;
        refreshRoleAndAccessMatrixUi(root);
      });
    });
  }

  function wireSeatEditorActions(root) {
    if (!root) return;
    wireCompanyMultiSelect(root);
    wireRolePermSelector(root);
    wireRolePermissionsMatrix(root);
    const sel = root.querySelector('#nu_seat_select');
    if (sel) {
      sel.addEventListener('change', e => {
        selectSeatForEdit(e.target.value, { focusName: e.target.value === '__new__' });
      });
    }
    root.querySelectorAll('[data-pick-seat]').forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.getAttribute('data-pick-seat');
        selectSeatForEdit(target, { focusName: target === '__new__' });
      });
    });
    const prevBtn = root.querySelector('#nuPrevSeatBtn');
    if (prevBtn) {
      prevBtn.addEventListener('click', () => {
        if (!STATE.users.length) return;
        const cur = getEditingSeatUser();
        const idx = cur ? STATE.users.findIndex(x => String(x.id) === String(cur.id)) : 0;
        const nextIdx = (idx - 1 + STATE.users.length) % STATE.users.length;
        selectSeatForEdit(STATE.users[nextIdx].id);
      });
    }
    const nextBtn = root.querySelector('#nuNextSeatBtn');
    if (nextBtn) {
      nextBtn.addEventListener('click', () => {
        if (!STATE.users.length) return;
        const cur = getEditingSeatUser();
        const idx = cur ? STATE.users.findIndex(x => String(x.id) === String(cur.id)) : -1;
        const nextIdx = (idx + 1) % STATE.users.length;
        selectSeatForEdit(STATE.users[nextIdx].id);
      });
    }
    const newBlankBtn = root.querySelector('#nuNewBlankBtn');
    if (newBlankBtn) {
      newBlankBtn.addEventListener('click', () => {
        selectSeatForEdit('__new__', { focusName: true });
      });
    }
    const cancelBtn = root.querySelector('#cancelAddUserBtn');
    if (cancelBtn) {
      cancelBtn.addEventListener('click', () => {
        hideRoleHoverCard(true);
        STATE.showAddUserForm = false;
        STATE.userFormDirty = false;
        updateSeatEditorDom();
      });
    }
    const openInspBtn = root.querySelector('#openSeatInspectorBtn');
    if (openInspBtn) {
      openInspBtn.addEventListener('click', () => {
        const cur = getEditingSeatUser();
        selectSeatForEdit(cur ? cur.id : (STATE.users[0] && STATE.users[0].id));
      });
    }
    const openNewBarBtn = root.querySelector('#openNewSeatBarBtn');
    if (openNewBarBtn) {
      openNewBarBtn.addEventListener('click', () => {
        selectSeatForEdit('__new__', { focusName: true });
      });
    }
    const resetBtn = root.querySelector('#resetSeatEditBtn');
    if (resetBtn) {
      resetBtn.addEventListener('click', () => {
        STATE.userFormDirty = false;
        STATE.draftRoleOverride = null;
        STATE.draftCompaniesOverride = null;
        STATE.draftAccessOverride = null;
        const cur = getEditingSeatUser();
        STATE.draftCustomPerms = (cur && resolveCanonicalRoleKey(cur.role) === 'Custom')
          ? cloneEffectivePermsToCustomDraft(cur)
          : null;
        updateSeatEditorDom();
        toast('Reverted unsaved field changes');
      });
    }
    const saveBtn = root.querySelector('#saveNewUserBtn');
    if (saveBtn) {
      saveBtn.addEventListener('click', () => {
        saveSeatEditorForm();
      });
    }
    const checkRoleBtn = root.querySelector('#checkRolePermsBtn');
    if (checkRoleBtn) {
      checkRoleBtn.addEventListener('click', () => {
        hideRoleHoverCard(true);
        const roleWrap = root.querySelector('#nuRolePermsSelector');
        const rolePop = root.querySelector('#nuRolePopover');
        const roleTrig = root.querySelector('#nuRoleTrigger');
        if (roleWrap) roleWrap.classList.remove('open');
        if (rolePop) rolePop.hidden = true;
        if (roleTrig) roleTrig.setAttribute('aria-expanded', 'false');
        STATE.showRolePermMatrix = !STATE.showRolePermMatrix;
        if (!STATE.showRolePermMatrix) STATE.permMatrixTab = 'all';
        refreshRoleAndAccessMatrixUi(root);
        if (STATE.showRolePermMatrix) {
          const mw = root.querySelector('#rolePermissionsMatrixWrap');
          if (mw) mw.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      });
    }
    const roleSelectEl = root.querySelector('#nu_role');
    const accessSelectEl = root.querySelector('#nu_access');
    if (roleSelectEl) {
      roleSelectEl.addEventListener('change', () => {
        const nextRole = roleSelectEl.value || 'Entry';
        if (resolveCanonicalRoleKey(nextRole) === 'Custom') {
          if (!STATE.draftCustomPerms) {
            const prevRole = STATE.draftRoleOverride || (getEditingSeatUser() && getEditingSeatUser().role) || 'Entry';
            const prevAcc = (accessSelectEl && accessSelectEl.value && accessSelectEl.value !== 'custom|custom')
              ? accessSelectEl.value
              : ((ROLE_PRESETS[resolveCanonicalRoleKey(prevRole)] && ROLE_PRESETS[resolveCanonicalRoleKey(prevRole)].defaultAccess) || 'partial|partial');
            const [pPbi, pStmt] = prevAcc.split('|');
            STATE.draftCustomPerms = cloneEffectivePermsToCustomDraft({
              role: resolveCanonicalRoleKey(prevRole) === 'Custom' ? 'Entry' : prevRole,
              pbi_access: pPbi || 'partial',
              statements_access: pStmt || 'partial',
              custom_perms: getEditingSeatUser() ? getEditingSeatUser().custom_perms : '{}'
            });
          }
          if (accessSelectEl) accessSelectEl.value = 'custom|custom';
          STATE.showRolePermMatrix = true;
        } else {
          const preset = ROLE_PRESETS[resolveCanonicalRoleKey(nextRole)] || ROLE_PRESETS['Entry'];
          if (accessSelectEl) accessSelectEl.value = preset.defaultAccess || 'partial|partial';
          STATE.draftCustomPerms = null;
        }
        STATE.userFormDirty = true;
        refreshRoleAndAccessMatrixUi(root);
      });
    }
    if (accessSelectEl) {
      accessSelectEl.addEventListener('change', () => {
        const nextAcc = accessSelectEl.value || 'partial|partial';
        if (nextAcc === 'custom|custom') {
          if (!STATE.draftCustomPerms) {
            STATE.draftCustomPerms = cloneEffectivePermsToCustomDraft(getDraftSeatPreviewUser());
          }
          if (roleSelectEl && roleSelectEl.value !== 'Custom') roleSelectEl.value = 'Custom';
          STATE.showRolePermMatrix = true;
          STATE.permMatrixTab = 'all';
        } else if (roleSelectEl && resolveCanonicalRoleKey(roleSelectEl.value) === 'Custom') {
          if (!STATE.draftCustomPerms) {
            STATE.draftCustomPerms = cloneEffectivePermsToCustomDraft(getDraftSeatPreviewUser());
          }
          const [pbiT, stmtT] = nextAcc.split('|');
          STATE.draftCustomPerms.dashboards = dashboardsFromAccessTier(pbiT || 'partial');
          STATE.draftCustomPerms.statements = statementsFromAccessTier(stmtT || 'partial');
          accessSelectEl.value = 'custom|custom';
          toast('Applied dashboard & statement preset to Custom Role');
        }
        STATE.userFormDirty = true;
        refreshRoleAndAccessMatrixUi(root);
      });
    }
    root.querySelectorAll('[data-enrol-user]').forEach(btn => {
      btn.addEventListener('click', () => {
        const uidTarget = btn.getAttribute('data-enrol-user');
        const u = STATE.users.find(x => String(x.id) === String(uidTarget));
        if (!u) return;
        FACE_STATE.enrolUserId = u.id;
        syncEnrolBufferFromUser(u, true);
        updateEnrolStudioDom();
        const panel = $('faceEnrolPanel');
        if (panel) scrollWorkspaceTo(panel);
      });
    });
    root.querySelectorAll('#nu_name, #nu_email, #nu_pin, #nu_role, #nu_companies, #nu_access, #nu_auth_mode, #nu_book_scope, #nu_status').forEach(inp => {
      inp.addEventListener('input', () => { STATE.userFormDirty = true; });
      inp.addEventListener('change', () => { STATE.userFormDirty = true; });
    });
  }

  function wireUsersDirectoryActions(root) {
    if (!root) return;
    root.querySelectorAll('[data-role-hover-user]').forEach(el => {
      const uidTarget = el.getAttribute('data-role-hover-user');
      const openHover = () => {
        const u = STATE.users.find(x => String(x.id) === String(uidTarget));
        if (u) showRoleHoverCard(el, u, { seatName: u.full_name, userId: u.id, focusCat: 'all' });
      };
      el.addEventListener('mouseenter', openHover);
      el.addEventListener('focus', openHover);
      el.addEventListener('mouseleave', () => hideRoleHoverCard(false));
      el.addEventListener('blur', () => hideRoleHoverCard(false));
    });
    root.querySelectorAll('[data-edit-user]').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      hideRoleHoverCard(true);
      const uidTarget = btn.getAttribute('data-edit-user');
      selectSeatForEdit(uidTarget, { scroll: true });
    }));
    root.querySelectorAll('[data-check-perms]').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      hideRoleHoverCard(true);
      if (!isOwner()) return;
      const uidTarget = btn.getAttribute('data-check-perms');
      selectSeatForEdit(uidTarget, { scroll: true, openPerms: true, permTab: 'all' });
    }));
    root.querySelectorAll('tr[data-user-row]').forEach(row => row.addEventListener('click', e => {
      if (!isOwner()) return;
      if (e.target && e.target.closest('button, a, input, select')) return;
      const uidTarget = row.getAttribute('data-user-row');
      if (uidTarget) selectSeatForEdit(uidTarget, { scroll: false });
    }));
    root.querySelectorAll('[data-enrol-user]').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      const uidTarget = btn.getAttribute('data-enrol-user');
      const u = STATE.users.find(x => String(x.id) === String(uidTarget));
      if (!u) return;
      FACE_STATE.enrolUserId = u.id;
      syncEnrolBufferFromUser(u, true);
      updateEnrolStudioDom();
      const panel = $('faceEnrolPanel');
      if (panel) scrollWorkspaceTo(panel);
    }));
    root.querySelectorAll('[data-sim-user]').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      if (!isOwner()) return;
      const u = STATE.users[Number(btn.getAttribute('data-sim-user'))];
      if (u) performLogin(u.email, u.pin_code || '1111', { bypass2FA: true, method: 'Owner Impersonation' });
    }));
    root.querySelectorAll('[data-invite-user]').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      if (!isOwner()) return;
      const u = STATE.users[Number(btn.getAttribute('data-invite-user'))];
      if (!u) return;
      const inviteUrl = `${location.origin}${location.pathname}?email=${encodeURIComponent(u.email)}&pin=${encodeURIComponent(u.pin_code || '1111')}`;
      const done = () => { btn.textContent = '✓ Copied Link!'; setTimeout(() => { btn.textContent = 'Invite Link'; }, 2000); toast('Invite link copied — it carries the PIN, share it privately'); };
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(inviteUrl).then(done).catch(() => { window.prompt('Copy this invite link:', inviteUrl); });
      else window.prompt('Copy this invite link:', inviteUrl);
    }));
    root.querySelectorAll('[data-toggle-user]').forEach(btn => btn.addEventListener('click', async e => {
      e.stopPropagation();
      if (!isOwner()) return;
      const idx = Number(btn.getAttribute('data-toggle-user'));
      const u = STATE.users[idx];
      if (!u) return;
      if (idx === STATE.activeUserIdx) { toast('You cannot suspend your own seat', 'err'); return; }
      u.status = u.status === 'Suspended' ? 'Active' : 'Suspended';
      u.seat_updated_at = new Date().toISOString();
      saveLocalAuthAndRecords();
      updateSeatEditorDom();
      updateEnrolStudioDom();
      if (HAS_LOCAL_API) { try { await fetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: u }) }); } catch (_) { /* no server.py */ } }
      syncWithCloud(true);
      toast(`${u.full_name} ${u.status === 'Suspended' ? 'suspended' : 're-activated'}`);
    }));
  }

  // Surgical DOM updater for the Biometric Enrolment Studio: NEVER destroys <video id="enrolFaceVideo">
  function updateEnrolStudioDom() {
    const panel = $('faceEnrolPanel');
    if (!panel) {
      renderApp();
      return;
    }
    const enrolUser = enrolTargetUser();
    const enrolSavedSamples = userFaceSamples(enrolUser);
    const capCount = FACE_STATE.enrolCaptures.length;
    const poseComplete = capCount >= 3;
    const faceCount = STATE.users.filter(userHasFaceId).length;
    const uCount = STATE.users.length;

    const cockpitCountEl = $('enrolCockpitCount');
    if (cockpitCountEl) {
      cockpitCountEl.textContent = `${faceCount} / ${uCount} Enrolled`;
      cockpitCountEl.className = `cockpit-pill-val ${faceCount ? 'emerald' : 'amber'}`;
    }

    const hdrBadge = $('enrolHeaderBadge');
    if (hdrBadge) {
      hdrBadge.className = `enrol-seat-pill ${enrolSavedSamples.length ? 'enrolled' : 'pending'}`;
      hdrBadge.textContent = enrolSavedSamples.length
        ? `✓ ${enrolUser.full_name} · ${enrolSavedSamples.length}/3 Poses Saved`
        : `${enrolUser.full_name} · Not Enrolled`;
    }

    const ph = $('enrolCamPlaceholder');
    if (ph) ph.hidden = !!FACE_STATE.enrolCamActive;

    const hudDot = $('enrolHudDot');
    if (hudDot) hudDot.className = `enrol-hud-dot ${FACE_STATE.enrolCamActive ? 'live' : ''}`;
    const hudTel = $('enrolHudTelemetry');
    if (hudTel && !FACE_STATE.enrolCamActive) {
      hudTel.textContent = capCount ? `${capCount}/3 POSES SAVED` : 'CAMERA STANDBY';
    }

    const strip = $('enrolThumbStrip');
    if (strip) {
      strip.innerHTML = renderEnrolThumbStripHtml();
      wireEnrolPoseSlots(strip);
    }

    const guide = $('enrolPoseGuide');
    if (guide) {
      guide.className = `mfg-pose-guide ${poseComplete ? 'complete' : ''}`;
      guide.innerHTML = renderEnrolPoseGuideInnerHtml();
    }

    const statusBar = $('enrolStatusBar');
    if (statusBar) {
      statusBar.className = `enrol-status-bar ${FACE_STATE.enrolStatusCls || ''}`.trim();
      statusBar.textContent = FACE_STATE.enrolStatusText || '';
      statusBar.hidden = !FACE_STATE.enrolStatusText;
    }

    const startBtn = $('enrolStartCamBtn');
    if (startBtn) {
      startBtn.innerHTML = FACE_STATE.enrolCamActive
        ? `${ENROL_SVGS.stop}<span>Stop Camera</span>`
        : `${ENROL_SVGS.cam}<span>Start Camera</span>`;
    }
    const capBtn = $('enrolCaptureBtn');
    if (capBtn) {
      capBtn.disabled = false;
      capBtn.innerHTML = `${ENROL_SVGS.shutter}<span>${poseComplete ? 'Retake All 3 Poses' : `Capture Pose (${Math.min(capCount + 1, 3)}/3)`}</span>`;
    }
    const testBtn = $('enrolTestBtn');
    if (testBtn) {
      testBtn.innerHTML = `${ENROL_SVGS.scan}<span>${FACE_STATE.enrolTestActive ? 'Stop Test' : 'Test Recognition'}</span>`;
    }
    const clrBtn = $('enrolClearBtn');
    if (clrBtn) {
      clrBtn.disabled = !(enrolSavedSamples.length || capCount);
    }

    const sel = $('enrolUserSelect');
    if (sel) {
      Array.from(sel.options).forEach(opt => {
        const valStr = String(opt.value || '');
        if (valStr.startsWith('stfbio:')) {
          const stObj = buildKioskStaffTargetObject(valStr.slice(7));
          if (stObj) {
            const n = userFaceSamples(stObj).length;
            opt.textContent = `${stObj.full_name} · ${stObj.companies} (${n ? n + '/3 poses' : 'no Face ID'})`;
            opt.selected = String(enrolUser.id) === valStr;
          }
          return;
        }
        const u = STATE.users.find(x => String(x.id) === valStr);
        if (u) {
          const n = userFaceSamples(u).length;
          opt.textContent = `${u.full_name} (${n ? n + '/3 poses' : 'no Face ID'})`;
          opt.selected = String(u.id) === String(enrolUser.id);
        }
      });
    }

    const seatAuthSel = $('enrolSeatAuthModeSelect');
    if (seatAuthSel) {
      const wsModeObj = AUTH_MODE_OPTIONS.find(o => o.value === getWorkspaceAuthMode()) || AUTH_MODE_OPTIONS[1];
      const inheritOpt = seatAuthSel.querySelector('option[value="inherit"]');
      if (inheritOpt) inheritOpt.textContent = `Workspace Default (${wsModeObj.short})`;
      seatAuthSel.value = (!enrolUser.isKioskStaffOnly && enrolUser.auth_mode && enrolUser.auth_mode !== 'inherit') ? enrolUser.auth_mode : 'inherit';
      seatAuthSel.disabled = !(isOwner() && !enrolUser.isKioskStaffOnly);
    }

    const wsAuthSel = $('enrolAuthModeSelect');
    if (wsAuthSel) wsAuthSel.value = getWorkspaceAuthMode();

    const liveModeSel = $('enrolLivenessModeSelect');
    if (liveModeSel) liveModeSel.value = STATE.faceSettings.livenessMode || 'blink_or_turn';

    const framesSel = $('enrolConfirmFramesSelect');
    if (framesSel) framesSel.value = String(Math.max(3, Number(STATE.faceSettings.confirmFrames || 3)));

    const req2faCb = $('enrolRequire2faCb');
    if (req2faCb) req2faCb.checked = getWorkspaceAuthMode() === 'both';

    const liveCb = $('enrolLivenessCb');
    if (liveCb) liveCb.checked = STATE.faceSettings.liveness !== false;

    const tbody = $('usersDirectoryTbody');
    if (tbody) {
      tbody.innerHTML = renderUsersDirectoryRowsHtml();
      wireUsersDirectoryActions(tbody);
    }

    const calibWrap = $('enrolCalibWrap');
    if (calibWrap) {
      calibWrap.hidden = !FACE_STATE.calibReportHtml;
      calibWrap.innerHTML = FACE_STATE.calibReportHtml || '';
    }
  }

  async function enrolFaceTick() {
    if (STATE.view !== 'users' || !FACE_STATE.enrolCamActive) return;
    const videoEl = $('enrolFaceVideo');
    const overlayEl = $('enrolFaceOverlay');
    const hudTel = $('enrolHudTelemetry');
    const hudDot = $('enrolHudDot');
    if (videoEl && !FACE_STATE.enrolBusy && videoEl.readyState >= 2 && videoEl.videoWidth > 0) {
      FACE_STATE.enrolBusy = true;
      try {
        await ensureFaceModelsLoaded();
        const det = await window.Face.detectOne(videoEl, false);
        if (det && det.descriptor) {
          FACE_STATE.lastLiveEnrolDet = det;
          FACE_STATE.lastLiveEnrolAt = Date.now();
          if (window.Face.snapshot) FACE_STATE.lastLiveEnrolSnap = window.Face.snapshot(videoEl);
        }
        if (overlayEl && window.Face.drawOverlay) {
          const col = det && det.descriptor ? '#22c55e' : '#D9A54A';
          window.Face.drawOverlay(overlayEl, videoEl, det, col);
        }
        if (hudTel) {
          if (det && det.descriptor) {
            const pct = Math.round(Math.max(0.72, Number(det.score || det.detScore || 0.9)) * 100);
            const capLen = FACE_STATE.enrolCaptures.length;
            hudTel.textContent = capLen < 3
              ? `FACE LOCKED · ${pct}% (POSE ${capLen + 1}/3)`
              : `FACE DETECTED · ${pct}% (3/3 COMPLETE)`;
            if (hudDot) hudDot.className = 'enrol-hud-dot live locked';
          } else {
            hudTel.textContent = 'CENTER FACE IN FRAME';
            if (hudDot) hudDot.className = 'enrol-hud-dot live';
          }
        }
        // Hands-free auto-capture when camera is live and user holds pose in frame (< 0.5s per pose)
        if (
          det && det.descriptor && !det.multiple &&
          !navigator.webdriver && !window.__MFG_HEADLESS_TEST &&
          FACE_STATE.enrolCaptures.length < 3 &&
          Date.now() >= (FACE_STATE.nextAutoEnrolAt || 0)
        ) {
          const fracVal = det.faceSizeFrac != null ? det.faceSizeFrac : det.frac;
          const scoreVal = det.detScore != null ? det.detScore : det.score;
          if ((fracVal == null || fracVal >= Number(STATE.faceSettings.minFaceFrac || 0.14)) && (scoreVal == null || scoreVal >= 0.28)) {
            FACE_STATE.autoEnrolStreak = (FACE_STATE.autoEnrolStreak || 0) + 1;
            if (FACE_STATE.autoEnrolStreak >= 2) {
              FACE_STATE.autoEnrolStreak = 0;
              FACE_STATE.nextAutoEnrolAt = Date.now() + 850;
              triggerEnrolShutterFlash();
              await captureEnrolDescriptor(det, FACE_STATE.lastLiveEnrolSnap || '');
            }
          } else {
            FACE_STATE.autoEnrolStreak = 0;
          }
        } else if (!det || !det.descriptor) {
          FACE_STATE.autoEnrolStreak = 0;
        }
      } catch (_) {
        /* ignore transient frame error */
      } finally {
        FACE_STATE.enrolBusy = false;
      }
    }
    if (STATE.view === 'users' && FACE_STATE.enrolCamActive) {
      FACE_STATE.enrolLoopTimer = setTimeout(enrolFaceTick, 60);
    }
  }

  async function startEnrolCamera() {
    const ev = $('enrolFaceVideo');
    if (!ev) return false;
    FACE_STATE.enrolStatusText = '';
    FACE_STATE.enrolStatusCls = '';
    FACE_STATE.autoEnrolStreak = 0;
    FACE_STATE.nextAutoEnrolAt = Date.now() + 250;
    updateEnrolStudioDom();
    const modelP = ensureFaceModelsLoaded().catch(() => {});
    const ok = await startFaceCamera(ev);
    await modelP;
    FACE_STATE.enrolCamActive = ok;
    if (ok) {
      for (let i = 0; i < 12; i++) {
        if (ev.readyState >= 2 && ev.videoWidth > 0) break;
        await new Promise(r => setTimeout(r, 25));
      }
      if (FACE_STATE.enrolLoopTimer) clearTimeout(FACE_STATE.enrolLoopTimer);
      FACE_STATE.enrolLoopTimer = setTimeout(enrolFaceTick, 15);
      FACE_STATE.enrolStatusText = '';
      FACE_STATE.enrolStatusCls = '';
    } else {
      FACE_STATE.enrolStatusText = 'Camera unavailable or permission denied on this device.';
      FACE_STATE.enrolStatusCls = 'warn';
    }
    updateEnrolStudioDom();
    return ok;
  }

  async function persistStaffBiometricEntryNow(staffKey, entryObj) {
    if (!staffKey || !entryObj) return;
    if (HAS_LOCAL_API) {
      try {
        await fetch('./api/staff_biometrics', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ key: staffKey, entry: entryObj })
        });
      } catch (_) {}
    }
  }

  async function persistTargetFaceNow(target) {
    if (!target) return;
    const nowIso = new Date().toISOString();
    const samples = FACE_STATE.enrolCaptures.slice(0, 5);
    const thumbs = FACE_STATE.enrolThumbs.slice(0, 3);
    target.face_samples = samples;
    target.face_thumbs = thumbs;
    target.face_required = samples.length > 0;
    target.face_cleared = samples.length === 0;
    target.face_updated_at = nowIso;
    FACE_STATE.enrolLoadedForUserId = String(target.id);

    let bioKey = '';
    let bioEntry = null;
    if (target.isKioskStaffOnly) {
      bioKey = target.staffKey || norm(target.full_name);
    } else if (!isGenericTerminalSeat(target) && norm(target.full_name)) {
      bioKey = norm(target.full_name);
    }
    if (bioKey) {
      if (!STATE.staffBiometrics || typeof STATE.staffBiometrics !== 'object') STATE.staffBiometrics = {};
      bioEntry = Object.assign({}, STATE.staffBiometrics[bioKey] || {}, {
        name: target.full_name,
        company: target.companies || defaultEntryCompany(),
        role: target.role || 'Active Staff',
        face_samples: samples,
        face_thumbs: thumbs,
        face_cleared: samples.length === 0,
        face_updated_at: nowIso,
        updated_at: nowIso
      });
      STATE.staffBiometrics[bioKey] = bioEntry;
    }

    saveLocalAuthAndRecords();
    const syncTask = async () => {
      if (!target.isKioskStaffOnly && HAS_LOCAL_API) {
        try { await fetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: target }) }); } catch (_) {}
      }
      if (bioKey && bioEntry) await persistStaffBiometricEntryNow(bioKey, bioEntry);
      await syncWithCloud(true);
    };
    if (navigator.webdriver || window.__MFG_HEADLESS_TEST) {
      await syncTask();
    } else {
      Promise.resolve().then(syncTask).catch(() => {});
    }
  }

  async function captureEnrolDescriptor(syntheticDet, syntheticThumb, slotOverride) {
    const target = enrolTargetUser();
    if (!target) return { ok: false, reason: 'no-user' };

    // Always auto-enable biometric consent when the user initiates capture so it never blocks storing their photo
    if (!FACE_STATE.enrolConsent) {
      FACE_STATE.enrolConsent = true;
      const cb = $('enrolConsentCb');
      if (cb) cb.checked = true;
    }

    const isSlotRetake = typeof slotOverride === 'number' && slotOverride >= 0 && slotOverride < 3;
    if (!isSlotRetake && FACE_STATE.enrolCaptures.length >= 3) {
      if (syntheticDet) {
        FACE_STATE.enrolStatusText = 'All 3 poses are already captured and stored.';
        FACE_STATE.enrolStatusCls = 'ok';
        updateEnrolStudioDom();
        return { ok: false, reason: 'already-3' };
      }
      // Interactive UI click on "Retake All 3 Poses": start a fresh 3-pose capture sequence
      FACE_STATE.enrolCaptures = [];
      FACE_STATE.enrolThumbs = [];
      FACE_STATE.nextAutoEnrolAt = Date.now() + 850;
    }

    let det = syntheticDet || null;
    let thumb = syntheticThumb || '';
    if (!det) {
      let videoEl = $('enrolFaceVideo');
      if (!FACE_STATE.enrolCamActive || !streamAlive() || !videoEl || videoEl.readyState < 2) {
        const started = await startEnrolCamera();
        videoEl = $('enrolFaceVideo');
        if (!started || !videoEl || videoEl.readyState < 2) {
          FACE_STATE.enrolStatusText = 'Camera could not start — grant camera permission in your browser address bar.';
          FACE_STATE.enrolStatusCls = 'warn';
          updateEnrolStudioDom();
          return { ok: false, reason: 'no-camera' };
        }
      }
      triggerEnrolShutterFlash();
      FACE_STATE.nextAutoEnrolAt = Date.now() + 900;
      // Instant 0ms fast-path: reuse fresh live detection from enrolFaceTick if < 1600ms old
      if (FACE_STATE.lastLiveEnrolDet && FACE_STATE.lastLiveEnrolDet.descriptor && (Date.now() - (FACE_STATE.lastLiveEnrolAt || 0)) < 1600) {
        det = FACE_STATE.lastLiveEnrolDet;
        thumb = (window.Face && window.Face.snapshot && window.Face.snapshot(videoEl)) || FACE_STATE.lastLiveEnrolSnap || '';
      } else {
        await ensureFaceModelsLoaded();
        // Pass allowCropFallback=true so backlit webcam frames still extract a 128-d descriptor + snapshot
        det = await window.Face.detectOne(videoEl, true);
        if ((!det || !det.descriptor) && FACE_STATE.lastLiveEnrolDet && (Date.now() - FACE_STATE.lastLiveEnrolAt) < 3000) {
          det = FACE_STATE.lastLiveEnrolDet;
        }
        if (window.Face.snapshot) {
          thumb = window.Face.snapshot(videoEl) || FACE_STATE.lastLiveEnrolSnap || '';
        }
      }
    }

    if (!det || !det.descriptor) {
      FACE_STATE.enrolStatusText = 'No face detected — position your face inside the reticle and click Capture Pose.';
      FACE_STATE.enrolStatusCls = 'crit';
      updateEnrolStudioDom();
      return { ok: false, reason: 'no-face' };
    }
    if (det.multiple) {
      FACE_STATE.enrolStatusText = 'Multiple faces in frame — only one person may be in view during enrolment.';
      FACE_STATE.enrolStatusCls = 'crit';
      updateEnrolStudioDom();
      return { ok: false, reason: 'multiple' };
    }
    const scoreVal = det.detScore != null ? det.detScore : det.score;
    if (scoreVal != null && scoreVal < 0.24) {
      FACE_STATE.enrolStatusText = `Face confidence too low (${Math.round(scoreVal * 100)}%) — face the camera directly.`;
      FACE_STATE.enrolStatusCls = 'warn';
      updateEnrolStudioDom();
      return { ok: false, reason: 'low-score' };
    }
    const fracVal = det.faceSizeFrac != null ? det.faceSizeFrac : det.frac;
    if (fracVal != null && fracVal < Number(STATE.faceSettings.minFaceFrac || 0.14)) {
      FACE_STATE.enrolStatusText = 'Move closer so your face fills the biometric reticle.';
      FACE_STATE.enrolStatusCls = 'warn';
      updateEnrolStudioDom();
      return { ok: false, reason: 'too-small' };
    }

    // Duplicate-person guard: refuse if this face already belongs to a DIFFERENT enrolled seat or staff member
    const others = usableFaces(null, { includeKioskStaff: true }).filter(x => {
      if (target.email && x.email && norm(x.email) === norm(target.email)) return false;
      if (norm(x.name) === norm(target.full_name)) return false;
      return true;
    });
    if (others.length && window.Face && window.Face.match) {
      const dupMatch = window.Face.match(det.descriptor, others);
      const thr = Number(STATE.faceSettings.threshold || 0.50);
      if (dupMatch.best && dupMatch.bestDist <= thr) {
        FACE_STATE.enrolStatusText = `Refused: this face is already enrolled under ${dupMatch.best.name} (d=${dupMatch.bestDist.toFixed(3)} ≤ τ=${thr.toFixed(2)}). Each person must have a distinct Face ID.`;
        FACE_STATE.enrolStatusCls = 'crit';
        if (STATE.faceSettings.sound && window.Face.Sound) window.Face.Sound.playError();
        updateEnrolStudioDom();
        return { ok: false, reason: 'duplicate-person', other: dupMatch.best.email || dupMatch.best.name, dist: dupMatch.bestDist };
      }
    }

    const vecArr = Array.from(det.descriptor);
    let targetSlot = FACE_STATE.enrolCaptures.length;
    if (isSlotRetake && slotOverride < FACE_STATE.enrolCaptures.length) {
      targetSlot = slotOverride;
      FACE_STATE.enrolCaptures[targetSlot] = vecArr;
      FACE_STATE.enrolThumbs[targetSlot] = thumb || FACE_STATE.enrolThumbs[targetSlot] || '';
    } else {
      FACE_STATE.enrolCaptures.push(vecArr);
      FACE_STATE.enrolThumbs.push(thumb || '');
      targetSlot = FACE_STATE.enrolCaptures.length - 1;
    }

    const count = FACE_STATE.enrolCaptures.length;
    if (STATE.faceSettings.sound && window.Face && window.Face.Sound) {
      window.Face.Sound.play(count >= 3 ? 'ok' : 'capture');
    }

    // Auto-persist immediately on every captured pose
    await persistTargetFaceNow(target);

    FACE_STATE.enrolStatusText = '';
    FACE_STATE.enrolStatusCls = '';
    updateEnrolStudioDom();
    if (!syntheticDet) {
      toast(count >= 3 ? `All 3 Face ID poses saved for ${target.full_name}` : `Pose ${count}/3 saved`);
    }
    return { ok: true, count, slot: targetSlot };
  }

  async function saveFaceEnrolment() {
    const target = enrolTargetUser();
    if (!target || !FACE_STATE.enrolCaptures.length) return false;
    await persistTargetFaceNow(target);
    FACE_STATE.enrolStatusText = '';
    FACE_STATE.enrolStatusCls = '';
    updateEnrolStudioDom();
    toast(`Face ID saved & synced for ${target.full_name}`);
    return true;
  }

  async function clearFaceEnrolment() {
    const target = enrolTargetUser();
    if (!target) return false;
    const nowIso = new Date().toISOString();
    FACE_STATE.enrolCaptures = [];
    FACE_STATE.enrolThumbs = [];
    target.face_samples = [];
    target.face_thumbs = [];
    target.face_required = false;
    target.face_cleared = true;
    target.face_updated_at = nowIso;
    FACE_STATE.enrolLoadedForUserId = String(target.id);
    FACE_STATE.enrolStatusText = '';
    FACE_STATE.enrolStatusCls = '';

    let bioKey = '';
    let bioEntry = null;
    if (target.isKioskStaffOnly) {
      bioKey = target.staffKey || norm(target.full_name);
    } else if (!isGenericTerminalSeat(target) && norm(target.full_name)) {
      bioKey = norm(target.full_name);
    }
    if (bioKey && STATE.staffBiometrics && typeof STATE.staffBiometrics === 'object') {
      bioEntry = Object.assign({}, STATE.staffBiometrics[bioKey] || {}, {
        name: target.full_name,
        face_samples: [],
        face_thumbs: [],
        face_cleared: true,
        face_updated_at: nowIso,
        updated_at: nowIso
      });
      STATE.staffBiometrics[bioKey] = bioEntry;
    }

    saveLocalAuthAndRecords();
    updateEnrolStudioDom();
    toast(`Cleared Face ID for ${target.full_name}`);
    if (!target.isKioskStaffOnly && HAS_LOCAL_API) {
      try { await fetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: target }) }); } catch (_) {}
    }
    if (bioKey && bioEntry) await persistStaffBiometricEntryNow(bioKey, bioEntry);
    await syncWithCloud(true);
    return true;
  }

  function runCalibrationReport() {
    const target = enrolTargetUser();
    const list = usableFaces(target);
    if (!window.Face || !window.Face.calibration) return null;
    const cal = window.Face.calibration(list);
    if (!list.length) {
      FACE_STATE.calibReportHtml = `<div class="enrol-calib-box"><small>No enrolled seats yet — capture 3 poses for at least 1 seat to compute intra-seat spread and inter-seat Euclidean separation.</small></div>`;
    } else {
      const rowsHtml = cal.perEmp.map(e => `
        <tr>
          <td><strong>${esc(e.name)}</strong></td>
          <td class="r mono">${e.samples}</td>
          <td class="r mono">${e.spread.toFixed(3)}</td>
          <td><span class="badge ${e.spread <= 0.38 ? 'badge-ok' : 'badge-warn'}">${e.spread <= 0.38 ? 'Tight Cluster' : 'Wide (Retake)'}</span></td>
        </tr>
      `).join('');
      const pairsHtml = cal.pairs.slice(0, 5).map(p => `
        <tr>
          <td>${esc(p.a)} ↔ ${esc(p.b)}</td>
          <td class="r mono"><strong>${p.d.toFixed(3)}</strong></td>
          <td><span class="badge ${p.d >= 0.55 ? 'badge-ok' : 'badge-warn'}">${p.d >= 0.55 ? 'Well Separated' : 'Close Pair'}</span></td>
        </tr>
      `).join('');
      FACE_STATE.calibReportHtml = `
        <div class="enrol-calib-box">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex-wrap:wrap;gap:6px">
            <strong>128-d Euclidean Calibration Matrix (${list.length} Enrolled Seat${list.length === 1 ? '' : 's'})</strong>
            ${cal.recommendedThreshold ? `<span class="badge badge-info">Recommended τ = ${cal.recommendedThreshold.toFixed(2)}</span>` : `<span class="badge badge-info">Active τ = ${Number(STATE.faceSettings.threshold).toFixed(2)}</span>`}
          </div>
          <div class="table-wrap">
            <table class="ledger-table">
              <thead><tr><th>Enrolled Seat</th><th class="r">Poses</th><th class="r">Max Intra-Seat Spread (d)</th><th>Quality</th></tr></thead>
              <tbody>${rowsHtml}</tbody>
            </table>
          </div>
          ${cal.pairs.length ? `
            <div class="table-wrap" style="margin-top:8px">
              <table class="ledger-table">
                <thead><tr><th>Closest Seat Pair</th><th class="r">Min Inter-Seat Distance (d)</th><th>Separation</th></tr></thead>
                <tbody>${pairsHtml}</tbody>
              </table>
            </div>
          ` : ''}
        </div>
      `;
    }
    updateEnrolStudioDom();
    return cal;
  }

