  function getInitials(name) {
    return String(name || 'IS').split(/\s+/).filter(Boolean).slice(0, 2).map(p => p[0].toUpperCase()).join('');
  }

  function selectCompanyScope(coKey, closePopover = true) {
    if (!coKey) return;
    STATE.company = coKey;
    STATE.shown = {};
    STATE.pbiTablePage = {};
    saveFilterState();
    if (closePopover) {
      const switchEl = $('companySwitch');
      const popEl = $('companySwitchPopover');
      const trigEl = $('companySwitchTrigger');
      if (switchEl) switchEl.classList.remove('open');
      if (popEl) popEl.hidden = true;
      if (trigEl) trigEl.setAttribute('aria-expanded', 'false');
    }
    renderApp();
  }

  function syncCompanySwitchUi() {
    const switchEl = $('companySwitch');
    if (!switchEl) return;
    const user = activeUser();
    const allowedCos = getAllowedCompanyKeys(user);
    const allowedNames = allowedCompanyNames(user);
    const allowedNameSet = new Set(allowedNames.map(n => n.toLowerCase()));
    const catalog = getCompanyCatalog();
    const indGroups = getIndustryGroups(catalog);
    const listEl = $('companySwitchList') || switchEl;

    // Ensure every company in catalog or allowedCos has an .entity-btn inside #companySwitchList
    const desiredKeys = ['manufacturing-group'];
    if (indGroups.length >= 2) {
      indGroups.forEach(g => {
        const indKey = `industry:${g.id}`;
        if (allowedCos.includes(indKey)) desiredKeys.push(indKey);
      });
    }
    catalog.forEach(c => { if (!desiredKeys.includes(c.key)) desiredKeys.push(c.key); });
    allowedCos.forEach(k => { if (!desiredKeys.includes(k)) desiredKeys.push(k); });

    desiredKeys.forEach(coKey => {
      let btn = switchEl.querySelector(`.entity-btn[data-company="${coKey}"]`);
      if (!btn) {
        btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'entity-btn';
        btn.setAttribute('data-company', coKey);
        if (coKey.startsWith('industry:')) {
          btn.textContent = `All ${coKey.slice(9)}`;
        } else {
          btn.textContent = COMPANY_BU_MATCH[coKey] || coKey;
        }
        btn.addEventListener('click', e => {
          e.stopPropagation();
          selectCompanyScope(coKey, true);
        });
        listEl.appendChild(btn);
      }
    });

    // Allowed industries for this user
    const allowedIndGroups = indGroups.map(g => ({
      ...g,
      permittedCos: g.companies.filter(c => allowedNameSet.has(c.name.toLowerCase()))
    })).filter(g => g.permittedCos.length > 0);
    const allowedIndCount = Math.max(1, allowedIndGroups.length);
    const firstAllowedInd = allowedIndGroups[0] ? allowedIndGroups[0].id : 'Manufacturing';

    if (STATE.companySwitchIndFilter !== 'all' && !allowedIndGroups.some(g => g.id === STATE.companySwitchIndFilter)) {
      STATE.companySwitchIndFilter = 'all';
    }

    // Populate Left Column: Industry Tabs (#companySwitchIndustryList)
    const indListEl = $('companySwitchIndustryList');
    if (indListEl) {
      const indTabsHtml = [
        `<button type="button" class="ep-ind-tab ${STATE.companySwitchIndFilter === 'all' ? 'active' : ''}" data-ep-ind="all">
          <span class="ep-ind-tab-name">All Industries</span>
          <em class="ep-ind-tab-cnt">${allowedNames.length}</em>
        </button>`
      ].concat(allowedIndGroups.map(g => `
        <button type="button" class="ep-ind-tab ${STATE.companySwitchIndFilter === g.id ? 'active' : ''}" data-ep-ind="${esc(g.id)}" title="${esc(g.label)} (${g.permittedCos.length} permitted)">
          <span class="ep-ind-tab-name">${esc(g.label)}</span>
          <em class="ep-ind-tab-cnt">${g.permittedCos.length}</em>
        </button>
      `)).join('');
      indListEl.innerHTML = indTabsHtml;
      indListEl.querySelectorAll('[data-ep-ind]').forEach(tabBtn => {
        tabBtn.addEventListener('click', e => {
          e.stopPropagation();
          const pickedInd = tabBtn.getAttribute('data-ep-ind') || 'all';
          STATE.companySwitchIndFilter = pickedInd;
          syncCompanySwitchUi();
        });
      });
    }

    const searchInp = $('companySwitchSearch');
    const q = searchInp ? String(searchInp.value || '').trim().toLowerCase() : '';
    const indFilter = STATE.companySwitchIndFilter || 'all';

    let visibleBtnCount = 0;
    switchEl.querySelectorAll('.entity-btn').forEach(btn => {
      const key = btn.getAttribute('data-company') || '';
      const isAllowed = allowedCos.includes(key);
      if (key === 'manufacturing-group') {
        btn.textContent = allowedNames.length >= catalog.length
          ? `All Group (${allowedNames.length})`
          : `All Assigned (${allowedNames.length})`;
        btn.setAttribute('data-ind', 'all');
        btn.setAttribute('data-ind-tag', allowedIndCount > 1 ? `${allowedIndCount} Ind` : firstAllowedInd);
        btn.setAttribute('data-co-search', `all group assigned consolidated ${allowedNames.join(' ').toLowerCase()}`);
      } else if (key.startsWith('industry:')) {
        const indName = key.slice(9);
        const grp = allowedIndGroups.find(g => g.id === indName);
        const cnt = grp ? grp.permittedCos.length : 0;
        btn.textContent = `All ${indName} (${cnt})`;
        btn.setAttribute('data-ind', indName);
        btn.setAttribute('data-ind-tag', 'Industry');
        btn.setAttribute('data-co-search', `all ${indName.toLowerCase()} industry consolidated`);
      } else {
        const coMeta = catalog.find(c => c.key === key);
        const indName = (coMeta && coMeta.industry) || COMPANY_INDUSTRY_BY_KEY[key] || 'Manufacturing';
        btn.setAttribute('data-ind', indName);
        btn.setAttribute('data-ind-tag', indName);
        btn.setAttribute('data-co-search', ((coMeta ? `${coMeta.name} ${coMeta.label} ${coMeta.sector} ${indName} ${coMeta.key}` : `${btn.textContent} ${key}`)).toLowerCase());
      }

      if (!isAllowed) {
        btn.hidden = true;
      } else {
        const btnInd = btn.getAttribute('data-ind') || 'Manufacturing';
        const hay = btn.getAttribute('data-co-search') || btn.textContent.toLowerCase();
        const matchInd = indFilter === 'all' || key === 'manufacturing-group' || btnInd === indFilter;
        const matchQ = !q || hay.includes(q);
        btn.hidden = !(matchInd && matchQ);
        if (!btn.hidden) visibleBtnCount += 1;
      }
      btn.classList.toggle('active', key === STATE.company);
    });

    // Update Trigger Box 2-Segment Labels (IND + CO)
    const indTextEl = $('companySwitchIndText');
    const coTextEl = $('companySwitchCoText');
    let trigInd = firstAllowedInd;
    let trigCo = `All Group (${allowedNames.length})`;
    if (STATE.company === 'manufacturing-group') {
      trigInd = allowedIndCount > 1 ? `All (${allowedIndCount} Ind)` : firstAllowedInd;
      trigCo = allowedNames.length >= catalog.length
        ? `All Group (${allowedNames.length})`
        : `All Assigned (${allowedNames.length})`;
    } else if (String(STATE.company || '').startsWith('industry:')) {
      const indName = String(STATE.company).slice(9);
      const grp = allowedIndGroups.find(g => g.id === indName);
      const cnt = grp ? grp.permittedCos.length : 0;
      trigInd = indName;
      trigCo = `All ${indName.split(' ')[0]} (${cnt})`;
    } else {
      const coMeta = catalog.find(c => c.key === STATE.company);
      trigInd = (coMeta && coMeta.industry) || COMPANY_INDUSTRY_BY_KEY[STATE.company] || 'Manufacturing';
      trigCo = (coMeta && coMeta.name) || COMPANY_BU_MATCH[STATE.company] || STATE.company;
    }
    if (indTextEl) { indTextEl.textContent = trigInd; indTextEl.title = trigInd; }
    if (coTextEl) { coTextEl.textContent = trigCo; coTextEl.title = trigCo; }

    const coHeadEl = $('companySwitchCoHead');
    if (coHeadEl) {
      coHeadEl.textContent = indFilter === 'all'
        ? `Operating Companies (${allowedNames.length} Permitted)`
        : `${indFilter} (${(allowedIndGroups.find(g => g.id === indFilter) || { permittedCos: [] }).permittedCos.length} Permitted)`;
    }
    const footEl = $('companySwitchFootStatus');
    if (footEl) {
      footEl.textContent = q
        ? `Showing ${visibleBtnCount} matching options · ${allowedNames.length} companies across ${allowedIndCount} ${allowedIndCount === 1 ? 'industry' : 'industries'}`
        : `${allowedIndCount} ${allowedIndCount === 1 ? 'Industry' : 'Industries'} · ${allowedNames.length} ${allowedNames.length === 1 ? 'Company' : 'Companies'} Permitted (RLS)`;
    }
    const demoBtn = $('companySwitchScalePreviewBtn');
    if (demoBtn) {
      demoBtn.hidden = !isOwner(user);
      demoBtn.classList.toggle('active', !!STATE.enterpriseScalePreview);
      demoBtn.innerHTML = STATE.enterpriseScalePreview
        ? `${ic('check_circle')} 10 Ind × 150 Co Preview (Reset to 3)`
        : `${ic('bolt')} Preview 10 Ind × 150 Co`;
    }
    const offBtn = $('officialScopeToggleBtn');
    if (offBtn) {
      const showOffToggle = isOwner(user) && !STATE.demoVisitor && getUserBookScope(user) !== 'official';
      const offOn = isOfficialScopeActive(user);
      offBtn.hidden = !showOffToggle;
      offBtn.classList.toggle('active', offOn);
      offBtn.innerHTML = offOn ? `${ic('shield')} Official Books (11% VAT)` : `${ic('shield')} All Books`;
    }
  }

  function wireCompanySwitch() {
    const switchEl = $('companySwitch');
    if (!switchEl || switchEl.dataset.pickerWired === '1') return;
    switchEl.dataset.pickerWired = '1';
    const trigBtn = $('companySwitchTrigger');
    const popEl = $('companySwitchPopover');
    const searchEl = $('companySwitchSearch');
    const allBtn = $('companySwitchSelectAllBtn');
    const demoBtn = $('companySwitchScalePreviewBtn');
    const offBtn = $('officialScopeToggleBtn');
    const doneBtn = $('companySwitchDoneBtn');

    const setOpen = (open) => {
      switchEl.classList.toggle('open', !!open);
      if (popEl) popEl.hidden = !open;
      if (trigBtn) trigBtn.setAttribute('aria-expanded', String(!!open));
      if (open) {
        syncCompanySwitchUi();
        if (searchEl) setTimeout(() => { try { searchEl.focus({ preventScroll: true }); } catch (_) {} }, 20);
      } else if (searchEl && searchEl.value) {
        searchEl.value = '';
        STATE.companySwitchIndFilter = 'all';
        syncCompanySwitchUi();
      }
    };

    if (trigBtn) {
      trigBtn.addEventListener('click', e => {
        e.stopPropagation();
        setOpen(popEl ? popEl.hidden : !switchEl.classList.contains('open'));
      });
    }
    if (doneBtn) {
      doneBtn.addEventListener('click', e => {
        e.stopPropagation();
        setOpen(false);
      });
    }
    if (searchEl) {
      searchEl.addEventListener('input', () => {
        syncCompanySwitchUi();
      });
    }
    if (allBtn) {
      allBtn.addEventListener('click', e => {
        e.stopPropagation();
        STATE.companySwitchIndFilter = 'all';
        if (searchEl) searchEl.value = '';
        const allowedCos = getAllowedCompanyKeys(activeUser());
        selectCompanyScope(allowedCos[0] || 'manufacturing-group', true);
      });
    }
    if (demoBtn) {
      demoBtn.addEventListener('click', e => {
        e.stopPropagation();
        STATE.enterpriseScalePreview = !STATE.enterpriseScalePreview;
        STATE.enterprisePreviewCompanies = STATE.enterpriseScalePreview ? buildEnterprisePreviewCatalog() : [];
        STATE.companySwitchIndFilter = 'all';
        if (!STATE.enterpriseScalePreview && !['manufacturing-group', 'wtc', 'bbconstruction', 'lionstransport'].includes(STATE.company)) {
          STATE.company = 'manufacturing-group';
        }
        applyUserRlsAndPermissions();
        if (STATE.view === 'users') {
          updateSeatEditorDom();
        }
        toast(STATE.enterpriseScalePreview
          ? '⚡ Enterprise Scale Preview active: 10 Industries × 15 Companies (150 Companies) loaded'
          : 'Restored live 3-company Manufacturing catalog (WTC · BBConstruction · Lions Transport)');
      });
    }
    if (offBtn) {
      offBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (!isOwner() || STATE.demoVisitor || getUserBookScope() === 'official') return;
        STATE.officialBookScope = !STATE.officialBookScope;
        STATE.shown = {};
        STATE.pbiTablePage = {};
        applyUserRlsAndPermissions();
        renderApp();
        toast(STATE.officialBookScope
          ? 'Official Books active: scoped strictly to 11% VAT-invoiced activity'
          : 'All Books active: showing complete operational ledger');
      });
    }
    switchEl.querySelectorAll('.entity-btn').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        selectCompanyScope(btn.getAttribute('data-company'), true);
      });
    });
    document.addEventListener('mousedown', e => {
      if (switchEl.classList.contains('open') && (!e.target || !e.target.closest('#companySwitch'))) {
        setOpen(false);
      }
    });
  }

  function applyUserRlsAndPermissions() {
    const user = activeUser();
    if (STATE._lastRlsUserId !== String(user && user.id || '')) {
      STATE._lastRlsUserId = String(user && user.id || '');
      STATE.companySwitchIndFilter = 'all';
      const searchInp = $('companySwitchSearch');
      if (searchInp) searchInp.value = '';
    }
    const allowedCos = getAllowedCompanyKeys(user);
    const allowedNames = allowedCompanyNames(user);
    const catalog = getCompanyCatalog();
    STATE.allowedCompanyNames = allowedNames;
    STATE._officialScopeActive = isOfficialScopeActive(user);
    STATE._canSeeTaxBreakdown = canSeeTaxBreakdown(user);
    STATE.isOfficialRecord = isOfficialRecord;
    STATE.canAccessRdlReport = r => canAccessRdlReport(r, user);

    if (!allowedCos.includes(STATE.company)) STATE.company = allowedCos[0];
    syncCompanySwitchUi();

    COMPANY_LABELS['manufacturing-group'] = allowedNames.length >= catalog.length
      ? `All Manufacturing Group (${allowedNames.slice(0, 3).join(' · ')}${allowedNames.length > 3 ? ' +' + (allowedNames.length - 3) + ' more' : ''})`
      : `Assigned Entities (${allowedNames.slice(0, 3).join(' · ')}${allowedNames.length > 3 ? ' +' + (allowedNames.length - 3) + ' more' : ''})`;
    COMPANY_MOBILE_LABELS['manufacturing-group'] = allowedNames.length >= catalog.length
      ? `All Group (${allowedNames.length})`
      : `All Assigned (${allowedNames.length})`;

    document.querySelectorAll('#sidebarNav .nav-item').forEach(btn => {
      const hubId = btn.getAttribute('data-hub') || btn.getAttribute('data-view');
      btn.hidden = !canViewHub(hubId, user);
    });
    document.querySelectorAll('#sidebarNav .grp').forEach(grpEl => {
      let sib = grpEl.nextElementSibling, anyVisible = false;
      while (sib && !sib.classList.contains('grp')) {
        if (sib.classList.contains('nav-item') && !sib.hidden) { anyVisible = true; break; }
        sib = sib.nextElementSibling;
      }
      grpEl.hidden = !anyVisible;
    });
    const sysBar = $('railSystemBar');
    if (sysBar) {
      let anySysVisible = false;
      sysBar.querySelectorAll('.rail-sys-btn').forEach(btn => {
        const hubId = btn.getAttribute('data-hub') || btn.getAttribute('data-view');
        const vis = canViewHub(hubId, user);
        btn.hidden = !vis;
        if (vis) anySysVisible = true;
      });
      sysBar.hidden = !anySysVisible;
    }
    if (!canViewView(STATE.view, user)) STATE.view = defaultViewFor(user);

    if (STATE.pbiPage && !canAccessPbiPage(STATE.pbiPage, user)) {
      STATE.pbiPage = 'p01_overview';
    }
    if (STATE.activeTableKey && !canAccessTable(STATE.activeTableKey, user)) {
      STATE.activeTableKey = 'sales_tickets';
    }
    if (window.MFG_RDL && Array.isArray(window.MFG_RDL.RDL_CATALOG)) {
      const permittedRdl = window.MFG_RDL.RDL_CATALOG.filter(r => canAccessRdlReport(r, user));
      if (permittedRdl.length && !permittedRdl.some(r => String(r.id || r.code) === String(STATE.activeStatement))) {
        STATE.activeStatement = permittedRdl[0].id || permittedRdl[0].code;
      }
    }

    const newBtn = $('newEntryBtn');
    if (newBtn) newBtn.hidden = !canEnterAny(user);

    const avEl = $('railUserAvatar'), nmEl = $('railUserName'), rlEl = $('activeRoleBadge'), scEl = $('railRlsScope');
    if (avEl) avEl.textContent = getInitials(user.full_name);
    if (nmEl) { nmEl.textContent = user.full_name; nmEl.setAttribute('data-full-text', user.full_name); nmEl.removeAttribute('title'); }
    if (rlEl) { rlEl.textContent = user.role; rlEl.setAttribute('data-full-text', user.role); rlEl.removeAttribute('title'); }
    if (scEl) {
      const shortNames = allowedNames.map(n => n.replace(/BBConstruction/g, 'BBC').replace(/Lions Transport/g, 'Lions'));
      const fullScope = allowedNames.join(' · ');
      scEl.textContent = shortNames.length <= 3
        ? shortNames.join(', ')
        : `${shortNames.slice(0, 2).join(', ')} +${shortNames.length - 2} more`;
      scEl.setAttribute('data-full-text', fullScope || scEl.textContent);
      scEl.removeAttribute('title');
    }
  }

  function resolveSelectedAuthUser() {
    if (FACE_STATE.pending2faUser || FACE_STATE.pendingPinUser) return null;
    const sel = norm(FACE_STATE.selectedAuthEmail || '');
    if (!sel) return null;
    return STATE.users.find(u => u.status !== 'Suspended' && norm(u.email) === sel) || null;
  }

  function syncAuthSelectedSeatUi() {
    const grp = $('authSelectedGroup');
    const bar = $('authSelectedSeatBar');
    const pinRow = $('authPinRow');
    const pinEl = $('authPinInput');
    const avEl = $('authSelectedSeatAvatar');
    const nmEl = $('authSelectedSeatName');
    const metaEl = $('authSelectedSeatMeta');
    const drawer = $('authSeatDrawer');
    const divEl = $('authMethodDivider');
    const divLblEl = $('authMethodDividerLabel');
    const selUser = resolveSelectedAuthUser();
    const waitingCam2FA = !!FACE_STATE.pending2faUser;
    const waitingPin2FA = !!FACE_STATE.pendingPinUser;
    const showPicker = !selUser && !waitingCam2FA && !waitingPin2FA;
    const showPinGroup = !!(selUser || waitingPin2FA);

    FACE_STATE.seatDrawerOpen = showPicker;

    if (drawer) {
      drawer.hidden = !showPicker;
    }
    if (grp) {
      grp.hidden = !showPinGroup;
    }
    if (bar) {
      if (selUser) {
        bar.hidden = false;
        if (avEl) avEl.textContent = getInitials(selUser.full_name);
        if (nmEl) nmEl.textContent = selUser.full_name;
        if (metaEl) metaEl.textContent = `${formatCleanSeatRole(selUser.role)} · ${formatSeatEntityCountLabel(selUser)}`;
      } else {
        bar.hidden = true;
      }
    }
    if (pinRow) {
      pinRow.hidden = !showPinGroup;
    }
    if (pinEl) {
      const targetUser = waitingPin2FA ? FACE_STATE.pendingPinUser : selUser;
      if (targetUser) {
        const firstName = String(targetUser.full_name || '').trim().split(/\s+/)[0] || 'account';
        pinEl.setAttribute('placeholder', `Enter PIN for ${firstName}`);
        pinEl.setAttribute('aria-label', `Access PIN for ${targetUser.full_name}`);
      } else {
        pinEl.setAttribute('placeholder', 'Access PIN');
        pinEl.setAttribute('aria-label', 'Access PIN');
      }
    }
    if (divEl) {
      const wsMode = getWorkspaceAuthMode();
      if (waitingCam2FA || waitingPin2FA || wsMode === 'pin_only') {
        divEl.hidden = true;
      } else {
        divEl.hidden = false;
        if (divLblEl) {
          divLblEl.textContent = showPicker
            ? (IS_DEMO ? 'or open a demo workspace' : 'or select account for PIN')
            : 'or sign in with PIN';
        }
      }
    }
  }

  function setAuthSeatDrawerOpen(open, opts = {}) {
    if (open) {
      FACE_STATE.selectedAuthEmail = '';
    }
    FACE_STATE.seatDrawerOpen = !!open;
    if (!open) FACE_STATE.disambiguatePin = '';
    const emEl = $('authEmailInput');
    const pinEl = $('authPinInput');
    if (emEl) {
      emEl.value = '';
    }
    renderQuickSeatsInAuthGate();
    syncAuthSelectedSeatUi();
    if (!opts.silentFocus && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
      if (open && emEl && !coarse) {
        setTimeout(() => { try { emEl.focus({ preventScroll: true }); } catch (_) {} }, 30);
      } else if (!open && pinEl && !coarse) {
        setTimeout(() => { try { pinEl.focus({ preventScroll: true }); } catch (_) {} }, 30);
      }
    }
  }

  function renderQuickSeatsInAuthGate() {
    const listEl = $('quickSeatList');
    if (!listEl) return;
    const emEl = $('authEmailInput');
    const rawFilter = (!resolveSelectedAuthUser() && emEl) ? norm(emEl.value) : '';
    const disPin = String(FACE_STATE.disambiguatePin || '').trim();
    const activeSeats = STATE.users.filter(u => u.status !== 'Suspended');
    const filtered = activeSeats.filter(u => {
      if (disPin && String(u.pin_code || '1111').trim() !== disPin) return false;
      if (!rawFilter) return true;
      return norm(u.full_name).includes(rawFilter) || norm(u.email).includes(rawFilter) || norm(u.role).includes(rawFilter);
    });

    if (!filtered.length) {
      listEl.innerHTML = `<div class="quick-seat-empty">No matching team account</div>`;
      return;
    }

    listEl.innerHTML = filtered.map(u => {
      const active = norm(FACE_STATE.selectedAuthEmail || '') === norm(u.email);
      const seatMode = effectiveSeatAuthMode(u);
      const rightTag = IS_DEMO
        ? `<span class="quick-seat-demo-tag">Open</span>`
        : (seatMode === 'face_only'
          ? `<span class="quick-seat-cue">Face ID</span>`
          : `<span class="quick-seat-cue">PIN <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></span>`);
      return `
      <button type="button" class="quick-seat-item${active ? ' is-selected' : ''}" data-quick-seat="${esc(u.email)}">
        <span class="quick-seat-av" aria-hidden="true">${esc(getInitials(u.full_name))}</span>
        <div class="quick-seat-copy">
          <b>${esc(u.full_name)}</b>
          <small>${esc(formatCleanSeatRole(u.role))} · ${esc(formatSeatEntityCountLabel(u))}</small>
        </div>
        ${rightTag}
      </button>
    `;
    }).join('');

    listEl.querySelectorAll('[data-quick-seat]').forEach(btn => {
      btn.addEventListener('click', () => {
        const u = STATE.users.find(x => norm(x.email) === norm(btn.getAttribute('data-quick-seat')));
        if (!u) return;
        const pinEl = $('authPinInput');
        if (IS_DEMO) {
          FACE_STATE.selectedAuthEmail = u.email;
          if (pinEl) pinEl.value = u.pin_code || '1111';
          performLogin(u.email, u.pin_code || '1111', { bypass2FA: true });
          return;
        }
        if (effectiveSeatAuthMode(u) === 'face_only') {
          authError(`${u.full_name} uses Face ID only. Look at the camera above.`, { noShake: true, keepPin: true });
          setAuthHint(`Look at camera to sign in as ${u.full_name}`, 'warn');
          if (!FACE_STATE.camActive && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) startAuthFaceScanner(true);
          return;
        }
        const pendingDisPin = String(FACE_STATE.disambiguatePin || '').trim();
        FACE_STATE.selectedAuthEmail = u.email;
        FACE_STATE.disambiguatePin = '';
        FACE_STATE.seatDrawerOpen = false;
        if (emEl) emEl.value = '';
        const errEl = $('authErrorBox');
        if (errEl) errEl.hidden = true;
        syncAuthSelectedSeatUi();
        if (pendingDisPin && pendingDisPin === String(u.pin_code || '1111').trim()) {
          performLogin(u.email, pendingDisPin);
          return;
        }
        if (pinEl) {
          pinEl.value = '';
          try { pinEl.focus({ preventScroll: true }); } catch (_) {}
        }
      });
    });
  }

  function openAuthGate(prefillEmail) {
    STATE.authed = false;
    window.__mfgSwResuming = false;
    document.documentElement.classList.remove('sw-resuming');
    FACE_STATE.pending2faUser = null;
    FACE_STATE.pendingPinUser = null;
    FACE_STATE.streakUser = null;
    FACE_STATE.streakCount = 0;
    FACE_STATE.disambiguatePin = '';
    setAuthStreak(0, 3);
    let candidateEmail = prefillEmail || '';
    if (!candidateEmail && !IS_DEMO && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      try { candidateEmail = localStorage.getItem('isabi_mfg_last_seat') || ''; } catch (_) {}
    }
    const preUser = candidateEmail ? STATE.users.find(u => u.status !== 'Suspended' && norm(u.email) === norm(candidateEmail)) : null;
    FACE_STATE.selectedAuthEmail = preUser ? preUser.email : '';
    FACE_STATE.seatDrawerOpen = !preUser;
    resetLivenessState();
    window.__mfgAuthedEmail = '';
    const emEl = $('authEmailInput');
    const pinEl = $('authPinInput');
    if (emEl) emEl.value = '';
    if (pinEl) pinEl.value = '';
    const errEl = $('authErrorBox');
    if (errEl) errEl.hidden = true;
    renderQuickSeatsInAuthGate();
    updateCloudBadges();
    updateAuthFaceUi();
    syncAuthSelectedSeatUi();
    const gate = $('authGate');
    if (gate) gate.hidden = false;
    document.body.classList.add('locked');
    if (!FACE_STATE.authCamStoppedByUser) startAuthFaceScanner(false);
    setTimeout(() => {
      if (!STATE.authed && preUser && pinEl) {
        const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
        if (!coarse && window.innerWidth > 860) {
          try { pinEl.focus({ preventScroll: true }); } catch (_) {}
        }
      }
    }, 60);
  }

  function closeAuthGate() {
    STATE.authed = true;
    window.__mfgSwResuming = false;
    document.documentElement.classList.remove('sw-resuming');
    FACE_STATE.pending2faUser = null;
    FACE_STATE.pendingPinUser = null;
    FACE_STATE.streakUser = null;
    FACE_STATE.streakCount = 0;
    FACE_STATE.seatDrawerOpen = false;
    FACE_STATE.disambiguatePin = '';
    FACE_STATE.enrolCamActive = false;
    setAuthStreak(0, 3);
    resetLivenessState();
    stopAuthFaceScanner();
    stopFaceCamera();
    window.__mfgAuthedEmail = activeUser().email;
    const gate = $('authGate');
    if (gate) gate.hidden = true;
    document.body.classList.remove('locked');
    const keep = new URLSearchParams();
    ['demo', 'nosse'].forEach(p => { if (PARAMS.has(p)) keep.set(p, PARAMS.get(p)); });
    const targetUrl = location.pathname + (keep.toString() ? '?' + keep.toString() : '') + (VIEW_TITLES[STATE.view] ? '#' + STATE.view : '');
    if (location.pathname + location.search + location.hash !== targetUrl) {
      history.replaceState({ view: STATE.view }, '', targetUrl);
    }
  }

  function signOut() {
    try { localStorage.removeItem('isabi_mfg_active_email'); } catch (_) {}
    try { localStorage.removeItem('isabi_mfg_last_seat'); } catch (_) {}
    try { sessionStorage.removeItem('isabi_mfg_sw_resume'); } catch (_) {}
    clearTimeout(toastTimer);
    clearTimeout(toastFadeTimer);
    const tEl = $('toast');
    if (tEl) { tEl.classList.remove('is-leaving'); tEl.hidden = true; }
    closeEntryModal(true);
    const keep = new URLSearchParams();
    ['demo', 'nosse'].forEach(p => { if (PARAMS.has(p)) keep.set(p, PARAMS.get(p)); });
    history.replaceState({ view: STATE.view }, '', location.pathname + (keep.toString() ? '?' + keep.toString() : ''));
    openAuthGate('');
  }

  function authError(msg, opts = {}) {
    const errEl = $('authErrorBox');
    if (errEl) { errEl.textContent = msg; errEl.hidden = false; }
    const card = document.querySelector('.auth-card');
    if (card && !opts.noShake) { card.classList.remove('shake'); void card.offsetWidth; card.classList.add('shake'); }
    const pinEl = $('authPinInput');
    if (pinEl && !opts.keepPin) {
      pinEl.value = '';
      try { pinEl.focus({ preventScroll: true }); } catch (_) {}
    }
  }

  let loginAttempts = 0;
  let loginLockUntil = 0;
  let authUiLoginBusy = false;
  async function performLogin(emailRaw, pinRaw, opts = {}) {
    let email = norm(emailRaw);
    const pin = String(pinRaw || '').trim();
    if (Date.now() < loginLockUntil) { authError(`Too many attempts. Wait ${Math.ceil((loginLockUntil - Date.now()) / 1000)}s.`); return false; }
    if (!email && pin) {
      const matches = STATE.users.filter(u => u.status !== 'Suspended' && String(u.pin_code || '1111').trim() === pin);
      if (matches.length === 1) {
        email = norm(matches[0].email);
        const emEl = $('authEmailInput');
        if (emEl && !FACE_STATE.seatDrawerOpen) emEl.value = matches[0].email;
      } else if (matches.length > 1) {
        FACE_STATE.disambiguatePin = pin;
        setAuthSeatDrawerOpen(true, { silentFocus: true });
        authError('Select your account below to finish signing in.', { keepPin: true, noShake: true });
        return false;
      } else {
        loginAttempts += 1;
        if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
        else authError('Incorrect Access PIN.');
        return false;
      }
    }
    if (!email) { authError('Enter your Access PIN.'); return false; }
    if (!pin) { authError('Enter your Access PIN.'); return false; }

    let idx = STATE.users.findIndex(u => norm(u.email) === email);
    if (idx < 0 && !email.includes('@')) {
      const subMatches = STATE.users.filter(u => u.status !== 'Suspended' && (norm(u.full_name).includes(email) || norm(u.email).includes(email)));
      if (subMatches.length === 1) idx = STATE.users.indexOf(subMatches[0]);
    }
    if (idx < 0) { authError('Account not found in this workspace.'); return false; }
    const user = STATE.users[idx];
    if (user.status === 'Suspended') { authError('This seat is suspended. Contact an administrator.'); return false; }
    if (pin !== String(user.pin_code || '1111').trim()) {
      loginAttempts += 1;
      if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
      else authError('Incorrect PIN for ' + user.full_name + '.');
      return false;
    }
    loginAttempts = 0;

    const seatMode = effectiveSeatAuthMode(user);
    // If seat is configured for Face ID Only, block PIN-only sign-in and prompt for live camera scan
    if (!opts.bypass2FA && seatMode === 'face_only') {
      authError(`${user.full_name} requires Face ID to sign in. Look at the camera above.`);
      setAuthHint(`Look at the camera to sign in as ${user.full_name}`, 'warn');
      if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
      return 'face_only_required';
    }

    // If user already completed Live Face ID Step 1 under 'both' mode, completing PIN Step 2 signs them in!
    const completedFaceFirst2FA = !!(FACE_STATE.pendingPinUser && norm(FACE_STATE.pendingPinUser.email) === norm(user.email));
    if (completedFaceFirst2FA) {
      FACE_STATE.pendingPinUser = null;
      opts = Object.assign({}, opts, { bypass2FA: true, method: opts.method || 'Face ID + PIN 2FA' });
    }

    // Step-Up 2FA Biometric Gate: if this seat has enrolled Face ID and 2FA ('both') is enforced, require Live Face ID confirmation!
    if (!opts.bypass2FA && userRequiresFace2FA(user)) {
      FACE_STATE.pending2faUser = user;
      FACE_STATE.pendingPinUser = null;
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      resetLivenessState();
      const errEl = $('authErrorBox');
      if (errEl) errEl.hidden = true;
      updateAuthFaceUi();
      setAuthHint(`PIN verified. Look at the camera to verify ${user.full_name}.`, 'ok');
      if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
      return '2fa_pending';
    }

    FACE_STATE.pending2faUser = null;
    FACE_STATE.pendingPinUser = null;
    const nowStr = nowStamp();
    const ua = navigator.userAgent || '';
    const devLabel = /iPhone|iPad/i.test(ua) ? 'iOS Safari' : (/Android/i.test(ua) ? 'Android Chrome' : (/Edg\//.test(ua) ? 'Desktop Edge' : 'Desktop Browser'));
    const standalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone;
    const authMethod = opts.method || 'PIN';
    const authConf = opts.confidence != null ? Number(opts.confidence) : null;

    user.last_login_at = nowStr.slice(0, 16);
    STATE.activeUserIdx = idx;
    try { localStorage.removeItem('isabi_mfg_active_email'); } catch (_) {}
    if (!IS_DEMO && !STATE.demoVisitor && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      try { localStorage.setItem('isabi_mfg_last_seat', user.email); } catch (_) {}
    }
    STATE.sessions.unshift({
      id: uid('sess'),
      full_name: user.full_name,
      email: user.email,
      role: user.role,
      companies: user.companies,
      device: devLabel + (standalone ? ' · Home Screen app' : ''),
      method: authMethod,
      confidence: authConf,
      logged_in_at: nowStr
    });
    STATE.sessions = STATE.sessions.slice(0, 50);
    saveLocalAuthAndRecords();

    if (HAS_LOCAL_API) {
      try { await fetch('./api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: user.email, pin, device: devLabel, method: authMethod, confidence: authConf }) }); } catch (_) { /* no server.py */ }
    }

    if (!getAllowedCompanyKeys(user).includes(STATE.company)) STATE.company = getAllowedCompanyKeys(user)[0];
    if (!canViewView(STATE.view, user)) STATE.view = defaultViewFor(user);
    closeAuthGate();
    STATE.search = '';
    STATE.showAddUserForm = false;
    renderApp();
    toastWelcome(user, authMethod);
    syncWithCloud(true);
    return true;
  }

  // ==========================================================================
  // ASK ISABI COPILOT ANSWERS (DATA-DRIVEN, WORD-BOUNDARY INTENTS)
  // ==========================================================================
  function answerAskIsabi(qRaw) {
    const q = ' ' + String(qRaw || '').toLowerCase() + ' ';
    const has = re => re.test(q);
    const g = (SEED.models['manufacturing-group'] || {}).periods || {};
    const gk = g[STATE.period] || g.all || {};
    const w = ((SEED.models.wtc || {}).periods || {})[STATE.period] || ((SEED.models.wtc || {}).periods || {}).all || {};
    const b = ((SEED.models.bbconstruction || {}).periods || {})[STATE.period] || ((SEED.models.bbconstruction || {}).periods || {}).all || {};
    const scope = `${COMPANY_LABELS[STATE.company].split('(')[0].trim()} · ${gk.label || 'All-Time'}`;
    const k = getKPI();
    const { fleet, pricing } = sentinelSlice();

    if (has(/\b(margin|gm|p&l|profit|compare|revenue|bbconstruction|wtc)\b/)) {
      return `<strong>P&amp;L — WTC vs BBConstruction (${esc(gk.label || 'All-Time')}):</strong><br>
        • <strong>WTC</strong>: Sales TTC ${fmtUSD(w.sales_ttc, 0)} on ${fmtNum(w.loads)} loads · net ${fmtUSD(w.net_sales, 0)} · raw cost ${fmtUSD(w.raw_cost, 0)} (${fmtNum(w.raw_loads)} loads) · gross margin ${fmtUSD(w.gross_margin, 0)} (<strong>${fmtPct(w.gm_pct, w.gross_margin, w.net_sales)}</strong>) · operating cash profit <strong>${fmtUSD(w.operating_profit, 0)}</strong> (${fmtPct(w.op_margin_pct, w.operating_profit, w.net_sales)}).<br>
        • <strong>BBConstruction</strong>: Sales TTC ${fmtUSD(b.sales_ttc, 0)} on ${fmtNum(b.loads)} loads · net ${fmtUSD(b.net_sales, 0)} · raw cost ${fmtUSD(b.raw_cost, 0)} (${fmtNum(b.raw_loads)} loads) · gross margin ${fmtUSD(b.gross_margin, 0)} (<strong>${fmtPct(b.gm_pct, b.gross_margin, b.net_sales)}</strong>) · operating cash profit <strong>${fmtUSD(b.operating_profit, 0)}</strong> (${fmtPct(b.op_margin_pct, b.operating_profit, b.net_sales)}).<br>
        • BBConstruction's higher GM comes from more own / JV pit material (lower third-party site royalties); its operating margin is thinner because expenses and payroll weigh more against a smaller top line.`;
    }
    if (has(/\b(ar|overdue|receivable|receivables|customer|customers|credit hold|dso)\b/)) {
      const topC = ((SEED.models[STATE.company] || SEED.models['manufacturing-group'] || {}).customers || []).slice(0, 5).map(c => `${esc(c.Customer)} (${fmtUSD(c.ar_balance, 0)}${Number(c.ar_60_plus || 0) > 0 ? ', ' + fmtUSD(c.ar_60_plus, 0) + ' past 60d' : ''})`).join(', ');
      return `<strong>FIFO Accounts Receivable — ${esc(scope)}:</strong><br>
        • Open AR <strong>${fmtUSD(k.ar_balance, 2)}</strong> (WTC ${fmtUSD(w.ar_balance, 2)} · BBConstruction ${fmtUSD(b.ar_balance, 2)}) · overdue &gt;30d ${fmtUSD(k.ar_overdue, 0)} · past 60 days <strong>${fmtUSD(k.ar_60_plus, 0)}</strong> · DSO ${fmtNum(k.dso_days, 0)} days.<br>
        • Aging: current ${fmtUSD(k.ar_current, 0)} · 1–10d ${fmtUSD(k.ar_1_10, 0)} · 11–30d ${fmtUSD(k.ar_11_30, 0)} · 31–60d ${fmtUSD(k.ar_31_60, 0)} · 60+ ${fmtUSD(k.ar_60_plus, 0)}. VAT-registered customers carry 11% inside their balance (m249).<br>
        • Largest balances: ${topC || '—'}. Credit hold candidates = anything past 60 days with no receipt this month.`;
    }
    if (has(/\b(ap|leg|legs|quarry|quarries|site|sites|supplier|suppliers|hauler|payable|payables)\b/)) {
      return `<strong>3-Leg Accounts Payable (m192) — ${esc(scope)}:</strong><br>
        1. <strong>Material leg ${fmtUSD(k.ap_material, 0)}</strong> owed to site owners.<br>
        2. <strong>Haulage leg ${fmtUSD(k.ap_haulage, 0)}</strong> owed to truck owners ($0 on company-fleet loads).<br>
        3. <strong>Supplies &amp; services leg ${fmtUSD(k.ap_expense, 0)}</strong> from credit expenses.<br>
        Settlements paid ${fmtUSD(k.settlements_paid, 0)} · net open AP <strong>${fmtUSD(k.ap_balance, 0)}</strong>${Number(k.ap_balance || 0) < 0 ? ' (negative = prepayments / advances exceed open legs)' : ''}.`;
    }
    if (has(/\b(diesel|tank|fuel|litre|litres|consumption|malfunction)\b/)) {
      const dtByCo = computeDieselTank().byCo || {};
      const wf = dtByCo.WTC || {};
      const bf = dtByCo.BBConstruction || {};
      const dtScoped = getDieselTankLedger();
      return `<strong>Diesel Tank &amp; Malfunction Reconciliation:</strong><br>
        • <strong>WTC</strong>: purchased ${fmtNum(wf.bought, 0)} L minus issued ${fmtNum(wf.issued, 0)} L minus malfunction/discrepancy ${fmtNum(wf.discrepancy || 0, 0)} L minus sold ${fmtNum(wf.sold, 0)} L = <code class="mono">${fmtNum(wf.balance, 0)} L</code> remaining in tank.<br>
        • <strong>BBConstruction</strong>: purchased ${fmtNum(bf.bought, 0)} L minus issued ${fmtNum(bf.issued, 0)} L minus malfunction/discrepancy ${fmtNum(bf.discrepancy || 0, 0)} L minus sold ${fmtNum(bf.sold, 0)} L = <code class="mono">${fmtNum(bf.balance, 0)} L</code> (negative because historical bulk diesel invoices were booked under General Expenses instead of Fuel Purchases).<br>
        • <strong>5% Malfunction Watchdog (${esc(scope)})</strong>: gross malfunction ${fmtNum(dtScoped.malfAbsL, 1)} L vs ${fmtNum(dtScoped.companyDieselUsedL, 1)} L company diesel used = <strong>${dtScoped.malfunctionPct.toFixed(1)}%</strong> (${dtScoped.malfunctionAlert ? 'ALERT >= ' + dtScoped.malfunctionThresholdPct.toFixed(1) + '% threshold' : 'OK < ' + dtScoped.malfunctionThresholdPct.toFixed(1) + '% threshold'}).<br>
        • Period issued ${fmtNum(k.diesel_litres, 0)} L · discrepancy ${fmtNum(k.diesel_discrepancy || 0, 0)} L · sold ${fmtNum(k.diesel_sold, 0)} L · fleet cost per ton hauled ${fmtUSD(k.cost_per_ton, 2)} · ${fmtNum((fleet.consumption_outliers || []).length)} consumption outliers flagged.`;
    }
    if (has(/\b(cash|till|drawer|cashflow|lbp|pounds)\b/)) {
      return `<strong>Cash Flow &amp; Physical Till — ${esc(scope)}:</strong><br>
        • <strong>Live Cash in Till</strong>: USD <strong>${fmtUSD(k.cash_till_usd, 2)}</strong> · LBP <strong>${fmtLBP(k.cash_till_lbp)}</strong> (Combined <strong>${fmtUSD(k.cash_till, 2)}</strong> @ ${fmtNum(k.rate_lbp || 89500, 0)} LL/$).<br>
        • <strong>WTC</strong>: ${fmtUSD(w.cash_till_usd, 2)} &amp; ${fmtLBP(w.cash_till_lbp)} · <strong>BBConstruction</strong>: ${fmtUSD(b.cash_till_usd, 2)} &amp; ${fmtLBP(b.cash_till_lbp)}.<br>
        • Selected period cash flow: In ${fmtUSD(k.cash_inflow, 2)} − Out ${fmtUSD(k.cash_outflow, 2)} = Net <strong>${fmtUSD(k.net_cash_flow, 2)}</strong>. Entry users can verify drawer cash anytime on <em>Cash Flow &amp; Till</em>.`;
    }
    if (has(/\b(trial|balance|coa|ledger|gl|tie|tied)\b/)) {
      const tb = Number(k.tb_check || 0);
      return `<strong>Lebanese CoA Double-Entry Trial Balance — ${esc(scope)}:</strong><br>
        • Variance <strong>${fmtUSD(tb, 2)}</strong> ${Math.abs(tb) < 0.005 ? '— every SOA journal leg across Class 4 (receivables / payables / VAT), Class 5 (cash & till), Class 6 (raw material, haulage, payroll, expenses) and Class 7 (sales) ties.' : '— open the General Ledger and the Sentinels page: the books do not tie for this scope.'}<br>
        • Output VAT 11% ${fmtUSD(k.sales_vat, 2)} · VAT receivable ${fmtUSD(k.vat_receivable, 2)} · cash till ${fmtUSD(k.cash_till, 2)}.`;
    }
    if (has(/\b(price|prices|pricing|agreement|agreements|below|commission)\b/)) {
      return `<strong>Price Agreements — ${esc(scope)}:</strong><br>
        • ${fmtNum(pricing.active_agreements || k.active_agreements)} active agreements · ${fmtUSD(pricing.sales_below_agreed_usd || 0, 0)} sold below the agreed price across ${fmtNum(pricing.below_agreed_pairs_count || 0)} customer × product pairs · ${fmtNum(pricing.lapsed_agreement_pairs_count || 0)} pairs trading on lapsed agreements.<br>
        • Weighted agreed price ${fmtUSD(pricing.weighted_agreed_price_usd || 0, 2)} vs actual average ${fmtUSD(pricing.actual_avg_price_usd || 0, 2)} · commission due ${fmtUSD(k.commission_due, 0)}.`;
    }
    if (has(/\b(overtime|driver|drivers|payroll|salary|salaries)\b/)) {
      return `<strong>Workforce — ${esc(scope)}:</strong><br>
        • Salaries paid ${fmtUSD(k.salaries_paid, 0)} · overtime bonus due ${fmtUSD(k.overtime_bonus, 0)} (sales ${fmtUSD(fleet.sales_overtime_bonus_usd || 0, 0)} + raw ${fmtUSD(fleet.raw_overtime_bonus_usd || 0, 0)} all-time) · ${fmtUSD(pricing.unmatched_salary_payments_usd || 0, 0)} paid without a contract.<br>
        • Overtime = a company-fleet load dispatched outside the 06:00–17:59 day shift (m48 / m93); third-party loads never earn the allowance.`;
    }
    if (has(/\b(defect|defects|part|parts|spare|spares|maintenance|workshop|broken|custody)\b/)) {
      const mIdx = getMaintIndex();
      const allowedCos = allowedCompanyNames();
      const openDefs = mIdx.openDefects.filter(d => !d.company || allowedCos.includes(d.company));
      const parts = mIdx.parts.filter(p => !p.company || allowedCos.includes(p.company));
      const storedCnt = parts.filter(p => /^Stored/i.test(p.removed_disposition || '')).length;
      const wsCnt = parts.filter(p => /^In Maintenance/i.test(p.removed_disposition || '')).length;
      const soldCnt = parts.filter(p => /^Sold/i.test(p.removed_disposition || '')).length;
      const proceeds = parts.reduce((a, p) => a + Number(p.sale_proceeds || 0), 0);
      const unnotified = parts.filter(p => !p.prior_defect_notified && !p.defect_ref).length;
      return `<strong>Equipment Defects &amp; Parts Custody — ${esc(scope)}:</strong><br>
        • <strong>Open Defects</strong>: <strong>${fmtNum(openDefs.length)}</strong> (${fmtNum(openDefs.filter(d => /^Critical/i.test(d.severity || '')).length)} critical · ${fmtNum(openDefs.filter(d => /Awaiting Part/i.test(d.status || '')).length)} awaiting part).<br>
        • <strong>Part Custody (${fmtNum(parts.length)} logged)</strong>: ${fmtNum(storedCnt)} stored in warehouse · ${fmtNum(wsCnt)} in maintenance / workshop · ${fmtNum(soldCnt)} sold (${fmtUSD(proceeds, 2)} proceeds).<br>
        • <strong>Pre-Defect Governance</strong>: ${unnotified === 0 ? '100% of part changes had a prior defect notification.' : fmtNum(unnotified) + ' unnotified emergency part change(s) flagged in AI Sentinel S10.'} Open <em>Fleet &amp; Diesel → Defects &amp; Parts</em> to log or update custody.`;
    }
    if (has(/\b(team|biometric|face id|access|architecture|seat|seats|security|rls)\b/)) {
      const n = STATE.users.length;
      const faceCnt = STATE.users.filter(userHasFaceId).length;
      return `<strong>Multi-Device Team Access, Face ID &amp; Row-Level Security:</strong><br>
        • <strong>${n} active team seats</strong> synchronize across phones, tablets, and laptops over the Cloud Relay (<code class="mono">${esc(CLOUD_DOC_KEY)}</code>) with relational SQLite (<code class="mono">data/mfg.db</code>) and PostgreSQL (<code class="mono">data/schema_postgres.sql</code>) storage.<br>
        • <strong>${faceCnt} / ${n} seats enrolled</strong> in 128-D neural Face ID liveness authentication with Business-Unit Row-Level Security across entities.`;
    }
    return `<strong>${esc(scope)} at a glance:</strong><br>
      • Revenue (TTC) <strong>${fmtUSD(k.sales_ttc, 2)}</strong> across <strong>${fmtNum(k.loads)} loads</strong> (${fmtNum(k.tons_sold, 0)} t) · gross margin ${fmtUSD(k.gross_margin, 0)} · operating cash profit ${fmtUSD(k.operating_profit, 0)}.<br>
      • Open AR ${fmtUSD(k.ar_balance, 0)} · open AP ${fmtUSD(k.ap_balance, 0)} · till ${fmtUSD(k.cash_till, 2)} · diesel in tank ${fmtNum(k.diesel_in_tank, 0)} L.<br>
      Ask about <em>margin</em>, <em>AR</em>, <em>AP legs</em>, <em>diesel</em>, <em>trial balance</em>, <em>pricing</em>, <em>overtime</em> or <em>team seats</em>.`;
  }

  // ==========================================================================
  // MASTER RENDER & EVENT WIRING
  // ==========================================================================
  let searchTimer = null;

  function contextFormForView(view, user) {
    user = user || activeUser();
    if (view === 'kiosks') {
      const kf = STATE.activeKiosk === 'raw' ? 'raw' : (STATE.activeKiosk === 'fuel' ? (STATE.kioskFuelSubmode === 'refill' ? 'expense' : (STATE.kioskFuelSubmode === 'malfunction' ? 'malfunction' : 'fuel')) : (STATE.activeKiosk === 'attendance' ? 'attendance' : 'sales'));
      if (canEnterForm(kf, user)) return kf;
    }
    const map = {
      kiosks: 'sales', sales: 'sales', sales_vat: 'vatinvoice', sales_analytics: 'sales',
      raw: 'raw', raw_pricing: 'pricerule_raw', raw_analytics: 'raw', raw_jv: 'jv', jv: 'jv',
      fleet: 'fuel', fleet_equip: 'companyequipment', fleet_maint: 'defect', fleet_drivers: 'triprate', fleet_analytics: 'triprate',
      pricing: 'pricerule',
      cashflow: 'receipt', cashflow_analytics: 'receipt',
      external: 'external', conversions: 'conversion',
      customers: 'receipt', ar: 'receipt',
      suppliers: 'settlement', ap: 'settlement',
      expenses: 'expense', expenses_analytics: 'expense', warehouse: 'warehousestock',
      payroll: 'salary', workforce_map: 'attendance', payroll_attendance: 'attendance', payroll_allowances: 'logistics', payroll_contracts: 'employment', payroll_analytics: 'salary',
      ledger: 'treasury', gl: 'treasury', ledger_treasury: 'treasury',
      tables: 'pricerule',
      reg_equipment: 'equipment', reg_drivers: 'driver', reg_sites: 'site', reg_regions: 'region',
      reg_products: 'product', reg_customers: 'customer', reg_suppliers: 'supplier', reg_categories: 'expensecategory',
      reg_fx_rates: 'fxrate', reg_currencies: 'currency', reg_vat_rates: 'vatrate'
    };
    let preferred = map[view] || 'sales';
    if (view === 'tables' && window.MFG_PBI) { // the hub's active table owns the form (e.g. Loans → Treasury desk)
      const meta = (window.MFG_PBI.TABLE_CATALOG || []).find(t => t.key === STATE.activeTableKey);
      if (meta && meta.form && FORM_TITLES[meta.form]) preferred = meta.form;
    } else if (String(view || '').startsWith('reg_') && window.MFG_PBI) {
      const meta = (window.MFG_PBI.TABLE_CATALOG || []).find(t => t.key === (STATE.activeUnivRegKey || UNIV_VIEW_TO_TABLE_KEY[view]));
      if (meta && meta.form && FORM_TITLES[meta.form]) preferred = meta.form;
    }
    if (canEnterForm(preferred, user)) return preferred;
    if (canEnterForm('sales', user)) return 'sales';
    if (canEnterForm('receipt', user)) return 'receipt';
    return 'sales';
  }

  function renderMobileSubnav(user, k, sentinelsOpen) {
    const el = $('mobileSubnav');
    if (!el) return;
    const v = STATE.view;
    const activeHubId = VIEW_TO_HUB[v] || 'overview';
    const activeHub = getHubDef(activeHubId) || HUB_CATALOG[0];
    const group = (activeHub && activeHub.group) || 'exec';

    const hubsInGroup = HUB_CATALOG.filter(h => {
      const sameDock = (group === 'commercial' || group === 'plant')
        ? (h.group === 'commercial' || h.group === 'plant')
        : ((group === 'books' || group === 'universal' || group === 'system' || group === 'master')
          ? (h.group === 'books' || h.group === 'universal' || h.group === 'system' || h.group === 'master')
          : h.group === group);
      return sameDock && canViewHub(h.id, user);
    });
    el.innerHTML = hubsInGroup.map(h => {
      const on = h.id === activeHubId;
      const badge = getHubExceptionBadge(h.id, user, k, sentinelsOpen);
      return `<button type="button" class="m-subnav-pill${on ? ' on' : ''}" data-subnav-hub="${esc(h.id)}" data-subnav-view="${esc(resolveHubView(h.id, user))}" title="${esc(h.title)}"><i class="m-subnav-ico" aria-hidden="true">${ic(h.id)}</i><span>${esc(h.title)}</span>${badge ? `<em class="${esc(badge.cls)}">${esc(badge.text)}</em>` : ''}</button>`;
    }).join('');
    el.querySelectorAll('[data-subnav-hub]').forEach(btn => btn.addEventListener('click', () => clickHub(btn.getAttribute('data-subnav-hub'))));

    // Sync Mobile Bottom Dock active states
    const dOver = $('dockBtnOverview'), dDisp = $('dockBtnDispatch'), dBooks = $('dockBtnBooks'), dEntry = $('mobileDockEntryBtn'), dEntryLbl = $('mobileDockEntryLabel');
    if (dOver) dOver.classList.toggle('on', group === 'exec');
    if (dDisp) dDisp.classList.toggle('on', group === 'commercial' || group === 'plant' || group === 'dispatch');
    if (dBooks) dBooks.classList.toggle('on', group === 'books' || group === 'universal' || group === 'system' || group === 'master');
    if (dEntry && dEntryLbl) {
      if (canEnterAny(user)) {
        dEntry.hidden = false;
        const formLabels = {
          sales: 'Post Ticket', raw: 'Post Raw', fuel: 'Log Fuel', malfunction: 'Log Malfunction', receipt: 'Post Receipt',
          settlement: 'Settle AP', expense: 'Post Expense', warehousestock: 'Warehouse Stock', salary: 'Pay Salary',
          vatinvoice: 'Post VAT Inv', attendance: 'Log Attendance', logistics: 'Site Transport', employment: 'New Contract',
          treasury: 'Post Treasury', pricerule: 'New Agreement', pricerule_raw: 'New Site Rate',
          jv: 'Post JV Entry', defect: 'Report Warning', repair: 'Log Repair', oillog: 'Log Oil', partlog: 'Log Part', companyequipment: 'Assign Unit',
          customer: 'New Customer', supplier: 'New Supplier', product: 'New Product', expensecategory: 'New Category',
          site: 'New Site', region: 'New Region', equipment: 'New Equipment', driver: 'New Driver',
          fxrate: 'New FX Rate', vatrate: 'New VAT Rate', currency: 'New Currency'
        };
        dEntryLbl.textContent = formLabels[contextFormForView(v, user)] || 'Post Entry';
      } else {
        dEntry.hidden = true;
      }
    }
  }

  function renderHubSubtabBar(user, k, sentinelsOpen) {
    const hubId = VIEW_TO_HUB[STATE.view] || 'overview';
    const hubDef = getHubDef(hubId);
    if (!hubDef || hubId === 'kiosks') return '';
    const permittedTabs = hubDef.tabs.filter(t => canViewView(t.view, user));
    if (permittedTabs.length <= 1) return '';
    const pillsHtml = permittedTabs.map(t => {
      const matchViews = t.match || [t.view];
      const isActive = matchViews.includes(STATE.view);
      const lbl = (isActive && !UNIV_VIEW_TO_TABLE_KEY[STATE.view] && VIEW_TITLES[STATE.view])
        ? VIEW_TITLES[STATE.view]
        : (t.shortLabel || t.label || VIEW_TITLES[t.view] || t.view);
      const badge = typeof t.badgeFn === 'function' ? t.badgeFn(user, k, sentinelsOpen) : null;
      const pillHtml = badge && badge.text ? `<em class="hub-subtab-pill${badge.cls ? ' ' + badge.cls : ''}">${esc(badge.text)}</em>` : '';
      return `<button type="button" class="hub-subtab${isActive ? ' active' : ''}" data-hub-subtab="${esc(t.view)}" aria-current="${isActive ? 'page' : 'false'}"><i class="nav-ico" aria-hidden="true">${ic(t.icon || t.view)}</i><span class="hub-subtab-lbl">${esc(lbl)}</span>${pillHtml}</button>`;
    }).join('');
    return `<nav class="hub-subtab-bar no-print" id="hubSubtabBar" data-parent-hub="${esc(hubId)}" aria-label="${esc(hubDef.title)} Sub-Views">${pillsHtml}</nav>`;
  }

  function setRailWidth(w, persist = true) {
    STATE.railWidth = clampRailWidth(w);
    if (persist) {
      try { localStorage.setItem('isabi_mfg_rail_width', String(STATE.railWidth)); } catch (_) {}
    }
    syncRailCollapseUi();
  }

  function syncRailCollapseUi() {
    const shell = $('appShell');
    const menuBtn = $('mobileMenuBtn');
    const menuLbl = $('sidebarToggleLbl');
    const narrowBtn = $('railNarrowBtn');
    const widerBtn = $('railWiderBtn');
    const resizer = $('railResizer');
    const isMobile = typeof window !== 'undefined' && window.innerWidth <= 860;
    const collapsed = !isMobile && !!STATE.railCollapsed;
    const w = clampRailWidth(STATE.railWidth);
    document.documentElement.style.setProperty('--rail-w', `${w}px`);
    if (shell) {
      shell.style.setProperty('--rail-w', `${w}px`);
      shell.classList.toggle('rail-collapsed', collapsed);
      shell.classList.toggle('rail-narrow', !isMobile && !collapsed && w < 218);
      shell.classList.toggle('rail-wide', !isMobile && !collapsed && w >= 290);
    }
    if (narrowBtn) narrowBtn.disabled = w <= RAIL_MIN_W;
    if (widerBtn) widerBtn.disabled = w >= RAIL_MAX_W;
    if (resizer) {
      resizer.setAttribute('aria-valuenow', String(w));
      resizer.title = `Sidebar width: ${w}px — Drag left or right to make wider/narrower · Double-click to reset (${RAIL_DEFAULT_W}px)`;
    }
    if (menuBtn) {
      menuBtn.classList.toggle('rail-is-hidden', collapsed);
      menuBtn.setAttribute('aria-expanded', String(!collapsed));
      menuBtn.title = isMobile
        ? 'Open navigation menu'
        : (collapsed ? 'Show left navigation sidebar' : 'Hide left navigation sidebar to expand main view');
    }
    if (menuLbl) {
      menuLbl.textContent = collapsed ? 'Show Menu' : 'Hide Menu';
    }
  }

  // ==========================================================================
  // VIEW 02B: UNIFIED 4-KIOSK SUITE (SALES · RAW · FUEL & LUBE · ATTENDANCE)
  // + BLUETOOTH ESC/POS THERMAL PRINTER (80MM / 58MM · PRICED / GATE PASS)
  // ==========================================================================
  const KIOSK_ATT_STATE = {
    camActive: false,
    loopTimer: null,
    busy: false,
    streakStaff: '',
    streakCount: 0,
    bestDist: 9,
    statusText: 'Start the camera for hands-free Face ID, or enter your 4-digit PIN.',
    statusCls: '',
    lastSnap: '',
    keyWired: false
  };

  function resolveKioskFormType() {
    if (STATE.activeKiosk === 'raw') return 'raw';
    if (STATE.activeKiosk === 'fuel') return STATE.kioskFuelSubmode === 'refill' ? 'expense' : (STATE.kioskFuelSubmode === 'malfunction' ? 'malfunction' : 'fuel');
    if (STATE.activeKiosk === 'attendance') return 'attendance';
    return 'sales';
  }

  function setKioskLockMode(locked, pinInput) {
    if (!locked && STATE.kioskLocked) {
      const cleanPin = String(pinInput == null ? '' : pinInput).trim();
      const u = activeUser();
      const userPin = String((u && u.pin_code) || '1111').trim();
      const validPin = cleanPin === '2401' || (isAdminUser(u) && (!cleanPin || cleanPin === userPin)) || cleanPin === userPin;
      if (!validPin) {
        toast('Enter Admin PIN (2401) or your seat PIN to unlock Kiosk Mode', 'err');
        return false;
      }
    }
    STATE.kioskLocked = !!locked;
    STATE.kioskUnlockPromptOpen = false;
    document.body.classList.toggle('kiosk-locked', STATE.kioskLocked);
    if (STATE.kioskLocked && STATE.view !== 'kiosks') {
      STATE.view = 'kiosks';
    }
    renderApp();
    toast(STATE.kioskLocked
      ? 'Kiosk Mode locked: sidebar and back-office menus hidden for shared station use'
      : 'Kiosk Mode unlocked: full Command Center navigation restored', 'ok');
    return true;
  }

  function buildDraftThermalRecordFromForm(calcRes) {
    const kMode = STATE.activeKiosk || 'sales';
    const company = val('f_company') || defaultEntryCompany();
    const date = val('f_date') || todayISO();
    const repDate = val('f_repdate') || date;
    const time = val('f_time') || new Date().toTimeString().slice(0, 5);
    const overtime = !!($('f_overtime') && $('f_overtime').checked);
    const notes = val('f_notes');
    const who = activeUser();

    if (kMode === 'raw') {
      const effCalc = calcRes || ($('f_qty') ? recalcRaw() : null);
      const qty = effCalc && effCalc.qty != null ? effCalc.qty : num('f_qty');
      const up = effCalc && effCalc.up != null ? effCalc.up : num('f_unitprice');
      const tp = effCalc && effCalc.tp != null ? effCalc.tp : num('f_transunitprice');
      const disc = effCalc && effCalc.disc != null ? effCalc.disc : num('f_discount');
      const uom = (effCalc && effCalc.uom) || val('f_uom') || 'm³';
      const isTruckUom = /truck/i.test(uom);
      const isCo = val('f_transportby') === 'Company fleet';
      const mat = (effCalc && effCalc.mat != null)
        ? round2(effCalc.mat)
        : ($('f_mat_total') && val('f_mat_total') !== '' ? num('f_mat_total') : round2(Math.max(0, (isTruckUom ? up : qty * up) - disc)));
      const tr = isCo
        ? 0
        : ((effCalc && effCalc.tr != null)
            ? round2(effCalc.tr)
            : ($('f_trans_total') && val('f_trans_total') !== '' ? num('f_trans_total') : round2(isTruckUom ? tp : qty * tp)));
      return {
        id: 'DRAFT-RAW',
        company,
        date,
        rep_date: repDate,
        time,
        overtime,
        ticket_no: val('f_ticketno') || nextTicketNo(company, [SEED.records.raw_purchases, STATE.customRecords.raw_purchases]) || '1001',
        product: val('f_product') || 'Raw Aggregate',
        site: val('f_site') || 'Site',
        site_owner: val('f_siteowner') || 'Site Owner',
        transport_by: val('f_transportby') || 'Company fleet',
        truck_owner: isCo ? company : (val('f_truckowner') || 'Hauler'),
        truck: val('f_truck') || '—',
        driver: val('f_driver') || '—',
        uom,
        qty,
        unit_cost: up,
        cost: mat,
        trans_unit_cost: tp,
        trans_cost: tr,
        discount: disc,
        total: round2(mat + tr),
        method: val('f_method') || 'Credit',
        entered_by: who.full_name,
        notes
      };
    }

    if (kMode === 'fuel') {
      if (STATE.kioskFuelSubmode === 'malfunction') {
        const discType = val('f_disctype') || 'Malfunction';
        const isWash = /^wash$/i.test(discType);
        const signed = round2(num('f_qty') || 0);
        return {
          id: 'DRAFT-FUEL-MALF',
          company,
          date,
          rep_date: repDate,
          time,
          ticket_no: (isWash && val('f_ticketno')) || 'TANK-MALF',
          fuel_type: discType,
          item: `Diesel (${signed >= 0 ? 'Shortage -Tank' : 'Surplus +Tank'})`,
          equipment: (isWash && val('f_truck')) || 'Main Plant Tank',
          driver: (isWash && val('f_driver')) || 'Tank Reconciliation',
          litres: signed,
          location: 'Main Plant Tank',
          entered_by: who.full_name,
          notes
        };
      }
      if (STATE.kioskFuelSubmode === 'refill') {
        const qty = num('f_qty') || 1000;
        const amt = num('f_amount') || 0;
        return {
          id: 'DRAFT-FUEL-REFILL',
          company,
          date,
          rep_date: repDate,
          time,
          ticket_no: val('f_reference') || 'TANK-REFILL',
          fuel_type: val('f_subcategory') || val('f_category') || 'Bulk Diesel Refill',
          item: `${val('f_category') || 'Fuel'} (${val('f_supplier') || 'Bulk Supplier'})`,
          equipment: val('f_truck') || 'Main Plant Tank',
          driver: val('f_supplier') || 'Tanker Delivery',
          litres: qty,
          location: 'Main Plant Tank',
          amount: amt,
          unit_cost: qty > 0 ? round2(amt / qty) : 0,
          entered_by: who.full_name,
          notes
        };
      }
      const eqDraftName = val('f_truck');
      const mType = val('f_metertype') || (eqDraftName ? equipMeterSpec(eqDraftName, company).type : 'odometer');
      const mVal = val('f_meter') ? num('f_meter') : null;
      const fType = val('f_fueltype') || 'Diesel';
      return {
        id: 'DRAFT-FUEL',
        company,
        date,
        rep_date: repDate,
        time,
        ticket_no: val('f_ticketno') || 'PUMP-01',
        fuel_type: fType,
        item: fType === 'Lubricant' ? (val('f_item') || 'Oil 15W40') : fType,
        equipment: val('f_truck') || 'Select Equipment',
        driver: val('f_driver') || '—',
        litres: num('f_qty') || 0,
        odometer: mType === 'odometer' ? mVal : null,
        hours: mType === 'hours' ? mVal : null,
        meter_delta: calcRes && calcRes.delta != null ? calcRes.delta : null,
        entered_by: who.full_name,
        notes
      };
    }

    // Default: Sales Dispatch Kiosk
    const effCalc = calcRes || ($('f_qty') ? recalcSales() : null);
    const qty = effCalc && effCalc.qty != null ? effCalc.qty : num('f_qty');
    const up = effCalc && effCalc.up != null ? effCalc.up : num('f_unitprice');
    const tp = effCalc && effCalc.tp != null ? effCalc.tp : num('f_transunitprice');
    const disc = effCalc && effCalc.disc != null ? effCalc.disc : num('f_discount');
    const uom = (effCalc && effCalc.uom) || val('f_uom') || 'm³';
    const saleType = (effCalc && effCalc.saleType) || val('f_saletype') || 'Delivery';
    const isTruckUom = /truck/i.test(uom);
    const mat = (effCalc && effCalc.mat != null)
      ? round2(Math.max(0, effCalc.mat - disc))
      : ($('f_mat_total') && val('f_mat_total') !== '' ? num('f_mat_total') : round2(Math.max(0, (isTruckUom ? up : qty * up) - disc)));
    const tr = saleType === 'Delivery'
      ? ((effCalc && effCalc.tr != null)
          ? round2(effCalc.tr)
          : ($('f_trans_total') && val('f_trans_total') !== '' ? num('f_trans_total') : round2(isTruckUom ? tp : qty * tp)))
      : 0;
    const net = round2(mat + tr);
    const cust = val('f_customer') || 'Walk-In / Customer';
    const ci = customerInfo(cust);
    const vatReg = !!(ci && (ci['VAT Registered'] === 'Yes' || ci.vat_registered));
    const vat = vatReg ? round2(net * getVatFraction(val('f_date') || todayISO())) : 0;
    const ttc = round2(net + vat);
    return {
      id: 'DRAFT-SALES',
      company,
      date,
      rep_date: repDate,
      time,
      overtime,
      ticket_no: val('f_ticketno') || nextTicketNo(company, [SEED.records.sales_tickets, STATE.customRecords.sales_tickets]) || '5001',
      sale_type: saleType,
      transport_by: val('f_transportby') || 'Company fleet',
      customer: cust,
      product: val('f_product') || 'Select Product',
      site: saleType === 'Delivery' ? (val('f_site') || 'Destination Site') : 'Plant Pickup',
      truck_owner: val('f_transportby') === 'Company fleet' ? company : (val('f_truckowner') || ''),
      truck: val('f_truck') || '—',
      driver: saleType === 'Delivery' ? (val('f_driver') || '—') : '',
      uom,
      qty,
      unit_price: up,
      price: mat,
      trans_unit_price: tp,
      trans_price: tr,
      discount: disc,
      total: net,
      vat,
      total_ttc: ttc,
      method: val('f_method') || 'Credit',
      vat_invoice: vatReg ? val('f_vatinvoice') : '',
      entered_by: who.full_name,
      notes
    };
  }

  function updateKioskLiveThermalPreview(calcRes) {
    const previewWrap = $('kioskLiveThermalPreview');
    if (!previewWrap || !window.MFG_PRINT) return;
    const docType = STATE.activeKiosk === 'raw' ? 'raw' : (STATE.activeKiosk === 'fuel' ? 'fuel' : 'sales');
    const paperWidth = window.MFG_PRINT.SETTINGS.paperWidth || 80;
    const priceMode = window.MFG_PRINT.SETTINGS.priceMode || 'priced';
    const draft = buildDraftThermalRecordFromForm(calcRes);
    previewWrap.innerHTML = window.MFG_PRINT.renderThermalTicketHtml(draft, { docType, paperWidth, priceMode });
    const metaEl = $('kioskEscPosByteMeta');
    if (metaEl) {
      const bytes = window.MFG_PRINT.buildEscPosBytes(draft, { docType, paperWidth, priceMode });
      metaEl.textContent = `ESC/POS Stream Ready · ${bytes.length.toLocaleString()} bytes · ${paperWidth}mm (${paperWidth === 58 ? '32 cols' : '48 cols'}) · ${priceMode === 'unpriced' ? 'UNPRICED GATE PASS' : 'PRICED VOUCHER'}`;
    }
  }

  async function saveKioskEntry(opts = {}) {
    if (STATE.saving) return { ok: false, reason: 'saving' };
    const formType = resolveKioskFormType();
    STATE.modalForm = formType;
    if (!canEnterForm(formType)) {
      toast('Your seat cannot post this kiosk entry', 'err');
      return { ok: false, reason: 'permission' };
    }
    const { errors, fieldErrors, record, crKey } = validateAndBuild();
    if (errors.length) {
      FORM_UI.postAttempted = true;
      recalcForm(true);
      syncFormValidationUI(fieldErrors, true);
      return { ok: false, errors, fieldErrors };
    }
    FORM_UI.postAttempted = false;
    syncFormValidationUI([], false);

    STATE.saving = true;
    const btnPrint = $('kioskPostAndPrintBtn');
    const btnPost = $('kioskPostOnlyBtn');
    if (btnPrint) { btnPrint.disabled = true; btnPrint.textContent = 'Posting & Printing…'; }
    if (btnPost) { btnPost.disabled = true; }
    try {
      STATE.customRecords[crKey].unshift(record);
      const kioskExtraPosts = [];
      if (crKey === 'sales_tickets') {
        applyOriginPriorDisposition(record, kioskExtraPosts);
      }
      applyCustomRecordsToSeed();
      saveLocalAuthAndRecords();
      const malfHit = crKey === 'fuel_malfunctions' ? getMalfunctionSaveWatchdogHit(record) : null;
      if (malfHit) {
        toast(`✓ Kiosk ${CR_LABEL[crKey] || 'entry'} posted · ⚠️ High Diesel Malfunction Alert (${malfHit.scopeLbl}): ${malfHit.hit.malfunctionPct.toFixed(1)}% of company diesel used`, 'warn');
      } else {
        toast(`✓ Kiosk ${CR_LABEL[crKey] || 'entry'} posted · ${record.name}`, 'ok');
      }

      let printResult = null;
      const shouldPrint = opts.print !== false;
      if (shouldPrint && window.MFG_PRINT) {
        const docType = STATE.activeKiosk === 'raw' ? 'raw' : (STATE.activeKiosk === 'fuel' ? 'fuel' : 'sales');
        const priceMode = opts.priceMode || window.MFG_PRINT.SETTINGS.priceMode || 'priced';
        const paperWidth = opts.paperWidth || window.MFG_PRINT.SETTINGS.paperWidth || 80;
        printResult = await window.MFG_PRINT.printThermalTicket(record, {
          docType,
          priceMode,
          paperWidth,
          channel: opts.channel || window.MFG_PRINT.SETTINGS.channel
        });
      }
      renderApp();
      await postRecordToLocalApi(crKey, record);
      for (const [ek, er] of kioskExtraPosts) {
        await postRecordToLocalApi(ek, er);
      }
      syncWithCloud(true);
      return { ok: true, record, crKey, printResult };
    } finally {
      STATE.saving = false;
    }
  }

  // ---- Attendance Biometric Kiosk Engine (Face ID + 4-Digit PIN + Smart 16h Shift Pairing) ----
  function getKioskStationSites(defCo) {
    const byCo = {
      'WTC': ['WTC Main Plant', 'WTC Crusher & Yard', 'Jiyeh JV Quarry', 'Halat JV Quarry'],
      'BBConstruction': ['BBConstruction Batching Plant', 'BBConstruction Yard'],
      'Lions Transport': ['Lions Transport Garage', 'Main Dispatch Yard']
    };
    const scopedCo = COMPANY_BU_MATCH[STATE.company] || '';
    if (scopedCo && byCo[scopedCo]) return byCo[scopedCo].slice();
    const allowed = allowedCompanyNames();
    const out = [];
    if (defCo && byCo[defCo]) out.push(...byCo[defCo]);
    Object.keys(byCo).forEach(co => {
      if (!allowed.length || allowed.includes(co)) {
        byCo[co].forEach(s => { if (!out.includes(s)) out.push(s); });
      }
    });
    if (!out.length) out.push(`${defCo || 'Main'} Plant Station`);
    return out;
  }

  const DEFAULT_SHIFT_TYPES = [
    { id: 'day_8_4', name: 'Day Shift', short: 'Day', start_time: '08:00', end_time: '16:00', hours: 8.0, overnight: false, days: [1, 2, 3, 4, 5, 6], grace_min: 10, tone: 'amber', isBuiltin: true },
    { id: 'night_7_3', name: 'Night Shift', short: 'Night', start_time: '19:00', end_time: '03:00', hours: 8.0, overnight: true, days: [1, 2, 3, 4, 5, 6], grace_min: 10, tone: 'indigo', isBuiltin: true },
    { id: 'ext_7_4', name: 'Extended Day', short: 'Ext', start_time: '07:00', end_time: '16:00', hours: 9.0, overnight: false, days: [1, 2, 3, 4, 5, 6], grace_min: 10, tone: 'sapphire', isBuiltin: true }
  ];

  function ensureWorkSchedulesState() {
    if (!STATE.workSchedules || typeof STATE.workSchedules !== 'object') {
      STATE.workSchedules = { shiftTypes: [], staffRules: {} };
    }
    if (!Array.isArray(STATE.workSchedules.shiftTypes)) STATE.workSchedules.shiftTypes = [];
    if (!STATE.workSchedules.staffRules || typeof STATE.workSchedules.staffRules !== 'object') {
      STATE.workSchedules.staffRules = {};
    }
    return STATE.workSchedules;
  }

  function parseClockMinutes(hhmm) {
    const f = fmtAttClockTime(hhmm);
    if (!f || !/^\d{2}:\d{2}$/.test(f)) return null;
    const [h, m] = f.split(':').map(Number);
    if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
    return (h % 24) * 60 + Math.max(0, Math.min(59, m));
  }

  function shiftIsoDateByDays(isoDate, deltaDays) {
    const s = String(isoDate || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return todayISO();
    const [y, m, d] = s.split('-').map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d + Number(deltaDays || 0)));
    return dt.toISOString().slice(0, 10);
  }

  function fmtShortDayMonth(isoDate) {
    const s = String(isoDate || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    const [, m, d] = s.split('-').map(Number);
    return `${String(d).padStart(2, '0')} ${MONTH_SHORT_NAMES[(m - 1) % 12] || ''}`.trim();
  }

  function buildLocalPunchDateObj(dateStr, timeStr, fallbackMs = Date.now()) {
    const dStr = String(dateStr || '').slice(0, 10);
    const tFmt = fmtAttClockTime(timeStr || '');
    if (/^\d{4}-\d{2}-\d{2}$/.test(dStr) && /^\d{2}:\d{2}$/.test(tFmt)) {
      const [y, mo, da] = dStr.split('-').map(Number);
      const [hh, mm] = tFmt.split(':').map(Number);
      return new Date(y, mo - 1, da, hh, mm, 0, 0);
    }
    return new Date(fallbackMs);
  }

  function normalizeShiftTypeObj(raw, fallback = null) {
    const base = Object.assign({}, fallback || {}, raw || {});
    const st = fmtAttClockTime(base.start_time || '08:00') || '08:00';
    const et = fmtAttClockTime(base.end_time || '16:00') || '16:00';
    const sMin = parseClockMinutes(st);
    const eMin = parseClockMinutes(et);
    const overnight = Boolean(sMin != null && eMin != null && eMin <= sMin);
    const durHrs = computeShiftWorkedHours(st, et) || 8.0;
    const daysArr = Array.isArray(base.days) && base.days.length
      ? Array.from(new Set(base.days.map(Number).filter(n => Number.isInteger(n) && n >= 0 && n <= 6))).sort((a, b) => a - b)
      : [1, 2, 3, 4, 5, 6];
    const nameStr = String(base.name || 'Custom Shift').trim() || 'Custom Shift';
    const shortStr = String(base.short || nameStr.split(/\s+/)[0] || 'Shift').trim().slice(0, 12);
    return {
      id: String(base.id || uid('shf')),
      name: nameStr,
      short: shortStr,
      start_time: st,
      end_time: et,
      hours: durHrs,
      overnight,
      days: daysArr,
      grace_min: Math.max(0, Math.min(60, Number(base.grace_min != null ? base.grace_min : 10))),
      tone: ['amber', 'indigo', 'sapphire', 'emerald'].includes(base.tone) ? base.tone : (overnight ? 'indigo' : 'amber'),
      isBuiltin: Boolean(base.isBuiltin || DEFAULT_SHIFT_TYPES.some(d => d.id === base.id)),
      voided: Boolean(base.voided),
      updated_at: String(base.updated_at || '')
    };
  }

  function getShiftTypes() {
    const ws = ensureWorkSchedulesState();
    const customById = new Map();
    ws.shiftTypes.forEach(s => {
      if (s && s.id) customById.set(String(s.id), s);
    });
    const out = [];
    DEFAULT_SHIFT_TYPES.forEach(def => {
      const ov = customById.get(def.id);
      out.push(normalizeShiftTypeObj(ov || def, def));
      customById.delete(def.id);
    });
    customById.forEach(custom => {
      if (custom && !custom.voided) {
        out.push(normalizeShiftTypeObj(custom));
      }
    });
    return out;
  }

  async function postWorkScheduleMutation(bodyObj) {
    if (!HAS_LOCAL_API) return;
    try {
      await fetch('./api/work_schedules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bodyObj)
      });
    } catch (_) {}
  }

  function saveShiftType(spec = {}) {
    const ws = ensureWorkSchedulesState();
    const nowIso = new Date().toISOString();
    const existingBuiltin = DEFAULT_SHIFT_TYPES.find(d => d.id === spec.id) || null;
    const existingCustomIdx = ws.shiftTypes.findIndex(s => s && String(s.id) === String(spec.id || ''));
    const prev = existingCustomIdx >= 0 ? ws.shiftTypes[existingCustomIdx] : existingBuiltin;
    const normalized = normalizeShiftTypeObj(Object.assign({}, prev || {}, spec, { voided: false, updated_at: nowIso }), existingBuiltin);
    if (!normalized.name || !normalized.start_time || !normalized.end_time) {
      return { ok: false, error: 'Shift name, start time, and end time are required' };
    }
    if (existingCustomIdx >= 0) ws.shiftTypes[existingCustomIdx] = normalized;
    else ws.shiftTypes.push(normalized);
    saveLocalAuthAndRecords();
    postWorkScheduleMutation({ op: 'upsert_shift', item: normalized });
    syncWithCloud(true);
    return { ok: true, shiftType: normalized };
  }

  function deleteShiftType(shiftId) {
    const id = String(shiftId || '');
    if (!id || DEFAULT_SHIFT_TYPES.some(d => d.id === id)) {
      return { ok: false, error: 'Built-in shift types cannot be deleted (you can edit their timing)' };
    }
    const ws = ensureWorkSchedulesState();
    const nowIso = new Date().toISOString();
    const idx = ws.shiftTypes.findIndex(s => s && String(s.id) === id);
    if (idx < 0) return { ok: false, error: 'Shift type not found' };
    ws.shiftTypes[idx] = Object.assign({}, ws.shiftTypes[idx], { voided: true, updated_at: nowIso });
    Object.values(ws.staffRules).forEach(r => {
      if (r && r.shift_id === id) {
        r.shift_id = 'day_8_4';
        r.updated_at = nowIso;
      }
    });
    saveLocalAuthAndRecords();
    postWorkScheduleMutation({ op: 'upsert_shift', item: ws.shiftTypes[idx] });
    syncWithCloud(true);
    return { ok: true };
  }

  function hasExplicitStaffWorkRule(staffName) {
    const k = norm(staffName);
    if (!k) return false;
    const ws = ensureWorkSchedulesState();
    return Boolean(ws.staffRules[k] && !ws.staffRules[k].reset_default);
  }

  let _habitualShiftCacheRev = '';
  let _habitualNightCrewSet = new Set();

  function ensureHabitualNightCrewSet() {
    const attArr = (SEED.records && Array.isArray(SEED.records.attendance)) ? SEED.records.attendance : [];
    const rev = `${attArr.length}|${STATE._customRev || 0}`;
    if (rev === _habitualShiftCacheRev) return _habitualNightCrewSet;
    _habitualShiftCacheRev = rev;
    const byKey = new Map();
    for (let i = 0; i < attArr.length; i++) {
      const a = attArr[i];
      if (!a || a.voided) continue;
      const rawIn = a.in_time || a.check_in;
      const rawOut = a.out_time || a.check_out;
      if (!rawIn || !rawOut) continue;
      const tin = fmtAttClockTime(rawIn);
      if (!tin || !fmtAttClockTime(rawOut)) continue;
      const sk = norm(a.staff);
      if (!sk) continue;
      const ck = `${norm(a.company || 'WTC')}|${sk}`;
      const d = String(a.set_date || a.rep_date || a.date || '').slice(0, 10);
      let arr = byKey.get(ck);
      if (!arr) { arr = []; byKey.set(ck, arr); }
      arr.push({ d, tin });
    }
    const nightSet = new Set();
    byKey.forEach((arr, ck) => {
      if (arr.length < 3) return;
      arr.sort((a, b) => a.d.localeCompare(b.d));
      const recent = arr.length > 15 ? arr.slice(-15) : arr;
      let nightCnt = 0;
      for (let i = 0; i < recent.length; i++) {
        const inMin = parseClockMinutes(recent[i].tin);
        if (inMin != null && inMin >= 17 * 60) nightCnt++;
      }
      if (nightCnt / recent.length >= 0.65) {
        nightSet.add(ck);
      }
    });
    _habitualNightCrewSet = nightSet;
    return nightSet;
  }

  function inferHabitualStaffShiftId(staffName, company) {
    const k = norm(staffName);
    const prof = getStaffContractProfile(staffName, company);
    const fallbackId = (prof.hasContract && Number(prof.workingHours) === 9) ? 'ext_7_4' : 'day_8_4';
    if (!k) return fallbackId;
    const coNorm = norm(company || prof.company || 'WTC');
    return ensureHabitualNightCrewSet().has(`${coNorm}|${k}`) ? 'night_7_3' : fallbackId;
  }

  function getStaffWorkRule(staffName, company) {
    const k = norm(staffName);
    const ws = ensureWorkSchedulesState();
    const raw = (k && ws.staffRules[k]) ? ws.staffRules[k] : null;
    const prof = getStaffContractProfile(staffName, company);
    const defaultShiftId = (raw && !raw.reset_default && raw.shift_id)
      ? raw.shift_id
      : ((raw && raw.reset_default)
        ? ((prof.hasContract && Number(prof.workingHours) === 9) ? 'ext_7_4' : 'day_8_4')
        : inferHabitualStaffShiftId(staffName, company));
    const base = Object.assign({
      staff: staffName || '',
      company: company || prof.company || defaultEntryCompany(),
      shift_id: defaultShiftId,
      custom_name: 'Custom Shift',
      custom_start: '08:00',
      custom_end: '16:00',
      custom_days: [1, 2, 3, 4, 5, 6],
      grace_min: 10,
      shift_overrides: [],
      ot_mode: 'none',
      ot_max_hours: 2,
      ot_window_start: '',
      ot_window_end: '',
      ot_passes: [],
      updated_at: ''
    }, raw && !raw.reset_default ? raw : {});
    base.ot_mode = ['none', 'always', 'max_hours', 'date_range'].includes(base.ot_mode) ? base.ot_mode : 'none';
    base.ot_max_hours = Math.max(0, Number(base.ot_max_hours != null ? base.ot_max_hours : 2));
    base.ot_window_start = fmtAttClockTime(base.ot_window_start || '');
    base.ot_window_end = fmtAttClockTime(base.ot_window_end || '');
    base.custom_start = fmtAttClockTime(base.custom_start || '08:00') || '08:00';
    base.custom_end = fmtAttClockTime(base.custom_end || '16:00') || '16:00';
    base.custom_days = Array.isArray(base.custom_days) && base.custom_days.length
      ? Array.from(new Set(base.custom_days.map(Number).filter(n => Number.isInteger(n) && n >= 0 && n <= 6))).sort((a, b) => a - b)
      : [1, 2, 3, 4, 5, 6];
    base.shift_overrides = Array.isArray(base.shift_overrides) ? base.shift_overrides.filter(o => o && o.start_date) : [];
    base.ot_passes = Array.isArray(base.ot_passes) ? base.ot_passes.filter(p => p && p.start_date) : [];
    return base;
  }

  function saveStaffWorkRule(staffName, patch = {}) {
    const k = norm(staffName);
    if (!k) return { ok: false, error: 'Staff member is required' };
    const ws = ensureWorkSchedulesState();
    const cur = getStaffWorkRule(staffName, patch.company);
    const nowIso = new Date().toISOString();
    const next = Object.assign({}, cur, patch, {
      staff: cur.staff || staffName,
      reset_default: false,
      updated_at: nowIso
    });
    next.ot_mode = ['none', 'always', 'max_hours', 'date_range'].includes(next.ot_mode) ? next.ot_mode : 'none';
    next.ot_max_hours = Math.max(0, Number(next.ot_max_hours != null ? next.ot_max_hours : 0));
    next.ot_window_start = fmtAttClockTime(next.ot_window_start || '');
    next.ot_window_end = fmtAttClockTime(next.ot_window_end || '');
    next.custom_start = fmtAttClockTime(next.custom_start || '08:00') || '08:00';
    next.custom_end = fmtAttClockTime(next.custom_end || '16:00') || '16:00';
    if (Array.isArray(next.custom_days)) {
      next.custom_days = Array.from(new Set(next.custom_days.map(Number).filter(n => Number.isInteger(n) && n >= 0 && n <= 6))).sort((a, b) => a - b);
    }
    next.shift_overrides = Array.isArray(next.shift_overrides) ? next.shift_overrides.filter(o => o && o.start_date) : [];
    next.ot_passes = Array.isArray(next.ot_passes) ? next.ot_passes.filter(p => p && p.start_date) : [];
    ws.staffRules[k] = next;
    saveLocalAuthAndRecords();
    postWorkScheduleMutation({ op: 'upsert_staff_rule', key: k, item: next });
    syncWithCloud(true);
    return { ok: true, rule: next };
  }

  function resetStaffWorkRule(staffName) {
    const k = norm(staffName);
    if (!k) return { ok: false };
    const ws = ensureWorkSchedulesState();
    const nowIso = new Date().toISOString();
    const tomb = { staff: staffName, reset_default: true, updated_at: nowIso };
    ws.staffRules[k] = tomb;
    saveLocalAuthAndRecords();
    postWorkScheduleMutation({ op: 'upsert_staff_rule', key: k, item: tomb });
    syncWithCloud(true);
    return { ok: true };
  }

  function addStaffShiftOverride(staffName, ovSpec = {}) {
    const startD = String(ovSpec.start_date || todayISO()).slice(0, 10);
    const endD = String(ovSpec.end_date || startD).slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(startD) || !/^\d{4}-\d{2}-\d{2}$/.test(endD) || endD < startD) {
      return { ok: false, error: 'Valid start and end dates are required' };
    }
    const cur = getStaffWorkRule(staffName);
    const ov = {
      id: ovSpec.id || uid('sov'),
      shift_id: String(ovSpec.shift_id || 'night_7_3'),
      custom_start: fmtAttClockTime(ovSpec.custom_start || '08:00') || '08:00',
      custom_end: fmtAttClockTime(ovSpec.custom_end || '16:00') || '16:00',
      start_date: startD,
      end_date: endD,
      note: String(ovSpec.note || '').trim()
    };
    const filtered = (cur.shift_overrides || []).filter(x => !(x.start_date === startD && x.end_date === endD));
    filtered.unshift(ov);
    return saveStaffWorkRule(staffName, { shift_overrides: filtered.slice(0, 30) });
  }

  function removeStaffShiftOverride(staffName, ovId) {
    const cur = getStaffWorkRule(staffName);
    const nextList = (cur.shift_overrides || []).filter(x => String(x.id) !== String(ovId));
    return saveStaffWorkRule(staffName, { shift_overrides: nextList });
  }

  function addStaffOtPass(staffName, passSpec = {}) {
    const startD = String(passSpec.start_date || todayISO()).slice(0, 10);
    const endD = String(passSpec.end_date || startD).slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(startD) || !/^\d{4}-\d{2}-\d{2}$/.test(endD) || endD < startD) {
      return { ok: false, error: 'Valid Overtime start and end dates are required' };
    }
    const cur = getStaffWorkRule(staffName);
    const pass = {
      id: passSpec.id || uid('otp'),
      start_date: startD,
      end_date: endD,
      max_hours: Math.max(0, Number(passSpec.max_hours || 0)),
      note: String(passSpec.note || '').trim()
    };
    const filtered = (cur.ot_passes || []).filter(x => !(x.start_date === startD && x.end_date === endD));
    filtered.unshift(pass);
    const nextMode = passSpec.keepMode ? cur.ot_mode : 'date_range';
    return saveStaffWorkRule(staffName, { ot_mode: nextMode, ot_passes: filtered.slice(0, 40) });
  }

  function removeStaffOtPass(staffName, passId) {
    const cur = getStaffWorkRule(staffName);
    const nextList = (cur.ot_passes || []).filter(x => String(x.id) !== String(passId));
    return saveStaffWorkRule(staffName, { ot_passes: nextList });
  }

  function resolveStaffShiftForDate(staffName, company, isoDate = todayISO()) {
    const dStr = String(isoDate || todayISO()).slice(0, 10);
    const rule = getStaffWorkRule(staffName, company);
    const types = getShiftTypes();
    const wk = attDateWeekdayInfo(dStr);
    const activeOv = (rule.shift_overrides || []).find(o => o && o.start_date <= dStr && dStr <= (o.end_date || o.start_date)) || null;

    let chosenShift = null;
    if (activeOv) {
      if (activeOv.shift_id === 'off') {
        return {
          id: 'off',
          name: 'Scheduled Day Off',
          short: 'Off',
          start_time: '08:00',
          end_time: '16:00',
          hours: 0,
          overnight: false,
          days: [],
          grace_min: Number(rule.grace_min != null ? rule.grace_min : 10),
          tone: 'muted',
          isOverride: true,
          overrideObj: activeOv,
          isWorkday: false,
          windowLabel: 'Day Off',
          badgeLabel: 'Day Off'
        };
      }
      if (activeOv.shift_id === 'custom') {
        chosenShift = normalizeShiftTypeObj({
          id: 'custom',
          name: activeOv.note || 'Custom Rotation',
          short: 'Custom',
          start_time: activeOv.custom_start || rule.custom_start,
          end_time: activeOv.custom_end || rule.custom_end,
          days: [0, 1, 2, 3, 4, 5, 6],
          grace_min: rule.grace_min,
          tone: 'emerald'
        });
      } else {
        const foundOv = types.find(t => t.id === activeOv.shift_id) || types[0];
        chosenShift = Object.assign({}, foundOv, { days: [0, 1, 2, 3, 4, 5, 6] });
      }
    } else if (rule.shift_id === 'custom') {
      chosenShift = normalizeShiftTypeObj({
        id: 'custom',
        name: rule.custom_name || 'Custom Shift',
        short: 'Custom',
        start_time: rule.custom_start,
        end_time: rule.custom_end,
        days: rule.custom_days,
        grace_min: rule.grace_min,
        tone: 'emerald'
      });
    } else {
      const found = types.find(t => t.id === rule.shift_id) || types[0];
      chosenShift = Object.assign({}, found);
      if (hasExplicitStaffWorkRule(staffName) && Array.isArray(rule.custom_days) && rule.use_custom_days) {
        chosenShift.days = rule.custom_days;
      }
      if (hasExplicitStaffWorkRule(staffName) && rule.grace_min != null) {
        chosenShift.grace_min = Number(rule.grace_min);
      }
    }

    const isWorkday = activeOv ? true : (wk.dayIdx < 0 ? true : chosenShift.days.includes(wk.dayIdx));
    const winSuffix = chosenShift.overnight ? ' (+1d)' : '';
    const windowLabel = `${chosenShift.start_time} - ${chosenShift.end_time}${winSuffix}`;
    const badgeLabel = `${chosenShift.short} · ${chosenShift.start_time}-${chosenShift.end_time}${chosenShift.overnight ? ' +1d' : ''}`;
    return Object.assign({}, chosenShift, {
      isOverride: Boolean(activeOv),
      overrideObj: activeOv,
      isWorkday,
      windowLabel,
      badgeLabel
    });
  }

  function resolveStaffAttendanceDefaultWindow(staffName, company, isoDate = todayISO()) {
    const dStr = String(isoDate || todayISO()).slice(0, 10);
    const prof = getStaffContractProfile(staffName, company, dStr);
    const contractHrs = Number(prof.workingHours || 8);
    const hasRule = staffName ? hasExplicitStaffWorkRule(staffName) : false;
    let sh = staffName ? resolveStaffShiftForDate(staffName, company, dStr) : null;
    if (sh && sh.id === 'off' && staffName) {
      const rule = getStaffWorkRule(staffName, company);
      const types = getShiftTypes();
      if (rule.shift_id === 'custom') {
        sh = normalizeShiftTypeObj({
          id: 'custom',
          name: rule.custom_name || 'Custom Shift',
          short: 'Custom',
          start_time: rule.custom_start,
          end_time: rule.custom_end,
          days: rule.custom_days,
          grace_min: rule.grace_min,
          tone: 'emerald'
        });
      } else {
        sh = Object.assign({}, types.find(t => t.id === rule.shift_id) || types[0]);
      }
      sh.badgeLabel = `${sh.short} · ${sh.start_time}-${sh.end_time}${sh.overnight ? ' +1d' : ''}`;
    }
    if (!sh) {
      return {
        id: 'day_8_4',
        name: 'Day Shift',
        short: 'Day',
        start_time: '08:00',
        end_time: '16:00',
        hours: contractHrs || 8,
        overnight: false,
        isOverride: false,
        badgeLabel: 'Day · 08:00-16:00'
      };
    }
    let startT = sh.start_time || '08:00';
    let endT = sh.end_time || '16:00';
    let durHrs = Number(sh.hours || contractHrs || 8);
    const defDay = DEFAULT_SHIFT_TYPES[0];
    if (!hasRule && !sh.isOverride && sh.id === 'day_8_4' && startT === defDay.start_time && endT === defDay.end_time && prof.hasContract && Math.abs(contractHrs - durHrs) > 0.05) {
      const sMin = parseClockMinutes(startT);
      if (sMin != null) {
        const eTotal = ((sMin + Math.round(contractHrs * 60)) % 1440 + 1440) % 1440;
        endT = `${String(Math.floor(eTotal / 60)).padStart(2, '0')}:${String(eTotal % 60).padStart(2, '0')}`;
        durHrs = contractHrs;
      }
    }
    const sMinFinal = parseClockMinutes(startT);
    const eMinFinal = parseClockMinutes(endT);
    const overnight = Boolean(sMinFinal != null && eMinFinal != null && eMinFinal <= sMinFinal);
    return {
      id: sh.id,
      name: sh.name || 'Regular Shift',
      short: sh.short || 'Shift',
      start_time: startT,
      end_time: endT,
      hours: durHrs,
      overnight,
      isOverride: Boolean(sh.isOverride),
      badgeLabel: `${sh.short || 'Shift'} · ${startT}-${endT}${overnight ? ' +1d' : ''}`
    };
  }

  function describeStaffOvertimeRule(staffName, company, refDate = todayISO()) {
    const dStr = String(refDate || todayISO()).slice(0, 10);
    const rule = getStaffWorkRule(staffName, company);
    const activePass = (rule.ot_passes || []).find(p => p && p.start_date <= dStr && dStr <= (p.end_date || p.start_date)) || null;
    if (activePass && (rule.ot_mode === 'date_range' || rule.ot_mode === 'none')) {
      const sameDay = activePass.start_date === (activePass.end_date || activePass.start_date);
      const dateLbl = sameDay
        ? (activePass.start_date === todayISO() ? 'Today' : fmtShortDayMonth(activePass.start_date))
        : `${fmtShortDayMonth(activePass.start_date)}-${fmtShortDayMonth(activePass.end_date)}`;
      const capLbl = activePass.max_hours > 0 ? ` (${fmtNum(activePass.max_hours, 1)}h)` : '';
      return {
        mode: 'date_range',
        badgeText: `OT: ${dateLbl}${capLbl}`,
        detailText: `Approved for ${dateLbl}${capLbl}`,
        tone: 'emerald',
        activeToday: true,
        pass: activePass
      };
    }
    if (rule.ot_mode === 'always') {
      return {
        mode: 'always',
        badgeText: 'OT: Anytime',
        detailText: 'Open overtime authorized anytime beyond shift',
        tone: 'emerald',
        activeToday: true
      };
    }
    if (rule.ot_mode === 'max_hours') {
      const cap = Number(rule.ot_max_hours || 0);
      const hasWin = Boolean(rule.ot_window_start && rule.ot_window_end);
      const capPart = cap > 0 ? `Max ${fmtNum(cap, cap % 1 ? 1 : 0)}h/d` : 'Window';
      const winPart = hasWin ? ` (${rule.ot_window_start}-${rule.ot_window_end})` : '';
      return {
        mode: 'max_hours',
        badgeText: `OT: ${capPart}${winPart}`,
        detailText: `${cap > 0 ? `Up to ${fmtNum(cap, 1)}h/day` : 'Allowed'}${hasWin ? ` between ${rule.ot_window_start} and ${rule.ot_window_end}` : ' beyond shift'}`,
        tone: 'sapphire',
        activeToday: true
      };
    }
    if (rule.ot_mode === 'date_range') {
      const upcoming = (rule.ot_passes || [])
        .filter(p => p && (p.end_date || p.start_date) >= dStr)
        .sort((a, b) => String(a.start_date).localeCompare(String(b.start_date)))[0] || null;
      if (upcoming) {
        const sameDay = upcoming.start_date === (upcoming.end_date || upcoming.start_date);
        const lbl = sameDay ? fmtShortDayMonth(upcoming.start_date) : `${fmtShortDayMonth(upcoming.start_date)}-${fmtShortDayMonth(upcoming.end_date)}`;
        return {
          mode: 'date_range',
          badgeText: `OT: ${lbl}`,
          detailText: `Scheduled OT pass (${lbl}); 0h paid OT today`,
          tone: 'amber',
          activeToday: false,
          pass: upcoming
        };
      }
      return {
        mode: 'date_range',
        badgeText: 'OT: Date Pass (None)',
        detailText: 'Date-range mode with no active date today (0h paid OT)',
        tone: 'muted',
        activeToday: false
      };
    }
    return {
      mode: 'none',
      badgeText: 'No Overtime',
      detailText: 'Late clock-out logs actual time with 0h paid overtime',
      tone: 'muted',
      activeToday: false
    };
  }

  function intervalOverlapMinutes(aStart, aEnd, bStart, bEnd) {
    if (aEnd <= aStart || bEnd <= bStart) return 0;
    return Math.max(0, Math.min(aEnd, bEnd) - Math.max(aStart, bStart));
  }

  function evaluateShiftPunchTiming(staffName, company, shiftDate, inTime, outTime, opts = {}) {
    const dStr = String(shiftDate || todayISO()).slice(0, 10);
    const rule = getStaffWorkRule(staffName, company);
    const shift = resolveStaffShiftForDate(staffName, company, dStr);
    const round1 = v => Math.round(Math.max(0, Number(v || 0)) * 10) / 10;

    const schedStartMin = parseClockMinutes(shift.start_time) ?? 480;
    const schedEndRaw = parseClockMinutes(shift.end_time) ?? 960;
    const schedEndMin = schedEndRaw <= schedStartMin ? (schedEndRaw + 1440) : schedEndRaw;
    const schedDurMin = shift.isWorkday ? Math.max(0, schedEndMin - schedStartMin) : 0;
    const scheduledHours = round1(schedDurMin / 60);

    const rawInMin = parseClockMinutes(inTime);
    if (rawInMin == null) {
      return {
        shift,
        rule,
        hasOut: false,
        scheduledHours,
        workedHours: 0,
        regularHours: 0,
        lateHours: 0,
        arrivalLateMin: 0,
        earlyLeaveMin: 0,
        rawExtraHours: 0,
        overtimeHours: 0,
        unapprovedOtHours: 0,
        otReason: ''
      };
    }

    const actualInMin = (shift.overnight && rawInMin < 480 && schedStartMin >= 960 && (!opts.inSameCalendarDay))
      ? (rawInMin + 1440)
      : rawInMin;
    const graceMin = Math.max(0, Number(shift.grace_min != null ? shift.grace_min : 10));
    const rawLateIn = shift.isWorkday ? Math.max(0, actualInMin - schedStartMin) : 0;
    const arrivalLateMin = rawLateIn > graceMin ? rawLateIn : 0;

    const rawOutMin = parseClockMinutes(outTime);
    if (rawOutMin == null) {
      return {
        shift,
        rule,
        hasOut: false,
        scheduledHours,
        workedHours: 0,
        regularHours: 0,
        lateHours: round1(arrivalLateMin / 60),
        arrivalLateMin,
        earlyLeaveMin: 0,
        rawExtraHours: 0,
        overtimeHours: 0,
        unapprovedOtHours: 0,
        otReason: ''
      };
    }

    let actualOutMin = rawOutMin;
    if (opts.outDate && /^\d{4}-\d{2}-\d{2}$/.test(String(opts.outDate).slice(0, 10)) && String(opts.outDate).slice(0, 10) > dStr) {
      const diffDays = Math.max(1, Math.round((Date.parse(String(opts.outDate).slice(0, 10) + 'T00:00:00Z') - Date.parse(dStr + 'T00:00:00Z')) / 86400000));
      actualOutMin = rawOutMin + diffDays * 1440;
      if (actualOutMin <= actualInMin) actualOutMin += 1440;
    } else if (actualOutMin <= actualInMin) {
      actualOutMin += 1440;
    }

    const workedMin = Math.max(0, Math.min(24 * 60, actualOutMin - actualInMin));
    const workedHours = round1(workedMin / 60);

    let inWindowMin = 0;
    let earlyLeaveMin = 0;
    let extraIntervals = [];
    if (!shift.isWorkday) {
      extraIntervals = [[actualInMin, actualOutMin]];
    } else {
      inWindowMin = intervalOverlapMinutes(actualInMin, actualOutMin, schedStartMin, schedEndMin);
      const rawEarlyOut = Math.max(0, schedEndMin - actualOutMin);
      earlyLeaveMin = rawEarlyOut > 5 ? rawEarlyOut : 0;
      if ((schedStartMin - actualInMin) >= 15) {
        extraIntervals.push([actualInMin, Math.min(actualOutMin, schedStartMin)]);
      }
      if ((actualOutMin - schedEndMin) >= 10) {
        extraIntervals.push([Math.max(actualInMin, schedEndMin), actualOutMin]);
      }
    }

    const rawExtraMin = extraIntervals.reduce((acc, [s, e]) => acc + Math.max(0, e - s), 0);
    const rawExtraHours = round1(rawExtraMin / 60);
    const lateHours = round1((arrivalLateMin + earlyLeaveMin) / 60);

    let approvedOtMin = 0;
    let otReason = '';
    const activePass = (rule.ot_passes || []).find(p => p && p.start_date <= dStr && dStr <= (p.end_date || p.start_date)) || null;

    if (activePass && (rule.ot_mode === 'date_range' || rule.ot_mode === 'none')) {
      const capMin = Number(activePass.max_hours || 0) > 0 ? Math.round(Number(activePass.max_hours) * 60) : Infinity;
      approvedOtMin = Math.min(rawExtraMin, capMin);
      otReason = activePass.start_date === (activePass.end_date || activePass.start_date)
        ? `Approved OT (${fmtDateDMY(activePass.start_date)})`
        : `Approved OT (${fmtDateDMY(activePass.start_date)} to ${fmtDateDMY(activePass.end_date)})`;
    } else if (rule.ot_mode === 'always') {
      approvedOtMin = rawExtraMin;
      otReason = 'Anytime OT authorized';
    } else if (rule.ot_mode === 'max_hours') {
      let eligibleMin = rawExtraMin;
      const winS = parseClockMinutes(rule.ot_window_start);
      const winE = parseClockMinutes(rule.ot_window_end);
      if (winS != null && winE != null) {
        const wEndBase = winE <= winS ? (winE + 1440) : winE;
        let winOverlap = 0;
        extraIntervals.forEach(([es, ee]) => {
          winOverlap += intervalOverlapMinutes(es, ee, winS, wEndBase);
          winOverlap += intervalOverlapMinutes(es, ee, winS + 1440, wEndBase + 1440);
        });
        eligibleMin = Math.min(rawExtraMin, winOverlap);
      }
      const capMin = Number(rule.ot_max_hours || 0) > 0 ? Math.round(Number(rule.ot_max_hours) * 60) : Infinity;
      approvedOtMin = Math.min(eligibleMin, capMin);
      otReason = capMin < Infinity ? `OT cap ${round1(capMin / 60)}h/day` : 'OT window';
    } else if (rule.ot_mode === 'date_range') {
      approvedOtMin = 0;
      otReason = rawExtraMin > 0 ? 'Outside approved OT dates' : 'Date-range OT';
    } else {
      approvedOtMin = 0;
      otReason = rawExtraMin > 0 ? 'Unapproved late clock-out (No OT)' : 'No Overtime';
    }

    const overtimeHours = round1(approvedOtMin / 60);
    const unapprovedOtHours = round1(Math.max(0, rawExtraHours - overtimeHours));
    const regularHours = shift.isWorkday ? round1(inWindowMin / 60) : 0;

    return {
      shift,
      rule,
      hasOut: true,
      isOvernight: actualOutMin >= 1440 && actualInMin < 1440,
      scheduledHours,
      workedHours,
      regularHours,
      lateHours,
      arrivalLateMin,
      earlyLeaveMin,
      rawExtraHours,
      overtimeHours,
      unapprovedOtHours,
      otReason
    };
  }

  function inferShiftDateForInPunch(staffName, company, punchDate, punchTime) {
    const dStr = String(punchDate || todayISO()).slice(0, 10);
    const tMin = parseClockMinutes(punchTime);
    if (tMin != null && tMin < 360) {
      const prevDate = shiftIsoDateByDays(dStr, -1);
      const prevShift = resolveStaffShiftForDate(staffName, company, prevDate);
      if (prevShift && prevShift.overnight) {
        const endMin = parseClockMinutes(prevShift.end_time) ?? 180;
        if (tMin <= endMin + 120) {
          return prevDate;
        }
      }
    }
    return dStr;
  }

  function isPunchActiveOnSite(punch, nowMs = Date.now()) {
    if (!punch || punch.voided || punch.direction !== 'IN') return false;
    const pMs = Date.parse(punch.iso || '') || 0;
    if (!pMs) return punch.date === todayISO();
    const elapsedHrs = (nowMs - pMs) / 3600000;
    return elapsedHrs >= -1 && elapsedHrs <= 18;
  }

  function isGenericTerminalSeat(u) {
    if (!u) return true;
    const idStr = String(u.id || '').trim();
    const nmStr = String(u.full_name || '').trim();
    if (/^(u4|u5|u6|u7|u8|u9|u10)$/i.test(idStr)) return true;
    return /\b(weighbridge|site dispatch|batching desk|site supervisor|fleet controller|garage officer|collector|kiosk|terminal)\b/i.test(nmStr);
  }

  function isEmploymentActiveToday(emp, refDate = todayISO()) {
    if (!emp || emp.voided) return false;
    if (emp.status === 'Ended' || emp.status === 'Inactive' || emp.status === 'Terminated') return false;
    if (emp.end_date && String(emp.end_date).slice(0, 10) < refDate) return false;
    return true;
  }

  function getStaffFaceSamplesAndThumbs(staffName, userObj = null) {
    const k = norm(staffName);
    const bio = (k && STATE.staffBiometrics && typeof STATE.staffBiometrics === 'object') ? STATE.staffBiometrics[k] : null;
    const bioCleared = Boolean(bio && bio.face_cleared);
    const bioSamples = (!bioCleared && bio && Array.isArray(bio.face_samples))
      ? bio.face_samples.filter(s => Array.isArray(s) && s.length === 128)
      : [];
    const bioThumbs = (!bioCleared && bio && Array.isArray(bio.face_thumbs)) ? bio.face_thumbs.slice(0, 3) : [];
    if (bioSamples.length) return { samples: bioSamples, thumbs: bioThumbs };
    if (userObj && !bioCleared) {
      const uSamples = userFaceSamples(userObj);
      if (uSamples.length) return { samples: uSamples, thumbs: userFaceThumbs(userObj) };
    }
    return { samples: [], thumbs: [] };
  }

  async function enrolStaffFacePose(staffName, detOrVec, thumbStr = '', slotOverride = null) {
    const dir = getKioskStaffDirectory();
    const entry = dir.find(s => norm(s.name) === norm(staffName));
    if (!entry) return { ok: false, reason: 'no-staff', error: 'Staff member not found in active roster' };

    const rawDesc = (detOrVec && detOrVec.descriptor) ? detOrVec.descriptor : detOrVec;
    if (!rawDesc || (rawDesc.length !== 128)) {
      return { ok: false, reason: 'no-face', error: 'Valid 128-d face descriptor required' };
    }
    const vecArr = Array.from(rawDesc);

    const others = usableFaces(null, { includeKioskStaff: true }).filter(x => {
      if (norm(x.name) === norm(entry.name)) return false;
      if (entry.email && x.email && norm(x.email) === norm(entry.email)) return false;
      return true;
    });
    if (others.length && window.Face && window.Face.match) {
      const dupMatch = window.Face.match(vecArr, others);
      const thr = Number(STATE.faceSettings.threshold || 0.50);
      if (dupMatch.best && dupMatch.bestDist <= thr) {
        return {
          ok: false,
          reason: 'duplicate-person',
          other: dupMatch.best.name,
          dist: dupMatch.bestDist,
          error: `This face is already enrolled under ${dupMatch.best.name}. Each staff member must have a unique Face ID.`
        };
      }
    }

    const cur = getStaffFaceSamplesAndThumbs(entry.name, entry.userObj);
    const samples = cur.samples.slice(0, 3);
    const thumbs = cur.thumbs.slice(0, 3);
    const isSlot = typeof slotOverride === 'number' && slotOverride >= 0 && slotOverride < 3;
    let usedSlot = samples.length;
    if (isSlot && slotOverride < samples.length) {
      usedSlot = slotOverride;
      samples[usedSlot] = vecArr;
      thumbs[usedSlot] = thumbStr || thumbs[usedSlot] || '';
    } else if (samples.length >= 3) {
      samples.length = 0;
      thumbs.length = 0;
      samples.push(vecArr);
      thumbs.push(thumbStr || '');
      usedSlot = 0;
    } else {
      samples.push(vecArr);
      thumbs.push(thumbStr || '');
      usedSlot = samples.length - 1;
    }

    const nowIso = new Date().toISOString();
    const targetKey = norm(entry.name);
    if (!STATE.staffBiometrics || typeof STATE.staffBiometrics !== 'object') STATE.staffBiometrics = {};
    const bioObj = Object.assign({}, STATE.staffBiometrics[targetKey] || {}, {
      name: entry.name,
      company: entry.company,
      role: entry.role,
      face_samples: samples,
      face_thumbs: thumbs,
      face_cleared: false,
      face_updated_at: nowIso,
      updated_at: nowIso
    });
    STATE.staffBiometrics[targetKey] = bioObj;

    if (entry.userObj) {
      entry.userObj.face_samples = samples.slice();
      entry.userObj.face_thumbs = thumbs.slice();
      entry.userObj.face_required = true;
      entry.userObj.face_cleared = false;
      entry.userObj.face_updated_at = nowIso;
    }

    saveLocalAuthAndRecords();
    await persistStaffBiometricEntryNow(targetKey, bioObj);
    if (entry.userObj && HAS_LOCAL_API) {
      try { await fetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: entry.userObj }) }); } catch (_) {}
    }
    syncWithCloud(true);
    return { ok: true, staff: entry.name, count: samples.length, slot: usedSlot };
  }

  async function clearStaffFaceId(staffName) {
    const dir = getKioskStaffDirectory();
    const entry = dir.find(s => norm(s.name) === norm(staffName));
    if (!entry) return { ok: false, error: 'Staff member not found' };
    const nowIso = new Date().toISOString();
    const targetKey = norm(entry.name);
    if (!STATE.staffBiometrics || typeof STATE.staffBiometrics !== 'object') STATE.staffBiometrics = {};
    const bioObj = Object.assign({}, STATE.staffBiometrics[targetKey] || {}, {
      name: entry.name,
      company: entry.company,
      role: entry.role,
      face_samples: [],
      face_thumbs: [],
      face_cleared: true,
      face_updated_at: nowIso,
      updated_at: nowIso
    });
    STATE.staffBiometrics[targetKey] = bioObj;
    if (entry.userObj) {
      entry.userObj.face_samples = [];
      entry.userObj.face_thumbs = [];
      entry.userObj.face_required = false;
      entry.userObj.face_cleared = true;
      entry.userObj.face_updated_at = nowIso;
    }
    saveLocalAuthAndRecords();
    await persistStaffBiometricEntryNow(targetKey, bioObj);
    if (entry.userObj && HAS_LOCAL_API) {
      try { await fetch('./api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user: entry.userObj }) }); } catch (_) {}
    }
    syncWithCloud(true);
    return { ok: true, staff: entry.name };
  }

  function getKioskStaffDirectory(opts = {}) {
    const out = [];
    const seen = new Set();
    const usedPins = new Set();
    const allowedCos = allowedCompanyNames();
    const defCo = defaultEntryCompany();
    const scopedCo = opts.scopeBySelectedCompany ? (COMPANY_BU_MATCH[STATE.company] || '') : '';
    const today = todayISO();
    const bioMap = (STATE.staffBiometrics && typeof STATE.staffBiometrics === 'object') ? STATE.staffBiometrics : {};

    const humanUsersByNorm = new Map();
    (STATE.users || []).forEach(u => {
      if (!u || u.status === 'Suspended' || isGenericTerminalSeat(u)) return;
      const nm = String(u.full_name || '').trim();
      const k = norm(nm);
      if (!k) return;
      if (!humanUsersByNorm.has(k)) humanUsersByNorm.set(k, u);
      const up = String(u.pin_code || '').trim();
      if (/^\d{4}$/.test(up)) usedPins.add(up);
    });
    Object.values(bioMap).forEach(b => {
      const bp = String((b && b.pin_code) || '').trim();
      if (/^\d{4}$/.test(bp)) usedPins.add(bp);
    });

    const makeDemoPin = k => {
      let h = 0;
      for (let i = 0; i < k.length; i++) h = (h * 31 + k.charCodeAt(i)) % 8900;
      let cand = 1050 + Math.abs(h);
      while (usedPins.has(String(cand).slice(0, 4)) || cand === 2401) {
        cand = ((cand - 1000 + 7) % 8999) + 1000;
      }
      const p = String(cand).slice(0, 4);
      usedPins.add(p);
      return p;
    };

    // 1. Active Contract Workforce per Company (exact parity with Payroll & Workforce Active Staff)
    const activeEmps = [];
    (SEED.records.employments || []).concat(STATE.customRecords.employments || []).forEach(emp => {
      if (!isEmploymentActiveToday(emp, today)) return;
      const nm = String(emp.staff || emp.name || '').trim();
      const k = norm(nm);
      if (!k || nm === '(Unassigned)') return;
      const empCo = emp.company || 'WTC';
      if (allowedCos.length && !allowedCos.includes(empCo)) return;
      if (scopedCo && empCo !== scopedCo) return;
      activeEmps.push({ emp, nm, k, empCo });
    });

    // 2. Named Human Seats (Owner / Supervisor / Entry individuals, excluding generic terminal accounts)
    (STATE.users || []).forEach(u => {
      if (!u || u.status === 'Suspended' || isGenericTerminalSeat(u)) return;
      const nm = String(u.full_name || '').trim();
      const k = norm(nm);
      if (!k || seen.has(k)) return;
      const uCos = parseUserCompanies(u);
      const matchingEmp = activeEmps.find(x => x.k === k);
      if (scopedCo) {
        const hasCoAccess = Boolean(matchingEmp) || uCos.includes(scopedCo) || isAdminUser(u);
        if (!hasCoAccess) return;
      } else if (allowedCos.length && uCos.length && !uCos.some(c => allowedCos.includes(c)) && !isAdminUser(u)) {
        return;
      }
      seen.add(k);
      const bio = bioMap[k] || null;
      const co = matchingEmp
        ? matchingEmp.empCo
        : ((scopedCo && (uCos.includes(scopedCo) || isAdminUser(u)))
          ? scopedCo
          : (uCos.find(c => allowedCos.includes(c)) || uCos[0] || defCo));
      const explicitPin = String((bio && bio.pin_code) || u.pin_code || '').trim();
      const faceInfo = getStaffFaceSamplesAndThumbs(nm, u);
      const shiftToday = resolveStaffShiftForDate(nm, co, today);
      const otToday = describeStaffOvertimeRule(nm, co, today);
      out.push({
        id: u.id,
        name: nm,
        email: u.email || '',
        company: co,
        role: matchingEmp ? (matchingEmp.emp.role || matchingEmp.emp.type || u.role || 'Staff') : (u.role || 'Management'),
        schedHours: shiftToday.hours || staffScheduledHours(nm, co),
        shift: shiftToday,
        otDesc: otToday,
        pin: explicitPin || (IS_DEMO ? makeDemoPin(k) : ''),
        hasExplicitPin: Boolean(explicitPin),
        hasFace: faceInfo.samples.length > 0,
        faceCount: faceInfo.samples.length,
        hasActiveContract: Boolean(matchingEmp),
        userObj: u
      });
    });

    // 3. Remaining Active Contract Employees ($0 ERP login seat required)
    activeEmps
      .slice()
      .sort((a, b) => a.nm.localeCompare(b.nm))
      .forEach(({ emp, nm, k, empCo }) => {
        if (seen.has(k)) return;
        seen.add(k);
        const u = humanUsersByNorm.get(k) || null;
        const bio = bioMap[k] || null;
        const explicitPin = String((bio && bio.pin_code) || (u && u.pin_code) || '').trim();
        const faceInfo = getStaffFaceSamplesAndThumbs(nm, u);
        const shiftToday = resolveStaffShiftForDate(nm, empCo, today);
        const otToday = describeStaffOvertimeRule(nm, empCo, today);
        out.push({
          id: emp.id || ('emp-' + k),
          name: nm,
          email: u ? (u.email || '') : '',
          company: empCo,
          role: emp.role || emp.type || 'Active Staff',
          schedHours: shiftToday.hours || Number(emp.working_hours || 0) || staffScheduledHours(nm, empCo),
          shift: shiftToday,
          otDesc: otToday,
          pin: explicitPin || (IS_DEMO ? makeDemoPin(k) : ''),
          hasExplicitPin: Boolean(explicitPin),
          hasFace: faceInfo.samples.length > 0,
          faceCount: faceInfo.samples.length,
          hasActiveContract: true,
          userObj: u
        });
      });

    return out;
  }

  function setKioskStaffPin(staffName, rawPin) {
    const dir = getKioskStaffDirectory();
    const entry = dir.find(s => norm(s.name) === norm(staffName));
    if (!entry) return { ok: false, error: 'Staff member not found in active roster' };
    const clean = String(rawPin == null ? '' : rawPin).trim();
    if (clean !== '' && !/^\d{4}$/.test(clean)) {
      return { ok: false, error: 'PIN must be exactly 4 digits (0000 to 9999)' };
    }
    if (clean === '2401') {
      return { ok: false, error: 'PIN 2401 is reserved for unlocking Locked Kiosk Mode' };
    }
    const targetKey = norm(entry.name);
    if (clean) {
      const clash = dir.find(s => norm(s.name) !== targetKey && s.hasExplicitPin && String(s.pin) === clean);
      if (clash) {
        return { ok: false, error: `PIN ${clean} is already assigned to ${clash.name}` };
      }
    }
    if (!STATE.staffBiometrics || typeof STATE.staffBiometrics !== 'object') STATE.staffBiometrics = {};
    const nowIso = new Date().toISOString();
    const bioObj = Object.assign({}, STATE.staffBiometrics[targetKey] || {}, {
      name: entry.name,
      company: entry.company,
      role: entry.role,
      pin_code: clean,
      updated_at: nowIso
    });
    STATE.staffBiometrics[targetKey] = bioObj;
    if (entry.userObj) {
      entry.userObj.pin_code = clean;
      entry.userObj.seat_updated_at = nowIso;
    }
    STATE.kioskEditingPinStaff = '';
    saveLocalAuthAndRecords();
    persistStaffBiometricEntryNow(targetKey, bioObj);
    syncWithCloud(true);
    return { ok: true, staff: entry.name, pin: clean };
  }

  function getStaffLastPunch(staffName) {
    const k = norm(staffName);
    if (!k) return null;
    return (STATE.kioskPunches || []).find(p => p && !p.voided && norm(p.staff) === k) || null;
  }

  function inferNextPunchDirection(staffName, refMs = Date.now()) {
    if (STATE.kioskAttDir === 'in') return 'IN';
    if (STATE.kioskAttDir === 'out') return 'OUT';
    const last = getStaffLastPunch(staffName);
    return isPunchActiveOnSite(last, refMs) ? 'OUT' : 'IN';
  }

  function syncAttendanceRecordFromPunch(punch) {
    if (!punch || !punch.staff) return null;
    if (!Array.isArray(STATE.customRecords.attendance)) STATE.customRecords.attendance = [];
    const staffNorm = norm(punch.staff);
    const shiftDateStr = String(punch.shift_date || punch.date || todayISO()).slice(0, 10);
    const coName = punch.company || defaultEntryCompany();
    const shiftObj = resolveStaffShiftForDate(punch.staff, coName, shiftDateStr);
    const schedH = shiftObj.isWorkday ? (shiftObj.hours || staffScheduledHours(punch.staff, coName, shiftDateStr)) : 0;

    let attRec = STATE.customRecords.attendance.find(a =>
      a && !a.voided
      && norm(a.staff) === staffNorm
      && String(a.set_date || a.date || '').slice(0, 10) === shiftDateStr
      && !/^(extra|config)/i.test(String(a.type || a.status || ''))
    );

    if (!attRec) {
      const inT = punch.direction === 'IN' ? punch.time : (punch.in_time || '');
      const outT = punch.direction === 'OUT' ? punch.time : '';
      const evalRes = evaluateShiftPunchTiming(punch.staff, coName, shiftDateStr, inT, outT, { outDate: punch.date });
      const workedH = punch.paired_hours != null ? punch.paired_hours : evalRes.workedHours;
      const otH = punch.overtime_hours != null ? punch.overtime_hours : evalRes.overtimeHours;
      const ltH = punch.late_hours != null ? punch.late_hours : evalRes.lateHours;
      const unappOt = punch.unapproved_ot_hours != null ? punch.unapproved_ot_hours : evalRes.unapprovedOtHours;
      const effType = otH > 0 ? 'Overtime' : (ltH > 0 ? 'Lateness' : 'Present');
      const noteParts = [`Kiosk ${punch.method} (${inT ? 'IN ' + inT : ''}${outT ? (inT ? ' · ' : '') + 'OUT ' + outT : ''})`];
      noteParts.push(shiftObj.badgeLabel);
      if (unappOt > 0) noteParts.push(`${fmtNum(unappOt, 1)}h unapproved OT (0h paid)`);
      attRec = {
        id: uid('at'),
        date: shiftDateStr,
        rep_date: shiftDateStr,
        set_date: shiftDateStr,
        month: shiftDateStr.slice(0, 7),
        company: coName,
        name: `ATT ${shiftDateStr} ${punch.staff}`,
        staff: punch.staff,
        type: effType,
        status: effType,
        shift_id: shiftObj.id,
        shift_label: shiftObj.badgeLabel,
        scheduled_hours: schedH,
        in_time: inT,
        out_time: outT,
        check_in: inT,
        check_out: outT,
        worked_hours: workedH,
        regular_hours: evalRes.hasOut ? evalRes.regularHours : (workedH > 0 ? Math.min(schedH, workedH) : 0),
        overtime_hours: otH,
        unapproved_ot_hours: unappOt,
        late_hours: ltH,
        tally: otH > 0 ? otH : (ltH > 0 ? ltH : workedH),
        source: 'app',
        entered_by: activeUser().full_name,
        entered_by_email: activeUser().email,
        entered_at: nowStamp(),
        voided: false,
        notes: noteParts.join(' · ')
      };
      STATE.customRecords.attendance.unshift(attRec);
    } else {
      if (punch.direction === 'IN') {
        attRec.check_in = punch.time;
        attRec.in_time = punch.time;
        attRec.out_time = '';
        attRec.check_out = '';
        const evalIn = evaluateShiftPunchTiming(punch.staff, coName, shiftDateStr, punch.time, '');
        attRec.worked_hours = 0;
        attRec.regular_hours = 0;
        attRec.overtime_hours = 0;
        attRec.unapproved_ot_hours = 0;
        attRec.late_hours = punch.late_hours != null ? punch.late_hours : evalIn.lateHours;
        attRec.type = attRec.late_hours > 0 ? 'Lateness' : 'Present';
        attRec.status = attRec.type;
        attRec.tally = attRec.late_hours > 0 ? attRec.late_hours : 0;
      } else if (punch.direction === 'OUT') {
        attRec.check_out = punch.time;
        attRec.out_time = punch.time;
        if (!attRec.in_time && punch.in_time) {
          attRec.in_time = punch.in_time;
          attRec.check_in = punch.in_time;
        }
        const inTimeRef = attRec.in_time || attRec.check_in || '';
        const evalOut = inTimeRef
          ? evaluateShiftPunchTiming(punch.staff, coName, shiftDateStr, inTimeRef, punch.time, { outDate: punch.date })
          : null;
        const workedH = punch.paired_hours != null ? punch.paired_hours : (evalOut ? evalOut.workedHours : 0);
        const otH = punch.overtime_hours != null ? punch.overtime_hours : (evalOut ? evalOut.overtimeHours : 0);
        const ltH = punch.late_hours != null ? punch.late_hours : (evalOut ? evalOut.lateHours : 0);
        const unappOt = punch.unapproved_ot_hours != null ? punch.unapproved_ot_hours : (evalOut ? evalOut.unapprovedOtHours : 0);
        attRec.worked_hours = workedH;
        attRec.regular_hours = evalOut && evalOut.hasOut ? evalOut.regularHours : Math.round(Math.min(schedH, workedH) * 10) / 10;
        attRec.overtime_hours = otH;
        attRec.unapproved_ot_hours = unappOt;
        attRec.late_hours = ltH;
        attRec.type = otH > 0 ? 'Overtime' : (ltH > 0 ? 'Lateness' : 'Present');
        attRec.status = attRec.type;
        attRec.tally = otH > 0 ? otH : (ltH > 0 ? ltH : workedH);
      }
      attRec.shift_id = shiftObj.id;
      attRec.shift_label = shiftObj.badgeLabel;
      attRec.scheduled_hours = schedH;
      const noteParts = [`Kiosk ${punch.method} (${attRec.check_in ? 'IN ' + attRec.check_in : ''}${attRec.check_out ? ' · OUT ' + attRec.check_out : ''})`];
      noteParts.push(shiftObj.badgeLabel);
      if (attRec.unapproved_ot_hours > 0) noteParts.push(`${fmtNum(attRec.unapproved_ot_hours, 1)}h unapproved OT (0h paid)`);
      attRec.notes = noteParts.join(' · ');
    }
    applyCustomRecordsToSeed();
    saveLocalAuthAndRecords();
    return attRec;
  }

  function recordKioskAttendancePunch(opts = {}) {
    const dirList = getKioskStaffDirectory();
    const staffRaw = String(opts.staff || STATE.kioskAttStaff || '').trim();
    const staffEntry = staffRaw
      ? dirList.find(s => norm(s.name) === norm(staffRaw))
      : null;
    if (!staffEntry) {
      toast('Enter your 4-digit PIN or select a staff member', 'err');
      return { ok: false, reason: 'no-staff' };
    }
    const staffName = staffEntry.name;
    const coName = staffEntry.company || defaultEntryCompany();
    const nowWallMs = Date.now();
    const hasCustomClock = Boolean(opts.date || opts.time);
    const defaultNowObj = new Date(nowWallMs);
    const timeStr = fmtAttClockTime(opts.time || defaultNowObj.toTimeString().slice(0, 5)) || defaultNowObj.toTimeString().slice(0, 5);
    const dateStr = String(opts.date || todayISO()).slice(0, 10);
    const punchDateObj = hasCustomClock ? buildLocalPunchDateObj(dateStr, timeStr, nowWallMs) : defaultNowObj;
    const punchMs = punchDateObj.getTime();
    const last = getStaffLastPunch(staffName);

    // Configurable anti-double-punch debounce guard (default 120s)
    const punchDebounceSec = isAlertRuleEnabled('G_KIOSK_PUNCH') ? getAlertParam('G_KIOSK_PUNCH', 'debounce_sec', 120) : 0;
    if (!opts.bypassDebounce && punchDebounceSec > 0 && last && last.iso) {
      const prevMs = Date.parse(last.iso) || 0;
      const ageSec = Math.round((punchMs - prevMs) / 1000);
      if (prevMs > 0 && ageSec >= 0 && ageSec < punchDebounceSec) {
        STATE.kioskLastPunch = last;
        STATE.kioskAttPin = '';
        STATE.kioskAttPinMsg = `${staffName} already clocked ${last.direction} ${ageSec}s ago. Use Switch to ${last.direction === 'IN' ? 'OUT' : 'IN'} if needed.`;
        STATE.kioskAttPinMsgCls = 'warn';
        toast(`${staffName} already clocked ${last.direction} ${ageSec}s ago. Tap Switch to ${last.direction === 'IN' ? 'OUT' : 'IN'} if needed.`, 'warn');
        if (STATE.view === 'kiosks') renderApp();
        return { ok: false, reason: 'debounced', punch: last, ageSec };
      }
    }

    const direction = opts.direction || inferNextPunchDirection(staffName, punchMs);
    const siteStr = String(opts.site || STATE.kioskAttSite || 'WTC Main Plant');

    let shiftDate = dateStr;
    let inTimeRef = '';
    let pairedHours = null;
    let overtimeHours = 0;
    let unapprovedOtHours = 0;
    let lateHours = 0;
    let shiftMeta = null;

    if (direction === 'IN') {
      shiftDate = inferShiftDateForInPunch(staffName, coName, dateStr, timeStr);
      const evalIn = evaluateShiftPunchTiming(staffName, coName, shiftDate, timeStr, '', { inSameCalendarDay: shiftDate === dateStr });
      shiftMeta = evalIn.shift;
      lateHours = evalIn.lateHours;
    } else {
      const openIn = (STATE.kioskPunches || []).find(p => {
        if (!p || p.voided || norm(p.staff) !== norm(staffName) || p.direction !== 'IN') return false;
        const pMs = Date.parse(p.iso || '') || 0;
        if (!pMs) return true;
        const hrs = (punchMs - pMs) / 3600000;
        return hrs >= -0.5 && hrs <= 22;
      }) || null;

      if (openIn) {
        shiftDate = String(openIn.shift_date || openIn.date || dateStr).slice(0, 10);
        inTimeRef = openIn.time || '';
        const evalOut = evaluateShiftPunchTiming(staffName, coName, shiftDate, inTimeRef, timeStr, { outDate: dateStr });
        shiftMeta = evalOut.shift;
        pairedHours = evalOut.workedHours;
        overtimeHours = evalOut.overtimeHours;
        unapprovedOtHours = evalOut.unapprovedOtHours;
        lateHours = evalOut.lateHours;
      } else {
        shiftMeta = resolveStaffShiftForDate(staffName, coName, dateStr);
        pairedHours = shiftMeta.hours || 8.0;
        overtimeHours = 0;
        unapprovedOtHours = 0;
        lateHours = 0;
      }
    }

    const punch = {
      id: uid('pn'),
      staff: staffName,
      company: coName,
      role: staffEntry.role || 'Staff',
      site: siteStr,
      direction,
      date: dateStr,
      shift_date: shiftDate,
      shift_id: shiftMeta ? shiftMeta.id : 'day_8_4',
      shift_label: shiftMeta ? shiftMeta.badgeLabel : 'Day · 08:00-16:00',
      in_time: direction === 'OUT' ? inTimeRef : timeStr,
      time: timeStr,
      iso: punchDateObj.toISOString(),
      method: opts.method || 'PIN',
      confidence: opts.confidence != null ? Number(opts.confidence) : null,
      snapshot: opts.snapshot || KIOSK_ATT_STATE.lastSnap || '',
      paired_hours: pairedHours,
      overtime_hours: overtimeHours,
      unapproved_ot_hours: unapprovedOtHours,
      late_hours: lateHours,
      voided: false
    };

    if (!Array.isArray(STATE.kioskPunches)) STATE.kioskPunches = [];
    STATE.kioskPunches.unshift(punch);
    STATE.kioskLastPunch = punch;
    STATE.kioskAttPin = '';
    STATE.kioskAttStaff = '';
    const otSummaryTxt = pairedHours != null
      ? (overtimeHours > 0
        ? ` · ${pairedHours}h (+${overtimeHours}h OT)`
        : (unapprovedOtHours > 0 ? ` · ${pairedHours}h (0h OT, No OT rule)` : ` · ${pairedHours}h`))
      : (lateHours > 0 ? ` · Late ${lateHours}h` : '');
    STATE.kioskAttPinMsg = `${staffName} clocked ${direction} at ${timeStr}${otSummaryTxt}`;
    STATE.kioskAttPinMsgCls = 'ok';
    const attRec = syncAttendanceRecordFromPunch(punch);
    if (STATE.faceSettings.sound && window.Face && window.Face.Sound) {
      window.Face.Sound.play('ok');
    }
    toast(`${staffName} clocked ${direction} at ${timeStr} (${punch.method})${otSummaryTxt}`, 'ok');
    if (STATE.view === 'kiosks') renderApp();
    syncWithCloud(true);
    return { ok: true, punch, attRec };
  }

  function flipKioskPunchDirection(punchId) {
    const targetId = punchId || (STATE.kioskLastPunch && STATE.kioskLastPunch.id);
    const p = (STATE.kioskPunches || []).find(x => x && x.id === targetId) || (STATE.kioskPunches || [])[0];
    if (!p) return { ok: false, reason: 'not-found' };
    p.direction = p.direction === 'IN' ? 'OUT' : 'IN';
    const sMeta = resolveStaffShiftForDate(p.staff, p.company, p.shift_date || p.date);
    if (p.direction === 'OUT' && p.paired_hours == null) {
      p.paired_hours = sMeta.hours || 8.0;
      p.overtime_hours = 0;
      p.unapproved_ot_hours = 0;
    } else if (p.direction === 'IN') {
      p.paired_hours = null;
      p.overtime_hours = 0;
      p.unapproved_ot_hours = 0;
    }
    p.rev = Number(p.rev || 0) + 1;
    p.updated_at = new Date().toISOString();
    STATE.kioskLastPunch = p;
    const attRec = syncAttendanceRecordFromPunch(p);
    toast(`Switched ${p.staff} punch to ${p.direction} (${p.time})`, 'ok');
    if (STATE.view === 'kiosks') renderApp();
    syncWithCloud(true);
    return { ok: true, punch: p, attRec };
  }

  function stopKioskAttCamera() {
    KIOSK_ATT_STATE.camActive = false;
    clearTimeout(KIOSK_ATT_STATE.loopTimer);
    KIOSK_ATT_STATE.loopTimer = null;
    KIOSK_ATT_STATE.busy = false;
    KIOSK_ATT_STATE.streakStaff = '';
    KIOSK_ATT_STATE.streakCount = 0;
    const v = $('kioskAttVideo');
    if (v && v.srcObject) {
      try { v.srcObject.getTracks().forEach(t => t.stop()); } catch (_) {}
      v.srcObject = null;
    }
  }

  async function startKioskAttCamera() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      KIOSK_ATT_STATE.statusText = 'Camera unavailable on this browser. Enter your 4-digit PIN on the keypad.';
      KIOSK_ATT_STATE.statusCls = 'warn';
      if (STATE.view === 'kiosks') renderApp();
      return false;
    }
    try {
      stopFaceCamera();
      const modelsP = ensureFaceModelsLoaded();
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } },
        audio: false
      });
      FACE_STATE.stream = stream;
      KIOSK_ATT_STATE.camActive = true;
      KIOSK_ATT_STATE.missedFrames = 0;
      KIOSK_ATT_STATE.statusText = 'Camera live: look straight ahead inside the oval guide';
      KIOSK_ATT_STATE.statusCls = 'ok';
      if (STATE.view === 'kiosks') renderApp();
      const v = $('kioskAttVideo');
      if (v) {
        v.srcObject = stream;
        await v.play().catch(() => {});
      }
      await modelsP;
      clearTimeout(KIOSK_ATT_STATE.loopTimer);
      KIOSK_ATT_STATE.loopTimer = setTimeout(kioskAttFaceTick, 20);
      return true;
    } catch (err) {
      KIOSK_ATT_STATE.camActive = false;
      KIOSK_ATT_STATE.statusText = 'Camera permission denied or busy. Enter your 4-digit PIN on the keypad.';
      KIOSK_ATT_STATE.statusCls = 'warn';
      if (STATE.view === 'kiosks') renderApp();
      return false;
    }
  }

  async function handleKioskAttDescriptor(det, opts = {}) {
    if (!det || !det.descriptor) {
      KIOSK_ATT_STATE.missedFrames = (KIOSK_ATT_STATE.missedFrames || 0) + 1;
      if (!opts.liveVideo || KIOSK_ATT_STATE.missedFrames >= 3) {
        KIOSK_ATT_STATE.streakStaff = '';
        KIOSK_ATT_STATE.streakCount = 0;
      }
      KIOSK_ATT_STATE.statusText = 'Position your face inside the oval guide to clock in or out';
      KIOSK_ATT_STATE.statusCls = '';
      return { ok: false, reason: 'no-face' };
    }
    KIOSK_ATT_STATE.missedFrames = 0;
    const pool = usableFaces(null, { includeKioskStaff: true });
    if (!pool.length || !window.Face) {
      KIOSK_ATT_STATE.statusText = 'No Face ID profiles enrolled yet. Use your 4-digit PIN or Enrol Face / PIN.';
      KIOSK_ATT_STATE.statusCls = 'warn';
      return { ok: false, reason: 'no-pool' };
    }
    const m = window.Face.match(det.descriptor, pool);
    const thr = Number(STATE.faceSettings.threshold || 0.50);
    const dec = window.Face.decide(m, Object.assign({}, window.Face.CONFIG, { threshold: thr }), { faceSizeFrac: det.faceSizeFrac || 0.26 });
    if (!dec.ok || !dec.best) {
      KIOSK_ATT_STATE.missedFrames = (KIOSK_ATT_STATE.missedFrames || 0) + 1;
      if (!opts.liveVideo || KIOSK_ATT_STATE.missedFrames >= 3) {
        KIOSK_ATT_STATE.streakStaff = '';
        KIOSK_ATT_STATE.streakCount = 0;
      }
      KIOSK_ATT_STATE.statusText = 'Face not recognized. Hold steady or enter your 4-digit PIN.';
      KIOSK_ATT_STATE.statusCls = 'warn';
      return { ok: false, reason: dec.status };
    }

    const matchedName = dec.best.name;
    if (KIOSK_ATT_STATE.streakStaff === matchedName) {
      KIOSK_ATT_STATE.streakCount += 1;
    } else {
      KIOSK_ATT_STATE.streakStaff = matchedName;
      KIOSK_ATT_STATE.streakCount = 1;
    }
    const needFrames = opts.instant ? 1 : (opts.liveVideo ? 2 : Math.max(2, Number(STATE.faceSettings.confirmFrames || 3)));
    if (KIOSK_ATT_STATE.streakCount < needFrames) {
      KIOSK_ATT_STATE.statusText = `Recognizing ${matchedName}...`;
      KIOSK_ATT_STATE.statusCls = 'ok';
      return { ok: false, reason: 'building-streak', streak: KIOSK_ATT_STATE.streakCount, needFrames, staff: matchedName };
    }

    KIOSK_ATT_STATE.streakCount = 0;
    if (opts.videoEl && window.Face && window.Face.snapshot) {
      KIOSK_ATT_STATE.lastSnap = window.Face.snapshot(opts.videoEl, 240) || '';
    }
    const conf = Math.max(0.75, Math.min(0.99, 1 - (m.bestDist || 0.2) * 0.6));
    const res = recordKioskAttendancePunch({
      staff: matchedName,
      method: 'Face ID',
      confidence: conf,
      snapshot: opts.snapshot || KIOSK_ATT_STATE.lastSnap || '',
      bypassDebounce: !!opts.bypassDebounce
    });
    KIOSK_ATT_STATE.statusText = res.ok
      ? `${matchedName} clocked ${res.punch.direction} at ${res.punch.time} (${(conf * 100).toFixed(0)}% match)`
      : `${matchedName} already clocked ${res.punch ? res.punch.direction : ''} (${res.ageSec || 0}s ago)`;
    KIOSK_ATT_STATE.statusCls = res.ok ? 'ok' : 'warn';
    return res;
  }

  async function kioskAttFaceTick() {
    if (STATE.view !== 'kiosks' || STATE.activeKiosk !== 'attendance' || !KIOSK_ATT_STATE.camActive) return;
    const v = $('kioskAttVideo');
    if (v && v.srcObject !== FACE_STATE.stream && streamAlive()) {
      v.srcObject = FACE_STATE.stream;
      v.play().catch(() => {});
    }
    if (v && v.readyState >= 2 && !KIOSK_ATT_STATE.busy && window.Face) {
      KIOSK_ATT_STATE.busy = true;
      try {
        const det = await window.Face.detectOne(v, false);
        await handleKioskAttDescriptor(det, { liveVideo: true, videoEl: v });
        const stEl = $('kioskAttCamStatus');
        if (stEl) {
          stEl.textContent = KIOSK_ATT_STATE.statusText;
          stEl.className = 'kiosk-att-status ' + (KIOSK_ATT_STATE.statusCls || '');
        }
      } catch (_) {}
      KIOSK_ATT_STATE.busy = false;
    }
    if (KIOSK_ATT_STATE.camActive && STATE.view === 'kiosks' && STATE.activeKiosk === 'attendance') {
      KIOSK_ATT_STATE.loopTimer = setTimeout(kioskAttFaceTick, 45);
    }
  }

  function sanitizeKioskPunchesState() {
    const raw = Array.isArray(STATE.kioskPunches) ? STATE.kioskPunches : [];
    const cleaned = sanitizeKioskPunchesList(raw);
    if (cleaned.length !== raw.length) {
      STATE.kioskPunches = cleaned;
      saveLocalAuthAndRecords();
    }
    if (STATE.kioskLastPunch && /^pn-seed-/.test(String(STATE.kioskLastPunch.id || ''))) {
      STATE.kioskLastPunch = STATE.kioskPunches[0] || null;
    }
  }

  function getScheduleWeekDates(weekOffset = 0) {
    const today = todayISO();
    const [y, m, d] = today.split('-').map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d));
    const dow = dt.getUTCDay(); // 0=Sun..6=Sat
    const diffToMon = dow === 0 ? -6 : (1 - dow);
    const monDt = new Date(Date.UTC(y, m - 1, d + diffToMon + (Number(weekOffset || 0) * 7)));
    const days = [];
    for (let i = 0; i < 7; i++) {
      const cur = new Date(Date.UTC(monDt.getUTCFullYear(), monDt.getUTCMonth(), monDt.getUTCDate() + i));
      const iso = cur.toISOString().slice(0, 10);
      const dayIdx = cur.getUTCDay();
      days.push({
        iso,
        dayIdx,
        short: ATT_WEEKDAYS[dayIdx] || '',
        dayNum: String(cur.getUTCDate()).padStart(2, '0'),
        monthShort: MONTH_SHORT_NAMES[cur.getUTCMonth()] || '',
        isToday: iso === today,
        isSunday: dayIdx === 0
      });
    }
    return days;
  }

  function formatWorkdaysCompact(daysArr) {
    if (!Array.isArray(daysArr) || !daysArr.length) return 'No Days';
    const sorted = Array.from(new Set(daysArr)).sort((a, b) => a - b);
    if (sorted.length === 7) return 'Mon-Sun';
    if (sorted.length === 6 && !sorted.includes(0)) return 'Mon-Sat';
    if (sorted.length === 5 && [1, 2, 3, 4, 5].every(x => sorted.includes(x))) return 'Mon-Fri';
    return sorted.map(d => ATT_WEEKDAYS[d] || '').filter(Boolean).join(', ');
  }

  function stopStaffEnrolModalCamera() {
    STAFF_FACE_MODAL_STATE.camActive = false;
    clearTimeout(STAFF_FACE_MODAL_STATE.loopTimer);
    STAFF_FACE_MODAL_STATE.loopTimer = null;
    STAFF_FACE_MODAL_STATE.busy = false;
    STAFF_FACE_MODAL_STATE.autoStreak = 0;
    const v = $('staffEnrolVideo');
    if (v && v.srcObject) {
      try { v.srcObject.getTracks().forEach(t => t.stop()); } catch (_) {}
      v.srcObject = null;
    }
    if (FACE_STATE.stream) {
      try { FACE_STATE.stream.getTracks().forEach(t => t.stop()); } catch (_) {}
      FACE_STATE.stream = null;
    }
  }

  function closeStaffFaceEnrolModal() {
    stopStaffEnrolModalCamera();
    STAFF_FACE_MODAL_STATE.open = false;
    const modal = $('staffFaceEnrolModal');
    if (modal) modal.hidden = true;
    document.body.classList.remove('modal-open');
    if (STATE.view === 'kiosks') renderApp();
  }

  async function staffEnrolModalTick() {
    if (!STAFF_FACE_MODAL_STATE.open || !STAFF_FACE_MODAL_STATE.camActive) return;
    const videoEl = $('staffEnrolVideo');
    const overlayEl = $('staffEnrolOverlay');
    const badgeEl = $('staffEnrolLiveBadge');
    if (videoEl && !STAFF_FACE_MODAL_STATE.busy && videoEl.readyState >= 2 && videoEl.videoWidth > 0 && window.Face) {
      STAFF_FACE_MODAL_STATE.busy = true;
      try {
        await ensureFaceModelsLoaded();
        const det = await window.Face.detectOne(videoEl, false);
        if (det && det.descriptor) {
          STAFF_FACE_MODAL_STATE.lastDet = det;
          STAFF_FACE_MODAL_STATE.lastAt = Date.now();
          if (window.Face.snapshot) STAFF_FACE_MODAL_STATE.lastSnap = window.Face.snapshot(videoEl);
        }
        if (overlayEl && window.Face.drawOverlay) {
          window.Face.drawOverlay(overlayEl, videoEl, det, det && det.descriptor ? '#22c55e' : '#D9A54A');
        }
        if (badgeEl) {
          if (det && det.descriptor) {
            const pct = Math.round(Math.max(0.74, Number(det.score || det.detScore || 0.9)) * 100);
            const cLen = STAFF_FACE_MODAL_STATE.captures.length;
            badgeEl.textContent = cLen < 3 ? `Face Locked · ${pct}% (Pose ${cLen + 1}/3)` : `3/3 Poses Saved · ${pct}%`;
            badgeEl.className = 'badge badge-ok';
          } else {
            badgeEl.textContent = 'Center face inside oval';
            badgeEl.className = 'badge';
          }
        }
        if (
          det && det.descriptor && !det.multiple
          && !navigator.webdriver && !window.__MFG_HEADLESS_TEST
          && STAFF_FACE_MODAL_STATE.captures.length < 3
          && Date.now() >= (STAFF_FACE_MODAL_STATE.nextAutoAt || 0)
        ) {
          const fracVal = det.faceSizeFrac != null ? det.faceSizeFrac : det.frac;
          const scoreVal = det.detScore != null ? det.detScore : det.score;
          if ((fracVal == null || fracVal >= Number(STATE.faceSettings.minFaceFrac || 0.14)) && (scoreVal == null || scoreVal >= 0.28)) {
            STAFF_FACE_MODAL_STATE.autoStreak = (STAFF_FACE_MODAL_STATE.autoStreak || 0) + 1;
            if (STAFF_FACE_MODAL_STATE.autoStreak >= 2) {
              STAFF_FACE_MODAL_STATE.autoStreak = 0;
              STAFF_FACE_MODAL_STATE.nextAutoAt = Date.now() + 900;
              await captureStaffModalPose(det, STAFF_FACE_MODAL_STATE.lastSnap || '');
            }
          } else {
            STAFF_FACE_MODAL_STATE.autoStreak = 0;
          }
        } else if (!det || !det.descriptor) {
          STAFF_FACE_MODAL_STATE.autoStreak = 0;
        }
      } catch (_) {}
      STAFF_FACE_MODAL_STATE.busy = false;
    }
    if (STAFF_FACE_MODAL_STATE.open && STAFF_FACE_MODAL_STATE.camActive) {
      STAFF_FACE_MODAL_STATE.loopTimer = setTimeout(staffEnrolModalTick, 60);
    }
  }

  async function startStaffEnrolModalCamera() {
    const videoEl = $('staffEnrolVideo');
    if (!videoEl) return false;
    stopKioskAttCamera();
    STAFF_FACE_MODAL_STATE.statusText = 'Starting front camera...';
    STAFF_FACE_MODAL_STATE.statusCls = '';
    STAFF_FACE_MODAL_STATE.autoStreak = 0;
    STAFF_FACE_MODAL_STATE.nextAutoAt = Date.now() + 300;
    syncStaffFaceEnrolModalDom();
    const modelsP = ensureFaceModelsLoaded().catch(() => {});
    const ok = await startFaceCamera(videoEl);
    await modelsP;
    STAFF_FACE_MODAL_STATE.camActive = ok;
    if (ok) {
      for (let i = 0; i < 12; i++) {
        if (videoEl.readyState >= 2 && videoEl.videoWidth > 0) break;
        await new Promise(r => setTimeout(r, 25));
      }
      clearTimeout(STAFF_FACE_MODAL_STATE.loopTimer);
      STAFF_FACE_MODAL_STATE.loopTimer = setTimeout(staffEnrolModalTick, 20);
      STAFF_FACE_MODAL_STATE.statusText = 'Hold steady for 3 quick poses: straight ahead, slightly left, slightly right.';
      STAFF_FACE_MODAL_STATE.statusCls = 'ok';
    } else {
      STAFF_FACE_MODAL_STATE.statusText = 'Camera unavailable or permission denied on this device.';
      STAFF_FACE_MODAL_STATE.statusCls = 'warn';
    }
    syncStaffFaceEnrolModalDom();
    return ok;
  }

  async function captureStaffModalPose(syntheticDet = null, syntheticThumb = '', slotOverride = null) {
    const staffName = STAFF_FACE_MODAL_STATE.staffName;
    if (!staffName) return { ok: false, reason: 'no-staff' };
    let det = syntheticDet;
    let thumb = syntheticThumb || '';
    if (!det) {
      let videoEl = $('staffEnrolVideo');
      if (!STAFF_FACE_MODAL_STATE.camActive || !streamAlive() || !videoEl || videoEl.readyState < 2) {
        const started = await startStaffEnrolModalCamera();
        videoEl = $('staffEnrolVideo');
        if (!started || !videoEl || videoEl.readyState < 2) {
          return { ok: false, reason: 'no-camera' };
        }
      }
      STAFF_FACE_MODAL_STATE.nextAutoAt = Date.now() + 950;
      if (STAFF_FACE_MODAL_STATE.lastDet && STAFF_FACE_MODAL_STATE.lastDet.descriptor && (Date.now() - (STAFF_FACE_MODAL_STATE.lastAt || 0)) < 1600) {
        det = STAFF_FACE_MODAL_STATE.lastDet;
        thumb = (window.Face && window.Face.snapshot && window.Face.snapshot(videoEl)) || STAFF_FACE_MODAL_STATE.lastSnap || '';
      } else if (window.Face) {
        await ensureFaceModelsLoaded();
        det = await window.Face.detectOne(videoEl, true);
        if (window.Face.snapshot) thumb = window.Face.snapshot(videoEl) || STAFF_FACE_MODAL_STATE.lastSnap || '';
      }
    }
    if (!det || !det.descriptor) {
      STAFF_FACE_MODAL_STATE.statusText = 'No face detected. Position face inside the oval guide and try again.';
      STAFF_FACE_MODAL_STATE.statusCls = 'warn';
      syncStaffFaceEnrolModalDom();
      return { ok: false, reason: 'no-face' };
    }
    if (det.multiple) {
      STAFF_FACE_MODAL_STATE.statusText = 'Multiple faces in frame. Only one staff member should be in view during enrolment.';
      STAFF_FACE_MODAL_STATE.statusCls = 'crit';
      syncStaffFaceEnrolModalDom();
      return { ok: false, reason: 'multiple' };
    }
    const res = await enrolStaffFacePose(staffName, det, thumb, slotOverride);
    if (!res.ok) {
      STAFF_FACE_MODAL_STATE.statusText = res.error || 'Could not enrol pose';
      STAFF_FACE_MODAL_STATE.statusCls = 'crit';
      syncStaffFaceEnrolModalDom();
      return res;
    }
    const dir = getKioskStaffDirectory();
    const entry = dir.find(s => norm(s.name) === norm(staffName));
    const faceInfo = getStaffFaceSamplesAndThumbs(staffName, entry ? entry.userObj : null);
    STAFF_FACE_MODAL_STATE.captures = faceInfo.samples;
    STAFF_FACE_MODAL_STATE.thumbs = faceInfo.thumbs;
    STAFF_FACE_MODAL_STATE.statusText = res.count >= 3
      ? `All 3 Face ID poses enrolled and ready for ${staffName}.`
      : `Saved Pose ${res.count} of 3 for ${staffName}.`;
    STAFF_FACE_MODAL_STATE.statusCls = 'ok';
    syncStaffFaceEnrolModalDom();
    if (!syntheticDet && res.count >= 3) toast(`Face ID enrolled for ${staffName} (3/3 poses)`, 'ok');
    return res;
  }

  function syncStaffFaceEnrolModalDom() {
    const modal = $('staffFaceEnrolModal');
    if (!modal || modal.hidden) return;
    const allStaff = getKioskStaffDirectory();
    const curEntry = allStaff.find(s => norm(s.name) === norm(STAFF_FACE_MODAL_STATE.staffName)) || allStaff[0] || null;
    if (curEntry) STAFF_FACE_MODAL_STATE.staffName = curEntry.name;
    const faceInfo = curEntry ? getStaffFaceSamplesAndThumbs(curEntry.name, curEntry.userObj) : { samples: [], thumbs: [] };
    STAFF_FACE_MODAL_STATE.captures = faceInfo.samples;
    STAFF_FACE_MODAL_STATE.thumbs = faceInfo.thumbs;
    const capCount = faceInfo.samples.length;

    const sel = $('staffEnrolSelect');
    if (sel) {
      Array.from(sel.options).forEach(opt => {
        const st = allStaff.find(x => norm(x.name) === norm(opt.value));
        if (st) {
          opt.textContent = `${st.name} · ${st.company} (${st.faceCount ? st.faceCount + '/3 Face ID' : 'No Face ID'}${st.hasExplicitPin ? ' · PIN Set' : ''})`;
          opt.selected = Boolean(curEntry && norm(st.name) === norm(curEntry.name));
        }
      });
    }
    const vp = $('staffEnrolViewport');
    if (vp) vp.classList.toggle('is-live', STAFF_FACE_MODAL_STATE.camActive);
    const ph = $('staffEnrolStandby');
    if (ph) ph.hidden = STAFF_FACE_MODAL_STATE.camActive;
    const camBtn = $('staffEnrolStartCamBtn');
    if (camBtn) camBtn.innerHTML = STAFF_FACE_MODAL_STATE.camActive ? 'Stop Camera' : `${ic('camera')} Start Camera`;
    const capBtn = $('staffEnrolCaptureBtn');
    if (capBtn) {
      capBtn.innerHTML = capCount >= 3
        ? `${ic('rotate')} Retake All 3 Poses`
        : `${ic('camera')} Capture Pose (${capCount + 1}/3)`;
    }
    const clrBtn = $('staffEnrolClearBtn');
    if (clrBtn) clrBtn.disabled = capCount === 0;
    const testBtn = $('staffEnrolTestBtn');
    if (testBtn) testBtn.disabled = capCount === 0;

    const poseGuide = $('staffEnrolPosePrompt');
    if (poseGuide) {
      const prompts = [
        'Pose 1 of 3: Look straight ahead at the camera',
        'Pose 2 of 3: Turn head slightly left while looking at camera',
        'Pose 3 of 3: Turn head slightly right while looking at camera'
      ];
      poseGuide.textContent = capCount >= 3
        ? 'Face ID profile complete (3/3 poses saved). Ready for hands-free Kiosk clock-in.'
        : prompts[capCount];
    }

    const strip = $('staffEnrolThumbs');
    if (strip) {
      const poseNames = ['1 · Straight', '2 · Slight Left', '3 · Slight Right'];
      strip.innerHTML = [0, 1, 2].map(idx => {
        const done = idx < capCount;
        const th = faceInfo.thumbs[idx] || '';
        return `
          <button type="button" class="staff-pose-slot ${done ? 'is-done' : (idx === capCount ? 'is-next' : '')}" data-staff-pose-slot="${idx}">
            ${th ? `<img src="${esc(th)}" alt="Pose ${idx + 1}">` : `<span class="staff-pose-placeholder">${done ? '✓ Saved' : 'Empty'}</span>`}
            <span class="staff-pose-lbl">${poseNames[idx]}${done ? ' · Retake' : ''}</span>
          </button>
        `;
      }).join('');
      strip.querySelectorAll('[data-staff-pose-slot]').forEach(btn => {
        btn.addEventListener('click', () => {
          const slotIdx = Number(btn.getAttribute('data-staff-pose-slot'));
          captureStaffModalPose(null, '', slotIdx);
        });
      });
    }

    const stEl = $('staffEnrolStatusMsg');
    if (stEl) {
      stEl.textContent = STAFF_FACE_MODAL_STATE.statusText || (capCount > 0 ? `${capCount}/3 Face ID poses stored for ${curEntry ? curEntry.name : ''}.` : 'Start camera to capture 3 quick Face ID poses.');
      stEl.className = 'kiosk-att-status ' + (STAFF_FACE_MODAL_STATE.statusCls || '');
    }

    const pinInp = $('staffEnrolPinInput');
    if (pinInp && curEntry && document.activeElement !== pinInp) {
      pinInp.value = curEntry.hasExplicitPin ? curEntry.pin : '';
    }
    stripNativeTitles(modal);
  }

