                <button type="button" class="kiosk-seg-btn ${pCfg.priceMode === 'unpriced' ? 'active' : ''}" data-tone="amber" data-kiosk-price-mode="unpriced"><span class="ksg-dot" aria-hidden="true"></span>${unpricedLbl}</button>
